window.MV_DATA=window.MV_DATA||{};window.MV_DATA[10]={"id":10,"topics":[{"id":91,"words":[{"en":"chassis","pos":"noun","ipa":"/ˈtʃæsi/","ja":"シャシ","kana":"シャシ","romaji":"shashi","vi":"khung gầm (sát-xi)","level":1,"def_vi":"Phần khung đỡ của ô tô gồm khung, hệ thống treo, lái, phanh và truyền lực, không tính thân xe.","def_en":"The supporting structure of a vehicle including frame, suspension, steering, brakes and driveline, excluding the body.","def_ja":"車体を除いた、フレーム・懸架装置・操舵装置・ブレーキ・駆動系などからなる車両の骨格部分。","usage_en":"Danh từ đếm được; số nhiều viết giống số ít (chassis) nhưng đọc /ˈtʃæsiz/. Hay đi với: chassis frame, chassis number, chassis tuning, ladder chassis.","usage_ja":"Hay đi với: シャシ性能, シャシ設計, シャシダイナモ. Ngoài xưởng hay viết シャシー; từ Hán 車台 ít dùng trong hội thoại.","context_vi":"Dùng trong thiết kế, lắp ráp và kiểm định xe tải, xe buýt, xe con, nhất là khi phân biệt phần gầm với phần thân.","ex_en":"The truck chassis is shipped to the body builder before the cargo box is mounted.","ex_ja":"荷台を架装する前に、トラックのシャシを架装メーカへ出荷する。","ex_vi":"Khung gầm xe tải được chuyển đến nhà đóng thùng trước khi lắp thùng hàng.","syn_en":["undercarriage (nghĩa gần)","frame (nghĩa hẹp hơn)"],"syn_ja":["シャシー","車台"]},{"en":"car body","pos":"noun phrase","ipa":"/ˈkɑːr ˌbɑːdi/","ja":"車体","kana":"しゃたい","romaji":"shatai","vi":"thân xe (vỏ xe)","level":1,"def_vi":"Phần vỏ và kết cấu chứa người, hàng hóa của ô tô, gồm sàn, khung cửa, mui và các tấm vỏ ngoài.","def_en":"The structure and outer panels of a vehicle that enclose passengers or cargo, including floor, pillars, roof and doors.","def_ja":"乗員や荷物を収める車両の構造と外板で、フロア・ピラー・ルーフ・ドアなどからなる。","usage_en":"Danh từ đếm được. Hay đi với: car body shop, car body panel, car body stiffness; trong nhà máy thường nói gọn body hoặc body-in-white (BIW) cho thân xe chưa sơn.","usage_ja":"Hay đi với: 車体剛性, 車体溶接, 車体組立ライン. Ngoài xưởng hay nói katakana ボデー (Toyota) hoặc ボディ.","context_vi":"Dùng ở xưởng hàn thân xe, xưởng sơn, khi đánh giá độ cứng vững và an toàn va chạm của xe.","ex_en":"Robots weld more than 4,000 spots on each car body.","ex_ja":"ロボットが1台の車体に4,000点以上のスポット溶接を行う。","ex_vi":"Robot hàn hơn 4.000 điểm hàn trên mỗi thân xe.","syn_en":["body-in-white (BIW, thân xe chưa sơn)","bodywork"],"syn_ja":["ボデー","ボディ"]},{"en":"suspension","pos":"noun","ipa":"/səˈspɛnʃən/","ja":"サスペンション","kana":"サスペンション","romaji":"sasupenshon","vi":"hệ thống treo","level":1,"def_vi":"Hệ thống gồm lò xo, giảm chấn và các tay đòn nối bánh xe với thân xe, giúp êm dịu và giữ bánh bám đường.","def_en":"The system of springs, dampers and links connecting the wheels to the body, providing ride comfort and road holding.","def_ja":"ばね・ダンパ・リンクで車輪と車体をつなぎ、乗り心地と接地性を確保する装置。","usage_en":"Danh từ không đếm được khi nói chung, đếm được khi chỉ một kiểu: a MacPherson strut suspension, front/rear suspension, independent suspension; động từ: tune / stiffen the suspension.","usage_ja":"Hay đi với: フロントサスペンション, 独立懸架, サスペンションを調整する. Văn bản chuẩn JIS dùng 懸架装置, ngoài xưởng gọi tắt サス.","context_vi":"Dùng khi thiết kế khung gầm, chỉnh độ êm và độ ổn định khi vào cua, và kiểm tra gầm xe trong bảo dưỡng.","ex_en":"The rear suspension was redesigned to reduce body roll in tight corners.","ex_ja":"急カーブでのロールを減らすため、リヤサスペンションを再設計した。","ex_vi":"Hệ thống treo sau được thiết kế lại để giảm độ nghiêng thân xe khi vào cua gắt.","syn_en":["suspension system"],"syn_ja":["懸架装置","サス (khẩu ngữ)"]},{"en":"tire","pos":"noun","ipa":"/ˈtaɪər/","ja":"タイヤ","kana":"タイヤ","romaji":"taiya","vi":"lốp xe","level":1,"def_vi":"Vỏ cao su bơm hơi lắp quanh vành bánh xe, tiếp xúc với mặt đường để truyền lực kéo, lực phanh và đỡ tải.","def_en":"An inflated rubber casing fitted on a wheel rim that contacts the road and transmits traction, braking and load.","def_ja":"ホイールのリムに装着し、路面と接して駆動力・制動力・荷重を伝える空気入りのゴム製部品。","usage_en":"Danh từ đếm được; tiếng Anh-Anh viết tyre. Hay đi với: tire pressure, tire tread, flat tire, radial tire; động từ: inflate / rotate / change a tire.","usage_ja":"Hay đi với: タイヤ空気圧, タイヤを交換する, タイヤのローテーション, ラジアルタイヤ. Chỉ dùng katakana.","context_vi":"Dùng hằng ngày trong xưởng dịch vụ, lắp ráp bánh xe, và khi thiết kế, thử nghiệm độ bám và lực cản lăn.","ex_en":"Check the tire pressure when the tires are cold.","ex_ja":"タイヤが冷えている状態でタイヤ空気圧を点検してください。","ex_vi":"Kiểm tra áp suất lốp khi lốp còn nguội.","syn_en":["tyre (Anh)"],"syn_ja":["空気入りタイヤ (nghĩa đầy đủ)"]},{"en":"steering wheel","pos":"noun phrase","ipa":"/ˈstɪrɪŋ ˌwiːl/","ja":"ステアリングホイール","kana":"ステアリングホイール","romaji":"sutearinguhoiiru","vi":"vô lăng (tay lái)","level":1,"def_vi":"Bánh lái tròn mà người lái xoay để điều khiển hướng chuyển động của các bánh xe dẫn hướng.","def_en":"The round wheel the driver turns to control the direction of the steered wheels.","def_ja":"運転者が回して操舵輪の向きを変えるための円形の操作部品。","usage_en":"Danh từ đếm được. Hay đi với: turn the steering wheel, steering wheel angle, steering wheel vibration; đừng nói 'steer wheel'.","usage_ja":"Hay đi với: ステアリングホイールを切る/回す, 舵角. Trong hội thoại và ngoài xưởng hầu như luôn nói ハンドル; ステアリングホイール dùng trong tài liệu kỹ thuật.","context_vi":"Dùng trong lắp ráp nội thất, thử nghiệm cảm giác lái, đo rung vô lăng và lắp túi khí người lái.","ex_en":"The driver reported vibration in the steering wheel at 100 km/h.","ex_ja":"運転者から時速100 kmでステアリングホイールが振動するとの報告があった。","ex_vi":"Người lái báo vô lăng bị rung ở tốc độ 100 km/h.","syn_en":["wheel (khẩu ngữ)"],"syn_ja":["ハンドル","ステアリング (khẩu ngữ)"]},{"en":"shock absorber","pos":"noun phrase","ipa":"/ˈʃɑːk əbˌzɔːrbər/","ja":"ショックアブソーバ","kana":"ショックアブソーバ","romaji":"shokkuabusooba","vi":"giảm chấn (phuộc nhún)","level":1,"def_vi":"Bộ phận thủy lực trong hệ thống treo dùng lực cản dầu để dập tắt dao động của lò xo.","def_en":"A hydraulic suspension component that damps spring oscillations by forcing oil through small orifices.","def_ja":"油が小穴を通る抵抗を利用して、ばねの振動を減衰させる懸架装置の部品。","usage_en":"Danh từ đếm được. Hay đi với: gas-filled shock absorber, leaking shock absorber; động từ: replace / fit a shock absorber. Kỹ sư hay gọi damper; khẩu ngữ Mỹ: shocks.","usage_ja":"Hay đi với: ショックアブソーバの減衰力, オイル漏れ. Ngoài xưởng gọi ショック hoặc ダンパ; từ Hán 緩衝器 ít dùng cho ô tô.","context_vi":"Dùng khi kiểm tra gầm xe, thay phuộc bị chảy dầu và khi tinh chỉnh độ êm của hệ thống treo.","ex_en":"A leaking shock absorber makes the car bounce after every bump.","ex_ja":"ショックアブソーバから油が漏れると、段差のたびに車が上下に揺れ続ける。","ex_vi":"Giảm chấn bị chảy dầu làm xe nảy lên xuống sau mỗi gờ đường.","syn_en":["damper","shocks (khẩu ngữ, Mỹ)"],"syn_ja":["ダンパ","ショック (khẩu ngữ)"]},{"en":"bumper","pos":"noun","ipa":"/ˈbʌmpər/","ja":"バンパ","kana":"バンパ","romaji":"banpa","vi":"cản xe (ba-đờ-xốc)","level":1,"def_vi":"Cụm chi tiết ở đầu và đuôi xe gồm vỏ nhựa và dầm gia cường, hấp thụ va chạm nhẹ và bảo vệ thân xe.","def_en":"The assembly at the front and rear of a vehicle, a plastic cover over a reinforcement beam, that absorbs low-speed impacts.","def_ja":"車両の前後にあり、樹脂製カバーと補強材からなり、軽い衝突を吸収して車体を守る部品。","usage_en":"Danh từ đếm được. Hay đi với: front / rear bumper, bumper cover (fascia), bumper beam, bumper sensor.","usage_ja":"Hay đi với: フロントバンパ, バンパカバー, バンパリインフォースメント. Thường viết バンパー; văn bản kỹ thuật của hãng hay bỏ trường âm.","context_vi":"Dùng trong ép phun, sơn chi tiết nhựa, lắp ráp ngoại thất và thử va chạm tốc độ thấp.","ex_en":"The rear bumper houses four parking sensors.","ex_ja":"リヤバンパには駐車センサが4個内蔵されている。","ex_vi":"Cản sau có gắn bốn cảm biến đỗ xe.","syn_en":["bumper fascia (vỏ cản, nghĩa hẹp)","fender (Mỹ, khẩu ngữ cũ)"],"syn_ja":["バンパー","バンパカバー (nghĩa hẹp)"]},{"en":"windshield","pos":"noun","ipa":"/ˈwɪndˌʃiːld/","ja":"フロントガラス","kana":"フロントガラス","romaji":"furontogarasu","vi":"kính chắn gió","level":1,"def_vi":"Tấm kính nhiều lớp phía trước khoang lái, chắn gió bụi và góp phần tăng độ cứng thân xe.","def_en":"The laminated glass panel at the front of the cabin that shields occupants and adds body stiffness.","def_ja":"車室前面の合わせガラスで、風やほこりを防ぎ、車体剛性にも寄与する。","usage_en":"Danh từ đếm được (Mỹ); tiếng Anh-Anh là windscreen. Hay đi với: laminated windshield, windshield wiper, crack in the windshield, bond the windshield.","usage_ja":"Hay đi với: フロントガラスの接着, 合わせガラス, ワイパ. Tài liệu kỹ thuật dùng ウインドシールドガラス; フロントガラス là từ ghép Nhật.","context_vi":"Dùng trong lắp ráp kính bằng keo, thiết kế tầm nhìn người lái và lắp camera hỗ trợ lái.","ex_en":"The camera is mounted behind the windshield near the rear-view mirror.","ex_ja":"カメラはルームミラー付近のフロントガラスの内側に取り付けられている。","ex_vi":"Camera được gắn sau kính chắn gió gần gương chiếu hậu.","syn_en":["windscreen (Anh)"],"syn_ja":["ウインドシールド","合わせガラス (loại kính, liên quan)"]},{"en":"seat belt","pos":"noun phrase","ipa":"/ˈsiːt ˌbɛlt/","ja":"シートベルト","kana":"シートベルト","romaji":"shiitoberuto","vi":"dây đai an toàn","level":1,"def_vi":"Dây đai giữ người ngồi trên ghế, hạn chế người lao về phía trước khi xe va chạm hoặc phanh gấp.","def_en":"A belt that restrains an occupant in the seat during a collision or sudden braking.","def_ja":"衝突や急制動時に乗員を座席に拘束するベルト。","usage_en":"Danh từ đếm được. Hay đi với: fasten / wear a seat belt, three-point seat belt, seat belt pretensioner, seat belt anchorage.","usage_ja":"Hay đi với: シートベルトを締める/着用する, シートベルトプリテンショナ, 3点式シートベルト.","context_vi":"Dùng trong lắp ráp nội thất, thử nghiệm va chạm và các quy chuẩn an toàn xe cơ giới.","ex_en":"The seat belt anchorage must withstand the pull test specified in the regulation.","ex_ja":"シートベルトの取付部は、規則で定められた引張試験に耐えなければならない。","ex_vi":"Điểm neo dây đai an toàn phải chịu được phép thử kéo quy định trong quy chuẩn.","syn_en":["safety belt"],"syn_ja":["座席ベルト (văn bản pháp quy)"]},{"en":"airbag","pos":"noun","ipa":"/ˈɛrˌbæɡ/","ja":"エアバッグ","kana":"エアバッグ","romaji":"eabaggu","vi":"túi khí","level":1,"def_vi":"Túi vải bung phồng tức thì bằng khí khi va chạm để đệm, bảo vệ người ngồi trong xe.","def_en":"A fabric bag that inflates instantly with gas in a crash to cushion and protect occupants.","def_ja":"衝突時にガスで瞬時に膨らみ、乗員を受け止めて保護する布製の袋。","usage_en":"Danh từ đếm được; cũng viết air bag. Hay đi với: driver / passenger / side / curtain airbag; động từ: the airbag deploys / inflates.","usage_ja":"Hay đi với: エアバッグが展開する, 運転席エアバッグ, カーテンエアバッグ. Tài liệu chính thức ghi SRSエアバッグ.","context_vi":"Dùng trong thiết kế an toàn bị động, thử nghiệm va chạm và khi chẩn đoán lỗi hệ thống túi khí.","ex_en":"The side airbag deployed within 15 milliseconds of impact.","ex_ja":"サイドエアバッグは衝突から15ミリ秒以内に展開した。","ex_vi":"Túi khí bên bung ra trong vòng 15 mili giây sau va chạm.","syn_en":["SRS airbag (supplemental restraint system)"],"syn_ja":["SRSエアバッグ"]},{"en":"wheel alignment","pos":"noun phrase","ipa":"/ˈwiːl əˌlaɪnmənt/","ja":"ホイールアライメント","kana":"ホイールアライメント","romaji":"hoiiruaraimento","vi":"cân chỉnh góc đặt bánh xe","level":2,"def_vi":"Việc đo và điều chỉnh các góc đặt bánh xe như độ chụm, góc doãng, góc nghiêng trụ lái theo thông số nhà sản xuất.","def_en":"Measuring and adjusting wheel angles such as toe, camber and caster to the manufacturer's specification.","def_ja":"トー・キャンバ・キャスタなどの車輪の取付け角を測定し、規定値に調整すること。","usage_en":"Cụm danh từ không đếm được (Anh còn gọi tracking). Hay đi với: do a wheel alignment, four-wheel alignment, alignment machine, out of alignment.","usage_ja":"Hay đi với: ホイールアライメント調整, アライメントテスタ. Khẩu ngữ: アライメント.","context_vi":"Dùng ở xưởng dịch vụ sau khi thay chi tiết treo, lái hoặc khi lốp mòn lệch, xe kéo lệch.","ex_en":"A wheel alignment is required after replacing the lower arm.","ex_ja":"ロアアーム交換後はホイールアライメントの調整が必要である。","ex_vi":"Sau khi thay càng dưới cần cân chỉnh góc đặt bánh xe.","syn_en":["alignment","tracking (Anh)"],"syn_ja":["アライメント (khẩu ngữ)","車輪整列 (ít dùng)"]},{"en":"drive shaft","pos":"noun phrase","ipa":"/ˈdraɪv ˌʃæft/","ja":"ドライブシャフト","kana":"ドライブシャフト","romaji":"doraibushafuto","vi":"trục láp (trục truyền động ra bánh)","level":2,"def_vi":"Trục truyền mô-men xoắn từ bộ vi sai tới bánh xe chủ động, có khớp đồng tốc ở hai đầu.","def_en":"A shaft transmitting torque from the differential to a driven wheel, usually with constant-velocity joints at both ends.","def_ja":"差動装置から駆動輪へトルクを伝える軸で、通常両端に等速ジョイントを持つ。","usage_en":"Danh từ đếm được; cũng viết driveshaft. Lưu ý: trong tiếng Anh-Mỹ 'drive shaft' cũng có thể chỉ trục các-đăng dọc xe; trục ra bánh hay gọi half shaft.","usage_ja":"Hay đi với: ドライブシャフトブーツ, 等速ジョイント. Người Nhật phân biệt rõ ドライブシャフト (ra bánh) và プロペラシャフト (trục dọc các-đăng).","context_vi":"Dùng trong xe dẫn động cầu trước và xe độc lập treo, khi thay chụp cao su khớp đồng tốc hoặc trục láp.","ex_en":"A torn boot let grit into the drive shaft joint.","ex_ja":"ブーツが破れて、ドライブシャフトのジョイントに砂が入った。","ex_vi":"Chụp cao su bị rách làm cát lọt vào khớp của trục láp.","syn_en":["half shaft","axle shaft"],"syn_ja":["駆動軸","プロペラシャフト (trục dọc, liên quan)"]},{"en":"powertrain","pos":"noun","ipa":"/ˈpaʊərˌtreɪn/","ja":"パワートレイン","kana":"パワートレイン","romaji":"pawaatorein","vi":"hệ truyền lực (powertrain)","level":2,"def_vi":"Toàn bộ các cụm tạo ra và truyền công suất đến bánh xe: động cơ hoặc mô-tơ, hộp số, trục và cầu.","def_en":"All components that generate and deliver power to the wheels: engine or motor, transmission, shafts and axles.","def_ja":"エンジンやモータ、変速機、軸、車軸など、動力を発生させ車輪へ伝える装置の総称。","usage_en":"Danh từ đếm được. Hay đi với: hybrid powertrain, electric powertrain, powertrain calibration, powertrain mount; drivetrain thì không gồm động cơ.","usage_ja":"Hay đi với: パワートレイン開発, 電動パワートレイン. Ngoài công ty hay gọi tắt パワトレ; tên phòng ban thường là パワートレイン部.","context_vi":"Dùng trong tổ chức phòng ban thiết kế, hiệu chỉnh và thử nghiệm công suất, tiêu hao nhiên liệu của xe.","ex_en":"The new electric powertrain fits in the same space as the old engine and gearbox.","ex_ja":"新しい電動パワートレインは、従来のエンジンと変速機と同じスペースに収まる。","ex_vi":"Hệ truyền lực điện mới vừa khít khoang chứa của động cơ và hộp số cũ.","syn_en":["drivetrain (nghĩa hẹp hơn, không gồm động cơ)","driveline"],"syn_ja":["動力伝達系 (nghĩa hẹp hơn)","パワトレ (khẩu ngữ)"]},{"en":"wheelbase","pos":"noun","ipa":"/ˈwiːlˌbeɪs/","ja":"ホイールベース","kana":"ホイールベース","romaji":"hoiirubeesu","vi":"chiều dài cơ sở","level":2,"def_vi":"Khoảng cách theo chiều dọc xe giữa tâm trục bánh trước và tâm trục bánh sau.","def_en":"The longitudinal distance between the centers of the front and rear axles.","def_ja":"前車軸の中心と後車軸の中心との前後方向の距離。","usage_en":"Danh từ đếm được, viết liền một từ. Hay đi với: long / short wheelbase (LWB / SWB), extend the wheelbase; đơn vị mm.","usage_ja":"Hay đi với: ロングホイールベース, ホイールベースを延長する. Văn bản JIS dùng 軸距, nhưng catalog và xưởng dùng katakana.","context_vi":"Dùng trong bảng thông số xe, khi bố trí khung gầm và tính bán kính quay vòng.","ex_en":"A longer wheelbase gives more cabin space and a smoother ride.","ex_ja":"ホイールベースが長いほど、室内空間が広くなり乗り心地も良くなる。","ex_vi":"Chiều dài cơ sở lớn hơn cho khoang cabin rộng hơn và xe chạy êm hơn.","syn_en":["axle base (ít dùng)"],"syn_ja":["軸距"]},{"en":"ground clearance","pos":"noun phrase","ipa":"/ˈɡraʊnd ˌklɪrəns/","ja":"最低地上高","kana":"さいていちじょうこう","romaji":"saiteichijoukou","vi":"khoảng sáng gầm xe","level":2,"def_vi":"Khoảng cách thẳng đứng từ mặt đường đến điểm thấp nhất của gầm xe khi xe đứng yên.","def_en":"The vertical distance between the road surface and the lowest point of the vehicle underbody.","def_ja":"路面から車体下部の最も低い点までの垂直距離。","usage_en":"Danh từ không đếm được. Hay đi với: high / low ground clearance, minimum ground clearance, a ground clearance of 200 mm.","usage_ja":"Hay đi với: 最低地上高を確保する, 最低地上高○○ mm. Trong hội thoại có thể nói 地上高 hoặc ロードクリアランス.","context_vi":"Dùng trong thông số xe SUV, xe địa hình và khi kiểm định xe sau khi hạ gầm hoặc độ xe.","ex_en":"The SUV has a ground clearance of 220 mm for rough roads.","ex_ja":"このSUVは悪路走行のために220 mmの最低地上高を確保している。","ex_vi":"Chiếc SUV này có khoảng sáng gầm 220 mm để đi đường xấu.","syn_en":["ride height (nghĩa gần)"],"syn_ja":["地上高","ロードクリアランス"]},{"en":"four-wheel drive","pos":"noun phrase","ipa":"/ˌfɔːr wiːl ˈdraɪv/","ja":"四輪駆動","kana":"よんりんくどう","romaji":"yonrinkudou","vi":"dẫn động bốn bánh","level":2,"def_vi":"Cách bố trí truyền lực trong đó động cơ dẫn động cả bốn bánh xe để tăng lực bám trên đường trơn, xấu.","def_en":"A drive layout in which power is delivered to all four wheels for better traction on poor surfaces.","def_ja":"四つの車輪すべてに動力を伝え、悪路や滑りやすい路面での駆動力を高める方式。","usage_en":"Cụm danh từ không đếm được, viết tắt 4WD; dùng như tính từ: a four-wheel drive vehicle. Phân biệt với all-wheel drive (AWD, thường toàn thời gian).","usage_ja":"Hay đi với: 四輪駆動車, フルタイム四輪駆動, パートタイム四輪駆動. Khẩu ngữ: 四駆 (よんく), viết tắt 4WD.","context_vi":"Dùng khi phân loại xe bán tải, SUV, xe quân sự và mô tả cấu hình truyền lực.","ex_en":"Engage four-wheel drive before climbing the muddy slope.","ex_ja":"ぬかるんだ坂を登る前に四輪駆動に切り替えてください。","ex_vi":"Hãy gài dẫn động bốn bánh trước khi leo dốc lầy.","syn_en":["4WD","all-wheel drive (AWD, gần nghĩa)"],"syn_ja":["4WD","四駆 (khẩu ngữ)"]},{"en":"automatic transmission","pos":"noun phrase","ipa":"/ˌɔːtəˈmætɪk trænzˈmɪʃən/","ja":"自動変速機","kana":"じどうへんそくき","romaji":"jidouhensokuki","vi":"hộp số tự động","level":2,"def_vi":"Hộp số tự chọn và chuyển cấp số theo tốc độ xe và tải, thường dùng biến mô và bộ bánh răng hành tinh.","def_en":"A transmission that selects and shifts gears automatically, typically using a torque converter and planetary gear sets.","def_ja":"車速や負荷に応じて自動で変速する変速機で、一般にトルクコンバータと遊星歯車を用いる。","usage_en":"Cụm danh từ đếm được, viết tắt AT. Hay đi với: six-speed automatic transmission, automatic transmission fluid (ATF); khẩu ngữ: an automatic.","usage_ja":"Hay đi với: 自動変速機油 (ATF), 6速自動変速機. Ngoài đời gọi AT hoặc オートマ.","context_vi":"Dùng trong bảng thông số xe, sửa chữa hộp số và đào tạo kỹ thuật viên dịch vụ.","ex_en":"The automatic transmission shifts harshly from second to third gear.","ex_ja":"この自動変速機は2速から3速への変速ショックが大きい。","ex_vi":"Hộp số tự động sang số từ số 2 lên số 3 bị giật mạnh.","syn_en":["AT","automatic (khẩu ngữ)"],"syn_ja":["AT","オートマ (khẩu ngữ)"]},{"en":"MacPherson strut","pos":"noun phrase","ipa":"/məkˈfɪərsən ˌstrʌt/","ja":"ストラット式サスペンション","kana":"ストラットしきサスペンション","romaji":"sutorattoshikisasupenshon","vi":"hệ treo kiểu MacPherson (thanh giằng)","level":2,"def_vi":"Kiểu treo độc lập trong đó cụm giảm chấn và lò xo đóng vai trò trụ dẫn hướng bánh xe, chỉ cần một càng dưới.","def_en":"An independent suspension in which the damper and coil spring unit also locates the wheel, needing only a lower arm.","def_ja":"ダンパとコイルばねの一体ユニットが車輪の位置決めも兼ね、ロアアームのみで構成される独立懸架。","usage_en":"Cụm danh từ đếm được, chữ M và P viết hoa (tên riêng). Hay đi với: MacPherson strut front suspension, strut mount, strut top.","usage_ja":"Hay đi với: マクファーソンストラット, ストラットアッパマウント. Ngoài xưởng nói gọn ストラット.","context_vi":"Dùng phổ biến ở hệ treo trước xe con cỡ nhỏ và trung, khi thiết kế bố trí gầm và thay giảm chấn.","ex_en":"Most compact cars use a MacPherson strut at the front to save space.","ex_ja":"多くの小型車は、スペースを節約するため前輪にストラット式サスペンションを採用している。","ex_vi":"Phần lớn xe cỡ nhỏ dùng hệ treo MacPherson ở bánh trước để tiết kiệm không gian.","syn_en":["strut suspension","McPherson strut (cách viết khác)"],"syn_ja":["マクファーソンストラット","ストラット (khẩu ngữ)"]},{"en":"power steering","pos":"noun phrase","ipa":"/ˈpaʊər ˌstɪrɪŋ/","ja":"パワーステアリング","kana":"パワーステアリング","romaji":"pawaasutearingu","vi":"trợ lực lái","level":2,"def_vi":"Hệ thống dùng thủy lực hoặc mô-tơ điện để giảm lực người lái cần tác dụng lên vô lăng.","def_en":"A system using hydraulic or electric assistance to reduce the effort needed to turn the steering wheel.","def_ja":"油圧や電動モータの補助で、ハンドル操作に必要な力を小さくする装置。","usage_en":"Cụm danh từ không đếm được. Hay đi với: electric power steering (EPS), hydraulic power steering, power steering pump, power steering fluid.","usage_ja":"Hay đi với: 電動パワーステアリング (EPS), パワーステアリングポンプ. Khẩu ngữ: パワステ.","context_vi":"Dùng trong thiết kế hệ thống lái, chẩn đoán lái nặng và hiệu chỉnh cảm giác lái.","ex_en":"Most new cars use electric power steering instead of a hydraulic pump.","ex_ja":"最近の車の多くは、油圧ポンプの代わりに電動パワーステアリングを採用している。","ex_vi":"Phần lớn xe mới dùng trợ lực lái điện thay cho bơm thủy lực.","syn_en":["power-assisted steering (Anh)","EPS (loại điện)"],"syn_ja":["パワステ (khẩu ngữ)","EPS (loại điện)"]},{"en":"anti-lock braking system","pos":"noun phrase","ipa":"/ˌænti ˈlɑːk ˈbreɪkɪŋ ˌsɪstəm/","ja":"アンチロックブレーキシステム","kana":"アンチロックブレーキシステム","romaji":"anchirokkubureekishisutemu","vi":"hệ thống chống bó cứng phanh (ABS)","level":2,"def_vi":"Hệ thống điều khiển điện tử tự giảm và tăng áp suất phanh liên tục để bánh xe không bị bó cứng khi phanh gấp.","def_en":"An electronic system that modulates brake pressure to prevent wheel lock-up during hard braking, preserving steering control.","def_ja":"急制動時にブレーキ圧を制御して車輪のロックを防ぎ、操舵性を保つ電子制御装置。","usage_en":"Cụm danh từ, hầu như luôn viết tắt ABS (không nói 'ABS system' trong văn bản chuẩn). Hay đi với: ABS sensor, ABS warning lamp, the ABS activates.","usage_ja":"Hay đi với: ABSが作動する, ABSセンサ, ABS警告灯. Trên xưởng và tài liệu chủ yếu viết ABS.","context_vi":"Dùng trong an toàn chủ động, chẩn đoán lỗi cảm biến tốc độ bánh và thử nghiệm phanh trên đường trơn.","ex_en":"The anti-lock braking system pulsed the brake pedal on the icy road.","ex_ja":"凍結路面でアンチロックブレーキシステムが作動し、ブレーキペダルが脈動した。","ex_vi":"Hệ thống chống bó cứng phanh làm bàn đạp phanh rung giật trên mặt đường đóng băng.","syn_en":["ABS","antilock brakes"],"syn_ja":["ABS"]},{"en":"tie rod","pos":"noun phrase","ipa":"/ˈtaɪ ˌrɑːd/","ja":"タイロッド","kana":"タイロッド","romaji":"tairoddo","vi":"thanh nối lái (rô-tuyn lái)","level":2,"def_vi":"Thanh nối từ cơ cấu lái tới cam quay bánh xe, truyền chuyển động lái và dùng để chỉnh độ chụm.","def_en":"A rod linking the steering gear to the steering knuckle, transmitting steering motion and used to adjust toe.","def_ja":"ステアリングギヤとナックルをつなぎ、操舵力を伝えるロッドで、トー調整にも使う。","usage_en":"Cụm danh từ đếm được. Hay đi với: inner / outer tie rod, tie rod end, adjust the tie rod; đầu khớp cầu thường gọi tie rod end.","usage_ja":"Hay đi với: タイロッドエンド, タイロッドを調整する, ガタ. Chỉ dùng katakana.","context_vi":"Dùng khi kiểm tra rơ hệ thống lái, thay rô-tuyn và cân chỉnh góc đặt bánh xe.","ex_en":"The mechanic adjusted the tie rod to correct the toe setting.","ex_ja":"整備士はトー値を修正するためにタイロッドを調整した。","ex_vi":"Thợ máy chỉnh thanh nối lái để sửa lại độ chụm.","syn_en":["track rod (Anh)","steering link"],"syn_ja":["タイロッドエンド (đầu thanh, liên quan)"]},{"en":"crumple zone","pos":"noun phrase","ipa":"/ˈkrʌmpəl ˌzoʊn/","ja":"クラッシャブルゾーン","kana":"クラッシャブルゾーン","romaji":"kurasshaburuzoon","vi":"vùng hấp thụ va chạm","level":2,"def_vi":"Phần đầu hoặc đuôi xe được thiết kế để biến dạng có kiểm soát khi va chạm, hấp thụ năng lượng bảo vệ khoang người ngồi.","def_en":"A front or rear vehicle area designed to deform in a controlled way, absorbing crash energy to protect the cabin.","def_ja":"衝突時に計画的につぶれて衝撃エネルギーを吸収し、客室を守る車体前後の部分。","usage_en":"Cụm danh từ đếm được. Hay đi với: front crumple zone, design a crumple zone, the crumple zone absorbs energy.","usage_ja":"Hay đi với: クラッシャブルゾーンが衝撃を吸収する, 衝撃吸収ボディ. Từ katakana này gốc 'crushable' nên khác tiếng Anh.","context_vi":"Dùng trong thiết kế kết cấu thân xe, mô phỏng và thử nghiệm va chạm.","ex_en":"The crumple zone collapsed as designed and the cabin stayed intact.","ex_ja":"クラッシャブルゾーンが設計どおりにつぶれ、客室は無事だった。","ex_vi":"Vùng hấp thụ va chạm bị bẹp đúng như thiết kế và khoang lái vẫn nguyên vẹn.","syn_en":["crush zone"],"syn_ja":["衝撃吸収構造"]},{"en":"electric vehicle","pos":"noun phrase","ipa":"/ɪˌlɛktrɪk ˈviːəkəl/","ja":"電気自動車","kana":"でんきじどうしゃ","romaji":"denkijidousha","vi":"xe điện","level":2,"def_vi":"Xe được dẫn động hoàn toàn bằng mô-tơ điện, lấy năng lượng từ pin sạc từ lưới điện.","def_en":"A vehicle driven entirely by electric motors powered by a rechargeable battery charged from the grid.","def_ja":"外部電源で充電した電池の電力でモータを回して走る自動車。","usage_en":"Cụm danh từ đếm được, viết tắt EV (an EV). Hay đi với: battery electric vehicle (BEV), EV charging, EV platform.","usage_ja":"Hay đi với: 電気自動車の充電, EV専用プラットフォーム. Trong công ty thường viết EV hoặc BEV.","context_vi":"Dùng trong thiết kế xe thế hệ mới, hạ tầng trạm sạc và chiến lược sản phẩm của hãng xe.","ex_en":"The electric vehicle has a range of 450 km on a full charge.","ex_ja":"この電気自動車は満充電で450 km走行できる。","ex_vi":"Chiếc xe điện này đi được 450 km sau một lần sạc đầy.","syn_en":["EV","BEV (battery electric vehicle)"],"syn_ja":["EV","BEV"]},{"en":"hybrid vehicle","pos":"noun phrase","ipa":"/ˌhaɪbrɪd ˈviːəkəl/","ja":"ハイブリッド車","kana":"ハイブリッドしゃ","romaji":"haiburiddosha","vi":"xe hybrid (xe lai)","level":2,"def_vi":"Xe kết hợp động cơ đốt trong với mô-tơ điện và pin để giảm tiêu hao nhiên liệu và khí thải.","def_en":"A vehicle combining an internal combustion engine with an electric motor and battery to cut fuel use and emissions.","def_ja":"エンジンと電動モータ・電池を組み合わせ、燃費と排出ガスを減らした自動車。","usage_en":"Cụm danh từ đếm được, viết tắt HEV; plug-in hybrid là PHEV. Khẩu ngữ: a hybrid. Hay đi với: full / mild hybrid.","usage_ja":"Hay đi với: ハイブリッド車の燃費, ストロングハイブリッド, マイルドハイブリッド. Viết tắt HV hoặc HEV.","context_vi":"Dùng khi so sánh các loại hệ truyền lực, trong bảng thông số xe và chính sách khí thải.","ex_en":"The hybrid vehicle runs on electric power alone at low speeds.","ex_ja":"ハイブリッド車は低速時にはモータだけで走行する。","ex_vi":"Xe hybrid chạy hoàn toàn bằng điện ở tốc độ thấp.","syn_en":["HEV","hybrid (khẩu ngữ)"],"syn_ja":["HV","HEV"]},{"en":"camber angle","pos":"noun phrase","ipa":"/ˈkæmbər ˌæŋɡəl/","ja":"キャンバ角","kana":"キャンバかく","romaji":"kyanbakaku","vi":"góc doãng (góc camber)","level":3,"def_vi":"Góc nghiêng của bánh xe so với phương thẳng đứng khi nhìn từ phía trước xe; nghiêng ra ngoài là dương.","def_en":"The inclination of a wheel from vertical viewed from the front; positive when the top leans outward.","def_ja":"車両前方から見た車輪の鉛直に対する傾き。上部が外側に傾くと正とする。","usage_en":"Cụm danh từ đếm được; thường nói gọn camber. Hay đi với: negative / positive camber angle, adjust the camber angle, camber change.","usage_ja":"Hay đi với: ネガティブキャンバ, キャンバ角を調整する. Có thể viết キャンバー角; ngoài xưởng nói キャンバ.","context_vi":"Dùng trong cân chỉnh góc đặt bánh xe, thiết kế hình học hệ thống treo và chẩn đoán mòn lốp lệch.","ex_en":"Excessive negative camber angle wears the inner edge of the tire.","ex_ja":"キャンバ角がネガティブ側に大きすぎると、タイヤの内側が偏摩耗する。","ex_vi":"Góc doãng âm quá lớn làm mòn mép trong của lốp.","syn_en":["camber"],"syn_ja":["キャンバ","キャンバー角"]},{"en":"toe-in","pos":"noun","ipa":"/ˈtoʊ ˌɪn/","ja":"トーイン","kana":"トーイン","romaji":"tooin","vi":"độ chụm (độ chụm dương)","level":3,"def_vi":"Trạng thái hai bánh xe cùng trục hướng mép trước vào nhau khi nhìn từ trên xuống, khoảng cách phía trước nhỏ hơn phía sau.","def_en":"A setting in which the front edges of a pair of wheels point slightly inward when viewed from above.","def_ja":"上から見て、左右の車輪の前側が後側より内向きになっている状態。","usage_en":"Danh từ không đếm được; ngược lại là toe-out. Hay đi với: set the toe-in, 2 mm of toe-in; khi nói chung dùng toe hoặc toe angle.","usage_ja":"Hay đi với: トーインに調整する, トーイン量. Ngược lại là トーアウト; nói chung dùng トー角.","context_vi":"Dùng khi cân chỉnh bánh xe trên máy chỉnh góc đặt bánh và khi thiết kế độ ổn định chạy thẳng.","ex_en":"A small amount of toe-in improves straight-line stability.","ex_ja":"わずかなトーインをつけると直進安定性が向上する。","ex_vi":"Một chút độ chụm giúp xe ổn định hơn khi chạy thẳng.","syn_en":["toe (nghĩa rộng)","toe-out (trái nghĩa, liên quan)"],"syn_ja":["トー角 (nghĩa rộng)","トーアウト (trái nghĩa, liên quan)"]},{"en":"understeer","pos":"noun","ipa":"/ˈʌndərˌstɪr/","ja":"アンダーステア","kana":"アンダーステア","romaji":"andaasutea","vi":"hiện tượng thiếu lái (understeer)","level":3,"def_vi":"Đặc tính quay vòng khi xe vào cua rộng hơn góc đánh lái do bánh trước mất bám trước bánh sau.","def_en":"A handling characteristic in which the car turns less than the steering input because the front tires lose grip first.","def_ja":"前輪が先にグリップを失い、ハンドル操作より旋回半径が大きくなる操縦特性。","usage_en":"Danh từ không đếm được, cũng dùng như động từ (the car understeers). Hay đi với: reduce understeer, understeer gradient; ngược lại là oversteer.","usage_ja":"Hay đi với: アンダーステアが出る, 弱アンダー, アンダーステア傾向. Ngoài xưởng nói gọn アンダー; ngược lại là オーバーステア.","context_vi":"Dùng trong thử nghiệm tính năng điều khiển, hiệu chỉnh hệ thống treo và kiểm soát ổn định xe.","ex_en":"Stiffer front anti-roll bars increase understeer at the limit.","ex_ja":"フロントのスタビライザを硬くすると、限界域でアンダーステアが強まる。","ex_vi":"Thanh cân bằng trước cứng hơn làm tăng hiện tượng thiếu lái ở giới hạn bám.","syn_en":["push (khẩu ngữ đua xe, Mỹ)","oversteer (trái nghĩa, liên quan)"],"syn_ja":["アンダー (khẩu ngữ)","オーバーステア (trái nghĩa, liên quan)"]},{"en":"advanced driver assistance system","pos":"noun phrase","ipa":"/ədˌvænst ˈdraɪvər əˈsɪstəns ˌsɪstəm/","ja":"先進運転支援システム","kana":"せんしんうんてんしえんシステム","romaji":"senshinuntenshienshisutemu","vi":"hệ thống hỗ trợ lái xe nâng cao (ADAS)","level":3,"def_vi":"Nhóm hệ thống dùng camera, radar và cảm biến để hỗ trợ người lái như phanh khẩn cấp tự động, giữ làn, ga tự động thích ứng.","def_en":"Systems using cameras, radar and sensors to assist the driver, such as automatic emergency braking, lane keeping and adaptive cruise.","def_ja":"カメラやレーダなどで運転を支援する装置群で、衝突被害軽減ブレーキや車線維持支援などを含む。","usage_en":"Cụm danh từ đếm được, gần như luôn viết tắt ADAS (dùng như danh từ chung: ADAS features). Hay đi với: ADAS calibration, ADAS sensor, ADAS camera.","usage_ja":"Hay đi với: ADASのエーミング (hiệu chuẩn), 衝突被害軽減ブレーキ. Hầu như luôn viết ADAS (エーダス).","context_vi":"Dùng trong phát triển xe mới, hiệu chuẩn camera và radar sau khi thay kính hoặc cản, và đánh giá an toàn.","ex_en":"After a windshield replacement the advanced driver assistance system camera must be recalibrated.","ex_ja":"フロントガラス交換後は、先進運転支援システムのカメラを再調整しなければならない。","ex_vi":"Sau khi thay kính chắn gió phải hiệu chuẩn lại camera của hệ thống hỗ trợ lái xe nâng cao.","syn_en":["ADAS","driver assistance system"],"syn_ja":["ADAS","運転支援システム"]},{"en":"monocoque body","pos":"noun phrase","ipa":"/ˈmɑːnəˌkoʊk ˌbɑːdi/","ja":"モノコックボディ","kana":"モノコックボディ","romaji":"monokokkubodi","vi":"thân xe chịu lực (liền khối, monocoque)","level":3,"def_vi":"Kết cấu thân xe trong đó vỏ và khung hàn liền thành một khối chịu lực, không cần khung sát-xi riêng.","def_en":"A body structure in which the shell itself carries the loads, with no separate frame.","def_ja":"独立したフレームを持たず、車体外殻そのものが荷重を受け持つ構造の車体。","usage_en":"Cụm danh từ đếm được. Tiếng Anh-Mỹ hay nói unibody; ngược lại là body-on-frame (ladder frame). Hay đi với: monocoque body structure, steel monocoque body.","usage_ja":"Hay đi với: モノコックボディ構造, フレーム付き車体と比較する. Cũng nói モノコック構造.","context_vi":"Dùng khi so sánh kết cấu xe con với xe tải khung rời, và trong thiết kế độ cứng xoắn thân xe.","ex_en":"Almost every passenger car today uses a monocoque body to save weight.","ex_ja":"現在の乗用車のほとんどは、軽量化のためモノコックボディを採用している。","ex_vi":"Hầu hết xe con ngày nay dùng thân xe chịu lực liền khối để giảm khối lượng.","syn_en":["unibody (Mỹ)","unitary construction"],"syn_ja":["モノコック構造"]},{"en":"electronic stability control","pos":"noun phrase","ipa":"/ɪˌlɛkˈtrɑːnɪk stəˈbɪləti kənˌtroʊl/","ja":"横滑り防止装置","kana":"よこすべりぼうしそうち","romaji":"yokosuberiboushisouchi","vi":"hệ thống cân bằng điện tử (ESC)","level":3,"def_vi":"Hệ thống phanh từng bánh riêng và giảm mô-men động cơ khi cảm biến phát hiện xe bị trượt ngang, giúp giữ đúng hướng lái.","def_en":"A system that brakes individual wheels and cuts engine torque when sensors detect skidding, keeping the car on its intended path.","def_ja":"横滑りを検知すると各輪のブレーキとエンジン出力を制御し、車両の進路を保つ装置。","usage_en":"Cụm danh từ không đếm được, viết tắt ESC; các hãng gọi ESP, VSC, DSC. Hay đi với: ESC intervention, yaw rate sensor, ESC off switch.","usage_ja":"Hay đi với: 横滑り防止装置の作動, ヨーレートセンサ. Viết tắt ESC; Toyota gọi VSC, Bosch gọi ESP.","context_vi":"Dùng trong an toàn chủ động bắt buộc theo quy chuẩn, hiệu chỉnh trên đường thử trơn và chẩn đoán cảm biến.","ex_en":"Electronic stability control prevented the car from spinning on the wet curve.","ex_ja":"濡れたカーブで横滑り防止装置が作動し、スピンを防いだ。","ex_vi":"Hệ thống cân bằng điện tử đã giúp xe không bị xoay vòng ở khúc cua ướt.","syn_en":["ESC","ESP (tên thương mại)"],"syn_ja":["ESC","VSC (tên thương mại)"]}]},{"id":92,"words":[{"en":"aircraft","pos":"noun","ipa":"/ˈɛrˌkræft/","ja":"航空機","kana":"こうくうき","romaji":"koukuuki","vi":"tàu bay (máy bay)","level":1,"def_vi":"Phương tiện bay trong khí quyển nhờ lực nâng khí động hoặc lực nổi, gồm máy bay, trực thăng, tàu lượn, khí cầu.","def_en":"Any vehicle that flies in the atmosphere using aerodynamic lift or buoyancy, such as airplanes, helicopters and gliders.","def_ja":"空気力による揚力や浮力で大気中を飛行する乗り物の総称で、飛行機・ヘリコプタなどを含む。","usage_en":"Danh từ đếm được, số nhiều không đổi (two aircraft, không nói 'aircrafts'). Hay đi với: commercial / military aircraft, aircraft maintenance, aircraft manufacturer.","usage_ja":"Hay đi với: 航空機部品, 航空機整備, 民間航空機. Trong hội thoại thường nói 飛行機, còn 航空機 dùng trong văn bản, tên ngành.","context_vi":"Dùng trong ngành chế tạo, bảo dưỡng tàu bay, quy định hàng không và chuỗi cung ứng linh kiện hàng không.","ex_en":"The plant machines titanium brackets for several aircraft programs.","ex_ja":"この工場では複数の航空機プログラム向けにチタン製ブラケットを加工している。","ex_vi":"Nhà máy gia công giá đỡ titan cho nhiều chương trình tàu bay.","syn_en":["airplane (Mỹ, nghĩa hẹp hơn)","aeroplane (Anh, nghĩa hẹp hơn)"],"syn_ja":["飛行機 (nghĩa hẹp hơn)","機体 (liên quan)"]},{"en":"fuselage","pos":"noun","ipa":"/ˈfjuːsəˌlɑːʒ/","ja":"胴体","kana":"どうたい","romaji":"doutai","vi":"thân máy bay","level":1,"def_vi":"Phần thân chính của máy bay chứa buồng lái, hành khách, hàng hóa và là nơi gắn cánh, đuôi.","def_en":"The main body of an aircraft that holds crew, passengers and cargo, and to which wings and tail attach.","def_ja":"乗員・乗客・貨物を収め、主翼と尾翼が取り付けられる航空機の本体部分。","usage_en":"Danh từ đếm được. Hay đi với: fuselage section, forward / aft fuselage, fuselage skin, fuselage frame; đừng nhầm với hull (thân tàu thủy).","usage_ja":"Hay đi với: 前部胴体, 後部胴体, 胴体パネル, 胴体結合. Không dùng katakana trong thực tế xưởng Nhật.","context_vi":"Dùng trong lắp ráp thân máy bay theo từng đoạn, kiểm tra kết cấu và sửa chữa vỏ máy bay.","ex_en":"The two fuselage sections were joined in the final assembly line.","ex_ja":"二つの胴体セクションを最終組立ラインで結合した。","ex_vi":"Hai đoạn thân máy bay được ghép lại trên dây chuyền lắp ráp cuối.","syn_en":["body (khẩu ngữ)"],"syn_ja":["機体 (nghĩa rộng hơn)","胴体部"]},{"en":"wing","pos":"noun","ipa":"/wɪŋ/","ja":"主翼","kana":"しゅよく","romaji":"shuyoku","vi":"cánh (cánh chính)","level":1,"def_vi":"Bề mặt khí động lớn gắn hai bên thân máy bay, tạo ra phần lớn lực nâng và thường chứa nhiên liệu.","def_en":"The large aerodynamic surface on each side of the fuselage that produces most of the lift and often holds fuel.","def_ja":"胴体の左右に取り付けられ、揚力の大部分を発生し、燃料タンクも兼ねることが多い翼。","usage_en":"Danh từ đếm được. Hay đi với: wing span, wing root, wing tip, swept wing, wing box; động từ: the wing generates lift.","usage_ja":"Hay đi với: 主翼の翼端, 翼根, 主翼構造, 後退翼. Từ chung 翼 (つばさ／よく) cũng dùng; ウイング ít dùng trong văn bản kỹ thuật.","context_vi":"Dùng trong thiết kế khí động, chế tạo kết cấu cánh và kiểm tra bảo dưỡng máy bay.","ex_en":"Fuel is stored in tanks inside the wing box.","ex_ja":"燃料は主翼内部の燃料タンクに搭載される。","ex_vi":"Nhiên liệu được chứa trong các thùng bên trong hộp cánh.","syn_en":["main wing","mainplane (Anh)"],"syn_ja":["翼 (nghĩa rộng hơn)","ウイング"]},{"en":"landing gear","pos":"noun phrase","ipa":"/ˈlændɪŋ ˌɡɪr/","ja":"降着装置","kana":"こうちゃくそうち","romaji":"kouchakusouchi","vi":"càng đáp (bộ càng hạ cánh)","level":1,"def_vi":"Cụm bánh xe, giảm chấn và cơ cấu thu thả đỡ máy bay khi lăn trên mặt đất, cất cánh và hạ cánh.","def_en":"The wheels, shock struts and retraction mechanism that support an aircraft on the ground and during takeoff and landing.","def_ja":"地上走行や離着陸時に機体を支える車輪・緩衝支柱・引込み機構などの装置。","usage_en":"Cụm danh từ không đếm được (the landing gear); hay đi với: main / nose landing gear, retract / extend the landing gear, landing gear bay.","usage_ja":"Hay đi với: 主脚, 前脚, 降着装置を格納する. Ngoài xưởng và phi công hay nói ランディングギア hoặc 脚 (あし).","context_vi":"Dùng trong chế tạo chi tiết rèn chịu tải lớn, thử nghiệm thả rơi và bảo dưỡng định kỳ máy bay.","ex_en":"The landing gear is retracted into the fuselage after takeoff.","ex_ja":"離陸後、降着装置は胴体内に格納される。","ex_vi":"Càng đáp được thu vào thân máy bay sau khi cất cánh.","syn_en":["undercarriage (Anh)","gear (khẩu ngữ)"],"syn_ja":["ランディングギア","脚 (khẩu ngữ)"]},{"en":"cockpit","pos":"noun","ipa":"/ˈkɑːkˌpɪt/","ja":"操縦室","kana":"そうじゅうしつ","romaji":"soujuushitsu","vi":"buồng lái","level":1,"def_vi":"Khoang ở phía trước máy bay nơi phi công ngồi điều khiển, có các bảng đồng hồ, màn hình và cần lái.","def_en":"The compartment at the front of an aircraft where pilots sit and operate the flight controls and instruments.","def_ja":"機首部にあり、操縦士が計器と操縦装置を操作する区画。","usage_en":"Danh từ đếm được. Hay đi với: cockpit display, glass cockpit, cockpit voice recorder; máy bay chở khách cũng gọi flight deck.","usage_ja":"Hay đi với: 操縦室の計器, グラスコックピット. Trong hội thoại thường nói コックピット; văn bản chính thức dùng 操縦室.","context_vi":"Dùng trong thiết kế giao diện người lái, lắp đặt thiết bị điện tử hàng không và huấn luyện phi công.","ex_en":"The new cockpit uses four large touch-screen displays.","ex_ja":"新しい操縦室には大型タッチパネル表示器が4面装備されている。","ex_vi":"Buồng lái mới dùng bốn màn hình cảm ứng lớn.","syn_en":["flight deck"],"syn_ja":["コックピット"]},{"en":"spacecraft","pos":"noun","ipa":"/ˈspeɪsˌkræft/","ja":"宇宙機","kana":"うちゅうき","romaji":"uchuuki","vi":"tàu vũ trụ (phương tiện vũ trụ)","level":1,"def_vi":"Phương tiện được thiết kế để hoạt động ngoài khí quyển Trái Đất, như vệ tinh, tàu thăm dò, tàu chở người.","def_en":"A vehicle designed to operate beyond Earth's atmosphere, such as satellites, probes and crewed capsules.","def_ja":"人工衛星や探査機、有人宇宙船など、大気圏外で運用するために設計された機体の総称。","usage_en":"Danh từ đếm được, số nhiều không đổi (two spacecraft). Hay đi với: crewed / uncrewed spacecraft, spacecraft bus, spacecraft design.","usage_ja":"Hay đi với: 宇宙機設計, 宇宙機システム. 宇宙船 thường chỉ tàu có người; 探査機 chỉ tàu thăm dò.","context_vi":"Dùng trong ngành vũ trụ, thiết kế kết cấu và hệ thống nhiệt cho vệ tinh, tàu thăm dò.","ex_en":"The spacecraft structure must survive launch vibration of over 10 g.","ex_ja":"宇宙機の構造は10 Gを超える打上げ振動に耐えなければならない。","ex_vi":"Kết cấu tàu vũ trụ phải chịu được rung động khi phóng trên 10 g.","syn_en":["space vehicle"],"syn_ja":["宇宙船 (có người, nghĩa hẹp hơn)","探査機 (liên quan)"]},{"en":"rocket","pos":"noun","ipa":"/ˈrɑːkɪt/","ja":"ロケット","kana":"ロケット","romaji":"roketto","vi":"tên lửa (rocket)","level":1,"def_vi":"Phương tiện bay được đẩy bằng phản lực của khí cháy phụt ra, mang theo cả nhiên liệu lẫn chất oxy hóa.","def_en":"A vehicle propelled by the reaction of exhaust gas, carrying both its fuel and oxidizer.","def_ja":"燃料と酸化剤を自ら搭載し、噴射ガスの反動で推進する飛しょう体。","usage_en":"Danh từ đếm được. Hay đi với: launch a rocket, rocket engine, rocket stage, two-stage rocket; tên lửa phóng vệ tinh gọi launch vehicle.","usage_ja":"Hay đi với: ロケットを打ち上げる, ロケットエンジン, 2段式ロケット. Chỉ dùng katakana.","context_vi":"Dùng trong phóng vệ tinh, thiết kế động cơ tên lửa và thử nghiệm đốt tĩnh.","ex_en":"The rocket placed two satellites into low Earth orbit.","ex_ja":"ロケットは2機の衛星を低軌道に投入した。","ex_vi":"Tên lửa đã đưa hai vệ tinh lên quỹ đạo thấp.","syn_en":["launch vehicle"],"syn_ja":["打上げロケット","ローンチビークル"]},{"en":"satellite","pos":"noun","ipa":"/ˈsætəˌlaɪt/","ja":"人工衛星","kana":"じんこうえいせい","romaji":"jinkoueisei","vi":"vệ tinh nhân tạo","level":1,"def_vi":"Thiết bị do con người phóng lên và bay trên quỹ đạo quanh Trái Đất hoặc thiên thể khác để quan sát, liên lạc, định vị.","def_en":"A human-made object placed in orbit around Earth or another body for observation, communication or navigation.","def_ja":"観測・通信・測位などのため、地球などの周りの軌道に投入された人工の物体。","usage_en":"Danh từ đếm được. Hay đi với: communications / Earth observation satellite, launch a satellite, satellite bus, small satellite.","usage_ja":"Hay đi với: 人工衛星を打ち上げる, 通信衛星, 地球観測衛星. Thường nói gọn 衛星.","context_vi":"Dùng trong ngành vũ trụ, viễn thám, viễn thông và chế tạo kết cấu nhẹ cho vệ tinh nhỏ.","ex_en":"The satellite deploys its solar panels after separation from the rocket.","ex_ja":"人工衛星はロケットから分離した後、太陽電池パドルを展開する。","ex_vi":"Vệ tinh nhân tạo mở các tấm pin mặt trời sau khi tách khỏi tên lửa.","syn_en":["artificial satellite"],"syn_ja":["衛星"]},{"en":"lift","pos":"noun","ipa":"/lɪft/","ja":"揚力","kana":"ようりょく","romaji":"youryoku","vi":"lực nâng","level":1,"def_vi":"Thành phần lực khí động vuông góc với hướng dòng khí tới, do cánh tạo ra để giữ máy bay trên không.","def_en":"The aerodynamic force perpendicular to the oncoming airflow, produced by the wing to hold an aircraft aloft.","def_ja":"流れの方向に垂直に働く空気力で、翼が発生させて機体を空中に支える力。","usage_en":"Danh từ không đếm được. Hay đi với: generate / produce lift, lift coefficient, lose lift, lift force; trong tiếng Anh 'lift' còn nghĩa thang máy (Anh), cần phân biệt.","usage_ja":"Hay đi với: 揚力を発生する, 揚力係数, 揚力を失う. Không dùng katakana リフト cho nghĩa này.","context_vi":"Dùng trong khí động học, tính toán cánh máy bay, cánh quạt, cánh tuabin gió.","ex_en":"Extending the flaps increases lift at low speed.","ex_ja":"フラップを下げると低速時の揚力が増える。","ex_vi":"Thả cánh tà làm tăng lực nâng ở tốc độ thấp.","syn_en":["lift force"],"syn_ja":["揚力係数 (liên quan)"]},{"en":"thrust","pos":"noun","ipa":"/θrʌst/","ja":"推力","kana":"すいりょく","romaji":"suiryoku","vi":"lực đẩy","level":1,"def_vi":"Lực đẩy phương tiện về phía trước do động cơ phản lực, cánh quạt hoặc động cơ tên lửa tạo ra.","def_en":"The forward force produced by a jet engine, propeller or rocket motor to propel a vehicle.","def_ja":"ジェットエンジン、プロペラ、ロケットエンジンが発生し、機体を前方へ推し進める力。","usage_en":"Danh từ không đếm được. Hay đi với: take-off thrust, thrust-to-weight ratio, reverse thrust, produce 120 kN of thrust.","usage_ja":"Hay đi với: 推力を発生する, 推力重量比, 逆推力装置. Kỹ thuật viên đôi khi nói スラスト.","context_vi":"Dùng khi chọn động cơ máy bay, thử nghiệm động cơ tên lửa và tính toán hiệu năng cất cánh.","ex_en":"Each engine produces 150 kN of thrust at take-off.","ex_ja":"各エンジンは離陸時に150 kNの推力を発生する。","ex_vi":"Mỗi động cơ tạo lực đẩy 150 kN khi cất cánh.","syn_en":["propulsive force"],"syn_ja":["推進力","スラスト"]},{"en":"aileron","pos":"noun","ipa":"/ˈeɪləˌrɑːn/","ja":"補助翼","kana":"ほじょよく","romaji":"hojoyoku","vi":"cánh liệng","level":2,"def_vi":"Mặt điều khiển có bản lề ở mép sau phía ngoài cánh, lệch ngược chiều hai bên để làm máy bay nghiêng (lăn).","def_en":"A hinged control surface on the outer trailing edge of each wing, deflected differentially to roll the aircraft.","def_ja":"主翼後縁外側にある操縦翼面で、左右逆に動かして機体をロールさせる。","usage_en":"Danh từ đếm được. Hay đi với: left / right aileron, aileron deflection, aileron actuator; động từ: deflect the aileron.","usage_ja":"Hay đi với: 補助翼を操作する, 補助翼アクチュエータ. Ngoài xưởng và phi công thường gọi エルロン.","context_vi":"Dùng trong thiết kế hệ thống điều khiển bay, lắp ráp mặt điều khiển và kiểm tra trước chuyến bay.","ex_en":"The pilot deflected the left aileron up to start a left roll.","ex_ja":"操縦士は左旋回を始めるため左の補助翼を上げた。","ex_vi":"Phi công nâng cánh liệng trái lên để bắt đầu nghiêng sang trái.","syn_en":["roll control surface (nghĩa rộng)"],"syn_ja":["エルロン"]},{"en":"elevator","pos":"noun","ipa":"/ˈɛləˌveɪtər/","ja":"昇降舵","kana":"しょうこうだ","romaji":"shoukouda","vi":"bánh lái độ cao","level":2,"def_vi":"Mặt điều khiển có bản lề ở mép sau cánh đuôi ngang, dùng để chúc hoặc ngóc mũi máy bay.","def_en":"A hinged control surface on the horizontal tail that pitches the aircraft's nose up or down.","def_ja":"水平尾翼の後縁にある操縦翼面で、機首を上げ下げする。","usage_en":"Danh từ đếm được; trong hàng không không phải 'thang máy'. Hay đi với: elevator trim, elevator deflection, pull back to raise the elevator.","usage_ja":"Hay đi với: 昇降舵を上げる, 昇降舵トリム. Phi công và kỹ thuật viên hay nói エレベータ.","context_vi":"Dùng trong điều khiển bay theo trục dọc (pitch), cân bằng máy bay và kiểm tra mặt điều khiển.","ex_en":"A jammed elevator would make it impossible to control pitch.","ex_ja":"昇降舵が固着すると、ピッチの制御ができなくなる。","ex_vi":"Nếu bánh lái độ cao bị kẹt thì không thể điều khiển góc chúc ngóc.","syn_en":["pitch control surface (nghĩa rộng)"],"syn_ja":["エレベータ"]},{"en":"vertical stabilizer","pos":"noun phrase","ipa":"/ˌvɜːrtɪkəl ˈsteɪbəˌlaɪzər/","ja":"垂直尾翼","kana":"すいちょくびよく","romaji":"suichokubiyoku","vi":"cánh đuôi đứng","level":2,"def_vi":"Bề mặt cố định thẳng đứng ở đuôi máy bay giữ ổn định hướng, mang bánh lái hướng ở mép sau.","def_en":"The fixed vertical tail surface that gives directional stability and carries the rudder.","def_ja":"機体尾部の垂直な固定翼面で、方向安定を与え、後縁に方向舵を持つ。","usage_en":"Cụm danh từ đếm được. Tiếng Anh-Anh hay nói fin hoặc vertical tail. Hay đi với: vertical stabilizer attachment, tail fin.","usage_ja":"Hay đi với: 垂直尾翼の取付部, 垂直安定板. Cùng nhóm với 水平尾翼; ngoài xưởng có thể gọi バーチカルスタビライザ.","context_vi":"Dùng trong thiết kế ổn định hướng, chế tạo kết cấu đuôi composite và kiểm tra sau va chạm chim.","ex_en":"The vertical stabilizer is made of carbon-fiber composite.","ex_ja":"垂直尾翼は炭素繊維複合材で作られている。","ex_vi":"Cánh đuôi đứng được làm bằng vật liệu composite sợi các-bon.","syn_en":["fin (Anh)","vertical tail"],"syn_ja":["垂直安定板","バーチカルスタビライザ"]},{"en":"flap","pos":"noun","ipa":"/flæp/","ja":"フラップ","kana":"フラップ","romaji":"furappu","vi":"cánh tà","level":2,"def_vi":"Tấm có thể thả ra ở mép sau cánh để tăng lực nâng và lực cản, giúp máy bay bay chậm khi cất, hạ cánh.","def_en":"A movable surface on the wing trailing edge that is extended to increase lift and drag for takeoff and landing.","def_ja":"主翼後縁にあり、離着陸時に下げて揚力と抗力を増やす可動翼面。","usage_en":"Danh từ đếm được, thường số nhiều: lower / extend / retract the flaps, flap setting, flaps 30.","usage_ja":"Hay đi với: フラップを下げる/上げる, フラップ角, ファウラーフラップ. Thuộc nhóm 高揚力装置.","context_vi":"Dùng trong thiết kế thiết bị tăng lực nâng, lắp đặt ray trượt cánh tà và quy trình cất hạ cánh.","ex_en":"The crew set the flaps to 30 degrees for landing.","ex_ja":"乗員は着陸のためフラップを30度に設定した。","ex_vi":"Tổ lái đặt cánh tà ở 30 độ để hạ cánh.","syn_en":["trailing-edge flap","high-lift device (nghĩa rộng)"],"syn_ja":["高揚力装置 (nghĩa rộng)"]},{"en":"nacelle","pos":"noun","ipa":"/nəˈsɛl/","ja":"ナセル","kana":"ナセル","romaji":"naseru","vi":"vỏ bọc động cơ (nacelle)","level":2,"def_vi":"Vỏ khí động bao quanh động cơ máy bay, gồm cửa hút gió, nắp mở bảo dưỡng và bộ đảo chiều lực đẩy.","def_en":"The streamlined housing around an aircraft engine, including the inlet, cowlings and thrust reverser.","def_ja":"航空機エンジンを覆う流線形の外殻で、インレット・カウル・逆推力装置などを含む。","usage_en":"Danh từ đếm được. Hay đi với: engine nacelle, nacelle inlet, open the nacelle cowling; tuabin gió cũng dùng nacelle cho vỏ chứa máy phát.","usage_ja":"Hay đi với: エンジンナセル, ナセルカウル. Chỉ dùng katakana; tuabin gió cũng gọi ナセル.","context_vi":"Dùng trong lắp đặt động cơ lên cánh, bảo dưỡng động cơ và thiết kế giảm ồn.","ex_en":"Technicians opened the nacelle to inspect the fuel lines.","ex_ja":"整備士は燃料配管を点検するためナセルを開けた。","ex_vi":"Kỹ thuật viên mở vỏ bọc động cơ để kiểm tra đường ống nhiên liệu.","syn_en":["engine cowling (nghĩa gần)","engine pod"],"syn_ja":["エンジンカウル (nghĩa gần)"]},{"en":"winglet","pos":"noun","ipa":"/ˈwɪŋlət/","ja":"ウイングレット","kana":"ウイングレット","romaji":"uinguretto","vi":"cánh nhỏ đầu mút (winglet)","level":2,"def_vi":"Phần cánh nhỏ dựng lên ở đầu mút cánh để giảm xoáy đầu cánh, từ đó giảm lực cản cảm ứng và tiết kiệm nhiên liệu.","def_en":"A small near-vertical surface at the wingtip that reduces tip vortices and induced drag, saving fuel.","def_ja":"翼端に付けた小さな翼で、翼端渦と誘導抗力を減らし燃費を改善する。","usage_en":"Danh từ đếm được. Hay đi với: blended winglet, split scimitar winglet, retrofit winglets.","usage_ja":"Hay đi với: ウイングレットを装着する, シャークレット (tên thương mại Airbus). Cũng viết ウィングレット.","context_vi":"Dùng trong cải tiến khí động máy bay chở khách, thiết kế đầu cánh và cánh quạt tuabin gió.","ex_en":"Retrofitting winglets cut fuel burn by about 4 percent.","ex_ja":"ウイングレットの後付けにより燃料消費を約4%削減した。","ex_vi":"Lắp thêm cánh nhỏ đầu mút giúp giảm khoảng 4% nhiên liệu tiêu thụ.","syn_en":["wingtip device (nghĩa rộng)"],"syn_ja":["ウィングレット","翼端板 (liên quan)"]},{"en":"airfoil","pos":"noun","ipa":"/ˈɛrˌfɔɪl/","ja":"翼型","kana":"よくがた","romaji":"yokugata","vi":"biên dạng cánh (profile cánh)","level":2,"def_vi":"Hình dạng mặt cắt ngang của cánh hoặc cánh quạt, được thiết kế để tạo lực nâng lớn với lực cản nhỏ.","def_en":"The cross-sectional shape of a wing or blade, designed to produce high lift with low drag.","def_ja":"翼やブレードの断面形状で、小さな抗力で大きな揚力を得るよう設計される。","usage_en":"Danh từ đếm được; tiếng Anh-Anh viết aerofoil. Hay đi với: NACA airfoil, symmetric airfoil, airfoil section, chord of the airfoil.","usage_ja":"Hay đi với: NACA翼型, 対称翼型, 翼型の選定. Cũng dùng 翼断面 hoặc katakana エアフォイル.","context_vi":"Dùng trong thiết kế khí động cánh máy bay, cánh quạt, cánh máy nén và cánh tuabin gió.","ex_en":"We selected a thicker airfoil to fit a stronger spar inside.","ex_ja":"内部に強い桁を収めるため、厚い翼型を選定した。","ex_vi":"Chúng tôi chọn biên dạng cánh dày hơn để đặt được dầm cánh khỏe hơn bên trong.","syn_en":["aerofoil (Anh)","wing section"],"syn_ja":["翼断面","エアフォイル"]},{"en":"angle of attack","pos":"noun phrase","ipa":"/ˌæŋɡəl əv əˈtæk/","ja":"迎え角","kana":"むかえかく","romaji":"mukaekaku","vi":"góc tấn","level":2,"def_vi":"Góc giữa dây cung của cánh và hướng dòng không khí tới; tăng góc tấn làm tăng lực nâng đến khi thất tốc.","def_en":"The angle between the wing chord line and the oncoming airflow; increasing it raises lift until stall.","def_ja":"翼弦線と一様流の方向とのなす角で、大きくすると失速まで揚力が増える。","usage_en":"Cụm danh từ đếm được, viết tắt AoA, ký hiệu α. Hay đi với: high angle of attack, critical angle of attack, angle of attack sensor.","usage_ja":"Hay đi với: 迎え角を大きくする, 失速迎え角, 迎え角センサ. Văn bản cũng viết 迎角.","context_vi":"Dùng trong khí động học, thử nghiệm hầm gió, hệ thống cảnh báo thất tốc và thiết kế cánh quạt.","ex_en":"Lift rises almost linearly with angle of attack until about 15 degrees.","ex_ja":"揚力は約15度まで迎え角にほぼ比例して増加する。","ex_vi":"Lực nâng tăng gần như tuyến tính theo góc tấn đến khoảng 15 độ.","syn_en":["AoA","alpha"],"syn_ja":["迎角"]},{"en":"stall","pos":"noun","ipa":"/stɔːl/","ja":"失速","kana":"しっそく","romaji":"shissoku","vi":"thất tốc (mất lực nâng)","level":2,"def_vi":"Hiện tượng dòng khí tách khỏi bề mặt cánh khi góc tấn quá lớn, làm lực nâng giảm đột ngột.","def_en":"A sudden loss of lift when airflow separates from the wing because the angle of attack is too high.","def_ja":"迎え角が大きすぎて翼面から流れがはく離し、揚力が急に低下する現象。","usage_en":"Danh từ đếm được, cũng là động từ (the aircraft stalls). Hay đi với: stall speed, stall warning, recover from a stall, deep stall.","usage_ja":"Hay đi với: 失速速度, 失速警報, 失速から回復する. Dùng 失速する làm động từ; katakana ストール ít dùng.","context_vi":"Dùng trong thiết kế cánh, thử nghiệm bay, đào tạo phi công và phân tích tuabin, máy nén.","ex_en":"The stall warning sounded as the airspeed dropped below 110 knots.","ex_ja":"対気速度が110ノットを下回ると失速警報が鳴った。","ex_vi":"Cảnh báo thất tốc kêu khi tốc độ bay giảm xuống dưới 110 hải lý/giờ.","syn_en":["aerodynamic stall"],"syn_ja":["ストール"]},{"en":"airframe","pos":"noun","ipa":"/ˈɛrˌfreɪm/","ja":"機体","kana":"きたい","romaji":"kitai","vi":"khung thân máy bay (airframe)","level":2,"def_vi":"Toàn bộ kết cấu cơ khí của máy bay gồm thân, cánh, đuôi và càng đáp, không tính động cơ và thiết bị điện tử.","def_en":"The mechanical structure of an aircraft — fuselage, wings, tail and landing gear — excluding engines and avionics.","def_ja":"エンジンや電子機器を除いた、胴体・主翼・尾翼・降着装置などの航空機の構造全体。","usage_en":"Danh từ đếm được. Hay đi với: airframe manufacturer, airframe structure, airframe hours, airframe and powerplant (A&P).","usage_ja":"Hay đi với: 機体構造, 機体メーカ, 機体整備. Phân biệt 機体 (khung thân) với エンジン; katakana エアフレーム ít dùng.","context_vi":"Dùng trong phân chia trách nhiệm giữa hãng chế tạo thân và hãng động cơ, và trong hồ sơ bảo dưỡng.","ex_en":"Composites make up about half of the airframe weight.","ex_ja":"複合材は機体重量の約半分を占める。","ex_vi":"Vật liệu composite chiếm khoảng một nửa khối lượng khung thân máy bay.","syn_en":["aircraft structure"],"syn_ja":["機体構造","エアフレーム"]},{"en":"spar","pos":"noun","ipa":"/spɑːr/","ja":"桁","kana":"けた","romaji":"keta","vi":"dầm cánh (xà dọc cánh)","level":2,"def_vi":"Dầm chịu lực chính chạy dọc theo sải cánh, chịu mô-men uốn và lực cắt do lực nâng gây ra.","def_en":"The main spanwise beam of a wing that carries the bending moment and shear from lift.","def_ja":"翼幅方向に通る主要な梁で、揚力による曲げモーメントとせん断力を受け持つ。","usage_en":"Danh từ đếm được. Hay đi với: front / rear spar, main spar, spar cap, spar web; cũng dùng cho cánh tuabin gió.","usage_ja":"Hay đi với: 前桁, 後桁, 主桁, 桁フランジ. Kỹ sư thiết kế cũng dùng katakana スパー.","context_vi":"Dùng trong thiết kế, phân tích bền và chế tạo kết cấu cánh máy bay và cánh tuabin gió.","ex_en":"Cracks were found near the rear spar attachment fitting.","ex_ja":"後桁の取付金具付近にき裂が見つかった。","ex_vi":"Phát hiện vết nứt gần chi tiết liên kết của dầm cánh sau.","syn_en":["wing spar","main spar"],"syn_ja":["主桁","スパー"]},{"en":"stringer","pos":"noun","ipa":"/ˈstrɪŋər/","ja":"縦通材","kana":"じゅうつうざい","romaji":"juutsuuzai","vi":"thanh tăng cứng dọc (stringer)","level":2,"def_vi":"Thanh định hình mảnh chạy dọc thân hoặc cánh, gắn vào tấm vỏ để chống mất ổn định và truyền tải dọc trục.","def_en":"A slender longitudinal member attached to the skin of a fuselage or wing to resist buckling and carry axial load.","def_ja":"胴体や主翼の外板に沿って取り付けられ、座屈を防ぎ軸力を受け持つ細長い部材。","usage_en":"Danh từ đếm được. Hay đi với: Z-section stringer, hat stringer, stringer pitch, skin-stringer panel.","usage_ja":"Hay đi với: 縦通材ピッチ, 外板と縦通材. Ngoài xưởng hay nói ストリンガー.","context_vi":"Dùng trong thiết kế kết cấu vỏ mỏng có gân tăng cứng của thân, cánh máy bay và thân tàu.","ex_en":"Each stringer is riveted to the skin at 25 mm pitch.","ex_ja":"各縦通材は25 mmピッチで外板にリベット止めされる。","ex_vi":"Mỗi thanh tăng cứng dọc được tán đinh vào tấm vỏ với bước 25 mm.","syn_en":["longeron (nghĩa gần)","stiffener (nghĩa rộng)"],"syn_ja":["ストリンガー","補強材 (nghĩa rộng)"]},{"en":"skin panel","pos":"noun phrase","ipa":"/ˈskɪn ˌpænəl/","ja":"外板","kana":"がいはん","romaji":"gaihan","vi":"tấm vỏ ngoài","level":2,"def_vi":"Tấm kim loại hoặc composite tạo bề mặt ngoài của thân, cánh máy bay, chịu áp suất và lực cắt.","def_en":"A metal or composite sheet forming the outer surface of a fuselage or wing, carrying pressure and shear loads.","def_ja":"胴体や主翼の外表面を構成する金属または複合材の板で、与圧やせん断力を受け持つ。","usage_en":"Cụm danh từ đếm được; nói chung gọi skin (không đếm được). Hay đi với: fuselage skin panel, replace a skin panel, skin thickness.","usage_ja":"Hay đi với: 外板パネル, 外板を交換する, 外板厚. Cũng nói スキン; ngành đóng tàu cũng dùng 外板.","context_vi":"Dùng khi chế tạo, sửa chữa vỏ máy bay, kiểm tra ăn mòn và va đập.","ex_en":"The dented skin panel was replaced during the C-check.","ex_ja":"Cチェックの際、へこんだ外板を交換した。","ex_vi":"Tấm vỏ ngoài bị móp đã được thay trong đợt bảo dưỡng C-check.","syn_en":["skin","outer skin"],"syn_ja":["スキン","外皮"]},{"en":"slat","pos":"noun","ipa":"/slæt/","ja":"スラット","kana":"スラット","romaji":"suratto","vi":"cánh tà trước (slat)","level":2,"def_vi":"Tấm di động ở mép trước cánh, trượt ra tạo khe hở giúp dòng khí bám cánh ở góc tấn lớn, tăng lực nâng khi bay chậm.","def_en":"A movable panel on the wing leading edge that extends to form a slot, delaying stall at high angle of attack.","def_ja":"主翼前縁の可動翼で、前方へ張り出してすき間を作り、大迎え角での失速を遅らせる。","usage_en":"Danh từ đếm được, thường số nhiều: extend / retract the slats, leading-edge slat, slat track. Đi cùng flaps khi cất hạ cánh.","usage_ja":"Hay đi với: 前縁スラット, スラットを展開する, スラットトラック. Thuộc nhóm 高揚力装置 cùng フラップ.","context_vi":"Dùng trong thiết kế thiết bị tăng lực nâng, lắp ráp ray trượt mép trước cánh và quy trình cất hạ cánh.","ex_en":"The slats extend automatically when the flap lever is moved to position 1.","ex_ja":"フラップレバーを1の位置にするとスラットが自動的に展開する。","ex_vi":"Cánh tà trước tự động bung ra khi gạt cần cánh tà sang vị trí 1.","syn_en":["leading-edge slat","high-lift device (nghĩa rộng)"],"syn_ja":["前縁スラット","高揚力装置 (nghĩa rộng)"]},{"en":"type certificate","pos":"noun phrase","ipa":"/ˈtaɪp sərˌtɪfɪkət/","ja":"型式証明","kana":"かたしきしょうめい","romaji":"katashikishoumei","vi":"giấy chứng nhận loại (chứng nhận kiểu loại tàu bay)","level":3,"def_vi":"Chứng chỉ do nhà chức trách hàng không cấp, xác nhận thiết kế một kiểu tàu bay, động cơ hoặc cánh quạt đạt tiêu chuẩn đủ điều kiện bay.","def_en":"A certificate issued by an aviation authority confirming that an aircraft, engine or propeller design meets airworthiness standards.","def_ja":"航空機・エンジン・プロペラの型式設計が耐空性基準に適合することを航空当局が証明するもの。","usage_en":"Cụm danh từ đếm được, viết tắt TC. Hay đi với: obtain / issue a type certificate, type certificate holder, supplemental type certificate (STC).","usage_ja":"Hay đi với: 型式証明を取得する, 型式証明審査, 追加型式設計承認. Viết tắt TC.","context_vi":"Dùng trong phát triển máy bay mới, chương trình thử nghiệm bay chứng nhận và cải tiến thiết kế sau khai thác.","ex_en":"The regional jet received its type certificate after 3,000 hours of flight testing.","ex_ja":"そのリージョナルジェットは3,000時間の飛行試験を経て型式証明を取得した。","ex_vi":"Máy bay phản lực khu vực đã nhận giấy chứng nhận loại sau 3.000 giờ bay thử.","syn_en":["TC","STC (chứng nhận bổ sung, liên quan)"],"syn_ja":["TC","耐空証明 (liên quan)"]},{"en":"specific impulse","pos":"noun phrase","ipa":"/spəˌsɪfɪk ˈɪmpʌls/","ja":"比推力","kana":"ひすいりょく","romaji":"hisuiryoku","vi":"xung lượng riêng (xung riêng)","level":3,"def_vi":"Chỉ số hiệu quả của động cơ tên lửa, bằng lực đẩy chia cho lưu lượng trọng lượng nhiên liệu tiêu thụ, đơn vị giây.","def_en":"A measure of rocket engine efficiency: thrust divided by propellant weight flow rate, expressed in seconds.","def_ja":"推力を推進剤の重量流量で割ったロケットエンジンの効率指標で、単位は秒。","usage_en":"Cụm danh từ không đếm được, viết tắt Isp. Hay đi với: vacuum specific impulse, high specific impulse, an Isp of 450 s.","usage_ja":"Hay đi với: 比推力が高い, 真空中比推力. Thường viết ký hiệu Isp.","context_vi":"Dùng khi so sánh nhiên liệu, động cơ tên lửa và động cơ đẩy điện của vệ tinh.","ex_en":"Liquid hydrogen engines offer a specific impulse of about 450 seconds.","ex_ja":"液体水素エンジンの比推力は約450秒である。","ex_vi":"Động cơ dùng hydro lỏng có xung lượng riêng khoảng 450 giây.","syn_en":["Isp"],"syn_ja":["Isp"]},{"en":"airworthiness","pos":"noun","ipa":"/ˈɛrˌwɜːrðinəs/","ja":"耐空性","kana":"たいくうせい","romaji":"taikuusei","vi":"tính đủ điều kiện bay","level":3,"def_vi":"Tình trạng máy bay hoặc linh kiện phù hợp thiết kế đã được phê chuẩn và đảm bảo khai thác an toàn.","def_en":"The condition of an aircraft or part conforming to its approved design and being safe to operate.","def_ja":"航空機や部品が承認された設計に適合し、安全に運航できる状態にあること。","usage_en":"Danh từ không đếm được. Hay đi với: certificate of airworthiness, airworthiness directive (AD), continuing airworthiness; tính từ: airworthy.","usage_ja":"Hay đi với: 耐空証明, 耐空性改善通報 (TCD/AD), 耐空性審査要領. Dùng trong văn bản pháp quy hàng không.","context_vi":"Dùng trong chứng nhận loại máy bay, hồ sơ bảo dưỡng và quy định của cơ quan hàng không như FAA, EASA, JCAB.","ex_en":"The repair must be approved before the aircraft's airworthiness can be restored.","ex_ja":"機体の耐空性を回復するには、その修理が承認されなければならない。","ex_vi":"Sửa chữa phải được phê duyệt trước khi khôi phục tính đủ điều kiện bay của máy bay.","syn_en":["flightworthiness (ít dùng)","airworthy (tính từ, liên quan)"],"syn_ja":["耐空証明 (liên quan)"]},{"en":"fly-by-wire","pos":"noun","ipa":"/ˌflaɪ baɪ ˈwaɪər/","ja":"フライバイワイヤ","kana":"フライバイワイヤ","romaji":"furaibaiwaiya","vi":"điều khiển bay bằng tín hiệu điện (fly-by-wire)","level":3,"def_vi":"Hệ thống điều khiển bay trong đó lệnh của phi công được máy tính xử lý và truyền bằng tín hiệu điện đến cơ cấu chấp hành.","def_en":"A flight control system in which pilot inputs are processed by computers and sent electrically to actuators.","def_ja":"操縦士の操作をコンピュータで処理し、電気信号でアクチュエータへ伝える操縦方式。","usage_en":"Danh từ không đếm được, cũng làm tính từ (a fly-by-wire aircraft); viết tắt FBW. Hay đi với: fly-by-wire system, digital fly-by-wire.","usage_ja":"Hay đi với: フライバイワイヤ方式, デジタルフライバイワイヤ. Viết tắt FBW; tiếng Hán ít dùng.","context_vi":"Dùng trong thiết kế hệ thống điều khiển bay hiện đại, phân tích độ tin cậy dự phòng và chứng nhận phần mềm.","ex_en":"Fly-by-wire replaced the heavy cables and pulleys of earlier designs.","ex_ja":"フライバイワイヤにより、従来の重いケーブルやプーリが不要になった。","ex_vi":"Điều khiển bay bằng tín hiệu điện đã thay thế dây cáp và puly nặng nề của thiết kế cũ.","syn_en":["FBW"],"syn_ja":["FBW","電気式操縦システム"]},{"en":"flutter","pos":"noun","ipa":"/ˈflʌtər/","ja":"フラッター","kana":"フラッター","romaji":"furattaa","vi":"rung đập khí đàn hồi (flutter)","level":3,"def_vi":"Dao động tự kích mất ổn định do tương tác giữa lực khí động, lực đàn hồi và quán tính của kết cấu, có thể phá hủy cánh.","def_en":"A self-excited, unstable oscillation caused by interaction of aerodynamic, elastic and inertial forces, potentially destroying a structure.","def_ja":"空気力・弾性力・慣性力の連成で生じる自励的な不安定振動で、構造破壊を招くことがある。","usage_en":"Danh từ không đếm được. Hay đi với: flutter speed, flutter margin, flutter analysis, flutter test; cũng là động từ thường (rung phần phật).","usage_ja":"Hay đi với: フラッター速度, フラッター解析, フラッター試験. Thuộc lĩnh vực 空力弾性.","context_vi":"Dùng trong phân tích khí đàn hồi, chứng nhận máy bay, thiết kế cầu dây văng và cánh tuabin gió.","ex_en":"Flutter analysis showed a 15 percent margin above the design dive speed.","ex_ja":"フラッター解析により、設計急降下速度に対して15%の余裕があることを確認した。","ex_vi":"Phân tích rung đập khí đàn hồi cho thấy biên an toàn 15% trên tốc độ bổ nhào thiết kế.","syn_en":["aeroelastic flutter"],"syn_ja":["空力弾性振動 (nghĩa rộng)"]},{"en":"lift-to-drag ratio","pos":"noun phrase","ipa":"/ˌlɪft tə ˈdræɡ ˌreɪʃioʊ/","ja":"揚抗比","kana":"ようこうひ","romaji":"youkouhi","vi":"tỉ số lực nâng trên lực cản (L/D)","level":3,"def_vi":"Tỉ số giữa lực nâng và lực cản của cánh hoặc cả máy bay, thể hiện hiệu quả khí động học.","def_en":"The ratio of lift to drag of a wing or aircraft, indicating aerodynamic efficiency.","def_ja":"翼や機体の揚力と抗力の比で、空力的な効率を表す。","usage_en":"Cụm danh từ đếm được, viết tắt L/D. Hay đi với: maximum lift-to-drag ratio, improve the lift-to-drag ratio; với tàu lượn gần nghĩa glide ratio.","usage_ja":"Hay đi với: 最大揚抗比, 揚抗比を向上させる. Cũng viết L/D.","context_vi":"Dùng trong thiết kế khí động, so sánh cấu hình cánh và tính tầm bay của máy bay.","ex_en":"The new wing raised the cruise lift-to-drag ratio from 17 to 19.","ex_ja":"新しい主翼により巡航時の揚抗比が17から19に向上した。","ex_vi":"Cánh mới nâng tỉ số lực nâng trên lực cản khi bay hành trình từ 17 lên 19.","syn_en":["L/D","glide ratio (nghĩa gần)"],"syn_ja":["L/D","滑空比 (nghĩa gần)"]}]},{"id":93,"words":[{"en":"rail","pos":"noun","ipa":"/reɪl/","ja":"レール","kana":"レール","romaji":"reeru","vi":"ray","level":1,"def_vi":"Thanh thép cán có tiết diện hình chữ I đặc biệt, đặt thành hai đường song song để dẫn hướng và đỡ bánh xe lửa.","def_en":"A rolled steel bar of special I-shaped section, laid in pairs to support and guide train wheels.","def_ja":"特殊なI形断面をもつ圧延鋼材で、2本平行に敷設して車輪を支持・案内する。","usage_en":"Danh từ đếm được. Hay đi với: rail head, rail web, rail foot, 60 kg rail, lay / replace rails; 'by rail' nghĩa là bằng đường sắt.","usage_ja":"Hay đi với: 50kgNレール, レール頭部, レール交換, レールを敷設する. Chỉ dùng katakana.","context_vi":"Dùng trong thi công, bảo trì đường sắt, cán thép ray và tính toán tải trọng bánh xe lên ray.","ex_en":"The worn rail on the curve was replaced during the night possession.","ex_ja":"曲線区間の摩耗したレールを夜間作業で交換した。","ex_vi":"Đoạn ray bị mòn ở đường cong đã được thay trong ca phong tỏa ban đêm.","syn_en":["running rail","railroad rail (Mỹ)"],"syn_ja":["軌条 (văn bản cũ)"]},{"en":"sleeper","pos":"noun","ipa":"/ˈsliːpər/","ja":"枕木","kana":"まくらぎ","romaji":"makuragi","vi":"tà vẹt","level":1,"def_vi":"Thanh bê tông, gỗ hoặc thép đặt ngang dưới ray để giữ khoảng cách ray và truyền tải xuống lớp đá ba-lát.","def_en":"A concrete, timber or steel beam laid across under the rails to hold gauge and spread load to the ballast.","def_ja":"レールの下に直角に敷き、軌間を保ち荷重を道床に分散させるコンクリート・木・鋼製の部材。","usage_en":"Danh từ đếm được; tiếng Anh-Anh là sleeper, tiếng Anh-Mỹ là tie hoặc crosstie. Hay đi với: concrete sleeper, sleeper spacing.","usage_ja":"Hay đi với: PCまくらぎ, まくらぎ間隔, まくらぎ交換. Văn bản chuyên ngành thường viết hiragana まくらぎ.","context_vi":"Dùng trong thiết kế kết cấu tầng trên đường sắt, thi công và thay thế tà vẹt.","ex_en":"Prestressed concrete sleepers are laid at 600 mm spacing.","ex_ja":"PC枕木を600 mm間隔で敷設する。","ex_vi":"Tà vẹt bê tông dự ứng lực được đặt với khoảng cách 600 mm.","syn_en":["railroad tie (Mỹ)","crosstie (Mỹ)"],"syn_ja":["まくらぎ","PCまくらぎ (loại bê tông)"]},{"en":"track","pos":"noun","ipa":"/træk/","ja":"線路","kana":"せんろ","romaji":"senro","vi":"đường ray (tuyến đường sắt)","level":1,"def_vi":"Toàn bộ kết cấu gồm ray, tà vẹt, phụ kiện liên kết và lớp ba-lát trên đó đoàn tàu chạy.","def_en":"The complete structure of rails, sleepers, fastenings and ballast on which trains run.","def_ja":"レール・まくらぎ・締結装置・道床からなり、列車が走行する構造全体。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: double track, track maintenance, track work, lay track; railway track (Anh), railroad track (Mỹ).","usage_ja":"Hay đi với: 線路内立入禁止, 複線, 線路保守. Thuật ngữ kỹ thuật là 軌道; 線路 dùng hằng ngày và trong quy định an toàn.","context_vi":"Dùng trong thi công, bảo trì đường sắt và quy định an toàn khi làm việc gần đường chạy tàu.","ex_en":"Workers must leave the track at least five minutes before a train passes.","ex_ja":"作業員は列車通過の5分前までに線路から退避しなければならない。","ex_vi":"Công nhân phải rời khỏi đường ray ít nhất năm phút trước khi tàu đi qua.","syn_en":["railway track (Anh)","permanent way (Anh)"],"syn_ja":["軌道"]},{"en":"locomotive","pos":"noun","ipa":"/ˌloʊkəˈmoʊtɪv/","ja":"機関車","kana":"きかんしゃ","romaji":"kikansha","vi":"đầu máy","level":1,"def_vi":"Phương tiện đường sắt có động lực, không chở khách hay hàng, dùng để kéo hoặc đẩy các toa xe.","def_en":"A powered rail vehicle that carries no passengers or freight and is used to haul or push trains.","def_ja":"旅客や貨物を載せず、客車や貨車をけん引・推進する動力付きの鉄道車両。","usage_en":"Danh từ đếm được; khẩu ngữ: loco. Hay đi với: diesel / electric locomotive, steam locomotive, locomotive depot.","usage_ja":"Hay đi với: 電気機関車, ディーゼル機関車, 蒸気機関車. Khẩu ngữ: 機関車 viết tắt EL / DL / SL.","context_vi":"Dùng trong vận tải hàng hóa, khai thác tàu kéo toa và xưởng sửa chữa đầu máy.","ex_en":"Two diesel locomotives haul the 40-wagon freight train.","ex_ja":"2両のディーゼル機関車が40両編成の貨物列車をけん引する。","ex_vi":"Hai đầu máy diesel kéo đoàn tàu hàng 40 toa.","syn_en":["engine (khẩu ngữ)","loco (khẩu ngữ)"],"syn_ja":["EL / DL (viết tắt theo loại)"]},{"en":"freight car","pos":"noun phrase","ipa":"/ˈfreɪt ˌkɑːr/","ja":"貨車","kana":"かしゃ","romaji":"kasha","vi":"toa hàng","level":1,"def_vi":"Toa xe đường sắt không có động lực dùng để chở hàng hóa như container, than, xăng dầu, ngũ cốc.","def_en":"An unpowered railway vehicle used to carry goods such as containers, coal, fuel or grain.","def_ja":"コンテナ・石炭・燃料・穀物などの貨物を運ぶ動力のない鉄道車両。","usage_en":"Cụm danh từ đếm được (Mỹ); tiếng Anh-Anh hay nói wagon hoặc goods wagon. Hay đi với: tank car, flat car, hopper car.","usage_ja":"Hay đi với: コンテナ貨車, タンク貨車, 有蓋貨車. Không dùng katakana.","context_vi":"Dùng trong vận tải hàng hóa đường sắt, xếp dỡ ở ga hàng và bảo dưỡng toa xe.","ex_en":"Each freight car is weighed before leaving the yard.","ex_ja":"各貨車は操車場を出る前に計量される。","ex_vi":"Mỗi toa hàng được cân trước khi rời bãi dồn tàu.","syn_en":["wagon (Anh)","goods wagon (Anh)"],"syn_ja":["貨物車"]},{"en":"passenger coach","pos":"noun phrase","ipa":"/ˈpæsəndʒər ˌkoʊtʃ/","ja":"客車","kana":"きゃくしゃ","romaji":"kyakusha","vi":"toa khách","level":1,"def_vi":"Toa xe đường sắt chở hành khách, thường không có động lực và được đầu máy kéo.","def_en":"A railway vehicle for passengers, usually unpowered and hauled by a locomotive.","def_ja":"旅客を乗せる鉄道車両で、通常は動力を持たず機関車にけん引される。","usage_en":"Cụm danh từ đếm được; tiếng Anh-Mỹ hay nói passenger car. Hay đi với: sleeper coach, coach interior, coupled coaches.","usage_ja":"Hay đi với: 寝台客車, 客車列車. Ở Nhật, toa khách có động cơ gọi là 電車 hoặc 気動車, không gọi 客車.","context_vi":"Dùng trong khai thác tàu khách kéo bằng đầu máy, đóng mới và cải tạo nội thất toa xe.","ex_en":"The train consists of one locomotive and twelve passenger coaches.","ex_ja":"この列車は機関車1両と客車12両で編成されている。","ex_vi":"Đoàn tàu gồm một đầu máy và mười hai toa khách.","syn_en":["passenger car (Mỹ)","carriage (Anh)"],"syn_ja":["旅客車 (nghĩa rộng)"]},{"en":"bogie","pos":"noun","ipa":"/ˈboʊɡi/","ja":"台車","kana":"だいしゃ","romaji":"daisha","vi":"giá chuyển hướng (bogie)","level":1,"def_vi":"Cụm khung mang hai hoặc ba trục bánh xe kèm lò xo, giảm chấn, quay được dưới thân toa để xe qua đường cong.","def_en":"A frame carrying two or more wheelsets with suspension, pivoting under the car body so the vehicle can negotiate curves.","def_ja":"2軸以上の輪軸とばね装置を備え、車体の下で旋回して曲線通過を可能にする走行装置。","usage_en":"Danh từ đếm được (Anh); tiếng Anh-Mỹ gọi truck. Hay đi với: bogie frame, motor bogie, trailer bogie, bolsterless bogie.","usage_ja":"Hay đi với: 台車枠, 動力台車, 付随台車, ボルスタレス台車. Ngoài xưởng có thể gọi ボギー.","context_vi":"Dùng trong thiết kế, chế tạo và bảo dưỡng toa xe, đầu máy, tàu điện.","ex_en":"The bogie frame was inspected for cracks after 1.2 million km.","ex_ja":"走行120万kmの後、台車枠のき裂を検査した。","ex_vi":"Khung giá chuyển hướng được kiểm tra vết nứt sau 1,2 triệu km.","syn_en":["truck (Mỹ)"],"syn_ja":["ボギー台車","ボギー (khẩu ngữ)"]},{"en":"wheelset","pos":"noun","ipa":"/ˈwiːlˌsɛt/","ja":"輪軸","kana":"りんじく","romaji":"rinjiku","vi":"bộ trục bánh xe","level":1,"def_vi":"Cụm gồm một trục và hai bánh xe ép chặt lên trục, quay cùng nhau trên ray.","def_en":"An assembly of one axle with two wheels press-fitted onto it, rotating together on the rails.","def_ja":"1本の車軸に2枚の車輪を圧入し、一体で回転する組立品。","usage_en":"Danh từ đếm được, viết liền. Hay đi với: wheelset maintenance, wheelset lathe, change a wheelset, wheelset back-to-back distance.","usage_ja":"Hay đi với: 輪軸の圧入, 輪軸交換, 車輪旋盤. Không dùng katakana.","context_vi":"Dùng trong xưởng toa xe khi ép bánh, tiện lại mặt lăn và kiểm tra siêu âm trục.","ex_en":"Each wheelset is ultrasonically tested before reuse.","ex_ja":"各輪軸は再使用の前に超音波探傷検査を受ける。","ex_vi":"Mỗi bộ trục bánh xe được kiểm tra siêu âm trước khi dùng lại.","syn_en":["wheel set","wheel and axle assembly"],"syn_ja":["車輪と車軸 (liên quan)"]},{"en":"coupler","pos":"noun","ipa":"/ˈkʌplər/","ja":"連結器","kana":"れんけつき","romaji":"renketsuki","vi":"móc nối (đầu đấm móc nối)","level":1,"def_vi":"Thiết bị ở hai đầu toa xe dùng để nối các toa với nhau và truyền lực kéo, lực đẩy.","def_en":"A device at each end of a rail vehicle that joins vehicles together and transmits traction and buffing forces.","def_ja":"車両の両端にあり、車両同士をつないで引張力と圧縮力を伝える装置。","usage_en":"Danh từ đếm được (Mỹ); tiếng Anh-Anh hay nói coupling. Hay đi với: automatic coupler, knuckle coupler, tightlock coupler, draft gear.","usage_ja":"Hay đi với: 自動連結器, 密着連結器, 連結器を連結する/解放する. Không dùng katakana.","context_vi":"Dùng trong lắp ráp, bảo dưỡng toa xe, dồn tàu và phân tích lực dọc đoàn tàu.","ex_en":"The automatic coupler locks as soon as the two cars touch.","ex_ja":"2両が接触するとすぐに自動連結器がロックされる。","ex_vi":"Móc nối tự động khóa lại ngay khi hai toa chạm nhau.","syn_en":["coupling (Anh)"],"syn_ja":["カプラー (ít dùng)"]},{"en":"pantograph","pos":"noun","ipa":"/ˈpæntəˌɡræf/","ja":"パンタグラフ","kana":"パンタグラフ","romaji":"pantagurafu","vi":"cần lấy điện (pantograph)","level":1,"def_vi":"Cơ cấu khung gập lắp trên nóc tàu điện, tì lên dây tiếp xúc trên cao để lấy điện cho tàu.","def_en":"A folding frame on the roof of an electric train that presses against the overhead wire to collect current.","def_ja":"電車の屋根に取り付けた折りたたみ式の装置で、架線に押し付けて集電する。","usage_en":"Danh từ đếm được. Hay đi với: raise / lower the pantograph, pantograph contact strip, single-arm pantograph.","usage_ja":"Hay đi với: パンタグラフを上げる/下げる, シングルアームパンタグラフ, すり板. Khẩu ngữ: パンタ.","context_vi":"Dùng trong khai thác và bảo dưỡng tàu điện, kiểm tra tấm trượt than và tương tác cần lấy điện với dây tiếp xúc.","ex_en":"The driver lowered the pantograph before entering the unwired siding.","ex_ja":"運転士は架線のない側線に入る前にパンタグラフを下げた。","ex_vi":"Lái tàu hạ cần lấy điện trước khi vào đường nhánh không có dây điện.","syn_en":["current collector (nghĩa rộng)"],"syn_ja":["パンタ (khẩu ngữ)","集電装置 (nghĩa rộng)"]},{"en":"track gauge","pos":"noun phrase","ipa":"/ˈtræk ˌɡeɪdʒ/","ja":"軌間","kana":"きかん","romaji":"kikan","vi":"khổ đường","level":2,"def_vi":"Khoảng cách giữa mép trong hai thanh ray đo ở vị trí quy định dưới mặt đỉnh ray, ví dụ 1.435 mm hoặc 1.000 mm.","def_en":"The distance between the inner faces of the two rails, measured a set distance below the railhead, e.g. 1,435 mm.","def_ja":"左右のレール頭部内側面間の距離で、1,435 mmや1,067 mmなどがある。","usage_en":"Cụm danh từ đếm được; nói gọn gauge (Mỹ có thể viết gage). Hay đi với: standard gauge, narrow gauge, metre gauge, gauge widening.","usage_ja":"Hay đi với: 標準軌, 狭軌, 軌間変動. Ngoài đời hay nói ゲージ.","context_vi":"Dùng khi thiết kế tuyến đường sắt, chọn giá chuyển hướng và đo kiểm hình học đường.","ex_en":"Vietnam's main line uses a metre track gauge.","ex_ja":"ベトナムの幹線は1,000 mmの軌間を採用している。","ex_vi":"Tuyến đường sắt chính của Việt Nam dùng khổ đường 1 mét.","syn_en":["gauge","rail gauge"],"syn_ja":["ゲージ"]},{"en":"ballast","pos":"noun","ipa":"/ˈbæləst/","ja":"バラスト","kana":"バラスト","romaji":"barasuto","vi":"đá ba-lát (đá dăm lót đường)","level":2,"def_vi":"Lớp đá dăm cứng rải dưới và quanh tà vẹt để phân bố tải, giữ ổn định ray và thoát nước.","def_en":"A layer of crushed hard stone under and around the sleepers that spreads load, holds the track and drains water.","def_ja":"まくらぎの下や周囲に敷く砕石の層で、荷重を分散し軌道を保持し排水する。","usage_en":"Danh từ không đếm được. Hay đi với: ballast bed, ballast tamping, ballast cleaning, ballasted track (ngược lại slab track).","usage_ja":"Hay đi với: バラスト軌道, バラストつき固め, 道床バラスト. Thuật ngữ chuẩn của lớp này là 道床.","context_vi":"Dùng trong thi công, bảo trì đường sắt, chèn đá bằng máy và làm sạch đá ba-lát.","ex_en":"The tamping machine compacts the ballast under each sleeper.","ex_ja":"マルチプルタイタンパが各まくらぎ下のバラストをつき固める。","ex_vi":"Máy chèn đá đầm chặt lớp đá ba-lát dưới từng tà vẹt.","syn_en":["track ballast","trackbed (nghĩa rộng)"],"syn_ja":["道床","砕石"]},{"en":"turnout","pos":"noun","ipa":"/ˈtɜːrnˌaʊt/","ja":"分岐器","kana":"ぶんきき","romaji":"bunkiki","vi":"ghi (bộ ghi rẽ)","level":2,"def_vi":"Kết cấu đường sắt gồm lưỡi ghi, tâm ghi và ray hộ bánh, cho phép tàu chuyển từ đường này sang đường khác.","def_en":"A track assembly of switch blades, crossing and check rails that lets trains move from one track to another.","def_ja":"トングレール・クロッシング・ガードレールなどからなり、列車を別の線路へ導く軌道構造。","usage_en":"Danh từ đếm được. Tiếng Anh-Anh hay nói points hoặc switch (Mỹ). Hay đi với: turnout number, No. 12 turnout, high-speed turnout.","usage_ja":"Hay đi với: 12番分岐器, 分岐器の転換, 高速分岐器. Ngoài hiện trường gọi ポイント.","context_vi":"Dùng trong thiết kế ga, bảo trì đường sắt và hệ thống tín hiệu liên khóa.","ex_en":"A No. 16 turnout allows trains to take the diverging route at 70 km/h.","ex_ja":"16番分岐器では分岐側を時速70 kmで通過できる。","ex_vi":"Bộ ghi số 16 cho phép tàu rẽ nhánh với tốc độ 70 km/h.","syn_en":["switch (Mỹ)","points (Anh)"],"syn_ja":["ポイント"]},{"en":"wheel flange","pos":"noun phrase","ipa":"/ˈwiːl ˌflændʒ/","ja":"車輪フランジ","kana":"しゃりんフランジ","romaji":"sharinfuranji","vi":"gờ bánh xe (lợi bánh)","level":2,"def_vi":"Gờ nhô ra ở mép trong bánh xe lửa giúp giữ bánh không trượt khỏi ray, nhất là khi qua đường cong.","def_en":"The projecting rim on the inner side of a railway wheel that keeps the wheel on the rail, especially in curves.","def_ja":"鉄道車輪の内側に張り出した縁で、特に曲線で車輪がレールから外れるのを防ぐ。","usage_en":"Cụm danh từ đếm được; nói gọn flange. Hay đi với: flange wear, flange climb, flange lubrication, flange height.","usage_ja":"Hay đi với: フランジ摩耗, フランジ乗り上がり, フランジ塗油. Ngoài xưởng nói gọn フランジ.","context_vi":"Dùng khi đo mòn bánh xe, phân tích trật bánh và bôi trơn ray ở đường cong.","ex_en":"Heavy wheel flange wear was found on the leading axle.","ex_ja":"先頭軸の車輪フランジに大きな摩耗が見つかった。","ex_vi":"Phát hiện gờ bánh xe ở trục dẫn đầu bị mòn nhiều.","syn_en":["flange"],"syn_ja":["フランジ"]},{"en":"axle box","pos":"noun phrase","ipa":"/ˈæksəl ˌbɑːks/","ja":"軸箱","kana":"じくばこ","romaji":"jikubako","vi":"hộp trục (hộp đầu trục)","level":2,"def_vi":"Hộp chứa ổ lăn ở hai đầu trục bánh xe, truyền tải từ giá chuyển hướng xuống trục.","def_en":"The housing at each end of an axle that holds the bearing and transfers load from the bogie to the wheelset.","def_ja":"車軸の両端で軸受を収め、台車から輪軸へ荷重を伝える箱状の部品。","usage_en":"Cụm danh từ đếm được; Mỹ hay nói journal box. Hay đi với: axle box bearing, axle box temperature, hot axle box detector.","usage_ja":"Hay đi với: 軸箱支持装置, 軸箱温度, 軸箱軸受. Không dùng katakana.","context_vi":"Dùng trong thiết kế giá chuyển hướng, bảo dưỡng ổ trục và giám sát nhiệt độ ổ trục dọc tuyến.","ex_en":"The detector flagged an overheated axle box on the third car.","ex_ja":"検知装置が3両目の軸箱の過熱を検出した。","ex_vi":"Thiết bị phát hiện báo hộp trục của toa thứ ba bị quá nhiệt.","syn_en":["journal box (Mỹ)","axlebox"],"syn_ja":["ジャーナルボックス (ít dùng)"]},{"en":"rail fastening","pos":"noun phrase","ipa":"/ˈreɪl ˌfæsənɪŋ/","ja":"レール締結装置","kana":"レールていけつそうち","romaji":"reeruteiketsusouchi","vi":"phụ kiện liên kết ray (cóc ray)","level":2,"def_vi":"Bộ phụ kiện gồm kẹp đàn hồi, đệm và bu lông giữ ray cố định trên tà vẹt, chống xô ray và giảm rung.","def_en":"The clips, pads and bolts that hold the rail to the sleeper, resisting rail creep and damping vibration.","def_ja":"レールをまくらぎに固定する板ばね・軌道パッド・ボルトなどからなる装置で、ふく進を防ぎ振動を減らす。","usage_en":"Cụm danh từ đếm được, thường số nhiều: rail fastenings. Hay đi với: elastic rail clip, rail pad, fastening system, tighten the fastenings.","usage_ja":"Hay đi với: 締結装置の緩み, 軌道パッド, 板ばね. Ngoài hiện trường nói gọn 締結 hoặc 締結具.","context_vi":"Dùng trong thi công đặt ray, bảo trì kiểm tra cóc ray lỏng và thiết kế đường giảm chấn.","ex_en":"Loose rail fastenings were found on the bridge approach.","ex_ja":"橋りょう取付部でレール締結装置の緩みが見つかった。","ex_vi":"Phát hiện phụ kiện liên kết ray bị lỏng ở đoạn đầu cầu.","syn_en":["fastening system","rail clip (nghĩa hẹp)"],"syn_ja":["締結装置","締結具"]},{"en":"overhead contact line","pos":"noun phrase","ipa":"/ˌoʊvərˌhɛd ˈkɑːntækt ˌlaɪn/","ja":"架線","kana":"かせん","romaji":"kasen","vi":"dây tiếp xúc trên cao (lưới điện kéo)","level":2,"def_vi":"Hệ thống dây dẫn treo phía trên đường ray cấp điện cho tàu điện qua cần lấy điện.","def_en":"The system of wires suspended above the track that supplies power to electric trains through the pantograph.","def_ja":"線路の上方に張られ、パンタグラフを通じて電車に電力を供給する電線。","usage_en":"Cụm danh từ đếm được, viết tắt OCL; Mỹ hay nói catenary hoặc overhead wire. Hay đi với: contact wire, messenger wire, OCL voltage.","usage_ja":"Hay đi với: 架線電圧, 架線断線, き電線, トロリ線. Văn bản chuẩn: 電車線; hiện trường dùng 架線.","context_vi":"Dùng trong điện khí hóa đường sắt, bảo trì cấp điện kéo và an toàn khi làm việc gần đường dây.","ex_en":"The overhead contact line is energized at 25 kV AC.","ex_ja":"この架線には交流25 kVが印加されている。","ex_vi":"Dây tiếp xúc trên cao được cấp điện xoay chiều 25 kV.","syn_en":["catenary (Mỹ)","overhead wire"],"syn_ja":["電車線","トロリ線 (dây tiếp xúc, nghĩa hẹp)"]},{"en":"electric multiple unit","pos":"noun phrase","ipa":"/ɪˌlɛktrɪk ˌmʌltəpəl ˈjuːnɪt/","ja":"電車","kana":"でんしゃ","romaji":"densha","vi":"đoàn tàu điện phân tán động lực (EMU)","level":2,"def_vi":"Đoàn tàu gồm nhiều toa, trong đó một số toa có mô-tơ kéo riêng, chạy bằng điện mà không cần đầu máy.","def_en":"A train of several cars, some with their own traction motors, powered by electricity without a separate locomotive.","def_ja":"一部または全部の車両に主電動機を備え、機関車なしで電気により走る編成列車。","usage_en":"Cụm danh từ đếm được, hầu như luôn viết tắt EMU. Hay đi với: an eight-car EMU, EMU depot; tàu diesel tương tự là DMU.","usage_ja":"Hay đi với: 通勤電車, 電車の編成, 電動車 / 付随車. Trong tiếng Nhật 電車 dùng hằng ngày cho mọi tàu điện; EMU dùng trong tài liệu quốc tế.","context_vi":"Dùng trong đường sắt đô thị, tàu cao tốc, metro và khi so sánh với tàu kéo bằng đầu máy.","ex_en":"The metro line operates six-car electric multiple units every three minutes.","ex_ja":"この地下鉄路線では6両編成の電車が3分間隔で運行している。","ex_vi":"Tuyến metro này chạy đoàn tàu điện 6 toa cứ ba phút một chuyến.","syn_en":["EMU"],"syn_ja":["EMU","電動車両 (nghĩa gần)"]},{"en":"traction motor","pos":"noun phrase","ipa":"/ˈtrækʃən ˌmoʊtər/","ja":"主電動機","kana":"しゅでんどうき","romaji":"shudendouki","vi":"động cơ điện kéo","level":2,"def_vi":"Mô-tơ điện công suất lớn lắp trên giá chuyển hướng để quay trục bánh xe, tạo lực kéo cho tàu.","def_en":"A high-power electric motor mounted on the bogie that drives the wheelsets to propel the train.","def_ja":"台車に装架され、輪軸を駆動して列車を走らせる大出力の電動機。","usage_en":"Cụm danh từ đếm được. Hay đi với: induction traction motor, traction motor cooling, traction motor bearing; cũng dùng cho xe điện, xe nâng.","usage_ja":"Hay đi với: 主電動機出力, 誘導主電動機, 主電動機の冷却. Ngoài ngành đường sắt gọi 駆動用モータ.","context_vi":"Dùng trong thiết kế hệ thống kéo, bảo dưỡng tàu điện và đầu máy điện.","ex_en":"Each motor car has four 190 kW traction motors.","ex_ja":"各電動車には190 kWの主電動機が4台搭載されている。","ex_vi":"Mỗi toa động lực có bốn động cơ điện kéo 190 kW.","syn_en":["drive motor (nghĩa rộng)"],"syn_ja":["トラクションモータ","駆動用モータ (nghĩa rộng)"]},{"en":"rolling stock","pos":"noun phrase","ipa":"/ˈroʊlɪŋ ˌstɑːk/","ja":"鉄道車両","kana":"てつどうしゃりょう","romaji":"tetsudousharyou","vi":"phương tiện giao thông đường sắt (đầu máy, toa xe)","level":2,"def_vi":"Tên gọi chung mọi phương tiện chạy trên ray như đầu máy, toa khách, toa hàng, tàu điện.","def_en":"The collective term for all vehicles that run on rails, including locomotives, coaches, wagons and multiple units.","def_ja":"機関車・客車・貨車・電車など、レール上を走る車両の総称。","usage_en":"Cụm danh từ không đếm được, không có số nhiều (không nói 'rolling stocks'). Hay đi với: rolling stock manufacturer, rolling stock maintenance.","usage_ja":"Hay đi với: 鉄道車両メーカ, 鉄道車両の保守. Trong ngành thường nói gọn 車両.","context_vi":"Dùng trong mua sắm, hợp đồng, chế tạo và quản lý đội xe của công ty đường sắt.","ex_en":"The operator ordered new rolling stock for the airport line.","ex_ja":"事業者は空港線向けに新しい鉄道車両を発注した。","ex_vi":"Đơn vị khai thác đã đặt mua phương tiện đường sắt mới cho tuyến sân bay.","syn_en":["railway vehicles"],"syn_ja":["車両 (khẩu ngữ)"]},{"en":"cant","pos":"noun","ipa":"/kænt/","ja":"カント","kana":"カント","romaji":"kanto","vi":"siêu cao (độ nâng ray ngoài)","level":2,"def_vi":"Chênh lệch chiều cao giữa ray ngoài và ray trong ở đường cong, giúp cân bằng lực ly tâm khi tàu chạy.","def_en":"The height difference between the outer and inner rails on a curve, used to counter centrifugal force.","def_ja":"曲線で外側レールを内側より高くした高低差で、遠心力を打ち消すために設ける。","usage_en":"Danh từ không đếm được (Anh); Mỹ và ngành đường bộ gọi superelevation. Hay đi với: applied cant, cant of 150 mm, cant gradient.","usage_ja":"Hay đi với: カント量, 設定カント, カント逓減. Chỉ dùng katakana trong đường sắt.","context_vi":"Dùng trong thiết kế tuyến cong, đo kiểm hình học đường và xác định tốc độ cho phép qua đường cong.","ex_en":"The curve has a cant of 105 mm for a design speed of 100 km/h.","ex_ja":"この曲線には設計速度100 km/hに対して105 mmのカントが設けられている。","ex_vi":"Đường cong có siêu cao 105 mm cho tốc độ thiết kế 100 km/h.","syn_en":["superelevation (Mỹ)"],"syn_ja":["片勾配 (đường bộ, liên quan)"]},{"en":"continuous welded rail","pos":"noun phrase","ipa":"/kənˌtɪnjuəs ˌwɛldɪd ˈreɪl/","ja":"ロングレール","kana":"ロングレール","romaji":"rongureeru","vi":"ray hàn liền (ray dài)","level":2,"def_vi":"Ray được hàn nối thành đoạn rất dài, loại bỏ mối nối để tàu chạy êm và giảm bảo trì.","def_en":"Rail welded into very long lengths without joints, giving a smoother ride and lower maintenance.","def_ja":"継目をなくすため溶接して非常に長くしたレールで、乗り心地が良く保守が少ない。","usage_en":"Cụm danh từ không đếm được, viết tắt CWR. Hay đi với: CWR track, stress-free temperature, rail buckling in CWR.","usage_ja":"Hay đi với: ロングレール化, ロングレールの設定温度, 張り出し. Thuật ngữ Nhật này khác hẳn tiếng Anh.","context_vi":"Dùng trong thi công, bảo trì đường sắt tốc độ cao, kiểm soát ứng suất nhiệt và chống cong ray mùa nóng.","ex_en":"Continuous welded rail must be laid at the correct stress-free temperature.","ex_ja":"ロングレールは適正な設定温度で敷設しなければならない。","ex_vi":"Ray hàn liền phải được đặt ở đúng nhiệt độ không ứng suất.","syn_en":["CWR","long welded rail (Anh)"],"syn_ja":["溶接レール (nghĩa gần)"]},{"en":"axle load","pos":"noun phrase","ipa":"/ˈæksəl ˌloʊd/","ja":"軸重","kana":"じくじゅう","romaji":"jikujuu","vi":"tải trọng trục","level":2,"def_vi":"Tổng trọng lượng mà một trục bánh xe truyền xuống đường ray hoặc mặt đường, quyết định tải cho phép của tuyến.","def_en":"The total weight transmitted to the track or road by one axle, which limits which lines a vehicle may use.","def_ja":"1本の車軸がレールや路面に伝える重量で、走行可能な線区を決める要素。","usage_en":"Cụm danh từ đếm được. Hay đi với: maximum axle load, a 25-tonne axle load, heavy axle load; xe tải cũng dùng axle load.","usage_ja":"Hay đi với: 最大軸重, 軸重制限, 軸重16トン. Ô tô cũng dùng 軸重.","context_vi":"Dùng trong thiết kế đường sắt, cầu, chọn toa xe và kiểm soát quá tải xe tải.","ex_en":"The bridge limits the axle load to 18 tonnes.","ex_ja":"この橋梁では軸重が18トンに制限されている。","ex_vi":"Cây cầu này giới hạn tải trọng trục ở 18 tấn.","syn_en":["axle weight"],"syn_ja":["輪重 (tải bánh, liên quan)"]},{"en":"derailment","pos":"noun","ipa":"/dɪˈreɪlmənt/","ja":"脱線","kana":"だっせん","romaji":"dassen","vi":"trật bánh","level":2,"def_vi":"Sự cố bánh xe lửa rời khỏi ray, do gờ bánh leo ray, ray hỏng, quá tốc độ hoặc vật cản.","def_en":"An accident in which railway wheels leave the rails, caused by flange climb, track defects, overspeed or obstruction.","def_ja":"車輪がレールから外れる事故で、乗り上がり・軌道不良・速度超過・障害物などで起こる。","usage_en":"Danh từ đếm được; động từ derail (the train derailed). Hay đi với: derailment investigation, derailment coefficient, cause a derailment.","usage_ja":"Hay đi với: 脱線事故, 脱線係数, 乗り上がり脱線, 脱線する. Không dùng katakana.","context_vi":"Dùng trong điều tra tai nạn, đánh giá an toàn chạy tàu và thiết kế chống trật bánh.","ex_en":"The derailment was caused by a broken rail on the curve.","ex_ja":"その脱線は曲線区間のレール破断が原因だった。","ex_vi":"Vụ trật bánh do ray bị gãy ở đoạn đường cong.","syn_en":["derail (động từ, liên quan)"],"syn_ja":["脱輪 (nghĩa gần)"]},{"en":"hunting oscillation","pos":"noun phrase","ipa":"/ˈhʌntɪŋ ˌɑːsəˈleɪʃən/","ja":"蛇行動","kana":"だこうどう","romaji":"dakoudou","vi":"dao động lắc ngang (dao động rắn bò)","level":3,"def_vi":"Dao động ngang và xoay tự kích của bộ trục bánh xe do mặt lăn hình côn, mất ổn định khi vượt tốc độ tới hạn.","def_en":"A self-excited lateral and yaw oscillation of wheelsets due to conical treads, becoming unstable above a critical speed.","def_ja":"踏面の円すい形状により輪軸に生じる自励的な左右・ヨー振動で、限界速度を超えると不安定になる。","usage_en":"Cụm danh từ không đếm được; nói gọn hunting. Hay đi với: hunting stability, critical hunting speed, suppress hunting with yaw dampers.","usage_ja":"Hay đi với: 蛇行動安定性, 蛇行動限界速度, ヨーダンパで抑制する. Không dùng katakana.","context_vi":"Dùng trong thiết kế giá chuyển hướng tàu tốc độ cao, phân tích động lực học và thử nghiệm chạy tàu.","ex_en":"Yaw dampers raise the critical speed for hunting oscillation.","ex_ja":"ヨーダンパにより蛇行動の限界速度が向上する。","ex_vi":"Giảm chấn chống xoay làm tăng tốc độ tới hạn của dao động lắc ngang.","syn_en":["hunting"],"syn_ja":["ハンチング (ít dùng)"]},{"en":"automatic train control","pos":"noun phrase","ipa":"/ˌɔːtəˌmætɪk ˈtreɪn kənˌtroʊl/","ja":"自動列車制御装置","kana":"じどうれっしゃせいぎょそうち","romaji":"jidouresshaseigyosouchi","vi":"hệ thống điều khiển tàu tự động (ATC)","level":3,"def_vi":"Hệ thống tín hiệu truyền tốc độ cho phép lên tàu và tự động phanh khi tàu chạy vượt mức đó.","def_en":"A signalling system that sends permitted speed to the train and automatically brakes if it is exceeded.","def_ja":"許容速度を車上に伝え、それを超えると自動的にブレーキをかける信号保安装置。","usage_en":"Cụm danh từ không đếm được, viết tắt ATC. Phân biệt ATP (bảo vệ), ATO (vận hành tự động), CBTC (điều khiển dựa trên truyền thông).","usage_ja":"Hay đi với: ATC区間, デジタルATC, ATCが作動する. Hầu như luôn viết tắt ATC.","context_vi":"Dùng trong đường sắt cao tốc, metro, thiết kế tín hiệu và an toàn chạy tàu.","ex_en":"Automatic train control applied the brakes when the train exceeded 260 km/h.","ex_ja":"列車が時速260 kmを超えたため、自動列車制御装置がブレーキをかけた。","ex_vi":"Hệ thống điều khiển tàu tự động đã phanh khi tàu vượt 260 km/h.","syn_en":["ATC","ATP (nghĩa gần)"],"syn_ja":["ATC"]},{"en":"track irregularity","pos":"noun phrase","ipa":"/ˈtræk ɪˌrɛɡjəˈlærəti/","ja":"軌道狂い","kana":"きどうくるい","romaji":"kidoukurui","vi":"sai lệch hình học đường","level":3,"def_vi":"Độ lệch của ray so với hình học thiết kế như cao thấp, phương hướng, khổ đường, thủy bình và vặn vỏ đỗ.","def_en":"Deviation of the rails from design geometry, such as longitudinal level, alignment, gauge, cross level and twist.","def_ja":"高低・通り・軌間・水準・平面性など、レールの設計上の位置からのずれ。","usage_en":"Cụm danh từ đếm được; Anh hay nói track geometry fault/defect. Hay đi với: measure track irregularity, track geometry car, irregularity limits.","usage_ja":"Hay đi với: 軌道狂いを測定する, 軌道検測車, 高低狂い, 通り狂い. Thuật ngữ chuẩn ngành đường sắt Nhật.","context_vi":"Dùng trong đo kiểm đường bằng xe kiểm tra, lập kế hoạch chèn đá và đánh giá chất lượng chạy tàu.","ex_en":"The geometry car detected a track irregularity of 12 mm in longitudinal level.","ex_ja":"軌道検測車が12 mmの高低の軌道狂いを検出した。","ex_vi":"Xe kiểm tra hình học phát hiện sai lệch hình học đường 12 mm theo cao độ dọc.","syn_en":["track geometry defect","track geometry fault (Anh)"],"syn_ja":["軌道変位"]},{"en":"equivalent conicity","pos":"noun phrase","ipa":"/ɪˌkwɪvələnt koʊˈnɪsəti/","ja":"等価踏面勾配","kana":"とうかとうめんこうばい","romaji":"toukatoumenkoubai","vi":"độ côn tương đương (mặt lăn bánh xe)","level":3,"def_vi":"Độ côn hiệu dụng của cặp bánh xe trên ray, phụ thuộc biên dạng mặt lăn và ray, quyết định độ ổn định lắc ngang.","def_en":"The effective cone angle of a wheelset on the rails, from wheel and rail profiles, governing hunting stability.","def_ja":"車輪とレールの断面形状から求める輪軸の実効的な踏面勾配で、蛇行動安定性を左右する。","usage_en":"Cụm danh từ không đếm được. Hay đi với: low / high equivalent conicity, calculate equivalent conicity, wheel profile; giá trị không thứ nguyên như 0.15.","usage_ja":"Hay đi với: 等価踏面勾配が大きい, 踏面形状, 円弧踏面. Ngoài xưởng nói gọn 踏面勾配.","context_vi":"Dùng trong thiết kế biên dạng bánh xe, phân tích động lực học tàu tốc độ cao và lập kế hoạch tiện bánh.","ex_en":"Worn wheels increased the equivalent conicity and caused unstable running.","ex_ja":"車輪の摩耗で等価踏面勾配が大きくなり、走行が不安定になった。","ex_vi":"Bánh xe bị mòn làm tăng độ côn tương đương và khiến tàu chạy mất ổn định.","syn_en":["effective conicity","tread conicity (nghĩa gần)"],"syn_ja":["踏面勾配 (nghĩa gần)"]},{"en":"cant deficiency","pos":"noun phrase","ipa":"/ˈkænt dɪˌfɪʃənsi/","ja":"カント不足","kana":"カントぶそく","romaji":"kantobusoku","vi":"thiếu siêu cao","level":3,"def_vi":"Phần siêu cao còn thiếu so với mức cân bằng khi tàu chạy nhanh hơn tốc độ cân bằng của đường cong, gây gia tốc ngang chưa bù.","def_en":"The extra cant that would be needed when a train runs faster than the curve's equilibrium speed; causes unbalanced lateral acceleration.","def_ja":"均衡速度より速く走行するときに不足するカント量で、超過遠心加速度の原因となる。","usage_en":"Cụm danh từ không đếm được, đơn vị mm. Hay đi với: permissible cant deficiency, a cant deficiency of 110 mm; ngược lại là cant excess.","usage_ja":"Hay đi với: 許容カント不足量, カント不足量110 mm. Ngược lại là カント超過.","context_vi":"Dùng khi xác định tốc độ qua đường cong, thiết kế tàu nghiêng và đánh giá độ thoải mái hành khách.","ex_en":"Tilting trains can run with a higher cant deficiency on curves.","ex_ja":"振子式車両は曲線でより大きなカント不足を許容して走行できる。","ex_vi":"Tàu nghiêng có thể chạy với mức thiếu siêu cao lớn hơn trên đường cong.","syn_en":["unbalanced superelevation (Mỹ)"],"syn_ja":["カント不足量","超過遠心加速度 (liên quan)"]},{"en":"maglev","pos":"noun","ipa":"/ˈmæɡˌlɛv/","ja":"磁気浮上式鉄道","kana":"じきふじょうしきてつどう","romaji":"jikifujoushikitetsudou","vi":"tàu đệm từ (maglev)","level":3,"def_vi":"Hệ thống đường sắt dùng lực từ để nâng, dẫn hướng và đẩy tàu, không có tiếp xúc bánh với ray.","def_en":"A rail system that uses magnetic forces to levitate, guide and propel vehicles without wheel–rail contact.","def_ja":"磁力で車両を浮上・案内・推進させ、車輪とレールの接触なしに走行する鉄道方式。","usage_en":"Danh từ đếm được và không đếm được, viết tắt của magnetic levitation. Hay đi với: maglev train, maglev line, superconducting maglev.","usage_ja":"Hay đi với: 超電導磁気浮上式鉄道, 磁気浮上式鉄道の実験線. Đại chúng gọi リニアモーターカー hoặc リニア.","context_vi":"Dùng khi nói về tàu siêu tốc như tuyến Chuo Shinkansen ở Nhật, Thượng Hải ở Trung Quốc.","ex_en":"The superconducting maglev reached 603 km/h on the test line.","ex_ja":"超電導磁気浮上式鉄道は実験線で時速603 kmを記録した。","ex_vi":"Tàu đệm từ siêu dẫn đạt 603 km/h trên tuyến thử nghiệm.","syn_en":["magnetic levitation train"],"syn_ja":["リニアモーターカー (khẩu ngữ)","リニア (khẩu ngữ)"]}]},{"id":94,"words":[{"en":"hull","pos":"noun","ipa":"/hʌl/","ja":"船体","kana":"せんたい","romaji":"sentai","vi":"thân tàu (vỏ tàu)","level":1,"def_vi":"Phần thân kín nước của tàu gồm đáy, mạn và boong, tạo lực nổi và chịu tải trọng sóng.","def_en":"The watertight body of a ship, including bottom, sides and deck, that provides buoyancy and resists wave loads.","def_ja":"船底・船側・甲板からなる船の水密な本体で、浮力を生み波浪荷重に耐える。","usage_en":"Danh từ đếm được. Hay đi với: steel hull, double hull, hull form, hull structure, hull cleaning; đừng nhầm với fuselage (thân máy bay).","usage_ja":"Hay đi với: 船体構造, 船体ブロック, 船体塗装, 船体抵抗. Từ katakana ハル ít dùng ở xưởng đóng tàu Nhật.","context_vi":"Dùng trong thiết kế, đóng mới, sửa chữa tàu và khi kiểm tra ăn mòn, biến dạng vỏ tàu.","ex_en":"The hull was blasted and repainted during the dry-docking.","ex_ja":"入渠中に船体をブラストして再塗装した。","ex_vi":"Thân tàu được phun cát làm sạch và sơn lại trong đợt lên đà.","syn_en":["ship's hull","hull structure (nghĩa gần)"],"syn_ja":["船殻 (kết cấu thép thân tàu)","ハル"]},{"en":"bow","pos":"noun","ipa":"/baʊ/","ja":"船首","kana":"せんしゅ","romaji":"senshu","vi":"mũi tàu","level":1,"def_vi":"Phần đầu phía trước của tàu, được tạo hình để rẽ nước và giảm sức cản sóng.","def_en":"The front end of a ship, shaped to cut through water and reduce wave resistance.","def_ja":"船の前端部で、水を切り分け造波抵抗を減らすよう形づくられている。","usage_en":"Danh từ đếm được, đọc /baʊ/ (không đọc như bow /boʊ/ là cái nơ, cây cung). Hay đi với: bulbous bow, bow section, bow thruster; ngược lại stern.","usage_ja":"Hay đi với: 球状船首 (バルバスバウ), 船首部, 船首楼. Ngoài xưởng hay gọi バウ hoặc おもて.","context_vi":"Dùng khi mô tả vị trí trên tàu, thiết kế hình dáng mũi và bố trí thiết bị neo.","ex_en":"The bulbous bow reduces fuel consumption at service speed.","ex_ja":"球状船首は航海速力での燃料消費を減らす。","ex_vi":"Mũi quả lê giúp giảm tiêu hao nhiên liệu ở tốc độ khai thác.","syn_en":["fore (vị trí, liên quan)","stem (sống mũi, nghĩa hẹp)"],"syn_ja":["バウ","船首部"]},{"en":"stern","pos":"noun","ipa":"/stɜːrn/","ja":"船尾","kana":"せんび","romaji":"senbi","vi":"đuôi tàu (lái tàu)","level":1,"def_vi":"Phần cuối phía sau của tàu, nơi bố trí chân vịt, bánh lái và thường có buồng máy.","def_en":"The rear end of a ship, where the propeller and rudder are located.","def_ja":"船の後端部で、プロペラや舵が配置される。","usage_en":"Danh từ đếm được. Hay đi với: stern tube, stern frame, transom stern, at the stern; hướng về phía sau gọi aft.","usage_ja":"Hay đi với: 船尾管, 船尾骨材, 船尾部. Ngoài xưởng hay nói スターン hoặc とも.","context_vi":"Dùng khi mô tả vị trí trên tàu, lắp đặt hệ trục chân vịt và bánh lái.","ex_en":"The engine room is located near the stern of the tanker.","ex_ja":"このタンカーの機関室は船尾付近に配置されている。","ex_vi":"Buồng máy của tàu dầu này nằm gần đuôi tàu.","syn_en":["aft (vị trí, liên quan)"],"syn_ja":["スターン","とも (khẩu ngữ)"]},{"en":"deck","pos":"noun","ipa":"/dɛk/","ja":"甲板","kana":"こうはん","romaji":"kouhan","vi":"boong tàu","level":1,"def_vi":"Sàn nằm ngang của tàu chia không gian theo chiều cao; boong trên cùng che kín thân tàu.","def_en":"A horizontal floor of a ship dividing it vertically; the uppermost one closes the top of the hull.","def_ja":"船内を上下に仕切る水平な床で、最上部のものは船体の上面を覆う。","usage_en":"Danh từ đếm được. Hay đi với: main deck, upper deck, deck plating, on deck, below deck, deck machinery.","usage_ja":"Hay đi với: 上甲板, 甲板機械, 甲板上. Thuyền viên thường đọc かんぱん; ngành đóng tàu đọc こうはん. Khẩu ngữ: デッキ.","context_vi":"Dùng trong thiết kế bố trí chung, đóng tàu và vận hành thiết bị trên boong.","ex_en":"The containers are stacked six high on deck.","ex_ja":"コンテナは甲板上に6段積みされる。","ex_vi":"Container được xếp chồng sáu tầng trên boong tàu.","syn_en":["deck plating (tấm boong, nghĩa hẹp)"],"syn_ja":["デッキ","かんぱん (cách đọc của thuyền viên)"]},{"en":"propeller","pos":"noun","ipa":"/prəˈpɛlər/","ja":"プロペラ","kana":"プロペラ","romaji":"puropera","vi":"chân vịt","level":1,"def_vi":"Bộ cánh xoắn lắp ở đuôi trục, quay để đẩy nước về phía sau, tạo lực đẩy cho tàu.","def_en":"A set of twisted blades on the shaft end that pushes water backward to produce thrust.","def_ja":"軸の端に付いたねじれた羽根で、水を後方へ押して推力を発生させる。","usage_en":"Danh từ đếm được. Hay đi với: fixed-pitch propeller, propeller blade, propeller shaft, propeller efficiency; khẩu ngữ: prop, screw.","usage_ja":"Hay đi với: プロペラ翼, プロペラ軸, プロペラ効率. Văn bản chuẩn: 推進器 hoặc 螺旋推進器 (ít dùng).","context_vi":"Dùng trong thiết kế hệ đẩy tàu, đúc và gia công chân vịt, kiểm tra hư hỏng cánh khi lên đà.","ex_en":"The bronze propeller weighs 65 tonnes and has five blades.","ex_ja":"この青銅製のプロペラは重さ65トンで、翼が5枚ある。","ex_vi":"Chân vịt bằng đồng này nặng 65 tấn và có năm cánh.","syn_en":["screw propeller","prop (khẩu ngữ)"],"syn_ja":["推進器","スクリュー (khẩu ngữ)"]},{"en":"rudder","pos":"noun","ipa":"/ˈrʌdər/","ja":"舵","kana":"かじ","romaji":"kaji","vi":"bánh lái","level":1,"def_vi":"Tấm phẳng hoặc dạng cánh đặt sau chân vịt, quay sang hai bên để đổi hướng đi của tàu.","def_en":"A flat or foil-shaped plate behind the propeller that turns to change the ship's heading.","def_ja":"プロペラの後方に設けた板状の装置で、左右に回して船の針路を変える。","usage_en":"Danh từ đếm được. Hay đi với: rudder stock, rudder angle, rudder blade, steering gear turns the rudder.","usage_ja":"Hay đi với: 舵角, 舵頭材, 舵取機. Văn bản kỹ thuật dùng 舵; ngoài xưởng có thể nói ラダー.","context_vi":"Dùng trong thiết kế khả năng điều động, lắp ráp hệ lái và kiểm tra khe hở ổ đỡ bánh lái.","ex_en":"The steering gear can turn the rudder 35 degrees to either side.","ex_ja":"舵取機は舵を左右それぞれ35度まで動かせる。","ex_vi":"Máy lái có thể quay bánh lái 35 độ sang mỗi bên.","syn_en":["rudder blade"],"syn_ja":["ラダー"]},{"en":"anchor","pos":"noun","ipa":"/ˈæŋkər/","ja":"錨","kana":"いかり","romaji":"ikari","vi":"neo","level":1,"def_vi":"Khối thép nặng có ngạnh, thả xuống đáy biển qua xích neo để giữ tàu đứng yên một chỗ.","def_en":"A heavy steel device with flukes, lowered to the seabed on a chain to hold a ship in place.","def_ja":"鎖を介して海底に下ろし、船をその場にとどめる爪付きの重い鋼製器具。","usage_en":"Danh từ đếm được, cũng là động từ (the ship anchored). Hay đi với: drop / weigh the anchor, anchor chain, anchor windlass.","usage_ja":"Hay đi với: 錨を下ろす/揚げる, 錨鎖, 揚錨機. Ngoài xưởng hay nói アンカー; văn bản viết いかり bằng hiragana cũng có.","context_vi":"Dùng trong trang bị boong mũi, thiết kế tời neo và vận hành tàu khi neo đậu.","ex_en":"The anchor and its chain are tested before the ship is delivered.","ex_ja":"錨と錨鎖は船の引渡し前に試験される。","ex_vi":"Neo và xích neo được thử trước khi bàn giao tàu.","syn_en":["bower anchor (neo mũi)"],"syn_ja":["アンカー","いかり"]},{"en":"keel","pos":"noun","ipa":"/kiːl/","ja":"キール","kana":"キール","romaji":"kiiru","vi":"ky tàu (sống chính đáy)","level":1,"def_vi":"Kết cấu dọc chính chạy dọc giữa đáy tàu từ mũi đến đuôi, như xương sống của thân tàu.","def_en":"The main longitudinal structural member along the centerline of the bottom, acting as the backbone of the hull.","def_ja":"船底中心線に沿って船首から船尾まで通る主要な縦通部材で、船体の背骨にあたる。","usage_en":"Danh từ đếm được. Hay đi với: flat plate keel, bilge keel, keel laying (đặt ky), keel block; nghĩa bóng: on an even keel.","usage_ja":"Hay đi với: 平板キール, ビルジキール, 起工 (đặt ky). Từ Hán 竜骨 dùng trong văn bản cũ hoặc tàu gỗ.","context_vi":"Dùng trong kết cấu đáy tàu, nghi thức đặt ky khởi công đóng tàu và bố trí căn kê trên ụ.","ex_en":"The flat plate keel is 25 mm thick along the midship section.","ex_ja":"中央部の平板キールの板厚は25 mmである。","ex_vi":"Ky tấm phẳng dày 25 mm ở đoạn giữa tàu.","syn_en":["keel plate","backbone (khẩu ngữ, nghĩa bóng)"],"syn_ja":["竜骨","平板キール"]},{"en":"bulkhead","pos":"noun","ipa":"/ˈbʌlkˌhɛd/","ja":"隔壁","kana":"かくへき","romaji":"kakuheki","vi":"vách ngăn","level":1,"def_vi":"Vách thẳng đứng chia thân tàu thành các khoang, thường kín nước để hạn chế ngập khi thủng vỏ.","def_en":"A vertical partition dividing the hull into compartments, usually watertight to limit flooding.","def_ja":"船体を区画に仕切る垂直な壁で、通常は浸水を限定するため水密となっている。","usage_en":"Danh từ đếm được. Hay đi với: watertight bulkhead, transverse / longitudinal bulkhead, collision bulkhead, corrugated bulkhead.","usage_ja":"Hay đi với: 水密隔壁, 横隔壁, 衝突隔壁, 波形隔壁. Ngoài xưởng có thể nói バルクヘッド.","context_vi":"Dùng trong thiết kế kết cấu, phân khoang chống chìm và cũng dùng trong máy bay, tàu ngầm.","ex_en":"The collision bulkhead must be watertight up to the freeboard deck.","ex_ja":"衝突隔壁は乾舷甲板まで水密でなければならない。","ex_vi":"Vách ngăn chống va phải kín nước đến boong mạn khô.","syn_en":["partition (nghĩa rộng)"],"syn_ja":["バルクヘッド","仕切壁 (nghĩa rộng)"]},{"en":"engine room","pos":"noun phrase","ipa":"/ˈɛndʒɪn ˌruːm/","ja":"機関室","kana":"きかんしつ","romaji":"kikanshitsu","vi":"buồng máy","level":1,"def_vi":"Khoang trên tàu đặt máy chính, máy phát điện, nồi hơi phụ, bơm và các thiết bị phục vụ.","def_en":"The compartment housing the main engine, generators, auxiliary boiler, pumps and other machinery.","def_ja":"主機・発電機・補助ボイラ・ポンプなどの機器を設置する船内の区画。","usage_en":"Cụm danh từ đếm được. Hay đi với: engine room crew, unmanned engine room, engine room ventilation, engine control room (ECR).","usage_ja":"Hay đi với: 機関室配置, 機関制御室, M0 (無人化機関室). Thuyền viên gọi tắt エンジンルーム hoặc 機関場.","context_vi":"Dùng trong bố trí thiết bị, lắp đặt đường ống máy tàu và vận hành, trực ca của sĩ quan máy.","ex_en":"Piping in the engine room is fitted before the main engine is lowered in.","ex_ja":"主機を搭載する前に機関室の配管を取り付ける。","ex_vi":"Đường ống trong buồng máy được lắp trước khi hạ máy chính xuống.","syn_en":["machinery space"],"syn_ja":["機関区域","エンジンルーム"]},{"en":"shipyard","pos":"noun","ipa":"/ˈʃɪpˌjɑːrd/","ja":"造船所","kana":"ぞうせんじょ","romaji":"zousenjo","vi":"nhà máy đóng tàu","level":2,"def_vi":"Cơ sở công nghiệp có ụ, triền, cẩu lớn và xưởng để đóng mới và sửa chữa tàu.","def_en":"An industrial facility with docks, slipways, large cranes and workshops for building and repairing ships.","def_ja":"ドック・船台・大型クレーン・工場を備え、船の建造や修繕を行う施設。","usage_en":"Danh từ đếm được. Hay đi với: shipyard worker, repair shipyard, at the shipyard; cũng nói yard (khẩu ngữ).","usage_ja":"Hay đi với: 造船所で建造する, 修繕造船所. Khẩu ngữ: ヤード; tên công ty thường có 造船所 hoặc 工場.","context_vi":"Dùng trong ngành đóng tàu, hợp đồng đóng mới, giám sát chủ tàu tại nhà máy.","ex_en":"The shipyard delivers about twenty bulk carriers a year.","ex_ja":"この造船所は年間約20隻のばら積み船を引き渡している。","ex_vi":"Nhà máy đóng tàu này bàn giao khoảng hai mươi tàu hàng rời mỗi năm.","syn_en":["yard (khẩu ngữ)","dockyard (Anh)"],"syn_ja":["ヤード (khẩu ngữ)","造船工場"]},{"en":"dry dock","pos":"noun phrase","ipa":"/ˈdraɪ ˌdɑːk/","ja":"乾ドック","kana":"かんドック","romaji":"kandokku","vi":"ụ khô","level":2,"def_vi":"Bể lớn có cửa chắn, sau khi tàu vào thì bơm cạn nước để tàu nằm khô trên căn kê cho đóng mới hoặc sửa chữa.","def_en":"A basin with a gate that is pumped dry after a ship enters, leaving it on blocks for building or repair.","def_ja":"船を入れた後に排水して、船を盤木の上に乾いた状態で据え、建造や修理を行う設備。","usage_en":"Cụm danh từ đếm được, cũng viết drydock; dùng như động từ: dry-dock a ship. Hay đi với: in dry dock, dry dock gate, floating dock (ụ nổi).","usage_ja":"Hay đi với: 乾ドックに入渠する, 浮きドック. Động từ: 入渠する, 出渠する; khẩu ngữ: ドック入り.","context_vi":"Dùng trong đóng mới theo phương pháp ụ, sửa chữa định kỳ phần dưới nước và kiểm tra của đăng kiểm.","ex_en":"The tanker entered dry dock for its five-yearly special survey.","ex_ja":"このタンカーは5年ごとの定期検査のため乾ドックに入った。","ex_vi":"Tàu dầu vào ụ khô để kiểm tra định kỳ năm năm.","syn_en":["graving dock","drydock"],"syn_ja":["ドライドック","ドック"]},{"en":"draft","pos":"noun","ipa":"/dræft/","ja":"喫水","kana":"きっすい","romaji":"kissui","vi":"mớn nước","level":2,"def_vi":"Khoảng cách thẳng đứng từ đáy ky đến mặt nước, thể hiện độ chìm của tàu.","def_en":"The vertical distance from the bottom of the keel to the waterline, showing how deep the ship sits.","def_ja":"キール下面から水線までの垂直距離で、船の沈み具合を示す。","usage_en":"Danh từ đếm được; tiếng Anh-Anh viết draught. Hay đi với: design draft, scantling draft, draft marks, read the draft; fore / aft draft.","usage_ja":"Hay đi với: 計画喫水, 満載喫水, 喫水標, 喫水を読む. Ngoài xưởng có thể nói ドラフト.","context_vi":"Dùng khi tính tải trọng, kiểm tra luồng lạch, cảng và đọc thước nước khi xếp dỡ hàng.","ex_en":"The port limits vessels to a maximum draft of 12.5 m.","ex_ja":"この港では船舶の最大喫水が12.5 mに制限されている。","ex_vi":"Cảng này giới hạn tàu có mớn nước tối đa 12,5 m.","syn_en":["draught (Anh)"],"syn_ja":["ドラフト"]},{"en":"freeboard","pos":"noun","ipa":"/ˈfriːˌbɔːrd/","ja":"乾舷","kana":"かんげん","romaji":"kangen","vi":"mạn khô","level":2,"def_vi":"Khoảng cách thẳng đứng từ đường nước đến mép boong mạn khô, đảm bảo dự trữ nổi cho tàu.","def_en":"The vertical distance from the waterline to the freeboard deck edge, providing reserve buoyancy.","def_ja":"水線から乾舷甲板の舷端までの垂直距離で、予備浮力を確保する。","usage_en":"Danh từ không đếm được. Hay đi với: minimum freeboard, freeboard deck, freeboard mark (Plimsoll line), assign freeboard.","usage_ja":"Hay đi với: 乾舷甲板, 満載喫水線標, 最小乾舷. Chủ yếu dùng trong văn bản quy phạm, công ước Load Line.","context_vi":"Dùng trong thiết kế theo công ước mạn khô, đánh dấu vạch mớn nước và kiểm tra quá tải.","ex_en":"The required freeboard depends on ship length and hatch arrangement.","ex_ja":"必要な乾舷は船の長さとハッチ配置によって決まる。","ex_vi":"Mạn khô yêu cầu phụ thuộc vào chiều dài tàu và cách bố trí miệng hầm hàng.","syn_en":["load line (liên quan)"],"syn_ja":["満載喫水線 (liên quan)","フリーボード"]},{"en":"ballast tank","pos":"noun phrase","ipa":"/ˈbæləst ˌtæŋk/","ja":"バラストタンク","kana":"バラストタンク","romaji":"barasutotanku","vi":"két dằn","level":2,"def_vi":"Két trong thân tàu được bơm nước biển vào hoặc ra để điều chỉnh mớn nước, độ chúi và ổn định khi tàu không hàng.","def_en":"A tank filled with or emptied of seawater to adjust a ship's draft, trim and stability.","def_ja":"海水を注排水して、船の喫水・トリム・復原性を調整するタンク。","usage_en":"Cụm danh từ đếm được. Hay đi với: water ballast tank, fill / pump out the ballast tanks, ballast tank coating, double-bottom ballast tank.","usage_ja":"Hay đi với: バラスト水, バラストタンクの塗装, 注水する/排水する. Văn bản có thể viết バラスト槽.","context_vi":"Dùng trong thiết kế két, sơn chống ăn mòn, vận hành bơm dằn và kiểm tra đăng kiểm.","ex_en":"The empty bulk carrier fills its ballast tanks to lower the propeller below the surface.","ex_ja":"空船のばら積み船は、プロペラを水面下に沈めるためバラストタンクに注水する。","ex_vi":"Tàu hàng rời không tải bơm nước vào két dằn để chân vịt chìm dưới mặt nước.","syn_en":["water ballast tank","WBT"],"syn_ja":["バラスト槽","WBT"]},{"en":"double bottom","pos":"noun phrase","ipa":"/ˌdʌbəl ˈbɑːtəm/","ja":"二重底","kana":"にじゅうてい","romaji":"nijuutei","vi":"đáy đôi","level":2,"def_vi":"Kết cấu đáy tàu gồm tôn bao đáy ngoài và tôn đáy trong, khoảng giữa dùng làm két và bảo vệ khi mắc cạn.","def_en":"A bottom structure with outer and inner bottom plating; the space between serves as tanks and protects against grounding.","def_ja":"外底板と内底板からなる船底構造で、間の空間はタンクとなり座礁時の浸水を防ぐ。","usage_en":"Cụm danh từ đếm được. Hay đi với: double bottom tank, double bottom height, inner bottom; liên quan double hull (vỏ kép).","usage_ja":"Hay đi với: 二重底タンク, 二重底高さ, 内底板. Không dùng katakana.","context_vi":"Dùng trong thiết kế kết cấu đáy, bố trí két nhiên liệu, két dằn và yêu cầu quy phạm.","ex_en":"Fuel oil is no longer allowed in tanks directly against the double bottom shell.","ex_ja":"船底外板に接する二重底タンクには燃料油を積載できなくなった。","ex_vi":"Không còn được chứa dầu nhiên liệu trong két sát tôn vỏ của đáy đôi.","syn_en":["inner bottom (tôn đáy trong, liên quan)","double hull (nghĩa rộng)"],"syn_ja":["二重船殻 (nghĩa rộng)","内底 (liên quan)"]},{"en":"hull block","pos":"noun phrase","ipa":"/ˈhʌl ˌblɑːk/","ja":"船体ブロック","kana":"せんたいブロック","romaji":"sentaiburokku","vi":"phân đoạn thân tàu (block)","level":2,"def_vi":"Một đoạn kết cấu thân tàu được chế tạo sẵn trong xưởng, sau đó cẩu lên ụ để ghép thành thân tàu hoàn chỉnh.","def_en":"A prefabricated section of hull structure built in the shop and then lifted into the dock to be joined.","def_ja":"工場であらかじめ製作し、ドックへ搭載して結合する船体構造の一区画。","usage_en":"Cụm danh từ đếm được; nói gọn block. Hay đi với: block erection, block assembly, grand block, outfitting on block.","usage_ja":"Hay đi với: ブロック搭載, 大組立, 総組 (グランドブロック), 先行艤装. Ngoài xưởng nói gọn ブロック.","context_vi":"Dùng trong công nghệ đóng tàu theo phân đoạn, lập kế hoạch cẩu lắp và hàn đấu đà.","ex_en":"The 600-tonne hull block was lifted into the dock by a goliath crane.","ex_ja":"重さ600トンの船体ブロックをゴライアスクレーンでドックへ搭載した。","ex_vi":"Phân đoạn thân tàu nặng 600 tấn được cẩu cổng lớn đưa xuống ụ.","syn_en":["block","hull section"],"syn_ja":["ブロック"]},{"en":"launching","pos":"noun","ipa":"/ˈlɔːntʃɪŋ/","ja":"進水","kana":"しんすい","romaji":"shinsui","vi":"hạ thủy","level":2,"def_vi":"Công đoạn đưa thân tàu đã đóng xong phần chính từ triền hoặc ụ xuống nước lần đầu.","def_en":"The operation of moving a newly built hull from the slipway or dock into the water for the first time.","def_ja":"建造中の船体を船台やドックから初めて水上に浮かべる作業。","usage_en":"Danh từ không đếm được; động từ launch (the ship was launched). Hay đi với: launching ceremony, side launching, launching weight.","usage_ja":"Hay đi với: 進水式, 進水する, 進水重量. Không dùng katakana.","context_vi":"Dùng trong kế hoạch đóng tàu theo mốc (đặt ky, hạ thủy, bàn giao) và tính toán hạ thủy trên triền.","ex_en":"Launching is scheduled for high tide on 14 March.","ex_ja":"進水は3月14日の満潮時に予定されている。","ex_vi":"Hạ thủy được lên lịch vào lúc nước lớn ngày 14 tháng 3.","syn_en":["launch"],"syn_ja":["進水式 (nghi lễ, liên quan)","浮上 (ụ khô, nghĩa gần)"]},{"en":"bow thruster","pos":"noun phrase","ipa":"/ˈbaʊ ˌθrʌstər/","ja":"バウスラスタ","kana":"バウスラスタ","romaji":"bausurasuta","vi":"chân vịt mũi (bow thruster)","level":2,"def_vi":"Chân vịt đặt trong ống xuyên ngang ở mũi tàu, tạo lực đẩy ngang giúp tàu quay trở khi cập, rời cầu.","def_en":"A propeller in a transverse tunnel at the bow that produces sideways thrust for berthing and maneuvering.","def_ja":"船首部の横方向トンネル内に設けたプロペラで、離着岸時に横向きの推力を発生させる。","usage_en":"Cụm danh từ đếm được. Hay đi với: bow thruster tunnel, bow thruster motor, use the bow thruster; ở đuôi gọi stern thruster.","usage_ja":"Hay đi với: バウスラスタを使用する, スラスタトンネル. Cũng viết バウスラスター; văn bản: サイドスラスタ.","context_vi":"Dùng trong thiết kế khả năng điều động, lắp đặt thiết bị mũi và vận hành cập cảng không cần tàu lai.","ex_en":"The ferry berths without tugs thanks to its bow thruster.","ex_ja":"このフェリーはバウスラスタのおかげでタグボートなしで着岸できる。","ex_vi":"Phà này cập cầu không cần tàu lai nhờ chân vịt mũi.","syn_en":["tunnel thruster","side thruster"],"syn_ja":["サイドスラスタ","バウスラスター"]},{"en":"main engine","pos":"noun phrase","ipa":"/ˈmeɪn ˌɛndʒɪn/","ja":"主機","kana":"しゅき","romaji":"shuki","vi":"máy chính","level":2,"def_vi":"Động cơ chính dẫn động chân vịt, trên tàu hàng lớn thường là động cơ diesel hai kỳ thấp tốc.","def_en":"The engine that drives the propeller, on large cargo ships usually a slow-speed two-stroke diesel.","def_ja":"プロペラを駆動する主たる機関で、大型商船では低速2ストロークディーゼルが一般的。","usage_en":"Cụm danh từ đếm được, viết tắt M/E. Hay đi với: main engine output, main engine room, start the main engine; máy phụ là auxiliary engine.","usage_ja":"Hay đi với: 主機出力, 主機関, 主機を始動する. Đối lập 補機 (máy phụ); viết tắt M/E trong nhật ký máy.","context_vi":"Dùng trong thiết kế hệ động lực tàu, lắp đặt, vận hành và bảo dưỡng ở buồng máy.","ex_en":"The main engine delivers 13,000 kW at 80 rpm.","ex_ja":"主機は80 rpmで13,000 kWを出力する。","ex_vi":"Máy chính phát công suất 13.000 kW ở 80 vòng/phút.","syn_en":["M/E","propulsion engine"],"syn_ja":["主機関","メインエンジン"]},{"en":"stern tube","pos":"noun phrase","ipa":"/ˈstɜːrn ˌtuːb/","ja":"船尾管","kana":"せんびかん","romaji":"senbikan","vi":"ống bao trục chân vịt","level":2,"def_vi":"Ống xuyên qua vỏ đuôi tàu chứa ổ đỡ và phớt kín, cho trục chân vịt đi ra ngoài mà không rò nước.","def_en":"The tube through the stern carrying bearings and seals so the propeller shaft can exit the hull watertight.","def_ja":"船尾を貫通し、軸受とシールを備えてプロペラ軸を水密に船外へ通す管。","usage_en":"Cụm danh từ đếm được. Hay đi với: stern tube bearing, stern tube seal, stern tube lube oil, aft / forward stern tube seal.","usage_ja":"Hay đi với: 船尾管軸受, 船尾管シール, 船尾管潤滑油. Không dùng katakana.","context_vi":"Dùng trong lắp đặt hệ trục, căn chỉnh đường trục và xử lý rò dầu phớt khi lên đà.","ex_en":"Oil leaking from the stern tube seal was found during the hull inspection.","ex_ja":"船体検査で船尾管シールからの油漏れが見つかった。","ex_vi":"Phát hiện dầu rò từ phớt ống bao trục chân vịt khi kiểm tra thân tàu.","syn_en":["stern tube assembly"],"syn_ja":["スターンチューブ"]},{"en":"sea trial","pos":"noun phrase","ipa":"/ˈsiː ˌtraɪəl/","ja":"海上試運転","kana":"かいじょうしうんてん","romaji":"kaijoushiunten","vi":"chạy thử đường dài (thử tàu trên biển)","level":2,"def_vi":"Đợt chạy thử tàu mới trên biển để kiểm tra tốc độ, máy móc, khả năng điều động trước khi bàn giao.","def_en":"Trials of a new ship at sea to verify speed, machinery and maneuvering before delivery.","def_ja":"引渡し前に海上で速力・機関・操縦性能などを確認する試運転。","usage_en":"Cụm danh từ đếm được, thường số nhiều: sea trials. Hay đi với: go on sea trials, speed trial, endurance test, sea trial report.","usage_ja":"Hay đi với: 海上試運転を実施する, 速力試験, 旋回試験. Khẩu ngữ: 試運転, 海試.","context_vi":"Dùng trong giai đoạn cuối đóng tàu, có đại diện chủ tàu và đăng kiểm tham gia.","ex_en":"The ship reached 15.2 knots during the sea trial.","ex_ja":"海上試運転で本船は15.2ノットを記録した。","ex_vi":"Con tàu đạt 15,2 hải lý/giờ trong đợt chạy thử trên biển.","syn_en":["sea trials","trial run"],"syn_ja":["試運転","公試運転 (nghĩa gần)"]},{"en":"hatch cover","pos":"noun phrase","ipa":"/ˈhætʃ ˌkʌvər/","ja":"ハッチカバー","kana":"ハッチカバー","romaji":"hacchikabaa","vi":"nắp hầm hàng","level":2,"def_vi":"Nắp thép kín thời tiết đóng miệng hầm hàng trên boong, mở bằng thủy lực hoặc cẩu khi xếp dỡ.","def_en":"A weathertight steel cover closing a cargo hatch on deck, opened hydraulically or by crane for loading.","def_ja":"甲板上の貨物倉口をふさぐ風雨密の鋼製のふたで、荷役時に油圧やクレーンで開閉する。","usage_en":"Cụm danh từ đếm được. Hay đi với: folding / side-rolling hatch cover, hatch cover packing, open / close the hatch covers.","usage_ja":"Hay đi với: ハッチカバーを開閉する, ハッチコーミング, パッキン. Chỉ dùng katakana.","context_vi":"Dùng trên tàu hàng rời, tàu container, khi thiết kế, kiểm tra độ kín và bảo dưỡng gioăng.","ex_en":"A hose test confirmed that every hatch cover was weathertight.","ex_ja":"ホーステストですべてのハッチカバーが風雨密であることを確認した。","ex_vi":"Phép thử phun nước xác nhận mọi nắp hầm hàng đều kín thời tiết.","syn_en":["hatch lid"],"syn_ja":["倉口蓋"]},{"en":"mooring line","pos":"noun phrase","ipa":"/ˈmʊrɪŋ ˌlaɪn/","ja":"係船索","kana":"けいせんさく","romaji":"keisensaku","vi":"dây buộc tàu","level":2,"def_vi":"Dây cáp hoặc dây sợi tổng hợp dùng để buộc tàu vào cầu cảng, phao hoặc tàu khác.","def_en":"A rope or wire used to secure a ship to a berth, buoy or another vessel.","def_ja":"船を岸壁・ブイ・他船につなぎ留めるためのロープやワイヤ。","usage_en":"Cụm danh từ đếm được. Hay đi với: head / stern line, spring line, mooring winch, single up the mooring lines.","usage_ja":"Hay đi với: 係船索を取る, 係船機, 係船設備. Thuyền viên hay nói もやい hoặc ロープ; văn bản cũng viết 係留索.","context_vi":"Dùng trong thiết kế trang bị buộc tàu, chọn tời và vận hành cập, rời cầu.","ex_en":"A parted mooring line can recoil and seriously injure crew.","ex_ja":"係船索が切断すると跳ね返り、乗組員が重傷を負うおそれがある。","ex_vi":"Dây buộc tàu bị đứt có thể bật ngược lại và gây thương tích nặng cho thuyền viên.","syn_en":["mooring rope","hawser (dây lớn)"],"syn_ja":["係留索","もやい (khẩu ngữ)"]},{"en":"deadweight tonnage","pos":"noun phrase","ipa":"/ˈdɛdˌweɪt ˌtʌnɪdʒ/","ja":"載貨重量トン数","kana":"さいかじゅうりょうトンすう","romaji":"saikajuuryoutonsuu","vi":"trọng tải toàn phần (DWT)","level":3,"def_vi":"Tổng khối lượng tàu có thể chở gồm hàng, nhiên liệu, nước, thực phẩm và thuyền viên ở mớn nước tối đa.","def_en":"The total mass a ship can carry — cargo, fuel, water, stores and crew — at its maximum draft.","def_ja":"満載喫水で積載できる貨物・燃料・清水・食料・乗組員などの総重量。","usage_en":"Cụm danh từ, viết tắt DWT; nói 'a 180,000 DWT bulk carrier'. Phân biệt với gross tonnage (dung tích, không phải khối lượng).","usage_ja":"Hay đi với: 載貨重量トン数18万トン, DWT. Khẩu ngữ: 載貨重量, デッドウェイト.","context_vi":"Dùng trong hợp đồng đóng tàu, thuê tàu, phân loại cỡ tàu và thiết kế tổng thể.","ex_en":"The deadweight tonnage of the new bulk carrier is 82,000 t.","ex_ja":"新造ばら積み船の載貨重量トン数は82,000トンである。","ex_vi":"Trọng tải toàn phần của tàu hàng rời mới là 82.000 tấn.","syn_en":["DWT","deadweight"],"syn_ja":["DWT","載貨重量"]},{"en":"gross tonnage","pos":"noun phrase","ipa":"/ˌɡroʊs ˈtʌnɪdʒ/","ja":"総トン数","kana":"そうトンすう","romaji":"soutonsuu","vi":"tổng dung tích (GT)","level":3,"def_vi":"Chỉ số không thứ nguyên biểu thị thể tích kín của toàn tàu, tính theo công ước đo dung tích, dùng cho phí cảng và quy định.","def_en":"A dimensionless index of a ship's total enclosed volume, calculated under the Tonnage Convention for fees and regulations.","def_ja":"トン数条約に基づき船内の総容積から算出する無次元の指標で、税や規則の適用に用いる。","usage_en":"Cụm danh từ không đếm được, viết tắt GT. Hay đi với: a ship of 5,000 GT, gross tonnage certificate; không phải là khối lượng.","usage_ja":"Hay đi với: 総トン数500トン未満, 国際総トン数. Viết tắt GT; đừng nhầm với 載貨重量トン数.","context_vi":"Dùng trong đăng ký tàu, tính phí cảng, xác định yêu cầu thuyền viên và áp dụng công ước.","ex_en":"Ships above 500 gross tonnage must carry a safety management certificate.","ex_ja":"総トン数500トン以上の船舶は安全管理証書を備えなければならない。","ex_vi":"Tàu có tổng dung tích trên 500 phải có giấy chứng nhận quản lý an toàn.","syn_en":["GT"],"syn_ja":["GT","国際総トン数 (nghĩa gần)"]},{"en":"classification society","pos":"noun phrase","ipa":"/ˌklæsɪfɪˈkeɪʃən səˌsaɪəti/","ja":"船級協会","kana":"せんきゅうきょうかい","romaji":"senkyuukyoukai","vi":"tổ chức đăng kiểm (hội phân cấp tàu)","level":3,"def_vi":"Tổ chức ban hành quy phạm kỹ thuật, duyệt thiết kế và kiểm tra tàu để cấp và duy trì cấp tàu.","def_en":"An organization that sets technical rules, approves designs and surveys ships to assign and maintain class.","def_ja":"技術規則を定め、設計承認と検査を行って船級を付与・維持する機関。","usage_en":"Cụm danh từ đếm được; khẩu ngữ: class. Hay đi với: class rules, class surveyor, approved by the classification society; ví dụ DNV, ABS, ClassNK, VR.","usage_ja":"Hay đi với: 船級規則, 船級検査員, 船級協会の承認. Ví dụ 日本海事協会 (ClassNK); khẩu ngữ: 船級.","context_vi":"Dùng trong duyệt bản vẽ, giám sát đóng mới, kiểm tra định kỳ và hồ sơ bảo hiểm tàu.","ex_en":"The weld procedure must be approved by the classification society.","ex_ja":"溶接施工要領は船級協会の承認を受けなければならない。","ex_vi":"Quy trình hàn phải được tổ chức đăng kiểm phê duyệt.","syn_en":["class society","class (khẩu ngữ)"],"syn_ja":["船級 (khẩu ngữ)","検査機関 (nghĩa rộng)"]},{"en":"inclining experiment","pos":"noun phrase","ipa":"/ɪnˈklaɪnɪŋ ɪkˌspɛrɪmənt/","ja":"重心査定試験","kana":"じゅうしんさていしけん","romaji":"juushinsateishiken","vi":"thử nghiêng tàu (xác định trọng tâm)","level":3,"def_vi":"Phép thử di chuyển khối tải đã biết sang ngang trên boong và đo góc nghiêng để xác định trọng tâm tàu không.","def_en":"A test in which known weights are shifted across the deck and the heel is measured to find the lightship center of gravity.","def_ja":"既知の重量物を甲板上で横移動させ、傾斜角を測って軽荷状態の重心位置を求める試験。","usage_en":"Cụm danh từ đếm được; cũng gọi inclining test. Hay đi với: carry out an inclining experiment, lightship weight, KG, stability booklet.","usage_ja":"Hay đi với: 重心査定試験を実施する, 軽荷重量, 復原性資料. Khẩu ngữ: 傾斜試験, インクライニング.","context_vi":"Dùng khi hoàn thiện đóng tàu hoặc sau hoán cải lớn, có đăng kiểm chứng kiến, làm cơ sở tính ổn định.","ex_en":"The inclining experiment was carried out in calm water with the surveyor present.","ex_ja":"重心査定試験は検査官立会いのもと、静穏な水域で実施された。","ex_vi":"Thử nghiêng tàu được thực hiện ở vùng nước lặng với sự chứng kiến của đăng kiểm viên.","syn_en":["inclining test","stability test (nghĩa rộng)"],"syn_ja":["傾斜試験","インクライニングテスト"]},{"en":"block coefficient","pos":"noun phrase","ipa":"/ˈblɑːk ˌkoʊɪˌfɪʃənt/","ja":"方形係数","kana":"ほうけいけいすう","romaji":"houkeikeisuu","vi":"hệ số béo thể tích (Cb)","level":3,"def_vi":"Tỉ số giữa thể tích phần chìm của tàu và thể tích hình hộp có cùng chiều dài, chiều rộng và mớn nước.","def_en":"The ratio of a ship's underwater volume to that of a box with the same length, breadth and draft.","def_ja":"船の排水容積と、同じ長さ・幅・喫水をもつ直方体の容積との比。","usage_en":"Cụm danh từ đếm được, ký hiệu Cb. Hay đi với: high / low block coefficient, a block coefficient of 0.85; tàu chậm, béo có Cb lớn.","usage_ja":"Hay đi với: 方形係数Cb, 肥大船, 痩せ型船. Thường viết Cb trong tính toán.","context_vi":"Dùng trong thiết kế sơ bộ hình dáng thân tàu, ước tính sức cản và công suất máy.","ex_en":"Tankers have a block coefficient of about 0.83, while container ships are near 0.65.","ex_ja":"タンカーの方形係数は約0.83だが、コンテナ船は0.65前後である。","ex_vi":"Tàu dầu có hệ số béo thể tích khoảng 0,83, còn tàu container khoảng 0,65.","syn_en":["Cb"],"syn_ja":["Cb","肥せき係数 (nghĩa gần)"]},{"en":"controllable pitch propeller","pos":"noun phrase","ipa":"/kənˌtroʊləbəl ˈpɪtʃ prəˌpɛlər/","ja":"可変ピッチプロペラ","kana":"かへんピッチプロペラ","romaji":"kahenpicchipuropera","vi":"chân vịt biến bước","level":3,"def_vi":"Chân vịt có cánh xoay được quanh trục cánh bằng thủy lực để thay đổi bước, điều chỉnh lực đẩy và lùi mà không đổi chiều quay trục.","def_en":"A propeller whose blades rotate hydraulically to change pitch, controlling thrust and astern without reversing the shaft.","def_ja":"翼を油圧で回転させてピッチを変え、軸の回転方向を変えずに推力や後進を制御するプロペラ。","usage_en":"Cụm danh từ đếm được, viết tắt CPP; đối lập fixed-pitch propeller (FPP). Hay đi với: CPP hub, pitch setting, CPP control system.","usage_ja":"Hay đi với: 可変ピッチプロペラ装置, 翼角, CPPハブ. Viết tắt CPP; đối lập 固定ピッチプロペラ (FPP).","context_vi":"Dùng trên phà, tàu kéo, tàu dịch vụ dầu khí cần điều động nhiều và máy chính chạy tốc độ không đổi.","ex_en":"The tug uses a controllable pitch propeller so the engine can run at constant speed.","ex_ja":"このタグボートは可変ピッチプロペラを使い、機関を一定回転で運転できる。","ex_vi":"Tàu kéo dùng chân vịt biến bước nên máy chính chạy ở tốc độ không đổi.","syn_en":["CPP","variable pitch propeller"],"syn_ja":["CPP","固定ピッチプロペラ (đối lập, liên quan)"]}]},{"id":95,"words":[{"en":"excavator","pos":"noun","ipa":"/ˈɛkskəˌveɪtər/","ja":"油圧ショベル","kana":"ゆあつショベル","romaji":"yuatsushoberu","vi":"máy đào (máy xúc đào)","level":1,"def_vi":"Máy xây dựng thủy lực có cần, tay gầu và gầu lắp trên thân quay 360°, dùng để đào đất, xúc và nâng vật.","def_en":"A hydraulic machine with boom, arm and bucket on a 360° rotating upper structure, used for digging and loading.","def_ja":"360度旋回する上部旋回体にブーム・アーム・バケットを備え、掘削や積込みを行う油圧式の建設機械。","usage_en":"Danh từ đếm được. Hay đi với: crawler excavator, wheeled excavator, 20-tonne excavator, excavator operator; Mỹ cũng gọi trackhoe, Anh gọi digger (khẩu ngữ).","usage_ja":"Hay đi với: 油圧ショベルで掘削する, 20トンクラス. Ngoài công trường gọi バックホウ, ユンボ (tên thương mại) hoặc パワーショベル.","context_vi":"Dùng ở công trường đào móng, san lấp, khai thác mỏ, phá dỡ và trong thiết kế, bảo dưỡng máy công trình.","ex_en":"The excavator loads a dump truck every two minutes.","ex_ja":"油圧ショベルが2分ごとにダンプトラックに積込みを行う。","ex_vi":"Máy đào chất đầy một xe ben cứ mỗi hai phút.","syn_en":["digger (Anh, khẩu ngữ)","hydraulic excavator"],"syn_ja":["バックホウ","ユンボ (khẩu ngữ)"]},{"en":"bulldozer","pos":"noun","ipa":"/ˈbʊlˌdoʊzər/","ja":"ブルドーザ","kana":"ブルドーザ","romaji":"burudooza","vi":"máy ủi","level":1,"def_vi":"Máy kéo bánh xích có lưỡi ủi lớn phía trước, dùng để ủi, san và đẩy đất đá.","def_en":"A crawler tractor with a large front blade used to push, spread and level soil and rock.","def_ja":"前部に大きな排土板を備えた履帯式トラクタで、土砂を押し・広げ・整地する。","usage_en":"Danh từ đếm được; khẩu ngữ: dozer. Hay đi với: crawler bulldozer, bulldozer blade, push with a bulldozer; động từ bulldoze.","usage_ja":"Hay đi với: ブルドーザで押土する, 湿地ブルドーザ. Cũng viết ブルドーザー; khẩu ngữ: ブル, ドーザ.","context_vi":"Dùng trong san lấp mặt bằng, làm đường, khai thác mỏ và phá rừng.","ex_en":"A bulldozer spread the fill material in 30 cm layers.","ex_ja":"ブルドーザで盛土材を30 cmずつ敷き均した。","ex_vi":"Máy ủi san vật liệu đắp thành từng lớp 30 cm.","syn_en":["dozer (khẩu ngữ)","crawler tractor"],"syn_ja":["ブルドーザー","ブル (khẩu ngữ)"]},{"en":"wheel loader","pos":"noun phrase","ipa":"/ˈwiːl ˌloʊdər/","ja":"ホイールローダ","kana":"ホイールローダ","romaji":"hoiirurooda","vi":"máy xúc lật","level":1,"def_vi":"Máy bánh lốp, thân khớp gập, có gầu lớn phía trước để xúc vật liệu rời và đổ lên xe tải.","def_en":"A wheeled, articulated machine with a large front bucket for scooping bulk material and loading trucks.","def_ja":"前部に大型バケットを備えたタイヤ式の車体屈折型機械で、ばら物をすくい積込む。","usage_en":"Cụm danh từ đếm được; khẩu ngữ: loader, front-end loader (Mỹ). Hay đi với: wheel loader bucket, compact wheel loader.","usage_ja":"Hay đi với: ホイールローダで積込む, バケット容量. Khẩu ngữ: ローダ, タイヤショベル (JIS cũ).","context_vi":"Dùng ở mỏ đá, bãi cát, nhà máy xi măng, cảng và trạm trộn bê tông.","ex_en":"The wheel loader feeds aggregate into the batching plant hopper.","ex_ja":"ホイールローダが骨材をバッチャープラントのホッパへ投入する。","ex_vi":"Máy xúc lật đổ cốt liệu vào phễu trạm trộn.","syn_en":["front-end loader (Mỹ)","loader (khẩu ngữ)"],"syn_ja":["タイヤショベル","ローダ (khẩu ngữ)"]},{"en":"dump truck","pos":"noun phrase","ipa":"/ˈdʌmp ˌtrʌk/","ja":"ダンプトラック","kana":"ダンプトラック","romaji":"danputorakku","vi":"xe ben (xe tự đổ)","level":1,"def_vi":"Xe tải có thùng nâng nghiêng bằng xi lanh thủy lực để tự đổ vật liệu như đất, đá, cát.","def_en":"A truck whose body is tilted by hydraulic cylinders to unload material such as soil, rock or sand.","def_ja":"油圧シリンダで荷台を傾け、土砂や砕石などを自ら降ろすトラック。","usage_en":"Cụm danh từ đếm được; Anh gọi dumper hoặc tipper. Hay đi với: off-highway / rigid dump truck, articulated dump truck (ADT), dump body.","usage_ja":"Hay đi với: ダンプトラックに積込む, 重ダンプ, アーティキュレートダンプ. Khẩu ngữ: ダンプ.","context_vi":"Dùng trong vận chuyển đất đá ở công trường, mỏ lộ thiên và thi công đường.","ex_en":"Each 100-tonne dump truck makes 25 trips per shift.","ex_ja":"100トン級のダンプトラックは1シフトに25往復する。","ex_vi":"Mỗi xe ben 100 tấn chạy 25 chuyến mỗi ca.","syn_en":["dumper (Anh)","tipper truck (Anh)"],"syn_ja":["ダンプ (khẩu ngữ)","ダンプカー"]},{"en":"road roller","pos":"noun phrase","ipa":"/ˈroʊd ˌroʊlər/","ja":"ロードローラ","kana":"ロードローラ","romaji":"roodoroora","vi":"xe lu (máy lu)","level":1,"def_vi":"Máy lu lèn có trống thép hoặc bánh lốp nặng để đầm chặt đất, cấp phối và bê tông nhựa.","def_en":"A compaction machine with heavy steel drums or tires used to compact soil, base course and asphalt.","def_ja":"重い鉄輪やタイヤで土・路盤・アスファルトを締め固める機械。","usage_en":"Cụm danh từ đếm được; kỹ sư hay gọi compactor hoặc roller. Hay đi với: vibratory roller, tandem roller, pneumatic tire roller, roller pass.","usage_ja":"Hay đi với: 振動ローラ, タイヤローラ, マカダムローラ, 転圧する. Khẩu ngữ: ローラ; cũng viết ロードローラー.","context_vi":"Dùng trong thi công nền đường, mặt đường nhựa, đập đất và sân bay.","ex_en":"The road roller made eight passes to reach 95 percent compaction.","ex_ja":"ロードローラで8回転圧し、締固め度95%を達成した。","ex_vi":"Xe lu chạy tám lượt để đạt độ chặt 95%.","syn_en":["compactor","roller (khẩu ngữ)"],"syn_ja":["ローラ (khẩu ngữ)","締固め機械 (nghĩa rộng)"]},{"en":"bucket","pos":"noun","ipa":"/ˈbʌkɪt/","ja":"バケット","kana":"バケット","romaji":"baketto","vi":"gầu","level":1,"def_vi":"Bộ phận công tác dạng thùng có răng ở máy đào, máy xúc lật dùng để cắt, xúc và chứa vật liệu.","def_en":"The toothed scoop on an excavator or loader that cuts, scoops and carries material.","def_ja":"油圧ショベルやローダの先端にある爪付きの容器状作業装置で、土砂を掘りすくう。","usage_en":"Danh từ đếm được. Hay đi với: bucket capacity, bucket teeth, bucket cylinder, rock bucket; dung tích tính bằng m³.","usage_ja":"Hay đi với: バケット容量, バケットツース, 法面バケット. Chỉ dùng katakana.","context_vi":"Dùng khi chọn máy theo dung tích gầu, thay răng gầu và hàn đắp chống mòn.","ex_en":"The worn bucket teeth were replaced before the rock excavation.","ex_ja":"岩盤掘削の前に摩耗したバケットのツースを交換した。","ex_vi":"Răng gầu bị mòn được thay trước khi đào đá.","syn_en":["scoop (khẩu ngữ)"],"syn_ja":["ショベル (nghĩa gần)"]},{"en":"crawler track","pos":"noun phrase","ipa":"/ˈkrɔːlər ˌtræk/","ja":"履帯","kana":"りたい","romaji":"ritai","vi":"xích di chuyển (dải xích)","level":1,"def_vi":"Dải xích vô tận gồm các mắt xích và guốc xích chạy quanh bánh sao, giúp máy di chuyển trên nền yếu.","def_en":"An endless chain of links and shoes running around sprockets and idlers, letting machines travel on soft ground.","def_ja":"リンクとシューを連ねた無端帯で、スプロケットと遊動輪に掛けて軟弱地でも走行できる。","usage_en":"Cụm danh từ đếm được; thường nói tracks. Hay đi với: track shoe, track tension, steel / rubber tracks; Caterpillar là tên thương hiệu.","usage_ja":"Hay đi với: 履帯張り, 履帯シュー, ゴム履帯. Ngoài công trường nói クローラ hoặc キャタピラ (tên thương mại).","context_vi":"Dùng trên máy đào, máy ủi, cần cẩu bánh xích; khi chỉnh độ căng xích và thay guốc xích.","ex_en":"Check the crawler track tension daily on muddy sites.","ex_ja":"泥の多い現場では履帯の張りを毎日点検すること。","ex_vi":"Ở công trường lầy cần kiểm tra độ căng xích di chuyển hằng ngày.","syn_en":["track","crawler"],"syn_ja":["クローラ","キャタピラ (tên thương mại)"]},{"en":"boom","pos":"noun","ipa":"/buːm/","ja":"ブーム","kana":"ブーム","romaji":"buumu","vi":"cần (cần chính)","level":1,"def_vi":"Cánh tay chính gắn vào thân máy đào hoặc cần trục, được xi lanh thủy lực nâng hạ.","def_en":"The main arm attached to the machine body of an excavator or crane, raised and lowered by hydraulic cylinders.","def_ja":"油圧ショベルやクレーンの本体に取り付けられ、シリンダで起伏する主腕。","usage_en":"Danh từ đếm được. Hay đi với: boom cylinder, raise / lower the boom, long-reach boom, telescopic boom.","usage_ja":"Hay đi với: ブームシリンダ, ブーム上げ/下げ, ロングブーム. Chỉ dùng katakana.","context_vi":"Dùng khi vận hành, thiết kế kết cấu hàn của máy đào, cần cẩu, xe bơm bê tông và kiểm tra vết nứt.","ex_en":"A crack was found at the boom foot of the excavator.","ex_ja":"油圧ショベルのブームフート部にき裂が見つかった。","ex_vi":"Phát hiện vết nứt ở chân cần của máy đào.","syn_en":["main boom","jib (cần cẩu, nghĩa gần)"],"syn_ja":["主ブーム","ジブ (cần phụ, liên quan)"]},{"en":"concrete mixer truck","pos":"noun phrase","ipa":"/ˈkɑːŋkriːt ˌmɪksər ˌtrʌk/","ja":"トラックミキサ","kana":"トラックミキサ","romaji":"torakkumikisa","vi":"xe bồn trộn bê tông","level":1,"def_vi":"Xe tải mang thùng trộn quay liên tục để chở bê tông tươi từ trạm trộn đến công trường mà không bị phân tầng.","def_en":"A truck with a rotating drum that carries ready-mixed concrete from the plant to site without segregation.","def_ja":"回転するドラムを備え、生コンクリートを分離させずに工場から現場へ運ぶトラック。","usage_en":"Cụm danh từ đếm được; khẩu ngữ: mixer truck, cement truck (Mỹ). Hay đi với: drum capacity, 7 m³ mixer, discharge chute.","usage_ja":"Hay đi với: トラックミキサの荷卸し, ドラム容量. Ngoài công trường gọi 生コン車 hoặc アジテータ車; cũng viết トラックミキサー.","context_vi":"Dùng trong cung ứng bê tông thương phẩm, đổ bê tông móng, sàn và xây cầu.","ex_en":"The concrete mixer truck must discharge within 90 minutes of batching.","ex_ja":"トラックミキサは練混ぜから90分以内に荷卸ししなければならない。","ex_vi":"Xe bồn trộn bê tông phải xả hết trong vòng 90 phút kể từ khi trộn.","syn_en":["mixer truck","transit mixer"],"syn_ja":["生コン車 (khẩu ngữ)","アジテータ車"]},{"en":"operator's cab","pos":"noun phrase","ipa":"/ˈɑːpəˌreɪtərz ˈkæb/","ja":"運転室","kana":"うんてんしつ","romaji":"untenshitsu","vi":"cabin người vận hành","level":1,"def_vi":"Buồng kín trên máy công trình nơi người lái ngồi điều khiển, có cần gạt, màn hình và kết cấu bảo vệ.","def_en":"The enclosed compartment where the operator sits and controls the machine, with levers, monitor and protective structure.","def_ja":"操作レバーやモニタを備え、オペレータが乗って機械を操作する囲われた区画。","usage_en":"Cụm danh từ đếm được; nói gọn cab. Hay đi với: cab glass, cab noise level, pressurized cab, climb into the cab.","usage_ja":"Hay đi với: 運転室内騒音, 運転室ガラス. Ngoài công trường nói キャブ hoặc 運転席.","context_vi":"Dùng trong thiết kế công thái học, đo tiếng ồn, điều hòa và an toàn cho người vận hành.","ex_en":"The new operator's cab reduces noise to 69 dB(A).","ex_ja":"新しい運転室は騒音を69 dB(A)まで低減した。","ex_vi":"Cabin người vận hành mới giảm tiếng ồn xuống 69 dB(A).","syn_en":["cab","cabin"],"syn_ja":["キャブ","運転席 (nghĩa gần)"]},{"en":"arm","pos":"noun","ipa":"/ɑːrm/","ja":"アーム","kana":"アーム","romaji":"aamu","vi":"tay gầu","level":2,"def_vi":"Đoạn cánh tay nối giữa cần và gầu của máy đào, được xi lanh tay gầu điều khiển để kéo gầu về phía máy.","def_en":"The member between the boom and bucket of an excavator, moved by the arm cylinder to pull the bucket in.","def_ja":"油圧ショベルのブームとバケットの間にある部材で、アームシリンダで動かす。","usage_en":"Danh từ đếm được; Mỹ hay nói stick, Anh nói dipper. Hay đi với: arm cylinder, arm in / out, long arm.","usage_ja":"Hay đi với: アームシリンダ, アーム引き/押し, ロングアーム. Chỉ dùng katakana.","context_vi":"Dùng khi vận hành, thay đổi tầm với và thiết kế bộ công tác máy đào.","ex_en":"A longer arm increases digging depth but reduces breakout force.","ex_ja":"アームを長くすると掘削深さは増えるが、掘削力は低下する。","ex_vi":"Tay gầu dài hơn tăng chiều sâu đào nhưng giảm lực đào.","syn_en":["stick (Mỹ)","dipper arm (Anh)"],"syn_ja":["スティック (ít dùng)"]},{"en":"attachment","pos":"noun","ipa":"/əˈtætʃmənt/","ja":"アタッチメント","kana":"アタッチメント","romaji":"atacchimento","vi":"thiết bị công tác thay thế (đồ gá lắp)","level":2,"def_vi":"Dụng cụ công tác lắp thay vào đầu tay gầu hoặc khung máy như búa phá, kẹp phá dỡ, mũi khoan, gầu sàng.","def_en":"An interchangeable tool fitted to a machine, such as a breaker, crusher, grapple or auger.","def_ja":"ブレーカ・圧砕機・グラップル・オーガなど、機械に付け替えて使う作業装置。","usage_en":"Danh từ đếm được. Hay đi với: quick coupler, hydraulic attachment, change attachments, attachment piping.","usage_ja":"Hay đi với: アタッチメント交換, クイックカプラ, アタッチメント配管. Chỉ dùng katakana.","context_vi":"Dùng khi đa năng hóa máy đào cho phá dỡ, lâm nghiệp, khoan cọc và khi lắp đường ống thủy lực phụ.","ex_en":"The quick coupler lets the operator change the attachment in one minute.","ex_ja":"クイックカプラにより、オペレータは1分でアタッチメントを交換できる。","ex_vi":"Khớp nối nhanh giúp người lái thay thiết bị công tác trong một phút.","syn_en":["work tool","implement (máy kéo)"],"syn_ja":["作業装置","フロントアタッチメント"]},{"en":"hydraulic breaker","pos":"noun phrase","ipa":"/haɪˈdrɔːlɪk ˈbreɪkər/","ja":"油圧ブレーカ","kana":"ゆあつブレーカ","romaji":"yuatsubureeka","vi":"búa phá đá thủy lực","level":2,"def_vi":"Thiết bị lắp trên máy đào, dùng piston thủy lực đập mũi đục liên tục để phá đá, bê tông.","def_en":"An excavator attachment whose hydraulic piston hammers a chisel repeatedly to break rock or concrete.","def_ja":"油圧ショベルに取り付け、油圧ピストンでチゼルを連打して岩やコンクリートを破砕する装置。","usage_en":"Cụm danh từ đếm được; khẩu ngữ: hammer, rock breaker. Hay đi với: breaker chisel, blow frequency, breaker piping.","usage_ja":"Hay đi với: 油圧ブレーカで小割する, ブレーカのチゼル. Khẩu ngữ: ブレーカ, ハンマ; cũng viết ブレーカー.","context_vi":"Dùng trong phá dỡ công trình, khai thác đá, đào đường hầm và phá bê tông cũ.","ex_en":"A hydraulic breaker was used to remove the old bridge pier.","ex_ja":"古い橋脚の撤去に油圧ブレーカを使用した。","ex_vi":"Búa phá đá thủy lực được dùng để phá bỏ trụ cầu cũ.","syn_en":["hydraulic hammer","rock breaker"],"syn_ja":["ブレーカ (khẩu ngữ)","ハンマ (khẩu ngữ)"]},{"en":"motor grader","pos":"noun phrase","ipa":"/ˈmoʊtər ˌɡreɪdər/","ja":"モータグレーダ","kana":"モータグレーダ","romaji":"mootagureeda","vi":"máy san (máy san gạt)","level":2,"def_vi":"Máy bánh lốp có lưỡi san dài đặt giữa hai cầu, dùng để san phẳng, tạo mui và rãnh cho nền đường chính xác.","def_en":"A wheeled machine with a long blade between its axles, used for fine grading, crowning and ditching roads.","def_ja":"前後輪の間に長いブレードを備え、路盤の精密な整地や勾配付けを行うタイヤ式機械。","usage_en":"Cụm danh từ đếm được; khẩu ngữ: grader. Hay đi với: grader blade (moldboard), fine grading, scarifier.","usage_ja":"Hay đi với: モータグレーダで敷均す, ブレード, スカリファイヤ. Khẩu ngữ: グレーダ.","context_vi":"Dùng trong thi công nền, mặt đường, sân bay và bảo dưỡng đường đất, đường mỏ.","ex_en":"The motor grader trimmed the base course to within ±10 mm.","ex_ja":"モータグレーダで路盤を±10 mmの精度に仕上げた。","ex_vi":"Máy san gạt hoàn thiện lớp móng đường với sai số ±10 mm.","syn_en":["grader","road grader"],"syn_ja":["グレーダ","モーターグレーダー"]},{"en":"mini excavator","pos":"noun phrase","ipa":"/ˈmɪni ˈɛkskəˌveɪtər/","ja":"ミニショベル","kana":"ミニショベル","romaji":"minishoberu","vi":"máy đào mini","level":2,"def_vi":"Máy đào cỡ nhỏ, thường dưới 6 tấn, nhiều mẫu có bán kính quay đuôi nhỏ để làm việc trong không gian hẹp.","def_en":"A small excavator, usually under six tonnes, often with a short tail swing for work in tight spaces.","def_ja":"おおむね6トン未満の小型油圧ショベルで、狭い場所での作業に適する。","usage_en":"Cụm danh từ đếm được; cũng gọi compact excavator. Hay đi với: zero tail swing mini excavator, mini excavator with dozer blade.","usage_ja":"Hay đi với: 後方超小旋回ミニショベル, ミニショベルのレンタル. Khẩu ngữ: ミニユンボ, ミニバックホウ.","context_vi":"Dùng trong đào rãnh ống nước, cáp ngầm, làm vườn, công trình dân dụng và thi công trong đô thị.","ex_en":"A mini excavator dug the cable trench along the narrow street.","ex_ja":"狭い道路沿いのケーブル溝をミニショベルで掘削した。","ex_vi":"Máy đào mini đã đào rãnh cáp dọc con phố hẹp.","syn_en":["compact excavator","mini digger (Anh)"],"syn_ja":["ミニユンボ (khẩu ngữ)","ミニバックホウ"]},{"en":"dozer blade","pos":"noun phrase","ipa":"/ˈdoʊzər ˌbleɪd/","ja":"排土板","kana":"はいどばん","romaji":"haidoban","vi":"lưỡi ủi","level":2,"def_vi":"Tấm thép cong lắp phía trước máy ủi hoặc máy đào mini, dùng để đẩy, san đất và làm chân chống.","def_en":"The curved steel plate on the front of a bulldozer or mini excavator used to push and level soil.","def_ja":"ブルドーザやミニショベルの前部に付けた湾曲鋼板で、土砂を押し均す。","usage_en":"Cụm danh từ đếm được; nói gọn blade. Hay đi với: straight / semi-U / angle blade, blade tilt, cutting edge.","usage_ja":"Hay đi với: 排土板の刃先 (カッティングエッジ), チルト. Ngoài công trường nói ブレード hoặc ドーザ.","context_vi":"Dùng khi vận hành máy ủi, chọn kiểu lưỡi theo vật liệu và thay lưỡi cắt bị mòn.","ex_en":"The worn cutting edge on the dozer blade was turned over and refitted.","ex_ja":"排土板の摩耗した刃先を裏返して付け直した。","ex_vi":"Lưỡi cắt bị mòn của lưỡi ủi được lật ngược và lắp lại.","syn_en":["blade","bulldozer blade"],"syn_ja":["ブレード","ドーザ (khẩu ngữ)"]},{"en":"ripper","pos":"noun","ipa":"/ˈrɪpər/","ja":"リッパ","kana":"リッパ","romaji":"rippa","vi":"răng xới (lưỡi xới)","level":2,"def_vi":"Răng thép lớn lắp phía sau máy ủi, cắm xuống đất để xới tơi đá mềm hoặc nền cứng trước khi ủi.","def_en":"A large steel shank at the rear of a bulldozer that is driven into the ground to break up hard soil or soft rock.","def_ja":"ブルドーザ後部に付けた大きな爪で、地中に貫入させて硬い地盤や軟岩を掘り起こす。","usage_en":"Danh từ đếm được. Hay đi với: single-shank / multi-shank ripper, ripper tip, ripping (động từ rip).","usage_ja":"Hay đi với: リッパ作業, リッパポイント, リッパ掘削. Cũng viết リッパー.","context_vi":"Dùng trong khai thác mỏ, làm đường qua vùng đá phong hóa khi không muốn nổ mìn.","ex_en":"The ripper broke up the weathered rock without blasting.","ex_ja":"リッパで発破を使わずに風化岩を掘り起こした。","ex_vi":"Răng xới đã làm tơi lớp đá phong hóa mà không cần nổ mìn.","syn_en":["ripper shank","scarifier (loại nhỏ, liên quan)"],"syn_ja":["リッパー","スカリファイヤ (liên quan)"]},{"en":"outrigger","pos":"noun","ipa":"/ˈaʊtˌrɪɡər/","ja":"アウトリガ","kana":"アウトリガ","romaji":"autoriga","vi":"chân chống (chân chống thủy lực)","level":2,"def_vi":"Chân thủy lực vươn ra hai bên máy và tì xuống đất để mở rộng đế đỡ, chống lật khi nâng hoặc bơm.","def_en":"A hydraulic leg extended from the machine and set on the ground to widen its base and prevent tipping.","def_ja":"車体から張り出して地面に据え、支持基盤を広げて転倒を防ぐ油圧式の脚。","usage_en":"Danh từ đếm được. Hay đi với: extend / set the outriggers, outrigger pad, outrigger load, fully extended outriggers.","usage_ja":"Hay đi với: アウトリガを張り出す, アウトリガ反力, 敷板. Cũng viết アウトリガー.","context_vi":"Dùng trên xe cẩu bánh lốp, xe bơm bê tông, xe khoan; khi tính phản lực chân chống lên nền.","ex_en":"Place steel plates under each outrigger on soft ground.","ex_ja":"軟弱地盤では各アウトリガの下に鉄板を敷くこと。","ex_vi":"Trên nền yếu phải kê tấm thép dưới mỗi chân chống.","syn_en":["stabilizer leg"],"syn_ja":["アウトリガー","スタビライザ (nghĩa gần)"]},{"en":"counterweight","pos":"noun","ipa":"/ˈkaʊntərˌweɪt/","ja":"カウンタウェイト","kana":"カウンタウェイト","romaji":"kauntaweito","vi":"đối trọng","level":2,"def_vi":"Khối gang hoặc thép nặng đặt ở đuôi máy để cân bằng tải ở phía cần, tăng độ ổn định chống lật.","def_en":"A heavy cast iron or steel mass at the rear of a machine that balances the front load and improves stability.","def_ja":"機械の後部に取り付けた鋳鉄などの重りで、前方の荷重と釣り合わせ安定性を高める。","usage_en":"Danh từ đếm được, cũng viết counter-weight. Hay đi với: removable counterweight, counterweight swing radius, add counterweight.","usage_ja":"Hay đi với: カウンタウェイトの取付け, 後端旋回半径. Cũng viết カウンターウエイト; văn bản: 釣合いおもり.","context_vi":"Dùng trên máy đào, xe nâng, cần cẩu; khi vận chuyển máy phải tháo đối trọng.","ex_en":"The counterweight is removed for road transport to meet weight limits.","ex_ja":"陸送時は重量制限を満たすためカウンタウェイトを取り外す。","ex_vi":"Đối trọng được tháo ra khi vận chuyển đường bộ để đáp ứng giới hạn tải trọng.","syn_en":["counterbalance","ballast (nghĩa gần)"],"syn_ja":["カウンターウエイト","釣合いおもり"]},{"en":"undercarriage","pos":"noun","ipa":"/ˈʌndərˌkærɪdʒ/","ja":"下部走行体","kana":"かぶそうこうたい","romaji":"kabusoukoutai","vi":"cụm gầm di chuyển (phần dưới)","level":2,"def_vi":"Phần dưới của máy bánh xích gồm khung xích, xích, bánh sao, bánh dẫn hướng, con lăn và mô-tơ di chuyển.","def_en":"The lower part of a tracked machine: track frame, tracks, sprockets, idlers, rollers and travel motors.","def_ja":"履帯式機械の下部で、トラックフレーム・履帯・スプロケット・遊動輪・転輪・走行モータからなる。","usage_en":"Danh từ đếm được. Hay đi với: undercarriage wear, undercarriage inspection, track rollers, idler; chiếm phần lớn chi phí bảo dưỡng máy xích.","usage_ja":"Hay đi với: 下部走行体の摩耗, 下回り点検. Ngoài xưởng nói 足回り hoặc 下回り.","context_vi":"Dùng trong bảo dưỡng máy đào, máy ủi, đo mòn xích, con lăn và lập kế hoạch thay thế.","ex_en":"Undercarriage wear accounts for half of the machine's repair cost.","ex_ja":"下部走行体の摩耗が機械の修理費の半分を占める。","ex_vi":"Mòn cụm gầm di chuyển chiếm một nửa chi phí sửa chữa máy.","syn_en":["lower structure","track system"],"syn_ja":["足回り (khẩu ngữ)","下回り (khẩu ngữ)"]},{"en":"upper structure","pos":"noun phrase","ipa":"/ˈʌpər ˌstrʌktʃər/","ja":"上部旋回体","kana":"じょうぶせんかいたい","romaji":"joubusenkaitai","vi":"phần thân quay (cụm toa quay)","level":2,"def_vi":"Phần trên của máy đào hoặc cần cẩu gồm động cơ, bơm, cabin, đối trọng, quay được trên phần gầm.","def_en":"The upper part of an excavator or crane, carrying engine, pumps, cab and counterweight, which rotates on the undercarriage.","def_ja":"エンジン・ポンプ・運転室・カウンタウェイトを載せ、下部走行体の上で旋回する部分。","usage_en":"Cụm danh từ đếm được; cũng gọi superstructure, revolving frame. Hay đi với: upper structure swing, upper frame.","usage_ja":"Hay đi với: 上部旋回体の旋回, 旋回フレーム. Ngoài xưởng nói gọn 上部 hoặc 上物.","context_vi":"Dùng trong thiết kế khung, bố trí động cơ, bơm và khi tháo lắp vận chuyển máy lớn.","ex_en":"The upper structure rotates 360 degrees on the slewing ring.","ex_ja":"上部旋回体は旋回輪の上で360度旋回する。","ex_vi":"Phần thân quay xoay 360 độ trên vòng quay toa.","syn_en":["superstructure","revolving frame"],"syn_ja":["旋回体","上部 (khẩu ngữ)"]},{"en":"slewing ring","pos":"noun phrase","ipa":"/ˈsluːɪŋ ˌrɪŋ/","ja":"旋回輪","kana":"せんかいりん","romaji":"senkairin","vi":"vòng quay toa (ổ quay lớn)","level":2,"def_vi":"Ổ lăn đường kính lớn có vành răng, nối phần thân quay với phần gầm, chịu tải dọc trục, hướng kính và mô-men lật.","def_en":"A large-diameter geared bearing joining upper structure and undercarriage, carrying axial, radial and overturning loads.","def_ja":"上部旋回体と下部走行体を結ぶ歯付きの大径軸受で、軸荷重・ラジアル荷重・転倒モーメントを受ける。","usage_en":"Cụm danh từ đếm được; cũng gọi swing bearing, slewing bearing. Hay đi với: slewing ring bolts, swing pinion, grease the slewing ring.","usage_ja":"Hay đi với: 旋回ベアリング, 旋回輪ボルト, 旋回ピニオン. Ngoài xưởng thường nói 旋回ベアリング.","context_vi":"Dùng trong lắp ráp máy đào, cần cẩu, tuabin gió; khi kiểm tra khe hở, siết bu lông và bôi mỡ.","ex_en":"Excessive tilt clearance in the slewing ring indicates raceway wear.","ex_ja":"旋回輪のがたが大きい場合は軌道面の摩耗が疑われる。","ex_vi":"Độ rơ nghiêng lớn ở vòng quay toa cho thấy rãnh lăn đã mòn.","syn_en":["swing bearing","slewing bearing"],"syn_ja":["旋回ベアリング","旋回軸受"]},{"en":"pile driver","pos":"noun phrase","ipa":"/ˈpaɪl ˌdraɪvər/","ja":"杭打機","kana":"くいうちき","romaji":"kuiuchiki","vi":"máy đóng cọc","level":2,"def_vi":"Máy có tháp dẫn hướng và búa hoặc bộ rung để đóng, ép cọc thép hoặc bê tông xuống đất làm móng.","def_en":"A machine with a leader mast and hammer or vibrator that drives steel or concrete piles into the ground.","def_ja":"リーダとハンマや振動機を備え、鋼杭やコンクリート杭を地中に打ち込む機械。","usage_en":"Cụm danh từ đếm được. Hay đi với: diesel / hydraulic pile hammer, vibratory pile driver, pile driving rig.","usage_ja":"Hay đi với: 杭打機のリーダ, 油圧ハンマ, バイブロハンマ. Cũng viết 杭打ち機; khẩu ngữ: 杭打ち.","context_vi":"Dùng trong thi công móng cọc nhà cao tầng, cầu, cảng và tường cừ.","ex_en":"The pile driver installed 40 sheet piles along the riverbank.","ex_ja":"杭打機で川岸に沿って40枚の鋼矢板を打設した。","ex_vi":"Máy đóng cọc đã đóng 40 cừ thép dọc bờ sông.","syn_en":["piling rig","pile hammer (bộ búa, nghĩa hẹp)"],"syn_ja":["杭打ち機","杭打ち (khẩu ngữ)"]},{"en":"concrete pump truck","pos":"noun phrase","ipa":"/ˈkɑːŋkriːt ˌpʌmp ˌtrʌk/","ja":"コンクリートポンプ車","kana":"コンクリートポンプしゃ","romaji":"konkuriitoponpusha","vi":"xe bơm bê tông","level":2,"def_vi":"Xe tải lắp bơm piston và cần phân phối gập nhiều đoạn để bơm bê tông tươi lên cao hoặc ra xa.","def_en":"A truck with a piston pump and folding placing boom that pumps fresh concrete to height or distance.","def_ja":"ピストンポンプと多段式ブームを備え、生コンクリートを高所や遠方へ圧送する車両。","usage_en":"Cụm danh từ đếm được; cũng gọi boom pump. Hay đi với: 52 m boom pump, pump output, placing boom, line pump.","usage_ja":"Hay đi với: コンクリートポンプ車で打設する, ブーム車, 配管車. Khẩu ngữ: ポンプ車, ポンプ屋 (nhà thầu).","context_vi":"Dùng khi đổ bê tông sàn, cột nhà cao tầng, cầu và đường hầm.","ex_en":"The concrete pump truck placed 120 m³ of concrete in five hours.","ex_ja":"コンクリートポンプ車で5時間に120 m³のコンクリートを打設した。","ex_vi":"Xe bơm bê tông đã bơm 120 m³ bê tông trong năm giờ.","syn_en":["boom pump","concrete pump"],"syn_ja":["ポンプ車 (khẩu ngữ)","ブーム車"]},{"en":"breakout force","pos":"noun phrase","ipa":"/ˈbreɪkˌaʊt ˌfɔːrs/","ja":"掘削力","kana":"くっさくりょく","romaji":"kussakuryoku","vi":"lực đào (lực bứt gầu)","level":3,"def_vi":"Lực lớn nhất tại mép răng gầu do xi lanh gầu hoặc tay gầu tạo ra, đặc trưng khả năng đào của máy theo ISO 6015.","def_en":"The maximum force at the bucket tip produced by the bucket or arm cylinder, rated per ISO 6015.","def_ja":"バケットまたはアームシリンダによりバケット刃先に生じる最大の力で、ISO 6015で規定される。","usage_en":"Cụm danh từ không đếm được. Hay đi với: bucket breakout force, arm breakout force (arm crowd force), rated in kN.","usage_ja":"Hay đi với: バケット掘削力, アーム掘削力, 掘削力○○ kN. Cũng nói 掘起し力 cho máy xúc lật.","context_vi":"Dùng trong bảng thông số máy, so sánh máy đào và thiết kế bộ công tác.","ex_en":"The 20-tonne model has a bucket breakout force of 140 kN.","ex_ja":"20トン機のバケット掘削力は140 kNである。","ex_vi":"Mẫu máy 20 tấn có lực đào của gầu là 140 kN.","syn_en":["digging force","crowd force (lực tay gầu, liên quan)"],"syn_ja":["掘起し力 (máy xúc lật)","掘削力値"]},{"en":"ground pressure","pos":"noun phrase","ipa":"/ˈɡraʊnd ˌprɛʃər/","ja":"接地圧","kana":"せっちあつ","romaji":"setchiatsu","vi":"áp lực lên nền (áp suất tiếp đất)","level":3,"def_vi":"Áp suất trung bình máy tác dụng lên mặt đất, bằng trọng lượng máy chia diện tích tiếp xúc của xích hoặc lốp.","def_en":"The average pressure a machine exerts on the ground: machine weight divided by track or tire contact area.","def_ja":"機械の重量を履帯やタイヤの接地面積で割った、地面に加わる平均的な圧力。","usage_en":"Cụm danh từ không đếm được, đơn vị kPa. Hay đi với: low ground pressure (LGP), wide track shoes reduce ground pressure.","usage_ja":"Hay đi với: 接地圧が低い, 平均接地圧, 湿地仕様. Đơn vị kPa.","context_vi":"Dùng khi chọn máy cho nền yếu, đầm lầy, đánh giá sức chịu tải nền và tính kê lót cho cần cẩu.","ex_en":"Wide shoes cut the ground pressure to 25 kPa for work on marshland.","ex_ja":"幅広シューにより、湿地作業向けに接地圧を25 kPaまで下げた。","ex_vi":"Guốc xích rộng giảm áp lực lên nền xuống 25 kPa để làm việc ở vùng lầy.","syn_en":["bearing pressure (nghĩa gần)","LGP (low ground pressure, liên quan)"],"syn_ja":["平均接地圧"]},{"en":"tipping load","pos":"noun phrase","ipa":"/ˈtɪpɪŋ ˌloʊd/","ja":"転倒荷重","kana":"てんとうかじゅう","romaji":"tentoukajuu","vi":"tải trọng lật","level":3,"def_vi":"Tải trọng tại gầu hoặc móc làm bánh sau máy vừa nhấc khỏi mặt đất; tải làm việc định mức chỉ là một phần của nó.","def_en":"The load at the bucket or hook that just lifts the rear of the machine; rated operating load is a fraction of it.","def_ja":"機械の後部がちょうど浮き上がるときのバケットやフックの荷重で、定格荷重はその一定割合とする。","usage_en":"Cụm danh từ đếm được. Hay đi với: static tipping load, full-turn tipping load; rated operating load = 50% tipping load cho máy xúc lật.","usage_ja":"Hay đi với: 静的転倒荷重, 全旋回転倒荷重, 定格荷重. Liên quan chặt với 安定度.","context_vi":"Dùng trong bảng thông số máy xúc lật, máy đào nâng hạ và tính ổn định khi thiết kế.","ex_en":"The full-turn static tipping load of the loader is 12,000 kg.","ex_ja":"このローダの全旋回時静的転倒荷重は12,000 kgである。","ex_vi":"Tải trọng lật tĩnh khi lái gập tối đa của máy xúc lật là 12.000 kg.","syn_en":["static tipping load"],"syn_ja":["静的転倒荷重","定格荷重 (liên quan)"]},{"en":"rollover protective structure","pos":"noun phrase","ipa":"/ˈroʊlˌoʊvər prəˈtɛktɪv ˌstrʌktʃər/","ja":"転倒時保護構造","kana":"てんとうじほごこうぞう","romaji":"tentoujihogokouzou","vi":"khung bảo vệ chống lật (ROPS)","level":3,"def_vi":"Khung hoặc cabin gia cường bảo vệ người lái không bị đè khi máy lật, được thử nghiệm theo ISO 3471.","def_en":"A reinforced frame or cab that protects the operator from being crushed if the machine rolls over, tested to ISO 3471.","def_ja":"機械が転倒した際にオペレータが押しつぶされないよう保護する補強フレームやキャブ。","usage_en":"Cụm danh từ đếm được, gần như luôn viết tắt ROPS; kèm FOPS (chống vật rơi). Hay đi với: ROPS cab, ROPS certification, wear the seat belt with ROPS.","usage_ja":"Hay đi với: ROPSキャブ, FOPS, ROPS認証. Thường viết tắt ROPS (ロプス).","context_vi":"Dùng trong thiết kế cabin, chứng nhận an toàn máy công trình, máy kéo nông nghiệp.","ex_en":"The rollover protective structure saved the operator when the dozer overturned.","ex_ja":"ブルドーザが転倒した際、転倒時保護構造がオペレータを守った。","ex_vi":"Khung bảo vệ chống lật đã cứu người lái khi máy ủi bị lật.","syn_en":["ROPS","FOPS (chống vật rơi, liên quan)"],"syn_ja":["ROPS","転倒保護構造"]},{"en":"load-sensing system","pos":"noun phrase","ipa":"/ˈloʊd ˌsɛnsɪŋ ˌsɪstəm/","ja":"ロードセンシングシステム","kana":"ロードセンシングシステム","romaji":"roodosenshingushisutemu","vi":"hệ thống thủy lực cảm biến tải (load-sensing)","level":3,"def_vi":"Hệ thủy lực trong đó bơm thay đổi lưu lượng chỉ cung cấp đủ áp suất và lưu lượng mà cơ cấu chấp hành cần, giảm tổn thất.","def_en":"A hydraulic system in which a variable pump supplies only the pressure and flow the actuators demand, cutting losses.","def_ja":"可変ポンプがアクチュエータの必要とする圧力と流量だけを供給し、損失を減らす油圧方式。","usage_en":"Cụm danh từ đếm được, viết tắt LS. Hay đi với: load-sensing pump, LS pressure, load-sensing valve, CLSS (Komatsu).","usage_ja":"Hay đi với: ロードセンシング制御, LS弁, LS差圧. Viết tắt LS; Komatsu dùng tên CLSS.","context_vi":"Dùng trong thiết kế mạch thủy lực máy đào, máy xúc lật, máy nông nghiệp để tiết kiệm nhiên liệu và điều khiển mịn.","ex_en":"The load-sensing system reduced fuel consumption by 10 percent.","ex_ja":"ロードセンシングシステムにより燃料消費量を10%削減した。","ex_vi":"Hệ thống thủy lực cảm biến tải giảm 10% mức tiêu hao nhiên liệu.","syn_en":["LS system","load-sensing hydraulics"],"syn_ja":["LSシステム","ロードセンシング制御"]},{"en":"machine guidance","pos":"noun phrase","ipa":"/məˈʃiːn ˌɡaɪdəns/","ja":"マシンガイダンス","kana":"マシンガイダンス","romaji":"mashingaidansu","vi":"hệ thống dẫn hướng máy (machine guidance)","level":3,"def_vi":"Hệ thống dùng GNSS và cảm biến góc để hiển thị vị trí lưỡi gầu so với mô hình thiết kế, giúp người lái đào đúng cao độ.","def_en":"A system using GNSS and angle sensors to show the bucket or blade position against the design model to the operator.","def_ja":"GNSSと角度センサで刃先の位置を設計データと比較してオペレータに表示するシステム。","usage_en":"Cụm danh từ không đếm được, viết tắt MG; nếu máy tự điều khiển cần, lưỡi thì gọi machine control (MC). Hay đi với: 3D machine guidance, GNSS rover.","usage_ja":"Hay đi với: 3Dマシンガイダンス, マシンコントロール (MC), ICT施工. Viết tắt MG.","context_vi":"Dùng trong thi công số hóa (ICT施工 ở Nhật), san nền, đào mái taluy chính xác không cần cọc mốc.","ex_en":"With machine guidance, the operator trimmed the slope without survey stakes.","ex_ja":"マシンガイダンスを使い、オペレータは丁張りなしで法面を仕上げた。","ex_vi":"Nhờ hệ thống dẫn hướng máy, người lái hoàn thiện mái dốc mà không cần cọc mốc trắc đạc.","syn_en":["MG","machine control (MC, nghĩa gần)"],"syn_ja":["MG","マシンコントロール (nghĩa gần)"]}]},{"id":96,"words":[{"en":"forklift","pos":"noun","ipa":"/ˈfɔːrklɪft/","ja":"フォークリフト","kana":"フォークリフト","romaji":"fookurifuto","vi":"xe nâng","level":1,"def_vi":"Xe tự hành có hai càng nâng phía trước, dùng để nâng, hạ và di chuyển pallet hoặc hàng hóa trong kho, xưởng.","def_en":"A powered truck with two front forks used to lift, lower and move pallets and goods.","def_ja":"車体前方の2本のフォークで、パレットや荷を持ち上げて運ぶ荷役車両。","usage_en":"Danh từ đếm được. Hay đi với: drive / operate a forklift, forklift driver, electric / diesel forklift, forklift license; viết liền forklift (đôi khi fork-lift truck ở Anh).","usage_ja":"Động từ đi kèm: フォークリフトを運転する, フォークリフトで運ぶ; người lái gọi là フォークリフト運転者. Ngoài xưởng hay gọi tắt là フォーク.","context_vi":"Dùng hằng ngày trong kho hàng, khu vực nhận/xuất hàng, xưởng sản xuất để bốc xếp pallet lên xe tải và lên giá kệ.","ex_en":"Only certified operators may drive the forklift in the loading area.","ex_ja":"荷積みエリアでは、資格を持つ者だけがフォークリフトを運転できる。","ex_vi":"Chỉ người vận hành có chứng chỉ mới được lái xe nâng trong khu vực bốc hàng.","syn_en":["lift truck","fork truck"],"syn_ja":["フォーク (khẩu ngữ)","フォークリフトトラック (văn bản)"]},{"en":"pallet","pos":"noun","ipa":"/ˈpælɪt/","ja":"パレット","kana":"パレット","romaji":"paretto","vi":"tấm kê hàng (pallet)","level":1,"def_vi":"Tấm sàn bằng gỗ, nhựa hoặc thép có khe để càng xe nâng luồn vào, dùng để gom và vận chuyển hàng theo đơn vị.","def_en":"A flat wooden, plastic or steel platform with openings for forks, used to handle goods as a unit load.","def_ja":"フォークを差し込む穴をもつ木製・樹脂製・鋼製の台で、荷をまとめて扱うためのもの。","usage_en":"Danh từ đếm được. Hay đi với: load / stack / wrap a pallet, wooden pallet, pallet load, per pallet; tránh viết nhầm thành palette (bảng màu).","usage_ja":"Hay đi với: パレットに積む, パレット積み, 木製パレット, プラスチックパレット, パレット単位で出荷する. Trong xưởng Việt Nam người Nhật cũng hiểu từ pallet tiếng Anh.","context_vi":"Dùng trong kho, logistics, đóng gói xuất hàng và khi tính số lượng hàng trên mỗi lần vận chuyển.","ex_en":"Each pallet carries 40 gearboxes and must not exceed 1,000 kg.","ex_ja":"1枚のパレットにギヤボックスを40台積み、1,000 kgを超えてはならない。","ex_vi":"Mỗi pallet chở 40 hộp số và không được vượt quá 1.000 kg.","syn_en":["skid (Mỹ, loại không có ván đáy)"],"syn_ja":["スキッド (loại không có ván đáy)","荷役台 (văn bản, ít dùng)"]},{"en":"belt conveyor","pos":"noun","ipa":"/ˈbelt kənˌveɪər/","ja":"ベルトコンベヤ","kana":"ベルトコンベヤ","romaji":"berutokonbeya","vi":"băng tải đai (băng tải)","level":1,"def_vi":"Thiết bị vận chuyển liên tục dùng một dải băng vô tận chạy vòng qua các tang trống để mang vật liệu hoặc chi tiết.","def_en":"A continuous conveyor in which an endless belt running over pulleys carries materials or parts.","def_ja":"プーリに掛けた無端ベルトを走らせて、物や部品を連続して運ぶコンベヤ。","usage_en":"Danh từ đếm được. Hay đi với: run / stop the belt conveyor, belt conveyor line, troughed belt conveyor; dải băng gọi là conveyor belt, còn cả thiết bị là belt conveyor.","usage_ja":"Hay đi với: ベルトコンベヤで搬送する, ベルトコンベヤを止める, ベルトの蛇行. Cách viết コンベヤ (JIS) và コンベア đều phổ biến; khẩu ngữ gọi ベルコン.","context_vi":"Dùng trong dây chuyền lắp ráp, đóng gói, mỏ, xi măng, cảng để chuyển vật liệu rời hoặc chi tiết giữa các công đoạn.","ex_en":"The belt conveyor stops automatically when the pull-cord switch is activated.","ex_ja":"非常停止ロープスイッチを引くと、ベルトコンベヤは自動で停止する。","ex_vi":"Băng tải đai tự động dừng khi công tắc dây kéo khẩn cấp bị kích hoạt.","syn_en":["conveyor belt (khẩu ngữ)","conveyor (nghĩa rộng hơn)"],"syn_ja":["ベルコン (khẩu ngữ)","ベルトコンベア"]},{"en":"overhead crane","pos":"noun","ipa":"/ˌoʊvərhed ˈkreɪn/","ja":"天井クレーン","kana":"てんじょうクレーン","romaji":"tenjoukureen","vi":"cầu trục","level":1,"def_vi":"Cần trục có dầm cầu chạy trên ray gắn cao trong nhà xưởng, mang xe con và palăng để nâng hạ, di chuyển tải.","def_en":"A crane with a bridge girder running on elevated rails inside a building, carrying a hoist trolley.","def_ja":"建屋の高所のレール上を走行するガーダにトロリやホイストを備えたクレーン。","usage_en":"Danh từ đếm được. Hay đi với: 10-ton overhead crane, operate the overhead crane, single-girder / double-girder overhead crane; ở nhà máy thường nói gọn là the crane.","usage_ja":"Hay đi với: 天井クレーンで吊る, 天井クレーンの運転, 10トン天井クレーン. Vận hành loại từ 5 tấn trở lên ở Nhật cần giấy phép クレーン運転士.","context_vi":"Dùng trong xưởng cơ khí, nhà máy thép, xưởng lắp ráp máy để nâng phôi, khuôn và cụm máy nặng.","ex_en":"The 20-ton overhead crane is inspected every month before use.","ex_ja":"20トンの天井クレーンは毎月点検してから使用する。","ex_vi":"Cầu trục 20 tấn được kiểm tra hằng tháng trước khi sử dụng.","syn_en":["bridge crane","EOT crane (electric overhead travelling crane)"],"syn_ja":["天井走行クレーン (văn bản)","ホイストクレーン (loại dùng palăng điện)"]},{"en":"hoist","pos":"noun","ipa":"/hɔɪst/","ja":"ホイスト","kana":"ホイスト","romaji":"hoisuto","vi":"palăng (palăng điện)","level":1,"def_vi":"Thiết bị gọn nhẹ gồm động cơ, tang cuốn cáp hoặc xích và móc, dùng để nâng hạ tải theo phương thẳng đứng.","def_en":"A compact unit with a motor, drum or chain wheel and hook, used to raise and lower loads vertically.","def_ja":"電動機、ドラムまたはチェーン車、フックを一体にし、荷を垂直に巻き上げ・巻き下げる装置。","usage_en":"Danh từ đếm được; cũng là động từ (hoist the load). Hay đi với: electric hoist, wire rope hoist, chain hoist, hoist capacity, mount a hoist on a monorail.","usage_ja":"Hay đi với: 電動ホイスト, ワイヤロープ式ホイスト, ホイストで巻き上げる. Trong hội thoại 巻き上げる/巻き下げる là động từ chính cho thao tác nâng/hạ.","context_vi":"Dùng trên cầu trục, monoray, cổng trục nhỏ trong xưởng để nâng chi tiết, khuôn, động cơ.","ex_en":"A 2-ton electric hoist was installed on the monorail above the press line.","ex_ja":"プレスラインの上のモノレールに2トンの電動ホイストを取り付けた。","ex_vi":"Một palăng điện 2 tấn đã được lắp trên monoray phía trên dây chuyền dập.","syn_en":["electric hoist","chain hoist (loại dùng xích)"],"syn_ja":["電動ホイスト","巻上げ機 (nghĩa rộng hơn)"]},{"en":"crane hook","pos":"noun","ipa":"/ˈkreɪn hʊk/","ja":"フック","kana":"フック","romaji":"fukku","vi":"móc cẩu","level":1,"def_vi":"Móc thép rèn treo ở đầu cáp hoặc xích của cần trục, dùng để móc cáp cẩu hoặc dụng cụ treo tải.","def_en":"A forged steel hook at the end of a crane's rope or chain that holds slings or lifting gear.","def_ja":"クレーンのロープやチェーンの先端に付く鍛造鋼のかぎで、玉掛け用具を掛けるもの。","usage_en":"Danh từ đếm được. Hay đi với: hook block, hook throat, hook opening, attach the sling to the crane hook; kiểm tra hook opening (độ mở miệng móc) để phát hiện biến dạng.","usage_ja":"Hay đi với: フックに掛ける, フックを外す, フックブロック, フックの口開き. Trong ngữ cảnh cẩu, chỉ nói フック là đủ hiểu.","context_vi":"Dùng khi kiểm tra hằng ngày cầu trục, palăng, khi móc tải và khi đánh giá biến dạng, nứt của móc.","ex_en":"The crane hook must be replaced if its throat opening has increased by more than 5 %.","ex_ja":"フックの口開きが5 %を超えて広がった場合は交換しなければならない。","ex_vi":"Móc cẩu phải được thay nếu độ mở miệng móc tăng quá 5 %.","syn_en":["lifting hook","load hook"],"syn_ja":["吊りフック","クレーンフック"]},{"en":"sling","pos":"noun","ipa":"/slɪŋ/","ja":"スリング","kana":"スリング","romaji":"suringu","vi":"cáp cẩu / dây cẩu (sling)","level":1,"def_vi":"Dây cáp thép, xích hoặc dây vải bản dẹt dùng để buộc, treo tải vào móc cẩu.","def_en":"A wire rope, chain or textile strap used to attach a load to the crane hook.","def_ja":"ワイヤロープ、チェーン、繊維ベルトなどで、荷をフックに吊るためのもの。","usage_en":"Danh từ đếm được; cũng là động từ (sling a load). Hay đi với: wire rope sling, chain sling, webbing sling, round sling, two-leg sling, inspect the slings.","usage_ja":"Hay đi với: ベルトスリング, ラウンドスリング, ワイヤスリング, スリングを掛ける. Ngoài công trường cáp thép hay gọi là 玉掛けワイヤ.","context_vi":"Dùng trong mọi công việc móc cẩu ở xưởng, công trường, cảng; phải kiểm tra trước khi dùng và loại bỏ khi bị đứt sợi, xoắn, cắt rách.","ex_en":"Use a webbing sling to protect the machined surface from scratches.","ex_ja":"加工面に傷を付けないよう、ベルトスリングで吊ること。","ex_vi":"Dùng dây cẩu vải bản dẹt để bảo vệ bề mặt gia công khỏi trầy xước.","syn_en":["lifting sling"],"syn_ja":["玉掛け用具 (nghĩa rộng hơn)","吊り具 (nghĩa rộng hơn)"]},{"en":"shackle","pos":"noun","ipa":"/ˈʃækəl/","ja":"シャックル","kana":"シャックル","romaji":"shakkuru","vi":"ma ní","level":1,"def_vi":"Chi tiết thép hình chữ U hoặc chữ D có chốt ren ngang miệng, dùng để nối cáp, xích với tai cẩu hoặc móc.","def_en":"A U- or D-shaped steel link closed by a screw pin, used to connect slings, chains and lifting points.","def_ja":"U字またはD字形の本体をボルトピンで閉じ、ワイヤやチェーンと吊り金具をつなぐ金具。","usage_en":"Danh từ đếm được. Hay đi với: D-shackle, bow shackle, screw-pin shackle, shackle pin, rated shackle; động từ: fit / tighten the shackle pin.","usage_ja":"Hay đi với: シャックルを付ける, シャックルのピンを締める, ストレートシャックル, バウシャックル. Thường ghi tải định mức trên thân (使用荷重).","context_vi":"Dùng khi nối dây cẩu vào tai cẩu của khuôn, kết cấu thép, thiết bị trong lắp đặt và bốc xếp.","ex_en":"Fit a 3.25-ton shackle to each lifting lug before attaching the slings.","ex_ja":"スリングを掛ける前に、各吊りピースに3.25トンのシャックルを取り付ける。","ex_vi":"Lắp ma ní 3,25 tấn vào từng tai cẩu trước khi móc dây cẩu.","syn_en":["D-shackle (một loại)","bow shackle (một loại)"],"syn_ja":["ストレートシャックル (một loại)","バウシャックル (một loại)"]},{"en":"hand pallet truck","pos":"noun","ipa":"/ˌhænd ˈpælɪt trʌk/","ja":"ハンドパレットトラック","kana":"ハンドパレットトラック","romaji":"handoparettotorakku","vi":"xe nâng tay","level":1,"def_vi":"Xe đẩy tay có hai càng và bơm thủy lực để nâng pallet lên một chút rồi kéo đi trên nền phẳng.","def_en":"A manually pushed truck with forks and a hydraulic pump that slightly raises a pallet for moving.","def_ja":"フォークと油圧ポンプを備え、パレットを少し持ち上げて人力で運ぶ台車。","usage_en":"Danh từ đếm được. Hay đi với: pump up / lower the hand pallet truck, push / pull a hand pallet truck; người Mỹ thường nói pallet jack.","usage_ja":"Trong xưởng Nhật gần như luôn gọi là ハンドリフト; ハンドパレットトラック là tên chính thức trong catalog. Động từ: ハンドリフトで運ぶ, ポンプで上げる.","context_vi":"Dùng để di chuyển pallet quãng ngắn trong kho, khu đóng gói, cạnh dây chuyền khi không cần xe nâng.","ex_en":"Move the pallet to the packing area with the hand pallet truck.","ex_ja":"ハンドパレットトラックでパレットを梱包エリアへ移動してください。","ex_vi":"Hãy dùng xe nâng tay chuyển pallet sang khu đóng gói.","syn_en":["pallet jack (Mỹ)","pump truck (khẩu ngữ)"],"syn_ja":["ハンドリフト (khẩu ngữ phổ biến)","ハンドパレット"]},{"en":"rated load","pos":"noun phrase","ipa":"/ˌreɪtɪd ˈloʊd/","ja":"定格荷重","kana":"ていかくかじゅう","romaji":"teikakukajuu","vi":"tải trọng định mức","level":1,"def_vi":"Khối lượng tải lớn nhất mà thiết bị nâng được phép nâng một cách an toàn theo thiết kế, ghi trên nhãn thiết bị.","def_en":"The maximum load that lifting equipment is designed and permitted to lift safely.","def_ja":"つり上げ装置が安全につり上げることを許される最大の荷の質量。","usage_en":"Danh từ không đếm được. Hay đi với: exceed the rated load, rated load of 5 t, rated load plate; trên móc, xích hay ghi SWL hoặc WLL thay cho rated load.","usage_ja":"Hay đi với: 定格荷重を超える, 定格荷重表示. Luật Nhật phân biệt: 吊り上げ荷重 tính cả móc, còn 定格荷重 là tải thực được treo (đã trừ khối lượng móc, dụng cụ).","context_vi":"Dùng trên biển hiệu cầu trục, palăng, xe nâng, dây cẩu và trong kế hoạch nâng hạ để kiểm tra không quá tải.","ex_en":"Never lift a load that exceeds the rated load shown on the crane girder.","ex_ja":"クレーンガーダに表示された定格荷重を超える荷を吊ってはならない。","ex_vi":"Tuyệt đối không nâng tải vượt quá tải trọng định mức ghi trên dầm cầu trục.","syn_en":["safe working load (SWL)","working load limit (WLL)"],"syn_ja":["使用荷重 (dùng cho dụng cụ treo)","吊り上げ荷重 (gần nghĩa, tính cả móc)"]},{"en":"wire rope","pos":"noun","ipa":"/ˌwaɪər ˈroʊp/","ja":"ワイヤロープ","kana":"ワイヤロープ","romaji":"waiyaroopu","vi":"cáp thép","level":2,"def_vi":"Dây gồm nhiều sợi thép bện thành tao rồi các tao bện quanh lõi, dùng làm cáp nâng và dây cẩu.","def_en":"A rope made of steel wires twisted into strands laid around a core, used for hoisting and slinging.","def_ja":"鋼線をより合わせたストランドを心綱の周りにより合わせたロープで、巻上げや玉掛けに使う。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: 6 x 37 wire rope, broken wires, rope diameter, kink, lubricate / inspect / discard the wire rope.","usage_ja":"Hay đi với: ワイヤロープの素線切れ, キンク, 径の減少, 廃棄基準. Ngoài xưởng thường gọi tắt là ワイヤ.","context_vi":"Dùng trên tang tời cầu trục, cần trục, thang máy và làm dây cẩu; kiểm tra định kỳ đứt sợi, mòn, gỉ, xoắn.","ex_en":"The wire rope was discarded because 10 % of its wires were broken in one lay length.","ex_ja":"1よりの間で素線の10 %が切断していたため、ワイヤロープを廃棄した。","ex_vi":"Cáp thép đã bị loại bỏ vì 10 % số sợi bị đứt trong một bước bện.","syn_en":["steel wire rope","cable (khẩu ngữ)"],"syn_ja":["ワイヤ (khẩu ngữ)","鋼索 (văn bản cũ)"]},{"en":"chain block","pos":"noun","ipa":"/ˈtʃeɪn blɑːk/","ja":"チェーンブロック","kana":"チェーンブロック","romaji":"cheenburokku","vi":"palăng xích kéo tay","level":2,"def_vi":"Palăng nâng tay dùng xích tay kéo vòng qua bộ truyền bánh răng để nâng hạ tải bằng xích tải.","def_en":"A manual hoist in which pulling a hand chain drives a gear train to raise or lower the load chain.","def_ja":"手鎖を引いて歯車機構を回し、ロードチェーンで荷を巻き上げ・巻き下げる手動の巻上げ機。","usage_en":"Danh từ đếm được, dùng nhiều trong tiếng Anh Anh/Á; tiếng Mỹ hay nói manual chain hoist hoặc chain fall. Hay đi với: hang a chain block from a beam, 1-ton chain block.","usage_ja":"Hay đi với: チェーンブロックで吊る, チェーンブロックを掛ける, 手動チェーンブロック, 電気チェーンブロック. Từ rất phổ biến trong xưởng và bảo trì.","context_vi":"Dùng trong bảo trì, lắp đặt máy, nơi không có cầu trục, treo trên dầm hoặc giá ba chân để nâng chi tiết nặng.","ex_en":"We used a 1-ton chain block to lift the motor off its base.","ex_ja":"1トンのチェーンブロックでモータを架台から吊り上げた。","ex_vi":"Chúng tôi dùng palăng xích kéo tay 1 tấn để nhấc động cơ khỏi bệ.","syn_en":["manual chain hoist","chain fall (Mỹ)"],"syn_ja":["手動チェーンブロック","ホイスト (nghĩa rộng hơn, thường là loại điện)"]},{"en":"lever hoist","pos":"noun","ipa":"/ˈlevər hɔɪst/","ja":"レバーホイスト","kana":"レバーホイスト","romaji":"rebaahoisuto","vi":"palăng lắc tay (tời lắc tay)","level":2,"def_vi":"Palăng xích cầm tay vận hành bằng tay đòn lắc qua lại, dùng để kéo, căng hoặc nâng tải theo nhiều phương.","def_en":"A portable chain hoist operated by a ratchet lever, used for pulling, tensioning or lifting in any direction.","def_ja":"レバーを往復操作してチェーンを巻く携帯用の巻上げ機で、引張り・張り・吊りに使う。","usage_en":"Danh từ đếm được. Hay đi với: ratchet lever hoist, tension the cable with a lever hoist; ở Mỹ khẩu ngữ gọi come-along.","usage_ja":"Ngoài công trường gần như luôn gọi レバーブロック (tên thương mại đã thành từ chung); văn bản dùng レバーホイスト. Động từ: レバーで張る, 引き寄せる.","context_vi":"Dùng khi căn chỉnh, kéo dịch máy khi lắp đặt, căng cáp, chằng buộc hàng, nơi chật hẹp không treo được palăng xích.","ex_en":"Use a lever hoist to pull the pump into alignment with the motor.","ex_ja":"レバーホイストでポンプを引き寄せて、モータと芯を合わせる。","ex_vi":"Dùng palăng lắc tay kéo bơm vào thẳng tâm với động cơ.","syn_en":["come-along (Mỹ, khẩu ngữ)","ratchet lever hoist"],"syn_ja":["レバーブロック (tên thương mại, khẩu ngữ)"]},{"en":"jib crane","pos":"noun","ipa":"/ˈdʒɪb kreɪn/","ja":"ジブクレーン","kana":"ジブクレーン","romaji":"jibukureen","vi":"cần trục quay (cẩu xoay)","level":2,"def_vi":"Cần trục có tay cần nằm ngang hoặc nghiêng gắn vào cột hay tường, quay được quanh trục để nâng tải trong vùng tròn.","def_en":"A crane with a horizontal or inclined arm mounted on a pillar or wall that slews to lift loads within a circle.","def_ja":"柱や壁に取り付けたジブを旋回させ、円形の範囲で荷をつり上げるクレーン。","usage_en":"Danh từ đếm được. Hay đi với: pillar jib crane, wall-mounted jib crane, slewing jib crane, jib length / outreach.","usage_ja":"Hay đi với: ピラージブクレーン, 壁クレーン, ジブを旋回させる. Theo JIS, ジブクレーン cũng gồm cần trục lớn ở cảng, xưởng đóng tàu.","context_vi":"Dùng cạnh máy công cụ, trạm lắp ráp, bàn hàn để nâng phôi trong bán kính nhỏ mà không cần cầu trục.","ex_en":"A 500 kg jib crane was installed next to the lathe for loading heavy shafts.","ex_ja":"重い軸を載せるため、旋盤の横に500 kgのジブクレーンを設置した。","ex_vi":"Một cẩu xoay 500 kg đã được lắp cạnh máy tiện để đưa trục nặng lên máy.","syn_en":["pillar jib crane (loại đứng trên cột)","slewing crane (nghĩa rộng hơn)"],"syn_ja":["ピラージブクレーン (loại đứng trên cột)","旋回クレーン (nghĩa rộng hơn)"]},{"en":"gantry crane","pos":"noun","ipa":"/ˈɡæntri kreɪn/","ja":"門形クレーン","kana":"もんがたクレーン","romaji":"mongatakureen","vi":"cổng trục","level":2,"def_vi":"Cần trục có dầm chính đặt trên hai chân chạy trên ray dưới mặt đất, tạo thành khung hình cổng.","def_en":"A crane whose girder is supported on legs running on ground-level rails, forming a portal frame.","def_ja":"ガーダを脚で支え、地上のレールを走行する門形の構造をもつクレーン。","usage_en":"Danh từ đếm được. Hay đi với: rubber-tyred gantry crane (RTG), rail-mounted gantry crane, semi-gantry crane, gantry crane leg.","usage_ja":"Hay đi với: 門形クレーンで荷役する, 橋形クレーン, セミ門形クレーン. Ngoài cảng, nhà sản xuất hay dùng katakana ガントリークレーン.","context_vi":"Dùng ngoài trời ở bãi thép, xưởng kết cấu, nhà máy bê tông đúc sẵn, cảng container, nơi không có kết cấu nhà để gắn ray trên cao.","ex_en":"The precast beams are moved in the yard by a 30-ton gantry crane.","ex_ja":"プレキャスト梁はヤード内で30トンの門形クレーンにより移動される。","ex_vi":"Các dầm bê tông đúc sẵn được di chuyển trong bãi bằng cổng trục 30 tấn.","syn_en":["goliath crane","portal crane"],"syn_ja":["ガントリークレーン","橋形クレーン (gần nghĩa, có công-xôn)"]},{"en":"trolley","pos":"noun","ipa":"/ˈtrɑːli/","ja":"トロリ","kana":"トロリ","romaji":"torori","vi":"xe con (cầu trục)","level":2,"def_vi":"Cụm xe chạy dọc theo dầm cầu trục hoặc cổng trục, mang cơ cấu nâng để di chuyển tải theo phương ngang.","def_en":"The carriage that travels along a crane girder and carries the hoisting mechanism.","def_ja":"クレーンのガーダ上を横行し、巻上げ装置を載せて荷を移動させる台車。","usage_en":"Danh từ đếm được. Hay đi với: crane trolley, trolley travel, trolley rail, push / geared / motorized trolley; trong cầu trục Anh có khi gọi crab.","usage_ja":"Hay đi với: トロリが横行する, トロリ線, クラブトロリ. Cách viết トロリ (JIS) và トロリー đều gặp.","context_vi":"Dùng khi mô tả cấu tạo, kiểm tra, sửa chữa cầu trục, cổng trục và monoray palăng.","ex_en":"The trolley wheels showed uneven wear and were replaced.","ex_ja":"トロリの車輪に偏摩耗が見られたので交換した。","ex_vi":"Bánh xe của xe con bị mòn không đều nên đã được thay.","syn_en":["crab (Anh)","carriage (nghĩa rộng hơn)"],"syn_ja":["トロリー","クラブトロリ (loại có tời)"]},{"en":"roller conveyor","pos":"noun","ipa":"/ˈroʊlər kənˌveɪər/","ja":"ローラコンベヤ","kana":"ローラコンベヤ","romaji":"roorakonbeya","vi":"băng tải con lăn","level":2,"def_vi":"Băng tải gồm nhiều con lăn đặt song song, chi tiết chạy trên con lăn nhờ trọng lực hoặc nhờ con lăn được dẫn động.","def_en":"A conveyor of parallel rollers on which items move by gravity or by driven rollers.","def_ja":"平行に並べたローラの上を、重力または駆動ローラで物が移動するコンベヤ。","usage_en":"Danh từ đếm được. Hay đi với: gravity roller conveyor, powered / live roller conveyor, accumulating roller conveyor, roller pitch.","usage_ja":"Hay đi với: フリーローラコンベヤ, 駆動ローラコンベヤ, ローラピッチ. Cách viết ローラーコンベア cũng phổ biến.","context_vi":"Dùng cho thùng, hộp, pallet có đáy phẳng trong kho, khu đóng gói, nối giữa các máy trong dây chuyền.","ex_en":"Cartons slide down a gravity roller conveyor to the shipping dock.","ex_ja":"段ボール箱は重力式ローラコンベヤで出荷場へ流れていく。","ex_vi":"Thùng các-tông trượt theo băng tải con lăn tự chảy xuống bến xuất hàng.","syn_en":["gravity conveyor (loại không động cơ)","live roller conveyor (loại có dẫn động)"],"syn_ja":["ローラーコンベア","フリーローラ (loại tự do)"]},{"en":"reach truck","pos":"noun","ipa":"/ˈriːtʃ trʌk/","ja":"リーチフォークリフト","kana":"リーチフォークリフト","romaji":"riichifookurifuto","vi":"xe nâng reach (xe nâng đứng lái)","level":2,"def_vi":"Xe nâng điện có cột nâng hoặc càng đẩy ra phía trước được, người lái đứng, dùng nâng pallet lên kệ cao trong lối đi hẹp.","def_en":"An electric lift truck whose mast or forks extend forward, used to stack pallets high in narrow aisles.","def_ja":"マストやフォークが前方へ移動する電動フォークリフトで、狭い通路で高い棚に荷を積む。","usage_en":"Danh từ đếm được. Hay đi với: reach truck operator, narrow-aisle reach truck, reach the top rack level; khác counterbalance forklift (xe nâng đối trọng).","usage_ja":"Hay đi với: リーチ式フォークリフト, カウンタバランス式 (loại đối trọng, để phân biệt). Khẩu ngữ trong kho gọi tắt リーチ.","context_vi":"Dùng trong kho có giá kệ cao, lối đi hẹp, trung tâm phân phối, kho lạnh.","ex_en":"The reach truck can place pallets on racks up to 9 m high.","ex_ja":"リーチフォークリフトは高さ9 mまでのラックにパレットを置ける。","ex_vi":"Xe nâng reach có thể đặt pallet lên kệ cao tới 9 m.","syn_en":["reach forklift","stand-up reach truck"],"syn_ja":["リーチ式フォークリフト","リーチ (khẩu ngữ)"]},{"en":"slinging","pos":"noun","ipa":"/ˈslɪŋɪŋ/","ja":"玉掛け","kana":"たまかけ","romaji":"tamakake","vi":"móc buộc tải (công việc móc cáp)","level":2,"def_vi":"Công việc buộc dây cẩu vào tải và móc vào móc cẩu, rồi tháo ra sau khi hạ, đảm bảo tải cân bằng và an toàn.","def_en":"The work of attaching slings to a load and to the crane hook, and removing them after landing.","def_ja":"荷にワイヤロープ等を掛けてクレーンのフックに掛け、着地後に外す作業。","usage_en":"Danh từ không đếm được (từ động từ sling). Hay đi với: slinging and signalling, slinging method, slinger (người móc cáp); tiếng Mỹ hay dùng rigging.","usage_ja":"Từ rất quan trọng ở Nhật: 玉掛け作業, 玉掛け技能講習, 玉掛け者, 玉掛けワイヤ. Muốn móc tải cho cẩu từ 1 tấn trở lên phải có chứng chỉ 玉掛け.","context_vi":"Dùng trong đào tạo an toàn, phân công công việc nâng hạ ở xưởng, công trường, cảng.","ex_en":"Slinging must be done by a trained worker holding a valid certificate.","ex_ja":"玉掛けは資格を持つ作業者が行わなければならない。","ex_vi":"Công việc móc buộc tải phải do công nhân đã qua đào tạo, có chứng chỉ còn hiệu lực thực hiện.","syn_en":["rigging (Mỹ, nghĩa rộng hơn)","hitching"],"syn_ja":["玉掛け作業","吊り作業 (khẩu ngữ)"]},{"en":"signal person","pos":"noun phrase","ipa":"/ˈsɪɡnəl ˌpɜːrsən/","ja":"合図者","kana":"あいずしゃ","romaji":"aizusha","vi":"người ra hiệu cẩu (xi-nhan)","level":2,"def_vi":"Người được chỉ định dùng tín hiệu tay, còi hoặc bộ đàm để chỉ dẫn người lái cẩu khi nâng hạ tải.","def_en":"The appointed person who directs the crane operator by hand signals, whistle or radio during a lift.","def_ja":"つり作業中、手合図・笛・無線でクレーン運転者に指示を出すよう指名された者。","usage_en":"Danh từ đếm được. Hay đi với: designated signal person, give hand signals, only one signal person at a time; tiếng Anh Anh gọi banksman.","usage_ja":"Hay đi với: 合図者を指名する, 合図を送る, 一人合図 (chỉ một người ra hiệu). Theo luật Nhật, mỗi việc cẩu phải chỉ định 合図者.","context_vi":"Dùng khi lập kế hoạch nâng hạ, họp an toàn đầu ca, công việc cẩu tải khi người lái không nhìn thấy tải.","ex_en":"The crane operator must follow the instructions of only one signal person.","ex_ja":"クレーン運転者は、一人の合図者の指示だけに従わなければならない。","ex_vi":"Người lái cẩu chỉ được làm theo chỉ dẫn của một người ra hiệu duy nhất.","syn_en":["banksman (Anh)","signalman"],"syn_ja":["誘導者 (gần nghĩa)","玉掛け者 (liên quan)"]},{"en":"tag line","pos":"noun","ipa":"/ˈtæɡ laɪn/","ja":"介錯ロープ","kana":"かいしゃくロープ","romaji":"kaishakuroopu","vi":"dây lèo (dây dẫn hướng tải)","level":2,"def_vi":"Dây buộc vào tải đang treo để người đứng dưới giữ, xoay và dẫn hướng tải mà không phải chạm tay vào tải.","def_en":"A rope tied to a suspended load so workers can control its swing and rotation from a safe distance.","def_ja":"吊り荷に取り付け、離れた位置から荷の振れや回転を制御するためのロープ。","usage_en":"Danh từ đếm được, cũng viết tagline. Hay đi với: attach / use a tag line, control the load with tag lines; không được quấn tag line quanh tay.","usage_ja":"Hay đi với: 介錯ロープを取る, 介錯ロープで振れを止める. Đây là từ chuyên ngành công trường/xưởng, người ngoài ngành ít biết.","context_vi":"Dùng khi cẩu tải dài, tải cồng kềnh hoặc khi có gió, để tránh tải xoay va vào người hay kết cấu.","ex_en":"Two tag lines were attached to keep the long beam from rotating.","ex_ja":"長い梁が回転しないよう、介錯ロープを2本取り付けた。","ex_vi":"Hai dây lèo được buộc vào để dầm dài không bị xoay.","syn_en":["guide rope","tagline"],"syn_ja":["介錯綱","控えロープ (gần nghĩa)"]},{"en":"lifting lug","pos":"noun","ipa":"/ˈlɪftɪŋ lʌɡ/","ja":"吊りピース","kana":"つりピース","romaji":"tsuripiisu","vi":"tai cẩu","level":2,"def_vi":"Tấm thép có lỗ được hàn hoặc bắt bu lông vào thiết bị, kết cấu làm điểm móc ma ní khi nâng.","def_en":"A plate with a hole welded or bolted to equipment to provide an attachment point for lifting.","def_ja":"機器や構造物に溶接またはボルト止めした穴あき板で、吊るときのシャックルの取付け点。","usage_en":"Danh từ đếm được. Hay đi với: weld a lifting lug, design / check the lifting lug, lifting lug capacity; trong dầu khí, hàng hải hay gọi padeye.","usage_ja":"Hay đi với: 吊りピースを溶接する, 吊りピースの強度計算. Văn bản cũng dùng 吊り金具, 吊り耳; trên bản vẽ có thể ghi 吊りピース.","context_vi":"Dùng khi thiết kế, chế tạo bồn, khung máy, kết cấu thép, mô-đun cần vận chuyển và lắp dựng bằng cẩu.","ex_en":"The lifting lug was designed for twice the module weight.","ex_ja":"吊りピースはモジュール質量の2倍の荷重で設計した。","ex_vi":"Tai cẩu được thiết kế cho tải gấp đôi khối lượng mô-đun.","syn_en":["padeye (hàng hải, dầu khí)","lifting eye"],"syn_ja":["吊り金具 (nghĩa rộng hơn)","吊り耳"]},{"en":"safety latch","pos":"noun","ipa":"/ˈseɪfti lætʃ/","ja":"外れ止め","kana":"はずれどめ","romaji":"hazuredome","vi":"khóa an toàn móc cẩu (lưỡi gà)","level":2,"def_vi":"Lẫy có lò xo đóng miệng móc cẩu, ngăn dây cẩu hoặc ma ní tuột ra khỏi móc.","def_en":"A spring-loaded gate closing the throat of a hook so slings cannot slip off.","def_ja":"フックの口をばねで閉じ、玉掛け用具が外れるのを防ぐ金具。","usage_en":"Danh từ đếm được. Hay đi với: hook safety latch, broken / missing safety latch, check that the safety latch closes.","usage_ja":"Hay đi với: フックの外れ止め, 外れ止め装置, 外れ止めが効いているか確認する. Hạng mục quan trọng của 始業点検 (kiểm tra đầu ca).","context_vi":"Dùng trong kiểm tra hằng ngày cầu trục, palăng, móc dây cẩu; móc thiếu khóa an toàn không được phép sử dụng.","ex_en":"The hoist was tagged out because the safety latch on the hook was broken.","ex_ja":"フックの外れ止めが壊れていたため、ホイストを使用禁止にした。","ex_vi":"Palăng bị treo biển cấm dùng vì khóa an toàn trên móc bị gãy.","syn_en":["hook latch","safety catch"],"syn_ja":["フック外れ止め","外れ止め装置"]},{"en":"sling angle","pos":"noun phrase","ipa":"/ˈslɪŋ ˌæŋɡəl/","ja":"吊り角度","kana":"つりかくど","romaji":"tsurikakudo","vi":"góc treo cáp (góc mở cáp)","level":2,"def_vi":"Góc giữa các nhánh dây cẩu (hoặc giữa nhánh và phương đứng); góc càng lớn thì lực căng mỗi nhánh càng tăng.","def_en":"The angle between sling legs or from vertical; a wider angle increases the tension in each leg.","def_ja":"玉掛け用具の脚どうしの角度で、角度が大きいほど各脚の張力が増える。","usage_en":"Danh từ đếm được. Hay đi với: sling angle factor, keep the sling angle below 60°/90°, reduce capacity at wide sling angles; cần nói rõ đo so với phương đứng hay phương ngang.","usage_ja":"Hay đi với: 吊り角度60度以内, 吊り角度が大きい, 張力係数 (hệ số lực căng). Ở Nhật, góc thường tính là góc mở giữa hai nhánh.","context_vi":"Dùng trong đào tạo móc cáp, lập kế hoạch nâng hạ, chọn dây cẩu và ma ní cho tải nặng.","ex_en":"With a sling angle of 120°, each leg carries a force equal to the full load.","ex_ja":"吊り角度が120度になると、各脚には荷の全質量と同じ力がかかる。","ex_vi":"Với góc mở cáp 120°, mỗi nhánh cáp chịu một lực bằng toàn bộ tải.","syn_en":["included angle (góc giữa hai nhánh)","leg angle"],"syn_ja":["開き角度","玉掛け角度"]},{"en":"lifting magnet","pos":"noun","ipa":"/ˈlɪftɪŋ ˌmæɡnət/","ja":"リフティングマグネット","kana":"リフティングマグネット","romaji":"rifutingumagunetto","vi":"nam châm nâng (nam châm cẩu)","level":3,"def_vi":"Nam châm điện hoặc nam châm vĩnh cửu treo vào móc cẩu, hút để nâng thép tấm, phôi thép, phế liệu sắt.","def_en":"An electromagnet or permanent magnet hung from a crane to lift steel plates, billets or scrap.","def_ja":"クレーンに吊り下げた電磁石または永久磁石で、鋼板、鋼片、スクラップを吸着してつり上げる装置。","usage_en":"Danh từ đếm được. Hay đi với: electro-permanent lifting magnet, battery-backup lifting magnet, magnet holding force, plate thickness limit.","usage_ja":"Khẩu ngữ trong xưởng thép rất hay nói リフマグ. Hay đi với: リフマグで吊る, 停電時の落下防止, 吸着力.","context_vi":"Dùng ở xưởng cắt tôn, kho thép, nhà máy luyện thép, bãi phế liệu; cần chú ý nguy cơ rơi tải khi mất điện.","ex_en":"A battery-backed lifting magnet is used to unload steel plates from trucks.","ex_ja":"トラックから鋼板を降ろすのに、バッテリー付きのリフティングマグネットを使っている。","ex_vi":"Nam châm nâng có ắc quy dự phòng được dùng để dỡ thép tấm từ xe tải.","syn_en":["magnetic lifter","electromagnet (nghĩa rộng hơn)"],"syn_ja":["リフマグ (khẩu ngữ)","吊り上げ電磁石"]},{"en":"spreader beam","pos":"noun","ipa":"/ˈspredər biːm/","ja":"吊り天秤","kana":"つりてんびん","romaji":"tsuritenbin","vi":"dầm treo (đòn gánh cẩu)","level":3,"def_vi":"Dầm hoặc thanh treo dưới móc cẩu, có nhiều điểm treo để chia tải và giữ các nhánh dây cẩu gần thẳng đứng.","def_en":"A beam hung below the hook with several lifting points to spread the load and keep sling legs near vertical.","def_ja":"フックの下に吊り、複数の吊り点で荷を分散させ、玉掛け用具をほぼ垂直に保つはり。","usage_en":"Danh từ đếm được. Hay đi với: use a spreader beam, adjustable spreader beam; về kỹ thuật, spreader bar chịu nén còn lifting beam chịu uốn, nhưng ngoài xưởng hay dùng lẫn.","usage_ja":"Khẩu ngữ hay gọi tắt 天秤 (てんびん). Hay đi với: 天秤で吊る, 吊り天秤を使う, 吊りビーム.","context_vi":"Dùng khi nâng tải dài, mềm hoặc dễ hỏng như ống, dầm, tấm lớn, máy có điểm treo xa nhau.","ex_en":"A 6 m spreader beam was used to lift the long conveyor frame without bending it.","ex_ja":"長いコンベヤフレームを曲げずに吊るため、6 mの吊り天秤を使用した。","ex_vi":"Một dầm treo dài 6 m đã được dùng để nâng khung băng tải dài mà không làm nó bị cong.","syn_en":["lifting beam (gần nghĩa)","spreader bar"],"syn_ja":["天秤 (khẩu ngữ)","吊りビーム"]},{"en":"overload limiter","pos":"noun","ipa":"/ˌoʊvərloʊd ˈlɪmɪtər/","ja":"過負荷防止装置","kana":"かふかぼうしそうち","romaji":"kafukaboushisouchi","vi":"thiết bị chống quá tải","level":3,"def_vi":"Thiết bị đo tải trên cần trục hoặc palăng và tự động chặn thao tác nâng khi tải vượt giá trị cài đặt.","def_en":"A device that senses the load on a crane or hoist and stops hoisting when a set limit is exceeded.","def_ja":"クレーンやホイストの荷重を検出し、設定値を超えると巻上げを自動停止させる装置。","usage_en":"Danh từ đếm được. Hay đi với: overload limiter trips, set / test / bypass the overload limiter; tuyệt đối không bypass trong vận hành.","usage_ja":"Hay đi với: 過負荷防止装置が作動する, 過負荷防止装置の調整. Trên cần trục di động hay dùng 過負荷防止装置 hoặc モーメントリミッタ.","context_vi":"Dùng trong thiết kế, kiểm định và bảo trì cầu trục, palăng điện, cần trục ô tô.","ex_en":"The overload limiter tripped when the operator tried to lift 11 tons with a 10-ton crane.","ex_ja":"10トンクレーンで11トンを吊ろうとしたところ、過負荷防止装置が作動した。","ex_vi":"Thiết bị chống quá tải đã ngắt khi người vận hành cố nâng 11 tấn bằng cầu trục 10 tấn.","syn_en":["load limiter","overload protection device"],"syn_ja":["オーバーロードリミッタ","モーメントリミッタ (loại cho cần trục di động)"]},{"en":"hoist limit switch","pos":"noun","ipa":"/ˈhɔɪst ˌlɪmɪt swɪtʃ/","ja":"巻過防止装置","kana":"まきすぎぼうしそうち","romaji":"makisugiboushisouchi","vi":"công tắc giới hạn nâng (chống quá cuốn)","level":3,"def_vi":"Công tắc tự động dừng cơ cấu nâng khi móc lên quá vị trí cao nhất cho phép, tránh va đập và đứt cáp.","def_en":"A switch that automatically stops hoisting when the hook block reaches its highest permitted position.","def_ja":"フックが上限位置に達すると巻上げを自動停止し、衝突やロープ破断を防ぐ装置。","usage_en":"Danh từ đếm được. Hay đi với: upper / lower hoist limit switch, test the hoist limit switch daily, the hook hit the limit switch; tránh dùng nó như cách dừng thường xuyên.","usage_ja":"Hay đi với: 巻過防止装置が作動する, 巻過防止装置の点検. Cũng viết 巻過ぎ防止装置; trên tài liệu bảo trì có khi ghi chung là リミットスイッチ.","context_vi":"Dùng trong kiểm tra đầu ca, kiểm định cầu trục, palăng và trong yêu cầu an toàn của luật về thiết bị nâng.","ex_en":"Check the hoist limit switch at the start of every shift by raising the empty hook slowly.","ex_ja":"毎回の始業時に空フックをゆっくり巻き上げ、巻過防止装置を点検する。","ex_vi":"Mỗi đầu ca, kiểm tra công tắc giới hạn nâng bằng cách nâng chậm móc không tải.","syn_en":["overhoist limit switch","upper limit switch"],"syn_ja":["巻過ぎ防止装置","リミットスイッチ (nghĩa rộng hơn)"]},{"en":"automated guided vehicle","pos":"noun phrase","ipa":"/ˌɔːtəmeɪtɪd ˌɡaɪdɪd ˈviːəkəl/","ja":"無人搬送車","kana":"むじんはんそうしゃ","romaji":"mujinhansousha","vi":"xe tự hành (AGV)","level":3,"def_vi":"Xe vận chuyển không người lái, tự chạy theo băng từ, mã QR hoặc định vị laser để chở hàng giữa các trạm.","def_en":"A driverless vehicle that follows magnetic tape, markers or laser navigation to carry loads between stations.","def_ja":"磁気テープ、マーカ、レーザなどで誘導され、ステーション間で荷を運ぶ無人の車両。","usage_en":"Danh từ đếm được, thường viết tắt AGV (số nhiều AGVs). Hay đi với: AGV route, docking station, AGV fleet; khác AMR là robot tự lập bản đồ, không cần đường dẫn cố định.","usage_ja":"Trong xưởng hay gọi AGV (エージーブイ). Hay đi với: 無人搬送車を導入する, 磁気誘導式, レーザ誘導式, 充電ステーション.","context_vi":"Dùng trong nhà máy ô tô, điện tử, kho thông minh để chuyển linh kiện từ kho đến dây chuyền.","ex_en":"Each automated guided vehicle tows three carts from the warehouse to the assembly line.","ex_ja":"各無人搬送車は、倉庫から組立ラインまで台車を3台けん引する。","ex_vi":"Mỗi xe tự hành kéo ba xe đẩy từ kho đến dây chuyền lắp ráp.","syn_en":["AGV","AMR (autonomous mobile robot, liên quan)"],"syn_ja":["AGV","無人搬送台車"]},{"en":"stacker crane","pos":"noun","ipa":"/ˈstækər kreɪn/","ja":"スタッカクレーン","kana":"スタッカクレーン","romaji":"sutakkakureen","vi":"cần trục xếp dỡ kho (stacker crane)","level":3,"def_vi":"Máy chạy trên ray dọc lối đi của kho tự động, có cột cao và bàn nâng để cất, lấy pallet ở các ô kệ.","def_en":"A rail-guided machine with a tall mast and carriage that stores and retrieves loads in an automated warehouse aisle.","def_ja":"自動倉庫の通路をレールで走行し、昇降台で棚へ荷を入出庫する機械。","usage_en":"Danh từ đếm được. Hay đi với: stacker crane aisle, single-mast / twin-mast stacker crane, storage and retrieval cycle time.","usage_ja":"Hay đi với: スタッカクレーンで入出庫する, 走行・昇降・フォーク動作. Cũng viết スタッカークレーン.","context_vi":"Dùng trong kho tự động cao tầng, kho lạnh, kho linh kiện của nhà máy lớn.","ex_en":"Each aisle is served by one stacker crane with a cycle time of 90 seconds.","ex_ja":"各通路には1台のスタッカクレーンがあり、サイクルタイムは90秒である。","ex_vi":"Mỗi lối đi có một cần trục xếp dỡ kho với thời gian chu kỳ 90 giây.","syn_en":["storage and retrieval machine (S/R machine)"],"syn_ja":["スタッカークレーン","自動倉庫 (liên quan)"]}]},{"id":97,"words":[{"en":"power plant","pos":"noun","ipa":"/ˈpaʊər plænt/","ja":"発電所","kana":"はつでんしょ","romaji":"hatsudensho","vi":"nhà máy điện","level":1,"def_vi":"Cơ sở công nghiệp biến đổi năng lượng từ nhiên liệu, nước, gió, hạt nhân… thành điện năng để cấp lên lưới.","def_en":"An industrial facility that converts energy from fuel, water, wind or nuclear sources into electricity for the grid.","def_ja":"燃料、水、風、原子力などのエネルギーを電気に変えて系統へ送る施設。","usage_en":"Danh từ đếm được. Hay đi với: build / operate / commission a power plant, coal-fired / gas-fired power plant, power plant capacity; tiếng Anh Anh hay nói power station.","usage_ja":"Thường ghép loại phía trước: 火力発電所, 水力発電所, 原子力発電所. Đọc là はつでんしょ (không phải はつでんじょ). Trong ngành hay gọi đơn vị tổ máy là 号機, ví dụ 1号機.","context_vi":"Dùng trong dự án EPC năng lượng, vận hành, bảo dưỡng tổ máy và báo cáo của công ty điện lực.","ex_en":"The power plant supplies electricity to about two million households.","ex_ja":"この発電所は約200万世帯に電気を供給している。","ex_vi":"Nhà máy điện này cung cấp điện cho khoảng hai triệu hộ gia đình.","syn_en":["power station (Anh)","generating station"],"syn_ja":["発電プラント","発電設備 (nghĩa rộng hơn)"]},{"en":"thermal power plant","pos":"noun","ipa":"/ˈθɜːrməl ˈpaʊər plænt/","ja":"火力発電所","kana":"かりょくはつでんしょ","romaji":"karyokuhatsudensho","vi":"nhà máy nhiệt điện","level":1,"def_vi":"Nhà máy điện đốt than, dầu hoặc khí để tạo hơi nước hay khí nóng làm quay tuabin và máy phát.","def_en":"A power plant that burns coal, oil or gas to produce steam or hot gas that drives turbines and generators.","def_ja":"石炭・石油・ガスを燃やし、蒸気や燃焼ガスでタービンと発電機を回す発電所。","usage_en":"Danh từ đếm được. Hay đi với: coal-fired thermal power plant, thermal power plant efficiency, emissions from a thermal power plant; khi nói rõ nhiên liệu có thể dùng coal-fired plant.","usage_ja":"Hay đi với: 石炭火力発電所, LNG火力, 火力発電所の運転. Khẩu ngữ ngành điện thường nói gọn 火力 (ví dụ 石炭火力).","context_vi":"Dùng khi nói về nhà máy nhiệt điện than Vĩnh Tân, Duyên Hải… hoặc nhà máy nhiệt điện khí, dầu.","ex_en":"Most of the region's electricity still comes from a coal-fired thermal power plant.","ex_ja":"この地域の電力の大部分は、今も石炭火力発電所から来ている。","ex_vi":"Phần lớn điện năng của vùng vẫn đến từ một nhà máy nhiệt điện than.","syn_en":["fossil-fuel power plant","coal-fired plant (một loại)"],"syn_ja":["火力 (khẩu ngữ)","火力発電プラント"]},{"en":"hydroelectric power plant","pos":"noun","ipa":"/ˌhaɪdroʊɪˈlektrɪk ˈpaʊər plænt/","ja":"水力発電所","kana":"すいりょくはつでんしょ","romaji":"suiryokuhatsudensho","vi":"nhà máy thủy điện","level":1,"def_vi":"Nhà máy điện dùng thế năng của nước từ hồ chứa hoặc dòng sông chảy qua tuabin nước để phát điện.","def_en":"A power plant that uses water falling from a reservoir or river through water turbines to generate electricity.","def_ja":"貯水池や河川の水の落差を利用し、水車で発電する発電所。","usage_en":"Danh từ đếm được. Hay đi với: run-of-river / pumped-storage hydroelectric power plant, dam, head, installed capacity; khẩu ngữ gọi hydro plant hoặc hydropower plant.","usage_ja":"Hay đi với: 揚水式水力発電所, 流れ込み式, 落差, 水車. Trong ngành thường nói gọn 水力.","context_vi":"Dùng khi nói về thủy điện Hòa Bình, Sơn La, thủy điện nhỏ, thủy điện tích năng.","ex_en":"The hydroelectric power plant has four Francis turbines with a total output of 1,920 MW.","ex_ja":"この水力発電所には、合計出力1,920 MWのフランシス水車が4台ある。","ex_vi":"Nhà máy thủy điện có bốn tuabin Francis với tổng công suất 1.920 MW.","syn_en":["hydropower plant","hydro plant (khẩu ngữ)"],"syn_ja":["水力 (khẩu ngữ)","水力発電プラント"]},{"en":"nuclear power plant","pos":"noun","ipa":"/ˈnuːkliər ˈpaʊər plænt/","ja":"原子力発電所","kana":"げんしりょくはつでんしょ","romaji":"genshiryokuhatsudensho","vi":"nhà máy điện hạt nhân","level":1,"def_vi":"Nhà máy điện dùng nhiệt từ phản ứng phân hạch hạt nhân trong lò phản ứng để tạo hơi làm quay tuabin.","def_en":"A power plant that uses heat from nuclear fission in a reactor to make steam for turbines.","def_ja":"原子炉内の核分裂で生じた熱で蒸気をつくり、タービンを回して発電する発電所。","usage_en":"Danh từ đếm được. Hay đi với: pressurized water reactor (PWR), boiling water reactor (BWR), decommission a nuclear power plant, nuclear safety.","usage_ja":"Khẩu ngữ và báo chí hay gọi tắt 原発 (げんぱつ). Hay đi với: 原子力発電所の再稼働, 廃炉, 加圧水型, 沸騰水型.","context_vi":"Dùng trong ngành năng lượng hạt nhân, tài liệu an toàn bức xạ, các dự án điện hạt nhân Nhật Bản, Hàn Quốc, Nga.","ex_en":"The nuclear power plant restarted after passing the new safety review.","ex_ja":"新しい安全審査に合格し、原子力発電所が再稼働した。","ex_vi":"Nhà máy điện hạt nhân đã vận hành trở lại sau khi vượt qua đợt thẩm định an toàn mới.","syn_en":["nuclear power station (Anh)","NPP"],"syn_ja":["原発 (khẩu ngữ, báo chí)","原子力発電プラント"]},{"en":"generator","pos":"noun","ipa":"/ˈdʒenəreɪtər/","ja":"発電機","kana":"はつでんき","romaji":"hatsudenki","vi":"máy phát điện","level":1,"def_vi":"Máy điện biến cơ năng từ tuabin hoặc động cơ thành điện năng nhờ cảm ứng điện từ.","def_en":"An electrical machine that converts mechanical energy from a turbine or engine into electricity by induction.","def_ja":"タービンやエンジンの機械エネルギーを電磁誘導で電気エネルギーに変える機械。","usage_en":"Danh từ đếm được. Hay đi với: turbine generator, synchronous generator, generator rotor / stator, diesel generator set; trong nhà máy điện hay nói turbine-generator unit.","usage_ja":"Hay đi với: タービン発電機, 同期発電機, 非常用ディーゼル発電機, 発電機の固定子・回転子. Khẩu ngữ đôi khi nói ジェネレータ.","context_vi":"Dùng khi nói về tổ máy tuabin–máy phát của nhà máy điện, máy phát dự phòng cho tòa nhà, nhà xưởng.","ex_en":"The generator is cooled by hydrogen to remove heat from the windings.","ex_ja":"巻線の熱を除去するため、発電機は水素で冷却されている。","ex_vi":"Máy phát điện được làm mát bằng khí hydro để giải nhiệt cho các cuộn dây.","syn_en":["alternator (máy phát xoay chiều)","genset (tổ máy phát diesel, khẩu ngữ)"],"syn_ja":["ジェネレータ (khẩu ngữ)","タービン発電機 (trong nhà máy điện)"]},{"en":"stack","pos":"noun","ipa":"/stæk/","ja":"煙突","kana":"えんとつ","romaji":"entotsu","vi":"ống khói","level":1,"def_vi":"Ống cao thải khói sau khi đã xử lý ra khí quyển, đủ cao để phát tán khí thải và tạo lực hút.","def_en":"A tall structure that discharges treated flue gas into the atmosphere and helps disperse emissions.","def_ja":"処理後の排ガスを大気へ放出し、拡散させるための高い筒状構造物。","usage_en":"Danh từ đếm được. Hay đi với: stack height, stack emissions, continuous emission monitoring at the stack, stack gas temperature; nghĩa đời thường là chimney.","usage_ja":"Hay đi với: 煙突高さ, 煙突出口, 煙突から排出する. Trong tài liệu kỹ thuật tiếng Anh–Nhật đôi khi viết スタック.","context_vi":"Dùng trong thiết kế và quan trắc môi trường nhà máy nhiệt điện, lò hơi công nghiệp, lò đốt rác.","ex_en":"SO2 concentration is measured continuously at the stack outlet.","ex_ja":"煙突出口でSO2濃度を連続測定している。","ex_vi":"Nồng độ SO2 được đo liên tục tại miệng ống khói.","syn_en":["chimney","flue stack"],"syn_ja":["スタック","排気筒 (gần nghĩa)"]},{"en":"control room","pos":"noun","ipa":"/kənˈtroʊl ruːm/","ja":"中央制御室","kana":"ちゅうおうせいぎょしつ","romaji":"chuuouseigyoshitsu","vi":"phòng điều khiển trung tâm","level":1,"def_vi":"Phòng đặt hệ thống điều khiển, màn hình giám sát, nơi kíp vận hành theo dõi và điều khiển toàn bộ nhà máy.","def_en":"The room housing control consoles and displays where operators monitor and run the whole plant.","def_ja":"制御装置や監視画面を備え、運転員がプラント全体を監視・操作する部屋。","usage_en":"Danh từ đếm được. Hay đi với: central control room (CCR), control room operator, report to the control room; thường dùng với the.","usage_ja":"Khẩu ngữ gọi tắt 中操 (ちゅうそう). Hay đi với: 中央制御室に連絡する, 運転員, 当直 (ca trực).","context_vi":"Dùng trong vận hành nhà máy điện, nhà máy hóa chất; mọi thao tác thiết bị hiện trường thường phải báo phòng điều khiển.","ex_en":"Inform the control room before isolating the pump.","ex_ja":"ポンプを隔離する前に中央制御室へ連絡すること。","ex_vi":"Phải báo phòng điều khiển trung tâm trước khi cô lập bơm.","syn_en":["central control room (CCR)"],"syn_ja":["中操 (khẩu ngữ)","制御室"]},{"en":"substation","pos":"noun","ipa":"/ˈsʌbsteɪʃən/","ja":"変電所","kana":"へんでんしょ","romaji":"hendensho","vi":"trạm biến áp","level":1,"def_vi":"Cơ sở có máy biến áp, máy cắt, thiết bị đóng cắt để tăng hoặc giảm điện áp và phân phối điện.","def_en":"A facility with transformers and switchgear that steps voltage up or down and distributes power.","def_ja":"変圧器や開閉装置を備え、電圧を上げ下げして電力を分配する施設。","usage_en":"Danh từ đếm được. Hay đi với: switchyard (trạm phân phối ngoài trời của nhà máy), step-up substation, 220 kV substation, outdoor substation.","usage_ja":"Hay đi với: 変電所に送る, 開閉所 (trạm đóng cắt), 屋外変電所. Trong nhà máy điện, sân phân phối thường gọi 開閉所 hoặc スイッチヤード.","context_vi":"Dùng khi nói về đấu nối nhà máy điện lên lưới, sơ đồ truyền tải, bảo trì thiết bị điện cao áp.","ex_en":"Power from the plant is sent to the 500 kV substation through two lines.","ex_ja":"発電所の電力は2回線で500 kV変電所へ送られる。","ex_vi":"Điện từ nhà máy được truyền đến trạm biến áp 500 kV qua hai đường dây.","syn_en":["switchyard (gần nghĩa, tại nhà máy)"],"syn_ja":["開閉所 (gần nghĩa)","スイッチヤード"]},{"en":"power grid","pos":"noun","ipa":"/ˈpaʊər ɡrɪd/","ja":"電力系統","kana":"でんりょくけいとう","romaji":"denryokukeitou","vi":"lưới điện (hệ thống điện)","level":1,"def_vi":"Mạng lưới các nhà máy điện, đường dây truyền tải, trạm biến áp và phụ tải liên kết với nhau để cung cấp điện.","def_en":"The interconnected network of power plants, transmission lines, substations and loads that supplies electricity.","def_ja":"発電所、送電線、変電所、需要家が結ばれた電力供給のネットワーク。","usage_en":"Danh từ đếm được, thường dùng với the. Hay đi với: connect to the power grid, grid frequency, grid code, feed power into the grid; khẩu ngữ chỉ nói the grid.","usage_ja":"Hay đi với: 電力系統に接続する, 系統周波数, 系統連系. Khẩu ngữ trong ngành nói gọn 系統; báo chí hay dùng 送電網 hoặc 電力網.","context_vi":"Dùng khi nói về điều độ hệ thống điện, đấu nối nhà máy, ổn định tần số và điện áp.","ex_en":"The unit was disconnected from the power grid after the frequency dropped to 49 Hz.","ex_ja":"周波数が49 Hzまで低下したため、ユニットは電力系統から切り離された。","ex_vi":"Tổ máy đã bị tách khỏi lưới điện sau khi tần số giảm xuống 49 Hz.","syn_en":["the grid (khẩu ngữ)","electrical grid"],"syn_ja":["系統 (khẩu ngữ)","送電網"]},{"en":"main transformer","pos":"noun","ipa":"/ˌmeɪn trænsˈfɔːrmər/","ja":"主変圧器","kana":"しゅへんあつき","romaji":"shuhen'atsuki","vi":"máy biến áp chính (máy biến áp tăng áp)","level":2,"def_vi":"Máy biến áp lớn nâng điện áp đầu cực máy phát lên điện áp truyền tải để đưa điện lên lưới.","def_en":"The large transformer that steps up generator voltage to transmission voltage for the grid.","def_ja":"発電機の電圧を送電電圧まで昇圧して系統へ送る大型の変圧器。","usage_en":"Danh từ đếm được. Hay đi với: generator step-up transformer (GSU), main transformer oil, transformer tap; ở nhà máy hay viết tắt GSU hoặc MTR.","usage_ja":"Hay đi với: 主変圧器の油, 主変圧器の点検, 所内変圧器 (máy biến áp tự dùng, để phân biệt). Viết tắt trên sơ đồ: 主変.","context_vi":"Dùng trong sơ đồ một sợi, bảo trì thiết bị điện, phân tích dầu máy biến áp của nhà máy điện.","ex_en":"Dissolved gas analysis of the main transformer oil is carried out every six months.","ex_ja":"主変圧器の油中ガス分析を6か月ごとに実施している。","ex_vi":"Phân tích khí hòa tan trong dầu máy biến áp chính được thực hiện sáu tháng một lần.","syn_en":["generator step-up transformer (GSU)","step-up transformer"],"syn_ja":["主変 (khẩu ngữ)","昇圧変圧器"]},{"en":"feedwater heater","pos":"noun","ipa":"/ˈfiːdwɔːtər ˌhiːtər/","ja":"給水加熱器","kana":"きゅうすいかねつき","romaji":"kyuusuikanetsuki","vi":"bình gia nhiệt nước cấp","level":2,"def_vi":"Bộ trao đổi nhiệt dùng hơi trích từ tuabin để hâm nóng nước cấp trước khi vào lò hơi, nâng hiệu suất chu trình.","def_en":"A heat exchanger that uses turbine extraction steam to preheat boiler feedwater and raise cycle efficiency.","def_ja":"タービン抽気でボイラ給水を予熱し、サイクル効率を高める熱交換器。","usage_en":"Danh từ đếm được. Hay đi với: low-pressure / high-pressure feedwater heater (LP / HP heater), extraction steam, heater drain, take a heater out of service.","usage_ja":"Hay đi với: 低圧給水加熱器, 高圧給水加熱器, 抽気, ドレン. Trong ca trực hay gọi tắt 低圧ヒータ, 高圧ヒータ.","context_vi":"Dùng trong chu trình hồi nhiệt của nhà máy nhiệt điện, khi phân tích hiệu suất và rò ống bình gia nhiệt.","ex_en":"Taking the HP feedwater heater out of service increased fuel consumption by 2 %.","ex_ja":"高圧給水加熱器を停止したところ、燃料消費量が2 %増えた。","ex_vi":"Việc ngừng bình gia nhiệt nước cấp cao áp làm tăng tiêu hao nhiên liệu 2 %.","syn_en":["FWH","LP / HP heater (khẩu ngữ)"],"syn_ja":["ヒータ (khẩu ngữ)","低圧ヒータ・高圧ヒータ (loại)"]},{"en":"deaerator","pos":"noun","ipa":"/diːˈeəreɪtər/","ja":"脱気器","kana":"だっきき","romaji":"dakkiki","vi":"bình khử khí","level":2,"def_vi":"Thiết bị gia nhiệt nước cấp bằng hơi để tách oxy và khí hòa tan, chống ăn mòn đường ống và lò hơi.","def_en":"A device that heats feedwater with steam to remove dissolved oxygen and gases, preventing corrosion.","def_ja":"給水を蒸気で加熱し、溶存酸素などのガスを除去して腐食を防ぐ装置。","usage_en":"Danh từ đếm được. Hay đi với: deaerator storage tank, deaerator pressure, dissolved oxygen at the deaerator outlet, vent steam.","usage_ja":"Hay đi với: 脱気器水位, 脱気器貯水タンク, 溶存酸素. Từ này dùng cả trong nhà máy điện và lò hơi công nghiệp.","context_vi":"Dùng trong vận hành hệ thống nước cấp, kiểm soát hóa nước của nhà máy nhiệt điện và lò hơi công nghiệp.","ex_en":"Dissolved oxygen at the deaerator outlet must stay below 7 ppb.","ex_ja":"脱気器出口の溶存酸素は7 ppb未満に保たなければならない。","ex_vi":"Hàm lượng oxy hòa tan ở đầu ra bình khử khí phải duy trì dưới 7 ppb.","syn_en":["deaerating heater","DA (khẩu ngữ)"],"syn_ja":["デアレータ","脱気装置"]},{"en":"pulverizer","pos":"noun","ipa":"/ˈpʌlvəraɪzər/","ja":"微粉炭機","kana":"びふんたんき","romaji":"bifuntanki","vi":"máy nghiền than","level":2,"def_vi":"Máy nghiền than cục thành bột mịn và sấy khô bằng không khí nóng để thổi vào buồng đốt lò hơi.","def_en":"A mill that grinds and dries coal into fine powder to be blown into the boiler furnace.","def_ja":"石炭を細かく粉砕・乾燥し、ボイラの火炉へ送る粉砕機。","usage_en":"Danh từ đếm được. Hay đi với: coal pulverizer, vertical roller mill, pulverizer outlet temperature, mill trip; trong vận hành thường nói mill.","usage_ja":"Trong ca trực hay gọi ミル (ví dụ A ミル停止). Hay đi với: 微粉炭機出口温度, ローラミル, 石炭粉砕.","context_vi":"Dùng ở nhà máy nhiệt điện than đốt than phun, trong vận hành và bảo trì con lăn, bàn nghiền.","ex_en":"One pulverizer was stopped to replace the worn grinding rollers.","ex_ja":"摩耗した粉砕ローラを交換するため、微粉炭機を1台停止した。","ex_vi":"Một máy nghiền than đã được dừng để thay con lăn nghiền bị mòn.","syn_en":["coal mill","mill (khẩu ngữ)"],"syn_ja":["ミル (khẩu ngữ)","石炭粉砕機"]},{"en":"electrostatic precipitator","pos":"noun","ipa":"/ɪˌlektrəˈstætɪk prɪˈsɪpɪteɪtər/","ja":"電気集じん器","kana":"でんきしゅうじんき","romaji":"denkishuujinki","vi":"lọc bụi tĩnh điện","level":2,"def_vi":"Thiết bị dùng điện trường cao áp làm hạt bụi trong khói tích điện rồi bám lên điện cực lắng để tách bụi.","def_en":"A device that charges dust particles in flue gas with a high-voltage field and collects them on plates.","def_ja":"高電圧で排ガス中の粒子を帯電させ、集じん極に付着させて除去する装置。","usage_en":"Danh từ đếm được, viết tắt ESP. Hay đi với: ESP field, collecting plates, rapping system, ESP efficiency, fly ash hopper.","usage_ja":"Trong nhà máy hay gọi tắt EP (イーピー). Hay đi với: 電気集じん器の荷電, 集じん極, 槌打ち (gõ rũ bụi), フライアッシュ. Cũng viết 電気集塵器.","context_vi":"Dùng ở nhà máy nhiệt điện than, nhà máy xi măng, luyện kim để đáp ứng giới hạn bụi trong khí thải.","ex_en":"The electrostatic precipitator removes more than 99 % of the fly ash.","ex_ja":"電気集じん器はフライアッシュの99 %以上を除去する。","ex_vi":"Bộ lọc bụi tĩnh điện loại bỏ hơn 99 % tro bay.","syn_en":["ESP","bag filter (liên quan, lọc túi vải)"],"syn_ja":["EP (khẩu ngữ)","バグフィルタ (liên quan)"]},{"en":"flue gas desulfurization","pos":"noun phrase","ipa":"/ˈfluː ɡæs diːˌsʌlfjərəˈzeɪʃən/","ja":"排煙脱硫","kana":"はいえんだつりゅう","romaji":"haiendatsuryuu","vi":"khử lưu huỳnh khói thải (FGD)","level":2,"def_vi":"Quá trình loại bỏ SO2 khỏi khói thải, phổ biến nhất là phun huyền phù đá vôi trong tháp hấp thụ tạo thạch cao.","def_en":"Removal of SO2 from flue gas, most often by spraying limestone slurry in an absorber to form gypsum.","def_ja":"排ガスからSO2を除去する処理で、主に石灰石スラリーを吸収塔で噴霧し石こうを生成する。","usage_en":"Danh từ không đếm được, viết tắt FGD. Hay đi với: FGD system / plant / unit, wet limestone FGD, seawater FGD, absorber.","usage_ja":"Thiết bị gọi 排煙脱硫装置; khẩu ngữ nói gọn 脱硫 hoặc 脱硫装置. Hay đi với: 石灰石-石こう法, 吸収塔, 脱硫効率.","context_vi":"Dùng ở nhà máy nhiệt điện than, dầu để đáp ứng quy chuẩn khí thải SO2.","ex_en":"The new flue gas desulfurization unit cut SO2 emissions by 95 %.","ex_ja":"新しい排煙脱硫装置により、SO2排出量が95 %削減された。","ex_vi":"Hệ thống khử lưu huỳnh khói thải mới đã giảm 95 % lượng SO2 phát thải.","syn_en":["FGD","desulfurization (nghĩa rộng hơn)"],"syn_ja":["脱硫 (khẩu ngữ)","排煙脱硫装置 (thiết bị)"]},{"en":"penstock","pos":"noun","ipa":"/ˈpenstɑːk/","ja":"水圧管路","kana":"すいあつかんろ","romaji":"suiatsukanro","vi":"đường ống áp lực","level":2,"def_vi":"Ống thép hoặc đường hầm chịu áp lực dẫn nước từ cửa lấy nước hoặc tháp điều áp xuống tuabin nước.","def_en":"A steel pipe or pressure tunnel that carries water from the intake or surge tank down to the turbines.","def_ja":"取水口や調圧水槽から水車まで水を導く鋼管または圧力トンネル。","usage_en":"Danh từ đếm được. Hay đi với: steel penstock, penstock inlet valve, penstock inspection, water hammer in the penstock.","usage_ja":"Phần ống thép thường gọi 水圧鉄管 (すいあつてっかん). Hay đi với: 水圧管路の点検, 水撃 (búa nước), 入口弁.","context_vi":"Dùng trong thiết kế, thi công, kiểm tra nhà máy thủy điện, đặc biệt khi tính búa nước và độ dày ống.","ex_en":"The penstock wall thickness was checked for water hammer during load rejection.","ex_ja":"負荷遮断時の水撃に対して、水圧管路の管厚を照査した。","ex_vi":"Chiều dày thành đường ống áp lực đã được kiểm tra với búa nước khi sa thải phụ tải.","syn_en":["pressure pipe","pressure shaft (đoạn đứng trong hầm)"],"syn_ja":["水圧鉄管","ペンストック"]},{"en":"circulating water pump","pos":"noun","ipa":"/ˈsɜːrkjəleɪtɪŋ ˈwɔːtər pʌmp/","ja":"循環水ポンプ","kana":"じゅんかんすいポンプ","romaji":"junkansuiponpu","vi":"bơm nước tuần hoàn","level":2,"def_vi":"Bơm lưu lượng rất lớn đưa nước biển, nước sông hoặc nước tháp giải nhiệt qua bình ngưng để làm mát.","def_en":"A very high-flow pump that sends sea, river or cooling-tower water through the condenser.","def_ja":"海水・河川水・冷却塔の水を大量に復水器へ送る大容量ポンプ。","usage_en":"Danh từ đếm được, viết tắt CWP. Hay đi với: CW pump trip, vertical mixed-flow circulating water pump, CW system.","usage_ja":"Viết tắt CWP. Hay đi với: 循環水ポンプ停止, 海水取水, 立軸斜流ポンプ. Nếu dùng nước biển, khẩu ngữ gọi 海水ポンプ.","context_vi":"Dùng ở trạm bơm nước làm mát của nhà máy nhiệt điện ven biển và nhà máy điện hạt nhân.","ex_en":"Loss of a circulating water pump caused the condenser vacuum to fall quickly.","ex_ja":"循環水ポンプが停止し、復水器の真空度が急速に低下した。","ex_vi":"Việc mất một bơm nước tuần hoàn làm chân không bình ngưng giảm nhanh.","syn_en":["CW pump","cooling water pump (gần nghĩa)"],"syn_ja":["CWP","海水ポンプ (khi dùng nước biển)"]},{"en":"auxiliary equipment","pos":"noun phrase","ipa":"/ɔːɡˈzɪljəri ɪˈkwɪpmənt/","ja":"補機","kana":"ほき","romaji":"hoki","vi":"thiết bị phụ trợ","level":2,"def_vi":"Các máy phục vụ thiết bị chính như bơm, quạt, máy nghiền, máy nén khí, cần để lò hơi và tuabin hoạt động.","def_en":"The pumps, fans, mills, compressors and other machines that support the main boiler, turbine and generator.","def_ja":"ボイラ、タービン、発電機などの主機を動かすためのポンプ、ファン、ミルなどの機器。","usage_en":"Danh từ không đếm được; cũng hay nói auxiliaries (số nhiều). Hay đi với: auxiliary equipment power consumption, start the auxiliaries, balance of plant.","usage_ja":"Từ ngắn rất hay dùng, đối lập với 主機 (thiết bị chính). Hay đi với: 補機を起動する, 補機動力, 補機冷却水.","context_vi":"Dùng trong vận hành, khởi động tổ máy, tính điện tự dùng, lập kế hoạch bảo trì nhà máy điện và tàu thủy.","ex_en":"All auxiliary equipment must be running before the boiler is fired.","ex_ja":"ボイラ点火前に、すべての補機が運転中でなければならない。","ex_vi":"Mọi thiết bị phụ trợ phải đang chạy trước khi đốt lò.","syn_en":["auxiliaries","balance of plant (BOP, nghĩa rộng hơn)"],"syn_ja":["補機類","主機 (liên quan, đối nghĩa)"]},{"en":"trip","pos":"noun","ipa":"/trɪp/","ja":"トリップ","kana":"トリップ","romaji":"torippu","vi":"ngừng sự cố (trip)","level":2,"def_vi":"Việc thiết bị hoặc tổ máy bị hệ thống bảo vệ tự động dừng khẩn cấp khi có thông số vượt ngưỡng an toàn.","def_en":"An automatic emergency shutdown of equipment or a unit by the protection system when a limit is exceeded.","def_ja":"保護装置が異常を検知し、機器やユニットを自動で緊急停止させること。","usage_en":"Danh từ đếm được, cũng là động từ (the unit tripped). Hay đi với: turbine trip, boiler trip, unit trip, trip signal, reset the trip, trip on high vibration.","usage_ja":"Hay đi với: タービントリップ, ユニットトリップ, トリップする, トリップ要因, リセット. Văn bản trang trọng có thể dùng 緊急停止.","context_vi":"Dùng hằng ngày trong vận hành nhà máy điện, báo cáo sự cố, phân tích nguyên nhân ngừng máy.","ex_en":"The turbine trip was caused by high bearing vibration.","ex_ja":"軸受振動大によりタービントリップが発生した。","ex_vi":"Sự cố ngừng tuabin là do rung ổ trục cao.","syn_en":["emergency shutdown","shutdown (nghĩa rộng hơn)"],"syn_ja":["緊急停止","非常停止 (gần nghĩa)"]},{"en":"base load","pos":"noun","ipa":"/ˈbeɪs loʊd/","ja":"ベースロード","kana":"ベースロード","romaji":"beesuroodo","vi":"phụ tải nền","level":2,"def_vi":"Mức nhu cầu điện tối thiểu luôn có suốt ngày đêm, thường do các nhà máy chạy liên tục, giá rẻ đảm nhận.","def_en":"The minimum level of electricity demand present all day, usually met by low-cost plants running continuously.","def_ja":"一日中常に存在する最低限の電力需要で、安価で連続運転する電源がまかなう。","usage_en":"Danh từ không đếm được; dùng như tính từ: base-load plant, run at base load. Đối lập với peak load (phụ tải đỉnh) và mid-merit.","usage_ja":"Hay đi với: ベースロード電源 (nguồn chạy nền), ミドル電源, ピーク電源. Cũng gặp cách viết ベース負荷.","context_vi":"Dùng trong quy hoạch nguồn điện, điều độ hệ thống và khi phân vai các loại nhà máy.","ex_en":"Nuclear and coal units are usually operated at base load.","ex_ja":"原子力と石炭火力は通常、ベースロードで運転される。","ex_vi":"Các tổ máy hạt nhân và than thường được vận hành ở phụ tải nền.","syn_en":["baseload","peak load (liên quan, đối nghĩa)"],"syn_ja":["ベース負荷","ピーク負荷 (liên quan, đối nghĩa)"]},{"en":"grid synchronization","pos":"noun phrase","ipa":"/ˈɡrɪd ˌsɪŋkrənəˈzeɪʃən/","ja":"系統並列","kana":"けいとうへいれつ","romaji":"keitouheiretsu","vi":"hòa đồng bộ (hòa lưới)","level":2,"def_vi":"Thao tác đóng máy cắt nối máy phát vào lưới khi điện áp, tần số và góc pha của máy phát khớp với lưới.","def_en":"Closing the breaker to connect a generator to the grid once its voltage, frequency and phase match.","def_ja":"発電機の電圧、周波数、位相を系統に合わせ、遮断器を投入して系統につなぐこと。","usage_en":"Danh từ không đếm được. Hay đi với: synchronize the unit to the grid, synchronizing panel, synchroscope, first synchronization; báo cáo vận hành hay viết sync.","usage_ja":"Hay đi với: 並列する, 並列投入, 解列 (tách lưới), 同期検定. Trong ca trực thường chỉ nói 並列 (へいれつ).","context_vi":"Dùng khi khởi động tổ máy, chạy thử nghiệm thu và báo cáo vận hành nhà máy điện.","ex_en":"Grid synchronization was completed at 06:40, and the unit began to take load.","ex_ja":"6時40分に系統並列を完了し、ユニットは負荷を取り始めた。","ex_vi":"Việc hòa đồng bộ hoàn tất lúc 06:40 và tổ máy bắt đầu nhận tải.","syn_en":["synchronizing","sync (khẩu ngữ)"],"syn_ja":["並列 (khẩu ngữ)","同期投入"]},{"en":"planned outage","pos":"noun phrase","ipa":"/ˌplænd ˈaʊtɪdʒ/","ja":"計画停止","kana":"けいかくていし","romaji":"keikakuteishi","vi":"ngừng máy theo kế hoạch (đại tu)","level":2,"def_vi":"Khoảng thời gian tổ máy được dừng chủ động theo lịch để kiểm tra, bảo dưỡng, đại tu hoặc cải tạo.","def_en":"A scheduled period when a unit is shut down for inspection, maintenance, overhaul or upgrades.","def_ja":"点検、保守、オーバーホール、改造のために予定どおりユニットを停止する期間。","usage_en":"Danh từ đếm được. Hay đi với: major / minor planned outage, outage schedule, extend the outage; đối lập với forced outage (ngừng sự cố).","usage_ja":"Hay đi với: 計画停止中, 定期点検, 定期検査 (kiểm tra theo luật). Khẩu ngữ hay gọi 定検 (ていけん). Đối nghĩa: 計画外停止.","context_vi":"Dùng trong lập kế hoạch bảo trì, hợp đồng dịch vụ, báo cáo độ khả dụng của nhà máy điện.","ex_en":"The turbine overhaul is scheduled for the 45-day planned outage next spring.","ex_ja":"タービンのオーバーホールは、来春45日間の計画停止中に予定されている。","ex_vi":"Việc đại tu tuabin được lên lịch trong đợt ngừng máy theo kế hoạch 45 ngày vào mùa xuân tới.","syn_en":["scheduled outage","forced outage (liên quan, đối nghĩa)"],"syn_ja":["定検 (khẩu ngữ)","計画外停止 (liên quan, đối nghĩa)"]},{"en":"heat rate","pos":"noun","ipa":"/ˈhiːt reɪt/","ja":"熱消費率","kana":"ねつしょうひりつ","romaji":"netsushouhiritsu","vi":"suất tiêu hao nhiệt","level":3,"def_vi":"Lượng nhiệt nhiên liệu cần để sản xuất một kWh điện; trị số càng thấp thì nhà máy càng hiệu quả.","def_en":"The fuel heat needed to produce one kWh of electricity; a lower value means a more efficient plant.","def_ja":"1 kWhの電力をつくるのに必要な燃料の熱量で、小さいほど効率が良い。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: gross / net heat rate, heat rate in kJ/kWh, improve / degrade the heat rate, heat rate test.","usage_ja":"Hay đi với: 熱消費率の悪化, プラント熱効率 (liên quan nghịch đảo), 熱消費率試験. Đơn vị kJ/kWh.","context_vi":"Dùng trong đánh giá hiệu suất, nghiệm thu bảo đảm, hợp đồng mua bán điện và tối ưu vận hành nhà máy nhiệt điện.","ex_en":"Condenser fouling increased the net heat rate by 80 kJ/kWh.","ex_ja":"復水器の汚れにより、送電端熱消費率が80 kJ/kWh悪化した。","ex_vi":"Bám bẩn bình ngưng làm suất tiêu hao nhiệt tịnh tăng 80 kJ/kWh.","syn_en":["thermal efficiency (liên quan, nghịch đảo)"],"syn_ja":["ヒートレート","熱効率 (liên quan)"]},{"en":"capacity factor","pos":"noun","ipa":"/kəˈpæsəti ˌfæktər/","ja":"設備利用率","kana":"せつびりようりつ","romaji":"setsubiriyouritsu","vi":"hệ số sử dụng công suất (capacity factor)","level":3,"def_vi":"Tỷ số giữa điện năng thực phát trong một thời kỳ và điện năng nếu nhà máy chạy liên tục ở công suất định mức.","def_en":"The ratio of actual energy generated in a period to the energy at full rated output for the whole period.","def_ja":"ある期間の実際の発電量を、定格出力で運転し続けた場合の発電量で割った比率。","usage_en":"Danh từ đếm được. Hay đi với: annual capacity factor, a capacity factor of 85 %, low capacity factor of solar; không nhầm với power factor (hệ số công suất cos φ).","usage_ja":"Hay đi với: 設備利用率が高い/低い, 年間設備利用率. Đừng nhầm với 力率 (cos φ).","context_vi":"Dùng trong báo cáo vận hành, đánh giá kinh tế dự án điện, so sánh nhà máy nhiệt điện với điện gió, điện mặt trời.","ex_en":"The offshore wind farm achieved a capacity factor of 45 % last year.","ex_ja":"その洋上風力発電所の昨年の設備利用率は45 %だった。","ex_vi":"Trang trại điện gió ngoài khơi đạt hệ số sử dụng công suất 45 % năm ngoái.","syn_en":["load factor (Anh, gần nghĩa)","plant factor"],"syn_ja":["稼働率 (gần nghĩa, khẩu ngữ)","利用率"]},{"en":"station service power","pos":"noun phrase","ipa":"/ˈsteɪʃən ˈsɜːrvɪs ˌpaʊər/","ja":"所内電力","kana":"しょないでんりょく","romaji":"shonaidenryoku","vi":"điện tự dùng","level":3,"def_vi":"Điện năng nhà máy tự tiêu thụ để chạy bơm, quạt, máy nghiền, chiếu sáng…, lấy từ chính tổ máy hoặc từ lưới.","def_en":"Electricity consumed inside the plant by pumps, fans, mills and lighting, supplied by the unit or the grid.","def_ja":"ポンプ、ファン、ミル、照明など発電所内で消費する電力。","usage_en":"Danh từ không đếm được. Hay đi với: station service transformer, auxiliary power consumption, gross output minus station service = net output.","usage_ja":"Hay đi với: 所内変圧器, 所内率 (tỷ lệ điện tự dùng), 発電端 / 送電端出力 (công suất đầu cực / công suất phát lên lưới).","context_vi":"Dùng khi tính công suất phát lên lưới, hiệu suất tịnh và trong sơ đồ cấp điện nội bộ nhà máy.","ex_en":"Station service power is about 6 % of gross output in this coal-fired unit.","ex_ja":"この石炭火力ユニットの所内電力は発電端出力の約6 %である。","ex_vi":"Điện tự dùng chiếm khoảng 6 % công suất đầu cực ở tổ máy nhiệt điện than này.","syn_en":["auxiliary power consumption","house load"],"syn_ja":["所内動力","所内率 (tỷ lệ, liên quan)"]},{"en":"selective catalytic reduction","pos":"noun phrase","ipa":"/sɪˌlektɪv ˌkætəˈlɪtɪk rɪˈdʌkʃən/","ja":"排煙脱硝","kana":"はいえんだっしょう","romaji":"haiendasshou","vi":"khử NOx xúc tác chọn lọc (SCR)","level":3,"def_vi":"Phương pháp phun amoniac vào khói thải rồi cho qua lớp xúc tác để biến NOx thành nitơ và nước.","def_en":"A process injecting ammonia into flue gas over a catalyst to convert NOx into nitrogen and water.","def_ja":"排ガスにアンモニアを注入し、触媒上でNOxを窒素と水に分解する方法。","usage_en":"Danh từ không đếm được, viết tắt SCR. Hay đi với: SCR catalyst, ammonia slip, SCR reactor, NOx removal efficiency; khác SNCR (không dùng xúc tác).","usage_ja":"Thiết bị gọi 排煙脱硝装置 hoặc gọn 脱硝装置; phương pháp gọi アンモニア接触還元法 hoặc 選択的触媒還元. Hay đi với: 脱硝触媒, リークアンモニア.","context_vi":"Dùng ở nhà máy nhiệt điện than, khí, tuabin khí, động cơ diesel tàu thủy để đạt giới hạn NOx.","ex_en":"Selective catalytic reduction reduces NOx at the boiler outlet by about 80 %.","ex_ja":"排煙脱硝によって、ボイラ出口のNOxを約80 %低減する。","ex_vi":"Khử NOx xúc tác chọn lọc giảm khoảng 80 % NOx tại đầu ra lò hơi.","syn_en":["SCR","DeNOx (khẩu ngữ)"],"syn_ja":["脱硝装置","SCR"]},{"en":"load following","pos":"noun phrase","ipa":"/ˈloʊd ˌfɑːloʊɪŋ/","ja":"負荷追従","kana":"ふかついじゅう","romaji":"fukatsuijuu","vi":"bám phụ tải (điều chỉnh công suất theo phụ tải)","level":3,"def_vi":"Khả năng hoặc chế độ tổ máy liên tục thay đổi công suất theo biến động nhu cầu điện trong ngày.","def_en":"The ability or mode of a unit to change its output continuously as electricity demand varies.","def_ja":"電力需要の変動に合わせて、ユニットの出力を連続的に変化させる運転やその能力。","usage_en":"Danh từ không đếm được; dùng như tính từ: load-following operation, load-following plant. Hay đi với: ramp rate (MW/min), minimum load.","usage_ja":"Hay đi với: 負荷追従運転, 負荷変化率 (tốc độ thay đổi tải), 最低負荷, DSS運転 (khởi động–dừng hằng ngày).","context_vi":"Dùng khi nhà máy nhiệt điện phải bù cho điện mặt trời, điện gió biến động, trong yêu cầu kỹ thuật đấu nối lưới.","ex_en":"The gas turbines are used for load following when solar output drops in the evening.","ex_ja":"夕方に太陽光の出力が下がると、ガスタービンが負荷追従を行う。","ex_vi":"Khi công suất điện mặt trời giảm vào buổi tối, các tuabin khí đảm nhận việc bám phụ tải.","syn_en":["load-following operation","cycling operation (gần nghĩa)"],"syn_ja":["負荷追従運転","負荷調整 (gần nghĩa)"]},{"en":"black start","pos":"noun","ipa":"/ˌblæk ˈstɑːrt/","ja":"ブラックスタート","kana":"ブラックスタート","romaji":"burakkusutaato","vi":"khởi động đen (khởi động khi mất điện toàn lưới)","level":3,"def_vi":"Khả năng khởi động lại tổ máy mà không cần điện từ lưới, nhờ máy phát diesel hay thủy điện, để khôi phục hệ thống sau rã lưới.","def_en":"Restarting a unit without power from the grid, using its own diesel or hydro source, to restore a collapsed system.","def_ja":"系統からの電力なしに、非常用発電機などで発電所を起動し、停電した系統を復旧させること。","usage_en":"Danh từ không đếm được; dùng như tính từ: black-start capability, black-start unit, black-start diesel generator.","usage_ja":"Hay đi với: ブラックスタート機能, ブラックスタート電源, 全停電 (mất điện toàn bộ), 系統復旧.","context_vi":"Dùng trong kế hoạch khôi phục hệ thống điện, yêu cầu dịch vụ phụ trợ, thiết kế nhà máy thủy điện và tuabin khí.","ex_en":"The hydro plant provides black start service to restore the southern grid.","ex_ja":"この水力発電所は、南部系統を復旧させるブラックスタート電源の役割を持つ。","ex_vi":"Nhà máy thủy điện cung cấp dịch vụ khởi động đen để khôi phục lưới điện miền Nam.","syn_en":["black-start capability","system restoration (liên quan)"],"syn_ja":["自立起動","系統復旧 (liên quan)"]},{"en":"control rod","pos":"noun","ipa":"/kənˈtroʊl rɑːd/","ja":"制御棒","kana":"せいぎょぼう","romaji":"seigyobou","vi":"thanh điều khiển","level":3,"def_vi":"Thanh chứa vật liệu hấp thụ nơtron, cắm vào hoặc rút ra khỏi lõi lò phản ứng để điều chỉnh hoặc dừng phản ứng phân hạch.","def_en":"A rod of neutron-absorbing material inserted into or withdrawn from a reactor core to control or stop fission.","def_ja":"中性子を吸収する材料の棒で、炉心へ出し入れして核分裂反応を制御・停止する。","usage_en":"Danh từ đếm được. Hay đi với: insert / withdraw the control rods, control rod drive mechanism (CRDM), scram (dừng lò khẩn cấp).","usage_ja":"Hay đi với: 制御棒を挿入する, 制御棒を引き抜く, 制御棒駆動機構, スクラム (dừng lò khẩn cấp).","context_vi":"Dùng trong vận hành, an toàn và thiết kế cơ khí lò phản ứng của nhà máy điện hạt nhân.","ex_en":"All control rods were inserted automatically within two seconds after the scram signal.","ex_ja":"スクラム信号の後、2秒以内に全制御棒が自動挿入された。","ex_vi":"Tất cả thanh điều khiển đã được tự động cắm vào trong vòng hai giây sau tín hiệu dừng lò khẩn cấp.","syn_en":["control element (gần nghĩa)","scram (liên quan)"],"syn_ja":["制御要素 (gần nghĩa)","スクラム (liên quan)"]}]},{"id":98,"words":[{"en":"project manager","pos":"noun","ipa":"/ˈprɑːdʒekt ˌmænɪdʒər/","ja":"プロジェクトマネージャ","kana":"プロジェクトマネージャ","romaji":"purojekutomaneeja","vi":"quản lý dự án (PM)","level":1,"def_vi":"Người chịu trách nhiệm chính lập kế hoạch, điều phối nguồn lực và đưa dự án hoàn thành đúng phạm vi, tiến độ, ngân sách.","def_en":"The person responsible for planning, coordinating resources and delivering a project on scope, time and budget.","def_ja":"計画を立て資源を調整し、範囲・期間・予算どおりにプロジェクトを完遂させる責任者。","usage_en":"Danh từ đếm được, viết tắt PM. Hay đi với: appoint a project manager, report to the project manager, project manager for the plant expansion.","usage_ja":"Hay viết tắt PM; khẩu ngữ gọi プロマネ. Cách viết プロジェクトマネージャー (có ー cuối) cũng phổ biến. Trong dự án Nhật còn có 工事責任者, 所長 tùy ngành.","context_vi":"Dùng trong mọi dự án kỹ thuật: lắp đặt dây chuyền, xây dựng nhà máy, phát triển sản phẩm, dự án EPC.","ex_en":"The project manager approved the revised installation schedule.","ex_ja":"プロジェクトマネージャが改訂した据付工程を承認した。","ex_vi":"Quản lý dự án đã phê duyệt tiến độ lắp đặt sửa đổi.","syn_en":["PM","project lead (gần nghĩa)"],"syn_ja":["PM","プロマネ (khẩu ngữ)"]},{"en":"project schedule","pos":"noun","ipa":"/ˈprɑːdʒekt ˌskedʒuːl/","ja":"工程表","kana":"こうていひょう","romaji":"kouteihyou","vi":"tiến độ dự án (bảng tiến độ)","level":1,"def_vi":"Bảng hoặc sơ đồ liệt kê các công việc của dự án với ngày bắt đầu, ngày kết thúc và thứ tự thực hiện.","def_en":"A table or chart listing project activities with their start dates, finish dates and sequence.","def_ja":"プロジェクトの作業を開始日・終了日・順序とともに示した表や図。","usage_en":"Danh từ đếm được. Hay đi với: prepare / update / issue the project schedule, be on / behind / ahead of schedule, master schedule, detailed schedule.","usage_ja":"Hay đi với: 工程表を作成する, 全体工程表, 詳細工程表, 工程が遅れる. Trong nói chuyện hằng ngày cũng dùng スケジュール; 工程 ở đây là tiến độ (khác 工程 = công đoạn sản xuất).","context_vi":"Dùng trong họp tiến độ, báo cáo cho khách hàng, lập kế hoạch thi công, lắp đặt và chạy thử.","ex_en":"The updated project schedule shows commissioning starting on 15 March.","ex_ja":"更新した工程表では、試運転は3月15日開始となっている。","ex_vi":"Tiến độ dự án cập nhật cho thấy chạy thử bắt đầu ngày 15 tháng 3.","syn_en":["programme (Anh)","timeline (khẩu ngữ)"],"syn_ja":["スケジュール","日程表"]},{"en":"milestone","pos":"noun","ipa":"/ˈmaɪlstoʊn/","ja":"マイルストーン","kana":"マイルストーン","romaji":"mairusutoon","vi":"mốc quan trọng (milestone)","level":1,"def_vi":"Thời điểm hoặc sự kiện quan trọng trong dự án, như hoàn thành thiết kế hay giao thiết bị, dùng để kiểm soát tiến độ.","def_en":"A key point or event in a project, such as design completion or equipment delivery, used to track progress.","def_ja":"設計完了や機器納入など、進捗管理の節目となる重要な時点や出来事。","usage_en":"Danh từ đếm được. Hay đi với: reach / achieve / miss a milestone, key milestone, milestone payment, milestone date; milestone có thời lượng bằng 0.","usage_ja":"Hay đi với: マイルストーンを設定する, マイルストーンを達成する, 主要マイルストーン. Văn bản tiếng Nhật thuần đôi khi dùng 節目 hoặc 里程標.","context_vi":"Dùng trong lập kế hoạch, hợp đồng thanh toán theo mốc, báo cáo tiến độ cho ban lãnh đạo.","ex_en":"Factory acceptance testing is the next milestone in the project.","ex_ja":"工場立会検査が、このプロジェクトの次のマイルストーンである。","ex_vi":"Thử nghiệm nghiệm thu tại xưởng là mốc quan trọng tiếp theo của dự án.","syn_en":["key date","checkpoint (gần nghĩa)"],"syn_ja":["節目","主要日程 (gần nghĩa)"]},{"en":"deadline","pos":"noun","ipa":"/ˈdedlaɪn/","ja":"期限","kana":"きげん","romaji":"kigen","vi":"hạn chót","level":1,"def_vi":"Ngày hoặc giờ muộn nhất mà một công việc, tài liệu hay sản phẩm phải được hoàn thành hoặc nộp.","def_en":"The latest date or time by which a task, document or product must be completed or submitted.","def_ja":"作業、書類、製品を完了または提出しなければならない最終の日時。","usage_en":"Danh từ đếm được. Hay đi với: meet / miss a deadline, tight deadline, extend the deadline, submission deadline; dùng giới từ by the deadline.","usage_ja":"Hay đi với: 期限を守る, 期限に間に合う, 提出期限, 期限を延長する. Khẩu ngữ hay dùng 締め切り; giao hàng thì dùng 納期.","context_vi":"Dùng khi giao việc, nộp bản vẽ, nộp hồ sơ thầu, giao thiết bị và trong email nhắc việc.","ex_en":"We will meet the deadline for the drawing submission if the client replies by Friday.","ex_ja":"顧客が金曜日までに回答すれば、図面提出の期限に間に合う。","ex_vi":"Chúng ta sẽ kịp hạn chót nộp bản vẽ nếu khách hàng trả lời trước thứ Sáu.","syn_en":["due date","cut-off date"],"syn_ja":["締め切り (khẩu ngữ)","納期 (gần nghĩa, ngày giao hàng)"]},{"en":"budget","pos":"noun","ipa":"/ˈbʌdʒɪt/","ja":"予算","kana":"よさん","romaji":"yosan","vi":"ngân sách","level":1,"def_vi":"Tổng số tiền được phê duyệt để chi cho dự án hoặc một hạng mục, chia theo các khoản chi phí.","def_en":"The approved amount of money to be spent on a project or work package, broken down by cost item.","def_ja":"プロジェクトや作業に使うことが承認された金額で、費目ごとに配分したもの。","usage_en":"Danh từ đếm được; cũng là động từ (budget for spare parts). Hay đi với: within / over / under budget, approve the budget, budget estimate, capital budget.","usage_ja":"Hay đi với: 予算内に収める, 予算を超える, 予算を確保する, 予算申請, 設備予算.","context_vi":"Dùng khi lập dự toán, xin phê duyệt đầu tư, theo dõi chi phí và báo cáo tài chính dự án.","ex_en":"The conveyor upgrade was completed 5 % under budget.","ex_ja":"コンベヤ更新工事は予算より5 %少なく完了した。","ex_vi":"Việc nâng cấp băng tải hoàn thành thấp hơn ngân sách 5 %.","syn_en":["cost budget","estimate (gần nghĩa)"],"syn_ja":["予算額","見積 (gần nghĩa)"]},{"en":"scope","pos":"noun","ipa":"/skoʊp/","ja":"スコープ","kana":"スコープ","romaji":"sukoopu","vi":"phạm vi công việc","level":1,"def_vi":"Toàn bộ công việc, sản phẩm và giới hạn mà dự án hoặc hợp đồng phải thực hiện, kể cả những gì không bao gồm.","def_en":"The total work, deliverables and boundaries a project or contract must cover, including what is excluded.","def_ja":"プロジェクトや契約で実施する作業・成果物とその範囲、および対象外の事項。","usage_en":"Danh từ không đếm được. Hay đi với: scope of work (SOW), in scope / out of scope, define the scope, scope change; không dùng số nhiều scopes trong nghĩa này.","usage_ja":"Hay đi với: スコープ外, スコープを明確にする. Trong văn bản Nhật hay dùng 作業範囲, 業務範囲, 工事範囲; bảng phân chia gọi 取合い表 hoặc 責任範囲表.","context_vi":"Dùng trong hợp đồng, hồ sơ mời thầu, họp khởi động dự án và khi tranh luận ai phải làm hạng mục nào.","ex_en":"Foundation work is outside our scope and will be done by the client.","ex_ja":"基礎工事は当社のスコープ外で、顧客が実施する。","ex_vi":"Phần móng nằm ngoài phạm vi công việc của chúng tôi và sẽ do khách hàng thực hiện.","syn_en":["scope of work (SOW)","work scope"],"syn_ja":["作業範囲","業務範囲"]},{"en":"kickoff meeting","pos":"noun","ipa":"/ˈkɪkɔːf ˌmiːtɪŋ/","ja":"キックオフミーティング","kana":"キックオフミーティング","romaji":"kikkuofumiitingu","vi":"cuộc họp khởi động dự án","level":1,"def_vi":"Cuộc họp đầu tiên của dự án để thống nhất mục tiêu, phạm vi, tổ chức, tiến độ và cách liên lạc giữa các bên.","def_en":"The first project meeting to agree on objectives, scope, organization, schedule and communication.","def_ja":"目標、範囲、体制、日程、連絡方法を関係者で確認するプロジェクト最初の会議。","usage_en":"Danh từ đếm được. Hay đi với: hold / attend a kickoff meeting, kickoff meeting minutes, project kickoff; cũng viết kick-off meeting.","usage_ja":"Hay đi với: キックオフミーティングを開催する, キックオフ会議. Khẩu ngữ chỉ nói キックオフ.","context_vi":"Dùng ngay sau khi ký hợp đồng hoặc phê duyệt dự án, giữa khách hàng, nhà thầu và nhà cung cấp.","ex_en":"The kickoff meeting with the customer is scheduled for next Monday.","ex_ja":"顧客とのキックオフミーティングは来週月曜日に予定されている。","ex_vi":"Cuộc họp khởi động với khách hàng được lên lịch vào thứ Hai tuần sau.","syn_en":["kick-off meeting","project launch meeting"],"syn_ja":["キックオフ (khẩu ngữ)","キックオフ会議"]},{"en":"progress","pos":"noun","ipa":"/ˈprɑːɡres/","ja":"進捗","kana":"しんちょく","romaji":"shinchoku","vi":"tiến độ (mức độ hoàn thành)","level":1,"def_vi":"Mức độ công việc đã hoàn thành so với kế hoạch tại một thời điểm, thường tính bằng phần trăm.","def_en":"How much of the work has been completed compared with the plan at a given time, often in percent.","def_ja":"ある時点で計画に対して作業がどれだけ進んだかの度合いで、多くは百分率で表す。","usage_en":"Danh từ không đếm được (không nói a progress / progresses). Hay đi với: make progress, progress report, track progress, physical progress of 60 %.","usage_ja":"Từ rất hay dùng trong công ty Nhật: 進捗報告, 進捗状況, 進捗率, 進捗を確認する. Khẩu ngữ: 進捗どう? (tiến độ thế nào?).","context_vi":"Dùng trong họp giao ban, báo cáo tuần/tháng, theo dõi tiến độ thiết kế, chế tạo và lắp đặt.","ex_en":"Overall progress on the piping installation is 72 %.","ex_ja":"配管据付の全体進捗は72 %である。","ex_vi":"Tiến độ tổng thể lắp đặt đường ống đạt 72 %.","syn_en":["status (gần nghĩa)","percent complete"],"syn_ja":["進捗状況","進み具合 (khẩu ngữ)"]},{"en":"stakeholder","pos":"noun","ipa":"/ˈsteɪkhoʊldər/","ja":"ステークホルダー","kana":"ステークホルダー","romaji":"suteekuhorudaa","vi":"bên liên quan","level":1,"def_vi":"Cá nhân hoặc tổ chức có quyền lợi bị ảnh hưởng bởi dự án hoặc có thể ảnh hưởng tới dự án.","def_en":"A person or organization that can affect, or is affected by, a project.","def_ja":"プロジェクトに影響を与える、または影響を受ける個人や組織。","usage_en":"Danh từ đếm được, thường số nhiều. Hay đi với: key stakeholders, stakeholder analysis, inform / engage stakeholders, stakeholder approval.","usage_ja":"Hay đi với: ステークホルダーと調整する, ステークホルダー分析. Văn bản trang trọng dùng 利害関係者; trong công ty hay nói 関係者, 関係部署.","context_vi":"Dùng khi lập kế hoạch truyền thông, phân tích ảnh hưởng, lấy ý kiến khách hàng, chính quyền, cộng đồng.","ex_en":"All stakeholders must review the layout before the design freeze.","ex_ja":"設計凍結の前に、すべてのステークホルダーがレイアウトを確認しなければならない。","ex_vi":"Tất cả các bên liên quan phải xem lại bố trí mặt bằng trước khi chốt thiết kế.","syn_en":["interested party","concerned party (gần nghĩa)"],"syn_ja":["利害関係者","関係者 (khẩu ngữ)"]},{"en":"delay","pos":"noun","ipa":"/dɪˈleɪ/","ja":"遅延","kana":"ちえん","romaji":"chien","vi":"chậm trễ (chậm tiến độ)","level":1,"def_vi":"Việc công việc hoặc giao hàng hoàn thành muộn hơn ngày đã lên kế hoạch hoặc cam kết.","def_en":"A situation in which work or delivery is completed later than planned or agreed.","def_ja":"作業や納入が計画または約束した日より遅れること。","usage_en":"Danh từ đếm được và không đếm được; cũng là động từ (the shipment was delayed). Hay đi với: cause / avoid / recover a delay, two-week delay, delay in delivery, delay penalty.","usage_ja":"Hay đi với: 工程遅延, 納期遅延, 遅延が発生する, 遅延を挽回する. Khẩu ngữ hay nói 遅れ (おくれ), ví dụ 2週間の遅れ.","context_vi":"Dùng trong báo cáo tiến độ, thư gửi khách hàng, khi phân tích nguyên nhân và yêu cầu gia hạn.","ex_en":"The delay in steel delivery pushed the fabrication start back by two weeks.","ex_ja":"鋼材納入の遅延により、製作開始が2週間後ろにずれた。","ex_vi":"Việc chậm giao thép làm việc bắt đầu gia công lùi lại hai tuần.","syn_en":["slippage (gần nghĩa)","hold-up (khẩu ngữ)"],"syn_ja":["遅れ (khẩu ngữ)","工程遅延"]},{"en":"work breakdown structure","pos":"noun phrase","ipa":"/ˌwɜːrk ˈbreɪkdaʊn ˌstrʌktʃər/","ja":"作業分解構成図","kana":"さぎょうぶんかいこうせいず","romaji":"sagyoubunkaikouseizu","vi":"cấu trúc phân chia công việc (WBS)","level":2,"def_vi":"Sơ đồ phân cấp chia toàn bộ phạm vi dự án thành các gói công việc nhỏ hơn, dễ giao việc, ước tính và kiểm soát.","def_en":"A hierarchical breakdown of the total project scope into smaller work packages that can be assigned and controlled.","def_ja":"プロジェクト全体の作業を、管理しやすい小さな作業パッケージへ階層的に分解したもの。","usage_en":"Danh từ đếm được, gần như luôn viết tắt WBS. Hay đi với: develop the WBS, WBS level, WBS code, work package.","usage_ja":"Trong thực tế gần như chỉ nói WBS (ダブリュービーエス); tên tiếng Nhật đầy đủ dùng trong sách. Hay đi với: WBSを作成する, ワークパッケージ.","context_vi":"Dùng khi lập kế hoạch dự án, mã hóa chi phí, giao việc cho các nhóm thiết kế, chế tạo, lắp đặt.","ex_en":"The work breakdown structure divides the plant into civil, mechanical, piping and electrical packages.","ex_ja":"作業分解構成図では、プラントを土木、機械、配管、電気のパッケージに分けている。","ex_vi":"Cấu trúc phân chia công việc chia nhà máy thành các gói xây dựng, cơ khí, đường ống và điện.","syn_en":["WBS"],"syn_ja":["WBS","ワークブレークダウンストラクチャ"]},{"en":"critical path","pos":"noun","ipa":"/ˌkrɪtɪkəl ˈpæθ/","ja":"クリティカルパス","kana":"クリティカルパス","romaji":"kuritikarupasu","vi":"đường găng","level":2,"def_vi":"Chuỗi công việc dài nhất trong mạng tiến độ, quyết định thời gian hoàn thành dự án; công việc trên đó không có thời gian dự trữ.","def_en":"The longest sequence of dependent activities, which sets the project finish date; its activities have zero float.","def_ja":"工程網の中で最も長い作業の連なりで、全体の完了日を決め、余裕がない経路。","usage_en":"Danh từ đếm được. Hay đi với: on the critical path, critical path method (CPM), critical path activity, shorten the critical path.","usage_ja":"Hay đi với: クリティカルパス上の作業, クリティカルパス法 (CPM), クリティカルパスを短縮する. Trong sách cũ còn gọi 臨界経路.","context_vi":"Dùng khi lập tiến độ mạng, phân tích ảnh hưởng chậm trễ, quyết định tăng ca hay thêm nhân lực.","ex_en":"Delivery of the main gearbox is on the critical path, so any delay moves the finish date.","ex_ja":"主減速機の納入はクリティカルパス上にあるため、遅れると完了日がずれる。","ex_vi":"Việc giao hộp giảm tốc chính nằm trên đường găng nên bất kỳ chậm trễ nào cũng làm lùi ngày hoàn thành.","syn_en":["CPM (phương pháp, liên quan)","longest path"],"syn_ja":["臨界経路 (sách cũ)","CPM (liên quan)"]},{"en":"deliverable","pos":"noun","ipa":"/dɪˈlɪvərəbəl/","ja":"成果物","kana":"せいかぶつ","romaji":"seikabutsu","vi":"sản phẩm bàn giao","level":2,"def_vi":"Kết quả cụ thể, có thể kiểm tra được mà dự án phải giao, như bản vẽ, báo cáo tính toán, thiết bị, phần mềm.","def_en":"A specific, verifiable output a project must hand over, such as drawings, calculations, equipment or software.","def_ja":"図面、計算書、機器、ソフトなど、プロジェクトが引き渡すべき具体的で確認可能な成果。","usage_en":"Danh từ đếm được, thường số nhiều. Hay đi với: project deliverables, deliverable list, submit / review / approve a deliverable.","usage_ja":"Hay đi với: 成果物を提出する, 成果物一覧, 納品物 (gần nghĩa). Trong dự án EPC, danh sách tài liệu nộp gọi 提出図書リスト.","context_vi":"Dùng trong hợp đồng, kế hoạch dự án, danh mục tài liệu nộp và khi nghiệm thu từng giai đoạn.","ex_en":"The stress report is a contractual deliverable due at the end of basic design.","ex_ja":"応力計算書は、基本設計終了時に提出すべき契約上の成果物である。","ex_vi":"Báo cáo tính ứng suất là sản phẩm bàn giao theo hợp đồng, đến hạn khi kết thúc thiết kế cơ sở.","syn_en":["output (gần nghĩa)","work product"],"syn_ja":["納品物 (gần nghĩa)","提出図書 (tài liệu nộp)"]},{"en":"risk register","pos":"noun","ipa":"/ˈrɪsk ˌredʒɪstər/","ja":"リスク登録簿","kana":"リスクとうろくぼ","romaji":"risukutourokubo","vi":"sổ đăng ký rủi ro","level":2,"def_vi":"Bảng liệt kê các rủi ro của dự án cùng khả năng xảy ra, mức ảnh hưởng, người phụ trách và biện pháp ứng phó.","def_en":"A list of project risks with their likelihood, impact, owner and response actions.","def_ja":"プロジェクトのリスクを発生確率、影響度、担当者、対応策とともに一覧にしたもの。","usage_en":"Danh từ đếm được. Hay đi với: update / maintain the risk register, add a risk to the risk register, risk owner, mitigation plan.","usage_ja":"Tên theo PMBOK tiếng Nhật; trong công ty hay gọi リスク一覧表 hoặc リスク管理表. Hay đi với: リスクを登録する, 対応策, リスクオーナー.","context_vi":"Dùng trong quản lý rủi ro dự án, họp định kỳ với khách hàng, báo cáo cho ban giám đốc.","ex_en":"Late approval of the vendor drawings was added to the risk register.","ex_ja":"ベンダー図面の承認遅れをリスク登録簿に追加した。","ex_vi":"Việc phê duyệt chậm bản vẽ nhà cung cấp đã được thêm vào sổ đăng ký rủi ro.","syn_en":["risk log"],"syn_ja":["リスク一覧表","リスク管理表"]},{"en":"responsibility assignment matrix","pos":"noun phrase","ipa":"/rɪˌspɑːnsəˈbɪləti əˈsaɪnmənt ˌmeɪtrɪks/","ja":"責任分担表","kana":"せきにんぶんたんひょう","romaji":"sekininbuntanhyou","vi":"ma trận phân công trách nhiệm (RACI)","level":2,"def_vi":"Bảng ma trận chỉ rõ ai thực hiện, ai chịu trách nhiệm, ai được hỏi ý kiến và ai được thông báo cho từng công việc.","def_en":"A matrix showing who is responsible, accountable, consulted and informed for each task.","def_ja":"各作業について実行・説明責任・相談・報告の担当を示すマトリクス表。","usage_en":"Danh từ đếm được, viết tắt RAM; dạng phổ biến là RACI chart (Responsible, Accountable, Consulted, Informed).","usage_ja":"Hay gọi RACIチャート hoặc 役割分担表. Trong dự án EPC Nhật, bảng phân chia phạm vi giữa các bên gọi 責任分担表 hoặc 取合い表.","context_vi":"Dùng khi tổ chức dự án nhiều bên, phân vai giữa khách hàng, nhà thầu chính, nhà thầu phụ.","ex_en":"According to the responsibility assignment matrix, the vendor is responsible for site supervision.","ex_ja":"責任分担表によると、現地指導はベンダーの担当である。","ex_vi":"Theo ma trận phân công trách nhiệm, nhà cung cấp chịu trách nhiệm giám sát tại công trường.","syn_en":["RACI chart","RAM"],"syn_ja":["RACIチャート","役割分担表"]},{"en":"change request","pos":"noun","ipa":"/ˈtʃeɪndʒ rɪˌkwest/","ja":"変更要求","kana":"へんこうようきゅう","romaji":"henkouyoukyuu","vi":"yêu cầu thay đổi","level":2,"def_vi":"Đề nghị chính thức thay đổi phạm vi, thiết kế, tiến độ hoặc chi phí đã duyệt, phải được đánh giá và phê duyệt trước khi làm.","def_en":"A formal proposal to change approved scope, design, schedule or cost that must be assessed and approved.","def_ja":"承認済みの範囲、設計、日程、費用を変更するための正式な申し入れ。","usage_en":"Danh từ đếm được, viết tắt CR. Hay đi với: raise / submit / approve / reject a change request, change request form, change control board.","usage_ja":"Hay đi với: 変更要求を出す, 変更依頼書, 変更管理. Trong hợp đồng xây lắp, khi đã ký kết thì là 設計変更 hoặc 契約変更.","context_vi":"Dùng khi khách hàng muốn thêm, bớt hạng mục, khi thiết kế phải sửa, và trong thủ tục kiểm soát thay đổi.","ex_en":"The customer submitted a change request to add a second discharge chute.","ex_ja":"顧客から、2つ目の排出シュートを追加する変更要求が出された。","ex_vi":"Khách hàng đã gửi yêu cầu thay đổi để bổ sung máng xả thứ hai.","syn_en":["CR","variation request (Anh, hợp đồng)"],"syn_ja":["変更依頼","設計変更 (gần nghĩa)"]},{"en":"baseline","pos":"noun","ipa":"/ˈbeɪslaɪn/","ja":"ベースライン","kana":"ベースライン","romaji":"beesurain","vi":"đường cơ sở (kế hoạch gốc)","level":2,"def_vi":"Phiên bản kế hoạch phạm vi, tiến độ hoặc chi phí đã được phê duyệt, dùng làm chuẩn để so sánh với thực tế.","def_en":"The approved version of the scope, schedule or cost plan used as the reference for measuring performance.","def_ja":"承認された範囲・日程・コスト計画で、実績と比較する基準とするもの。","usage_en":"Danh từ đếm được. Hay đi với: schedule baseline, cost baseline, set / re-baseline the plan, compare actual vs baseline.","usage_ja":"Hay đi với: スケジュールベースライン, コストベースライン, ベースラインと比較する. Trong công ty hay nói 当初計画 (kế hoạch ban đầu).","context_vi":"Dùng trong theo dõi tiến độ, phân tích chênh lệch, báo cáo EVM và khi phải lập lại kế hoạch.","ex_en":"The project is now three weeks behind the approved baseline.","ex_ja":"プロジェクトは現在、承認済みのベースラインより3週間遅れている。","ex_vi":"Dự án hiện chậm ba tuần so với kế hoạch gốc đã duyệt.","syn_en":["baseline plan","original plan (khẩu ngữ)"],"syn_ja":["当初計画","基準計画"]},{"en":"resource allocation","pos":"noun phrase","ipa":"/ˈriːsɔːrs ˌæləˈkeɪʃən/","ja":"リソース配分","kana":"リソースはいぶん","romaji":"risoosuhaibun","vi":"phân bổ nguồn lực","level":2,"def_vi":"Việc phân chia nhân lực, máy móc, vật tư và tiền cho các công việc của dự án theo thời gian.","def_en":"Assigning people, equipment, materials and money to project activities over time.","def_ja":"人員、機材、資材、資金をプロジェクトの作業に時間軸で割り当てること。","usage_en":"Danh từ không đếm được. Hay đi với: resource allocation plan, optimize resource allocation, allocate engineers to a task, resource conflict.","usage_ja":"Hay đi với: リソースを配分する, 要員計画 (kế hoạch nhân lực), 人員の割り当て. Văn bản cũng dùng 資源配分.","context_vi":"Dùng khi nhiều dự án chạy song song tranh nhau kỹ sư, thợ, cẩu, máy móc.","ex_en":"Resource allocation was revised to move two welders to the critical tank work.","ex_ja":"リソース配分を見直し、溶接工2名を重要なタンク工事へ回した。","ex_vi":"Phân bổ nguồn lực đã được điều chỉnh để chuyển hai thợ hàn sang công việc bồn chứa quan trọng.","syn_en":["resource assignment","resource planning (gần nghĩa)"],"syn_ja":["資源配分","要員配置 (gần nghĩa, nhân lực)"]},{"en":"progress meeting","pos":"noun","ipa":"/ˈprɑːɡres ˌmiːtɪŋ/","ja":"定例会議","kana":"ていれいかいぎ","romaji":"teireikaigi","vi":"họp giao ban tiến độ (họp định kỳ)","level":2,"def_vi":"Cuộc họp tổ chức đều đặn (hằng tuần, hằng tháng) giữa các bên để rà soát tiến độ, vấn đề và hành động tiếp theo.","def_en":"A regular weekly or monthly meeting where parties review progress, issues and next actions.","def_ja":"週次・月次などで定期的に開き、進捗、課題、次の行動を確認する会議。","usage_en":"Danh từ đếm được. Hay đi với: weekly progress meeting, progress meeting minutes, action items, chair the progress meeting.","usage_ja":"Khẩu ngữ gọi tắt 定例. Hay đi với: 週次定例, 工程会議, 議事録 (biên bản), 定例で報告する.","context_vi":"Dùng trong mọi dự án lắp đặt, xây dựng, thiết kế; biên bản họp là tài liệu quan trọng khi có tranh chấp.","ex_en":"The welding issue will be discussed at Thursday's progress meeting.","ex_ja":"溶接の問題は木曜日の定例会議で議論する。","ex_vi":"Vấn đề hàn sẽ được thảo luận tại cuộc họp giao ban tiến độ thứ Năm.","syn_en":["status meeting","weekly meeting"],"syn_ja":["定例 (khẩu ngữ)","工程会議"]},{"en":"cost overrun","pos":"noun","ipa":"/ˈkɔːst ˌoʊvərʌn/","ja":"予算超過","kana":"よさんちょうか","romaji":"yosanchouka","vi":"vượt chi phí (vượt ngân sách)","level":2,"def_vi":"Phần chi phí thực tế vượt quá ngân sách đã được phê duyệt của dự án hoặc hạng mục.","def_en":"The amount by which actual cost exceeds the approved budget of a project or item.","def_ja":"実際の費用が承認された予算を上回ること、またはその超過額。","usage_en":"Danh từ đếm được. Hay đi với: cause / avoid a cost overrun, a 15 % cost overrun, schedule overrun (vượt thời gian).","usage_ja":"Hay đi với: 予算超過が発生する, 予算超過を防ぐ, コスト超過. Khẩu ngữ: 予算オーバー.","context_vi":"Dùng trong báo cáo tài chính dự án, phân tích chênh lệch chi phí và khi xin bổ sung ngân sách.","ex_en":"Rework on the frame welds caused a cost overrun of 8 %.","ex_ja":"フレーム溶接の手直しにより8 %の予算超過が生じた。","ex_vi":"Việc làm lại mối hàn khung đã gây vượt chi phí 8 %.","syn_en":["budget overrun","over budget (cụm tính từ)"],"syn_ja":["コスト超過","予算オーバー (khẩu ngữ)"]},{"en":"handover","pos":"noun","ipa":"/ˈhændoʊvər/","ja":"引き渡し","kana":"ひきわたし","romaji":"hikiwatashi","vi":"bàn giao","level":2,"def_vi":"Việc chính thức chuyển giao thiết bị, công trình và hồ sơ hoàn công cho khách hàng sau khi nghiệm thu.","def_en":"The formal transfer of completed equipment, works and documents to the client after acceptance.","def_ja":"検収後に、完成した設備・工事と図書を正式に顧客へ渡すこと。","usage_en":"Danh từ đếm được; động từ là hand over (hai từ). Hay đi với: handover certificate, handover documents, handover to operations, mechanical completion and handover.","usage_ja":"Hay đi với: 引き渡しを行う, 引渡し書, 引き渡し前検査, 竣工引き渡し. Cách viết 引渡し cũng đúng.","context_vi":"Dùng ở giai đoạn cuối dự án, khi ký biên bản bàn giao, chuyển trách nhiệm vận hành và bắt đầu thời gian bảo hành.","ex_en":"The warranty period starts from the date of handover.","ex_ja":"保証期間は引き渡しの日から始まる。","ex_vi":"Thời gian bảo hành bắt đầu từ ngày bàn giao.","syn_en":["turnover (Mỹ)","hand-off"],"syn_ja":["引渡し","竣工 (liên quan, hoàn công)"]},{"en":"punch list","pos":"noun","ipa":"/ˈpʌntʃ lɪst/","ja":"パンチリスト","kana":"パンチリスト","romaji":"panchirisuto","vi":"danh sách tồn đọng (punch list)","level":2,"def_vi":"Danh sách các khiếm khuyết và việc còn dang dở phát hiện khi kiểm tra cuối, phải xử lý trước khi nghiệm thu, bàn giao.","def_en":"A list of defects and unfinished items found at final inspection, to be fixed before acceptance.","def_ja":"最終検査で見つかった不具合や未完了事項の一覧で、検収前に処理するもの。","usage_en":"Danh từ đếm được. Hay đi với: punch list item, close out the punch list, category A / B punch items, walk-down (đi kiểm tra hiện trường).","usage_ja":"Hay đi với: パンチリストを作成する, パンチ項目, パンチを消化する. Từ Nhật tương đương: 残工事リスト, 指摘事項リスト.","context_vi":"Dùng ở cuối giai đoạn lắp đặt, trước chạy thử và bàn giao trong dự án nhà máy, công trình.","ex_en":"Twelve items remain open on the punch list, including missing guards.","ex_ja":"パンチリストには、カバー未取付を含めて12件が未完了のまま残っている。","ex_vi":"Còn 12 hạng mục chưa đóng trong danh sách tồn đọng, bao gồm cả các tấm che an toàn còn thiếu.","syn_en":["snag list (Anh)","deficiency list"],"syn_ja":["残工事リスト","指摘事項リスト"]},{"en":"lessons learned","pos":"noun phrase","ipa":"/ˌlesənz ˈlɜːrnd/","ja":"教訓","kana":"きょうくん","romaji":"kyoukun","vi":"bài học kinh nghiệm","level":2,"def_vi":"Những kinh nghiệm tốt và chưa tốt rút ra trong dự án, được ghi lại để áp dụng cho các dự án sau.","def_en":"Knowledge gained from what went well or badly in a project, recorded for use in future projects.","def_ja":"プロジェクトでうまくいった点・いかなかった点から得た知識で、次に生かすために記録するもの。","usage_en":"Cụm danh từ số nhiều. Hay đi với: lessons learned report / session / register, capture lessons learned, share lessons learned across projects.","usage_ja":"Hay đi với: 教訓を生かす, 教訓集, 振り返り (buổi họp rút kinh nghiệm). Công ty Nhật còn dùng 反省会 cho buổi họp rút kinh nghiệm.","context_vi":"Dùng khi đóng dự án, sau sự cố, khi chuẩn bị chào thầu dự án tương tự.","ex_en":"The lessons learned from the last shutdown were reviewed before planning this one.","ex_ja":"今回の計画を立てる前に、前回の停止工事の教訓を確認した。","ex_vi":"Bài học kinh nghiệm từ đợt dừng máy lần trước đã được xem lại trước khi lập kế hoạch lần này.","syn_en":["post-project review (liên quan)","retrospective"],"syn_ja":["振り返り","反省会 (buổi họp, liên quan)"]},{"en":"earned value management","pos":"noun phrase","ipa":"/ˌɜːrnd ˈvæljuː ˌmænɪdʒmənt/","ja":"アーンドバリューマネジメント","kana":"アーンドバリューマネジメント","romaji":"aandobaryuumanejimento","vi":"quản lý giá trị thu được (EVM)","level":3,"def_vi":"Phương pháp so sánh giá trị kế hoạch, giá trị công việc đã làm và chi phí thực tế để đánh giá đồng thời tiến độ và chi phí.","def_en":"A method comparing planned value, earned value and actual cost to measure schedule and cost performance together.","def_ja":"計画価値・出来高・実コストを比べ、進捗とコストの状況を同時に評価する手法。","usage_en":"Danh từ không đếm được, viết tắt EVM. Hay đi với: planned value (PV), earned value (EV), actual cost (AC), CPI, SPI.","usage_ja":"Hay viết tắt EVM. Hay đi với: 出来高 (EV), 計画価値 (PV), 実コスト (AC), コスト効率指数 (CPI), スケジュール効率指数 (SPI).","context_vi":"Dùng trong dự án EPC, quốc phòng, xây dựng lớn để báo cáo hiệu suất và dự báo chi phí hoàn thành.","ex_en":"Earned value management showed a CPI of 0.92, meaning the project was over budget.","ex_ja":"アーンドバリューマネジメントの結果、CPIは0.92で、予算超過であることが分かった。","ex_vi":"Quản lý giá trị thu được cho thấy CPI bằng 0,92, nghĩa là dự án đang vượt ngân sách.","syn_en":["EVM","earned value analysis (EVA)"],"syn_ja":["EVM","出来高管理 (gần nghĩa)"]},{"en":"float","pos":"noun","ipa":"/floʊt/","ja":"フロート","kana":"フロート","romaji":"furooto","vi":"thời gian dự trữ","level":3,"def_vi":"Khoảng thời gian một công việc có thể bị trễ mà không làm chậm công việc kế tiếp hoặc ngày hoàn thành dự án.","def_en":"The time an activity can be delayed without delaying the next activity or the project finish date.","def_ja":"後続作業やプロジェクト完了日を遅らせずに、作業を遅らせることのできる余裕時間。","usage_en":"Danh từ không đếm được. Hay đi với: total float, free float, zero / negative float, consume the float; tiếng Mỹ cũng gọi slack.","usage_ja":"Hay đi với: トータルフロート, フリーフロート, フロートがない. Từ tiếng Nhật thuần: 余裕日数, 余裕時間.","context_vi":"Dùng khi phân tích tiến độ mạng, quyết định ưu tiên công việc và xử lý khiếu nại gia hạn.","ex_en":"Painting has 10 days of total float, so a short delay will not affect handover.","ex_ja":"塗装には10日のトータルフロートがあるので、少しの遅れは引き渡しに影響しない。","ex_vi":"Công tác sơn có 10 ngày dự trữ tổng nên chậm một chút sẽ không ảnh hưởng đến bàn giao.","syn_en":["slack (Mỹ)","total float (một loại)"],"syn_ja":["余裕日数","スラック"]},{"en":"project charter","pos":"noun","ipa":"/ˈprɑːdʒekt ˌtʃɑːrtər/","ja":"プロジェクト憲章","kana":"プロジェクトけんしょう","romaji":"purojekutokenshou","vi":"điều lệ dự án","level":3,"def_vi":"Văn bản chính thức cho phép khởi động dự án, nêu mục tiêu, phạm vi sơ bộ, người quản lý dự án và quyền hạn.","def_en":"The document that formally authorizes a project and states its objectives, outline scope, manager and authority.","def_ja":"プロジェクトを正式に認可し、目的、概略範囲、責任者、権限を示す文書。","usage_en":"Danh từ đếm được. Hay đi với: draft / sign / approve the project charter, project sponsor; thuật ngữ chuẩn PMBOK.","usage_ja":"Thuật ngữ PMBOK; công ty Nhật truyền thống hay dùng 企画書 hoặc プロジェクト計画書 cho mục đích gần tương tự.","context_vi":"Dùng ở giai đoạn khởi tạo dự án theo PMBOK, trong công ty đa quốc gia và dự án cải tiến lớn.","ex_en":"The project charter names the plant manager as sponsor of the automation project.","ex_ja":"プロジェクト憲章には、工場長が自動化プロジェクトのスポンサーとして記載されている。","ex_vi":"Điều lệ dự án ghi tên giám đốc nhà máy là nhà tài trợ của dự án tự động hóa.","syn_en":["project brief (gần nghĩa)","project initiation document (PID, Anh)"],"syn_ja":["企画書 (gần nghĩa)","プロジェクト計画書 (gần nghĩa)"]},{"en":"contingency reserve","pos":"noun phrase","ipa":"/kənˈtɪndʒənsi rɪˌzɜːrv/","ja":"予備費","kana":"よびひ","romaji":"yobihi","vi":"chi phí dự phòng","level":3,"def_vi":"Khoản tiền hoặc thời gian dự phòng thêm vào kế hoạch để xử lý các rủi ro đã nhận diện nếu chúng xảy ra.","def_en":"Money or time added to a plan to cover identified risks if they occur.","def_ja":"特定済みのリスクが起きた場合に備えて、計画に加えておく費用や時間。","usage_en":"Danh từ đếm được. Hay đi với: include a 10 % contingency reserve, draw on the contingency, management reserve (dự phòng cho rủi ro chưa biết).","usage_ja":"Hay đi với: 予備費を計上する, 予備費を使う. Trong dự án quốc tế cũng nói コンティンジェンシー; dự phòng thời gian gọi 予備日 hoặc バッファ.","context_vi":"Dùng khi lập dự toán, chào giá dự án EPC, quản lý rủi ro và phê duyệt chi tiêu phát sinh.","ex_en":"A contingency reserve of 7 % was included for unexpected soil conditions.","ex_ja":"想定外の地盤条件に備え、7 %の予備費を計上した。","ex_vi":"Đã đưa vào khoản chi phí dự phòng 7 % cho điều kiện nền đất ngoài dự kiến.","syn_en":["contingency","management reserve (liên quan)"],"syn_ja":["コンティンジェンシー","バッファ (dự phòng thời gian)"]},{"en":"fast-tracking","pos":"noun","ipa":"/ˈfæst ˌtrækɪŋ/","ja":"ファストトラッキング","kana":"ファストトラッキング","romaji":"fasutotorakkingu","vi":"thực hiện song song (rút ngắn tiến độ)","level":3,"def_vi":"Kỹ thuật rút ngắn tiến độ bằng cách cho các công việc vốn nối tiếp được thực hiện chồng lấn, chấp nhận rủi ro làm lại.","def_en":"Shortening a schedule by overlapping activities normally done in sequence, accepting more rework risk.","def_ja":"本来順に行う作業を並行させて工期を短縮する手法で、手戻りのリスクが増える。","usage_en":"Danh từ không đếm được; động từ fast-track (fast-track the project). Hay đi với: fast-tracking design and procurement, fast-track project.","usage_ja":"Hay đi với: ファストトラッキングで工期短縮, 設計と調達を並行させる. Khẩu ngữ Nhật hay nói 前倒し, 並行作業.","context_vi":"Dùng khi dự án bị chậm hoặc khách hàng cần đưa nhà máy vào vận hành sớm.","ex_en":"Fast-tracking allowed long-lead items to be ordered before the design was frozen.","ex_ja":"ファストトラッキングにより、設計凍結前に長納期品を発注できた。","ex_vi":"Việc thực hiện song song cho phép đặt hàng các thiết bị giao lâu trước khi chốt thiết kế.","syn_en":["concurrent engineering (gần nghĩa)","crashing (liên quan, cách rút ngắn khác)"],"syn_ja":["並行作業 (gần nghĩa)","前倒し (khẩu ngữ)"]},{"en":"crashing","pos":"noun","ipa":"/ˈkræʃɪŋ/","ja":"クラッシング","kana":"クラッシング","romaji":"kurasshingu","vi":"rút ngắn tiến độ bằng tăng nguồn lực (crashing)","level":3,"def_vi":"Kỹ thuật rút ngắn thời gian công việc trên đường găng bằng cách tăng thêm nhân lực, ca làm hoặc máy móc với chi phí cao hơn.","def_en":"Shortening critical-path activities by adding people, shifts or equipment at extra cost.","def_ja":"人員、シフト、機材を追加してクリティカルパス上の作業期間を短縮する手法で、費用が増える。","usage_en":"Danh từ không đếm được; động từ crash (crash the schedule). Hay đi với: schedule crashing, crash cost, crash duration; đừng nhầm với nghĩa đâm/va chạm.","usage_ja":"Từ chuyên ngành PM; ngoài công trường hay diễn đạt bằng 人員を増やして工期を短縮する, 突貫工事 (thi công gấp, khẩu ngữ).","context_vi":"Dùng khi phân tích phương án đuổi tiến độ, so sánh chi phí tăng ca với tiền phạt chậm trễ.","ex_en":"Crashing the erection work with a night shift cost less than the delay penalty.","ex_ja":"夜勤を追加する据付作業のクラッシングは、遅延ペナルティより安かった。","ex_vi":"Rút ngắn công việc lắp dựng bằng ca đêm tốn ít hơn tiền phạt chậm tiến độ.","syn_en":["schedule compression (nghĩa rộng hơn)"],"syn_ja":["工期短縮 (nghĩa rộng hơn)","突貫工事 (khẩu ngữ)"]},{"en":"scope creep","pos":"noun","ipa":"/ˈskoʊp kriːp/","ja":"スコープクリープ","kana":"スコープクリープ","romaji":"sukoopukuriipu","vi":"phình phạm vi (tăng phạm vi không kiểm soát)","level":3,"def_vi":"Hiện tượng phạm vi dự án dần tăng thêm do yêu cầu nhỏ lẻ mà không qua kiểm soát thay đổi, không điều chỉnh chi phí, tiến độ.","def_en":"Gradual, uncontrolled growth of project scope without matching changes to cost or schedule.","def_ja":"変更管理を経ずに、費用や日程を見直さないまま作業範囲が少しずつ広がること。","usage_en":"Danh từ không đếm được. Hay đi với: prevent / control scope creep, suffer from scope creep; thường mang nghĩa tiêu cực.","usage_ja":"Hay đi với: スコープクリープを防ぐ, 変更管理. Công ty Nhật hay diễn đạt là 仕様の追加が膨らむ hoặc なし崩しの範囲拡大.","context_vi":"Dùng khi khách hàng liên tục yêu cầu thêm tính năng, hạng mục nhỏ mà không có hợp đồng bổ sung.","ex_en":"Strict change control helped us avoid scope creep on the test rig project.","ex_ja":"厳格な変更管理により、試験装置プロジェクトでスコープクリープを防げた。","ex_vi":"Kiểm soát thay đổi chặt chẽ giúp chúng tôi tránh phình phạm vi trong dự án giàn thử nghiệm.","syn_en":["requirement creep","feature creep (phần mềm)"],"syn_ja":["範囲の膨張","仕様追加 (gần nghĩa)"]}]},{"id":99,"words":[{"en":"procurement","pos":"noun","ipa":"/proʊˈkjʊrmənt/","ja":"調達","kana":"ちょうたつ","romaji":"choutatsu","vi":"mua sắm (thu mua, cung ứng)","level":1,"def_vi":"Toàn bộ quá trình tìm nguồn, hỏi giá, chọn nhà cung cấp, đặt hàng và nhận vật tư, thiết bị, dịch vụ cho công ty hoặc dự án.","def_en":"The whole process of sourcing, selecting suppliers, ordering and receiving materials, equipment and services.","def_ja":"資材、機器、サービスの調達先を探し、選定し、発注して受け取るまでの一連の業務。","usage_en":"Danh từ không đếm được. Hay đi với: procurement department, procurement process, procurement of long-lead items; trong EPC, chữ P chính là procurement.","usage_ja":"Hay đi với: 調達部, 部品を調達する, 現地調達, 調達先. Trong công ty Nhật bộ phận thu mua còn gọi 購買部 (こうばいぶ).","context_vi":"Dùng trong phòng mua hàng, dự án EPC, kế hoạch sản xuất và khi chọn nguồn linh kiện trong nước hay nhập khẩu.","ex_en":"Procurement of the castings will start as soon as the drawings are approved.","ex_ja":"図面が承認され次第、鋳物の調達を開始する。","ex_vi":"Việc mua sắm các chi tiết đúc sẽ bắt đầu ngay khi bản vẽ được phê duyệt.","syn_en":["purchasing (nghĩa hẹp hơn)","sourcing (gần nghĩa)"],"syn_ja":["購買 (nghĩa hẹp hơn)","資材調達"]},{"en":"supplier","pos":"noun","ipa":"/səˈplaɪər/","ja":"仕入先","kana":"しいれさき","romaji":"shiiresaki","vi":"nhà cung cấp","level":1,"def_vi":"Công ty hoặc cá nhân bán và giao vật tư, linh kiện, thiết bị hay dịch vụ cho công ty mình.","def_en":"A company or person that sells and delivers materials, parts, equipment or services to a buyer.","def_ja":"材料、部品、機器、サービスを販売し納入する会社や人。","usage_en":"Danh từ đếm được. Hay đi với: approved supplier, local / overseas supplier, select / qualify / change a supplier, supplier of bearings.","usage_ja":"Hay đi với: 仕入先を選定する, 仕入先評価, 仕入先を変更する. Trong nhà máy rất hay dùng サプライヤー; cách viết 仕入れ先 cũng đúng.","context_vi":"Dùng hằng ngày trong mua hàng, kiểm tra chất lượng đầu vào và khi xử lý khiếu nại hàng lỗi.","ex_en":"We asked three suppliers to quote for the stainless steel sheet.","ex_ja":"ステンレス鋼板について、3社の仕入先に見積を依頼した。","ex_vi":"Chúng tôi đã đề nghị ba nhà cung cấp báo giá tấm thép không gỉ.","syn_en":["vendor","seller (nghĩa rộng hơn)"],"syn_ja":["サプライヤー","取引先 (nghĩa rộng hơn)"]},{"en":"quotation","pos":"noun","ipa":"/kwoʊˈteɪʃən/","ja":"見積書","kana":"みつもりしょ","romaji":"mitsumorisho","vi":"bảng báo giá","level":1,"def_vi":"Văn bản nhà cung cấp gửi cho người mua, nêu giá, số lượng, thời hạn giao hàng, điều kiện và thời hạn hiệu lực của giá.","def_en":"A supplier's document stating price, quantity, delivery time, conditions and validity for goods or services.","def_ja":"仕入先が価格、数量、納期、条件、有効期限を示して買い手に出す書類。","usage_en":"Danh từ đếm được; khẩu ngữ là quote. Hay đi với: request / submit / receive a quotation, quotation valid for 30 days, compare quotations.","usage_ja":"Hay đi với: 見積書を出す, 見積書を提出する, 見積有効期限. Khẩu ngữ chỉ nói 見積 hoặc 見積もり; 相見積 là lấy báo giá nhiều nơi để so sánh.","context_vi":"Dùng ở giai đoạn hỏi giá trước khi đặt hàng, so sánh giá giữa các nhà cung cấp và trình duyệt mua.","ex_en":"The quotation includes packing and delivery to our factory in Bac Ninh.","ex_ja":"この見積書には、梱包費とバクニン工場までの配送費が含まれている。","ex_vi":"Bảng báo giá đã bao gồm đóng gói và giao hàng đến nhà máy của chúng tôi ở Bắc Ninh.","syn_en":["quote (khẩu ngữ)","price offer"],"syn_ja":["見積 (khẩu ngữ)","お見積書 (lịch sự)"]},{"en":"purchase order","pos":"noun","ipa":"/ˈpɜːrtʃəs ˌɔːrdər/","ja":"注文書","kana":"ちゅうもんしょ","romaji":"chuumonsho","vi":"đơn đặt hàng (PO)","level":1,"def_vi":"Văn bản chính thức người mua gửi nhà cung cấp, xác nhận mặt hàng, số lượng, giá, ngày giao và điều kiện mua.","def_en":"A buyer's official document to a supplier confirming items, quantities, prices, delivery dates and terms.","def_ja":"買い手が仕入先に出す正式な書類で、品目、数量、価格、納期、条件を示す。","usage_en":"Danh từ đếm được, viết tắt PO. Hay đi với: issue / place / cancel a purchase order, PO number, quote the PO number on the invoice.","usage_ja":"Hay đi với: 注文書を発行する, 注文番号, 注文請書 (giấy xác nhận nhận đơn của nhà cung cấp). Trong công ty cũng dùng 発注書; khẩu ngữ nói PO.","context_vi":"Dùng khi chốt mua hàng sau báo giá; số PO được ghi trên phiếu giao hàng và hóa đơn để đối chiếu.","ex_en":"Please quote our purchase order number on all delivery notes.","ex_ja":"すべての納品書に当社の注文書番号を記載してください。","ex_vi":"Vui lòng ghi số đơn đặt hàng của chúng tôi trên tất cả phiếu giao hàng.","syn_en":["PO","order (khẩu ngữ)"],"syn_ja":["発注書","PO"]},{"en":"contract","pos":"noun","ipa":"/ˈkɑːntrækt/","ja":"契約","kana":"けいやく","romaji":"keiyaku","vi":"hợp đồng","level":1,"def_vi":"Thỏa thuận có giá trị pháp lý giữa các bên, quy định công việc, giá, thời hạn, quyền và nghĩa vụ của mỗi bên.","def_en":"A legally binding agreement between parties setting out work, price, time, rights and obligations.","def_ja":"当事者間で作業、価格、期間、権利と義務を定めた法的拘束力のある取り決め。","usage_en":"Danh từ đếm được; động từ contract (với trọng âm khác: /kənˈtrækt/). Hay đi với: sign / award / terminate a contract, under the contract, contract price, breach of contract.","usage_ja":"Hay đi với: 契約を結ぶ, 契約を締結する, 契約書 (văn bản hợp đồng), 契約違反, 契約金額.","context_vi":"Dùng khi mua thiết bị lớn, thuê nhà thầu lắp đặt, ký thỏa thuận dịch vụ bảo trì.","ex_en":"The contract requires delivery of the press within 20 weeks.","ex_ja":"契約では、プレス機を20週間以内に納入することになっている。","ex_vi":"Hợp đồng yêu cầu giao máy dập trong vòng 20 tuần.","syn_en":["agreement"],"syn_ja":["契約書 (văn bản)","取り決め (khẩu ngữ, nghĩa rộng)"]},{"en":"invoice","pos":"noun","ipa":"/ˈɪnvɔɪs/","ja":"請求書","kana":"せいきゅうしょ","romaji":"seikyuusho","vi":"hóa đơn","level":1,"def_vi":"Chứng từ người bán gửi người mua để yêu cầu thanh toán, ghi hàng hóa, số lượng, đơn giá, thuế và tổng tiền.","def_en":"A seller's document requesting payment, listing goods, quantities, unit prices, tax and total amount.","def_ja":"売り手が買い手に代金の支払いを求める書類で、品目、数量、単価、税、合計を記す。","usage_en":"Danh từ đếm được; cũng là động từ (invoice the customer). Hay đi với: issue / send / pay an invoice, commercial invoice (xuất nhập khẩu), invoice number.","usage_ja":"Hay đi với: 請求書を発行する, 請求書を送る, 請求金額. Trong xuất nhập khẩu, hóa đơn thương mại gọi インボイス hoặc 商業送り状.","context_vi":"Dùng ở bộ phận kế toán, mua hàng khi thanh toán và trong hồ sơ xuất nhập khẩu.","ex_en":"The invoice does not match the purchase order price, so payment is on hold.","ex_ja":"請求書の金額が注文書と合わないため、支払いを保留している。","ex_vi":"Hóa đơn không khớp với giá trên đơn đặt hàng nên việc thanh toán đang bị tạm giữ.","syn_en":["bill","commercial invoice (xuất nhập khẩu)"],"syn_ja":["インボイス (xuất nhập khẩu)","請求明細書"]},{"en":"delivery date","pos":"noun phrase","ipa":"/dɪˈlɪvəri ˌdeɪt/","ja":"納期","kana":"のうき","romaji":"nouki","vi":"ngày giao hàng (thời hạn giao hàng)","level":1,"def_vi":"Ngày hoặc thời hạn mà nhà cung cấp phải giao hàng hóa, thiết bị đến địa điểm đã thỏa thuận.","def_en":"The date or deadline by which a supplier must deliver goods to the agreed place.","def_ja":"仕入先が品物を約束した場所へ納めなければならない日や期限。","usage_en":"Danh từ đếm được. Hay đi với: confirm / meet / miss the delivery date, agreed delivery date, delivery date of 15 May.","usage_ja":"Từ cực kỳ phổ biến trong công ty Nhật: 納期を守る, 納期回答, 納期遅れ, 短納期, 納期を前倒しする. 納期 có thể chỉ cả ngày giao lẫn khoảng thời gian giao.","context_vi":"Dùng khi đặt hàng, trao đổi với nhà cung cấp, lập kế hoạch sản xuất và khi xử lý giao hàng trễ.","ex_en":"The supplier confirmed a delivery date of 20 June for the gear blanks.","ex_ja":"仕入先から、歯車素材の納期は6月20日との回答があった。","ex_vi":"Nhà cung cấp đã xác nhận ngày giao hàng phôi bánh răng là 20 tháng 6.","syn_en":["due date","delivery time (khoảng thời gian)"],"syn_ja":["納入日","納入期限"]},{"en":"warranty","pos":"noun","ipa":"/ˈwɔːrənti/","ja":"保証","kana":"ほしょう","romaji":"hoshou","vi":"bảo hành","level":1,"def_vi":"Cam kết của người bán sửa chữa hoặc thay thế miễn phí sản phẩm bị lỗi trong một thời gian nhất định sau khi giao.","def_en":"A seller's commitment to repair or replace defective products free of charge for a set period.","def_ja":"一定期間内に不具合が出た製品を、売り手が無償で修理・交換する約束。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: under warranty, warranty period, warranty claim, 12-month warranty, void the warranty.","usage_ja":"Hay đi với: 保証期間, 保証書, 保証対象, 無償保証. Trong hợp đồng thường viết 瑕疵担保 hoặc 契約不適合責任 cho trách nhiệm pháp lý về khuyết tật.","context_vi":"Dùng khi đàm phán hợp đồng, khi thiết bị hỏng trong thời gian bảo hành và khi gửi yêu cầu bảo hành.","ex_en":"The gearbox failed after eight months, so it is still under warranty.","ex_ja":"減速機は8か月で故障したので、まだ保証期間内である。","ex_vi":"Hộp giảm tốc hỏng sau tám tháng nên vẫn còn trong thời gian bảo hành.","syn_en":["guarantee","defects liability (hợp đồng xây lắp)"],"syn_ja":["保証期間 (thời hạn)","契約不適合責任 (pháp lý)"]},{"en":"shipment","pos":"noun","ipa":"/ˈʃɪpmənt/","ja":"出荷","kana":"しゅっか","romaji":"shukka","vi":"xuất hàng (lô hàng gửi đi)","level":1,"def_vi":"Việc gửi hàng đi từ kho của người bán, hoặc chính lô hàng được gửi đi bằng xe, tàu, máy bay.","def_en":"The sending of goods from the seller's site, or the batch of goods sent by truck, ship or air.","def_ja":"売り手の拠点から品物を送り出すこと、またはその送り出す荷。","usage_en":"Danh từ đếm được và không đếm được. Hay đi với: ship the goods, partial shipment, shipment date, track a shipment, ready for shipment.","usage_ja":"Hay đi với: 出荷する, 出荷日, 出荷検査, 分納 (giao nhiều đợt). Với tàu biển dùng 船積み (ふなづみ).","context_vi":"Dùng trong kho, logistics, xuất nhập khẩu và khi trao đổi về tình trạng đơn hàng với nhà cung cấp.","ex_en":"The shipment left the Osaka plant yesterday and will arrive in Hai Phong next week.","ex_ja":"大阪工場からの出荷は昨日で、来週ハイフォンに到着する予定だ。","ex_vi":"Lô hàng đã xuất từ nhà máy Osaka hôm qua và sẽ đến Hải Phòng tuần sau.","syn_en":["consignment (Anh)","dispatch"],"syn_ja":["発送","船積み (đường biển)"]},{"en":"request for quotation","pos":"noun phrase","ipa":"/rɪˌkwest fər kwoʊˈteɪʃən/","ja":"見積依頼","kana":"みつもりいらい","romaji":"mitsumoriirai","vi":"yêu cầu báo giá (RFQ)","level":2,"def_vi":"Văn bản người mua gửi nhiều nhà cung cấp kèm bản vẽ, thông số, số lượng để mời họ gửi báo giá.","def_en":"A buyer's document, with drawings, specifications and quantities, inviting suppliers to submit prices.","def_ja":"図面、仕様、数量を添えて、仕入先に価格の提示を求める書類。","usage_en":"Danh từ đếm được, viết tắt RFQ. Hay đi với: issue / send an RFQ, RFQ package, respond to an RFQ; khác RFP (request for proposal) cần cả giải pháp kỹ thuật.","usage_ja":"Hay đi với: 見積依頼を出す, 見積依頼書, 見積依頼先. Khẩu ngữ: 見積を取る (lấy báo giá).","context_vi":"Dùng ở bước đầu của mua hàng, khi gửi bản vẽ chi tiết gia công ngoài hoặc thông số thiết bị cho nhiều nhà cung cấp.","ex_en":"The request for quotation was sent to five machining shops with the 3D models attached.","ex_ja":"3Dモデルを添付して、加工メーカー5社に見積依頼を出した。","ex_vi":"Yêu cầu báo giá đã được gửi đến năm xưởng gia công kèm theo mô hình 3D.","syn_en":["RFQ","request for proposal (RFP, gần nghĩa)"],"syn_ja":["見積依頼書","引合い (gần nghĩa)"]},{"en":"tender","pos":"noun","ipa":"/ˈtendər/","ja":"入札","kana":"にゅうさつ","romaji":"nyuusatsu","vi":"đấu thầu (hồ sơ dự thầu)","level":2,"def_vi":"Hình thức mua sắm trong đó nhiều nhà thầu nộp hồ sơ và giá theo yêu cầu, bên mua chọn đơn vị phù hợp nhất.","def_en":"A procurement method where several bidders submit offers to set requirements and the buyer selects the best.","def_ja":"複数の業者が条件に沿って価格などを提出し、発注者が最適な者を選ぶ方式。","usage_en":"Danh từ đếm được; cũng là động từ (tender for a project). Hay đi với: invite tenders, submit a tender, tender documents, win / lose a tender; tiếng Mỹ hay dùng bid.","usage_ja":"Hay đi với: 入札に参加する, 入札書類, 落札する (trúng thầu), 競争入札, 一般競争入札.","context_vi":"Dùng trong dự án nhà nước, dự án EPC, mua thiết bị giá trị lớn có quy định đấu thầu.","ex_en":"Six companies submitted a tender for the boiler retrofit project.","ex_ja":"ボイラ改造工事の入札には6社が参加した。","ex_vi":"Sáu công ty đã nộp hồ sơ dự thầu cho dự án cải tạo lò hơi.","syn_en":["bid (Mỹ)","bidding"],"syn_ja":["競争入札","ビッド (khẩu ngữ)"]},{"en":"payment terms","pos":"noun phrase","ipa":"/ˈpeɪmənt tɜːrmz/","ja":"支払条件","kana":"しはらいじょうけん","romaji":"shiharaijouken","vi":"điều kiện thanh toán","level":2,"def_vi":"Các quy định về thời hạn, tỷ lệ và phương thức thanh toán, ví dụ tạm ứng 30 %, phần còn lại 60 ngày sau giao hàng.","def_en":"The agreed timing, proportions and method of payment, e.g. 30 % advance and the balance 60 days after delivery.","def_ja":"支払時期、割合、方法の取り決めで、例えば前払30 %、残金は納入後60日など。","usage_en":"Luôn ở số nhiều. Hay đi với: agree on payment terms, net 30 / net 60, advance payment, payment against documents.","usage_ja":"Hay đi với: 支払条件を交渉する, 前払金, 月末締め翌月末払い (chốt cuối tháng, trả cuối tháng sau). Cách viết 支払い条件 cũng đúng.","context_vi":"Dùng khi đàm phán hợp đồng, so sánh báo giá và quản lý dòng tiền của dự án.","ex_en":"The payment terms are 30 % with the order and 70 % after acceptance.","ex_ja":"支払条件は、発注時30 %、検収後70 %である。","ex_vi":"Điều kiện thanh toán là 30 % khi đặt hàng và 70 % sau nghiệm thu.","syn_en":["terms of payment"],"syn_ja":["支払い条件","決済条件"]},{"en":"Incoterms","pos":"noun","ipa":"/ˈɪŋkoʊtɜːrmz/","ja":"インコタームズ","kana":"インコタームズ","romaji":"inkotaamuzu","vi":"điều kiện thương mại quốc tế (Incoterms)","level":2,"def_vi":"Bộ quy tắc của Phòng Thương mại Quốc tế xác định trách nhiệm, chi phí và điểm chuyển rủi ro giữa người bán và người mua khi giao hàng.","def_en":"ICC rules defining seller and buyer duties, costs and the point where risk passes in delivery.","def_ja":"国際商業会議所の規則で、売り手と買い手の費用負担と危険の移転点を定める。","usage_en":"Danh từ riêng, viết hoa, thường kèm năm: Incoterms 2020. Hay đi với: EXW, FOB, CIF, DAP, DDP; ví dụ price FOB Yokohama (Incoterms 2020).","usage_ja":"Hay đi với: インコタームズ2020, 貿易条件, FOB価格, CIF条件. Trong báo giá xuất khẩu luôn ghi điều kiện như FOB 横浜.","context_vi":"Dùng trong báo giá và hợp đồng nhập khẩu thiết bị, máy móc, linh kiện từ Nhật, Trung Quốc, châu Âu.","ex_en":"The price is quoted DAP Hai Phong according to Incoterms 2020.","ex_ja":"価格はインコタームズ2020に基づくDAPハイフォン条件で提示されている。","ex_vi":"Giá được báo theo điều kiện DAP Hải Phòng của Incoterms 2020.","syn_en":["trade terms","delivery terms (gần nghĩa)"],"syn_ja":["貿易条件","取引条件 (nghĩa rộng hơn)"]},{"en":"delivery note","pos":"noun","ipa":"/dɪˈlɪvəri noʊt/","ja":"納品書","kana":"のうひんしょ","romaji":"nouhinsho","vi":"phiếu giao hàng","level":2,"def_vi":"Chứng từ đi kèm hàng khi giao, ghi số đơn hàng, mặt hàng và số lượng để bên nhận kiểm đếm và ký xác nhận.","def_en":"A document sent with goods listing the order number, items and quantities for the receiver to check and sign.","def_ja":"品物に添えて渡す書類で、注文番号、品目、数量を記し、受取側が確認する。","usage_en":"Danh từ đếm được. Hay đi với: sign the delivery note, check goods against the delivery note; tiếng Mỹ gọi packing slip hoặc delivery receipt.","usage_ja":"Hay đi với: 納品書を添付する, 納品書と照合する, 受領書 (biên nhận). Khi giao hàng ở Nhật thường kèm bộ 納品書・受領書.","context_vi":"Dùng tại kho nhận hàng, khi kiểm đếm hàng đến và đối chiếu với đơn đặt hàng, hóa đơn.","ex_en":"The quantity on the delivery note was 500, but only 480 brackets arrived.","ex_ja":"納品書の数量は500個だったが、ブラケットは480個しか届かなかった。","ex_vi":"Số lượng trên phiếu giao hàng là 500 nhưng chỉ có 480 giá đỡ được giao đến.","syn_en":["packing slip (Mỹ)","delivery receipt"],"syn_ja":["納品伝票","受領書 (liên quan)"]},{"en":"packing list","pos":"noun","ipa":"/ˈpækɪŋ lɪst/","ja":"パッキングリスト","kana":"パッキングリスト","romaji":"pakkingurisuto","vi":"phiếu đóng gói (packing list)","level":2,"def_vi":"Chứng từ liệt kê nội dung từng kiện hàng, kích thước, khối lượng tịnh và cả bì, dùng cho vận chuyển, hải quan và kiểm nhận.","def_en":"A document listing the contents, dimensions and net and gross weights of each package for shipping, customs and receipt.","def_ja":"各梱包の内容、寸法、正味・総重量を記した書類で、輸送、通関、受入に使う。","usage_en":"Danh từ đếm được, viết tắt P/L. Hay đi với: prepare / attach the packing list, case number, gross / net weight; luôn đi cùng commercial invoice khi xuất nhập khẩu.","usage_ja":"Hay viết tắt P/L. Văn bản tiếng Nhật thuần gọi 梱包明細書. Hay đi với: パッキングリストを作成する, ケース番号, 総重量・正味重量.","context_vi":"Dùng trong xuất nhập khẩu máy móc, khi làm thủ tục hải quan và khi mở kiện kiểm tra thiết bị tại công trường.","ex_en":"According to the packing list, the spare parts are in case No. 7.","ex_ja":"パッキングリストによると、予備品は7番ケースに入っている。","ex_vi":"Theo phiếu đóng gói, phụ tùng dự phòng nằm trong kiện số 7.","syn_en":["P/L","packing specification"],"syn_ja":["梱包明細書","P/L"]},{"en":"bill of lading","pos":"noun phrase","ipa":"/ˌbɪl əv ˈleɪdɪŋ/","ja":"船荷証券","kana":"ふなにしょうけん","romaji":"funanishouken","vi":"vận đơn đường biển (B/L)","level":2,"def_vi":"Chứng từ do hãng tàu cấp, xác nhận đã nhận hàng lên tàu, là hợp đồng vận chuyển và chứng từ sở hữu để nhận hàng.","def_en":"A carrier's document confirming goods are loaded, serving as transport contract and title document.","def_ja":"船会社が貨物の受取りを証明して発行する書類で、運送契約と貨物の引換証になる。","usage_en":"Danh từ đếm được, viết tắt B/L, số nhiều bills of lading. Hay đi với: original bill of lading, B/L date, surrender the B/L; vận tải hàng không dùng air waybill.","usage_ja":"Khẩu ngữ gọi B/L (ビーエル). Hay đi với: B/L原本, 船積日, サレンダーB/L. Hàng không dùng エアウェイビル.","context_vi":"Dùng trong nhập khẩu thiết bị bằng đường biển, thanh toán bằng L/C và khi nhận hàng tại cảng.","ex_en":"The bank released the bill of lading after the payment was made.","ex_ja":"支払い完了後、銀行は船荷証券を引き渡した。","ex_vi":"Ngân hàng đã giao vận đơn đường biển sau khi thanh toán được thực hiện.","syn_en":["B/L","air waybill (hàng không, liên quan)"],"syn_ja":["B/L","エアウェイビル (hàng không, liên quan)"]},{"en":"customs clearance","pos":"noun phrase","ipa":"/ˈkʌstəmz ˌklɪrəns/","ja":"通関","kana":"つうかん","romaji":"tsuukan","vi":"thông quan","level":2,"def_vi":"Thủ tục khai báo hải quan, nộp thuế và được cơ quan hải quan cho phép hàng xuất khẩu hoặc nhập khẩu đi qua biên giới.","def_en":"The procedure of declaring goods, paying duties and obtaining customs permission to import or export them.","def_ja":"貨物を申告し関税などを納め、税関の許可を得て輸出入すること。","usage_en":"Danh từ không đếm được. Hay đi với: customs clearance agent, delay in customs clearance, clear customs, import / export clearance, HS code.","usage_ja":"Hay đi với: 通関手続き, 通関業者, 輸入通関, 通関が遅れる. Đại lý hải quan gọi 通関業者 hoặc フォワーダー (nghĩa rộng hơn).","context_vi":"Dùng khi nhập khẩu máy móc, linh kiện, nguyên liệu và khi lên kế hoạch thời gian hàng về nhà máy.","ex_en":"Customs clearance took four days because the HS code on the invoice was wrong.","ex_ja":"請求書のHSコードが誤っていたため、通関に4日かかった。","ex_vi":"Việc thông quan mất bốn ngày vì mã HS trên hóa đơn bị sai.","syn_en":["customs procedure","clearance (khẩu ngữ)"],"syn_ja":["通関手続き","税関手続き"]},{"en":"purchase specification","pos":"noun phrase","ipa":"/ˈpɜːrtʃəs ˌspesəfɪˈkeɪʃən/","ja":"購入仕様書","kana":"こうにゅうしようしょ","romaji":"kounyuushiyousho","vi":"đặc tính kỹ thuật mua hàng (spec mua hàng)","level":2,"def_vi":"Tài liệu kỹ thuật kèm theo yêu cầu mua, nêu yêu cầu về thông số, vật liệu, tiêu chuẩn, kiểm tra và tài liệu nhà cung cấp phải nộp.","def_en":"A technical document attached to a purchase stating required data, materials, standards, tests and vendor documents.","def_ja":"購入品に求める性能、材料、規格、検査、提出図書などを定めた技術文書。","usage_en":"Danh từ đếm được. Hay đi với: issue the purchase specification, comply with the purchase specification, deviation from the specification, technical bid evaluation.","usage_ja":"Hay đi với: 購入仕様書に従う, 購入仕様書を作成する, 仕様逸脱. Khẩu ngữ gọi 購入仕様 hoặc 仕様書.","context_vi":"Dùng khi mua bơm, van, động cơ, thiết bị theo yêu cầu riêng trong dự án nhà máy hoặc chế tạo máy.","ex_en":"The purchase specification requires all wetted parts to be SUS316.","ex_ja":"購入仕様書では、接液部はすべてSUS316と規定している。","ex_vi":"Đặc tính kỹ thuật mua hàng yêu cầu mọi chi tiết tiếp xúc chất lỏng phải là SUS316.","syn_en":["technical specification (nghĩa rộng hơn)","material requisition (MR, liên quan)"],"syn_ja":["購入仕様","仕様書 (nghĩa rộng hơn)"]},{"en":"receiving inspection","pos":"noun phrase","ipa":"/rɪˈsiːvɪŋ ɪnˌspekʃən/","ja":"受入検査","kana":"うけいれけんさ","romaji":"ukeirekensa","vi":"kiểm tra đầu vào (kiểm tra nhận hàng)","level":2,"def_vi":"Việc kiểm tra số lượng, ngoại quan, kích thước và chứng chỉ của hàng mua khi nhận để quyết định chấp nhận hay trả lại.","def_en":"Checking quantity, appearance, dimensions and certificates of purchased goods on arrival to accept or reject them.","def_ja":"購入品の到着時に数量、外観、寸法、証明書を確認し、合否を判定する検査。","usage_en":"Danh từ không đếm được. Hay đi với: pass / fail receiving inspection, receiving inspection report, incoming inspection; viết tắt IQC (incoming quality control).","usage_ja":"Hay đi với: 受入検査を行う, 受入検査で不合格, 検収 (nghiệm thu để thanh toán, liên quan). Cách viết 受け入れ検査 cũng gặp.","context_vi":"Dùng ở kho và phòng QC khi nhận linh kiện, vật liệu từ nhà cung cấp, trước khi đưa vào sản xuất.","ex_en":"The bolts were rejected at receiving inspection because the mill certificate was missing.","ex_ja":"ミルシートが添付されていなかったため、ボルトは受入検査で不合格となった。","ex_vi":"Lô bu lông bị loại ở khâu kiểm tra đầu vào vì thiếu chứng chỉ vật liệu.","syn_en":["incoming inspection","IQC"],"syn_ja":["受け入れ検査","検収 (liên quan)"]},{"en":"outsourcing","pos":"noun","ipa":"/ˈaʊtsɔːrsɪŋ/","ja":"外注","kana":"がいちゅう","romaji":"gaichuu","vi":"thuê ngoài (gia công ngoài)","level":2,"def_vi":"Việc giao cho công ty bên ngoài thực hiện một phần công việc như gia công, xử lý nhiệt, thiết kế thay vì tự làm.","def_en":"Having an outside company perform part of the work, such as machining, heat treatment or design.","def_ja":"加工、熱処理、設計などの作業の一部を社外の会社に任せること。","usage_en":"Danh từ không đếm được; động từ outsource (outsource the plating). Hay đi với: outsourcing partner, outsourcing cost, in-house vs outsourcing.","usage_ja":"Hay đi với: 外注する, 外注先, 外注費, 外注加工, 内製 (tự làm, đối nghĩa). Từ ngữ hiện đại: アウトソーシング.","context_vi":"Dùng khi quyết định tự làm hay thuê ngoài, quản lý xưởng gia công vệ tinh, tính giá thành.","ex_en":"Outsourcing the heat treatment reduced our lead time by one week.","ex_ja":"熱処理を外注にしたことで、リードタイムが1週間短くなった。","ex_vi":"Việc thuê ngoài nhiệt luyện đã rút ngắn thời gian chờ của chúng tôi một tuần.","syn_en":["subcontracting (gần nghĩa)","contracting out"],"syn_ja":["アウトソーシング","外部委託"]},{"en":"subcontractor","pos":"noun","ipa":"/ˌsʌbkənˈtræktər/","ja":"協力会社","kana":"きょうりょくがいしゃ","romaji":"kyouryokugaisha","vi":"nhà thầu phụ","level":2,"def_vi":"Công ty được nhà thầu chính thuê lại để thực hiện một phần công việc của hợp đồng, như lắp đặt, sơn, cách nhiệt.","def_en":"A company hired by the main contractor to carry out part of the contracted work, such as erection or painting.","def_ja":"元請から仕事の一部（据付、塗装など）を請け負う会社。","usage_en":"Danh từ đếm được. Hay đi với: hire / appoint a subcontractor, piping subcontractor, main contractor and subcontractors, subcontract agreement.","usage_ja":"Công ty Nhật thường dùng 協力会社 cho lịch sự; 下請け (したうけ) mang sắc thái thấp hơn. Nhà thầu chính gọi 元請 (もとうけ).","context_vi":"Dùng trong dự án xây lắp, EPC, đóng tàu và các xưởng có mạng lưới gia công vệ tinh.","ex_en":"The insulation work will be done by a local subcontractor.","ex_ja":"保温工事は現地の協力会社が行う。","ex_vi":"Công việc bảo ôn sẽ do một nhà thầu phụ địa phương thực hiện.","syn_en":["sub (khẩu ngữ)","subcontracted supplier"],"syn_ja":["下請け","下請業者"]},{"en":"supply chain","pos":"noun","ipa":"/səˈplaɪ tʃeɪn/","ja":"サプライチェーン","kana":"サプライチェーン","romaji":"sapuraicheen","vi":"chuỗi cung ứng","level":2,"def_vi":"Toàn bộ mạng lưới các công ty và hoạt động từ nguyên liệu, sản xuất linh kiện, lắp ráp đến phân phối sản phẩm tới khách hàng.","def_en":"The network of companies and activities from raw materials through parts and assembly to delivery to customers.","def_ja":"原材料から部品製造、組立、顧客への流通までをつなぐ企業と活動の連なり。","usage_en":"Danh từ đếm được. Hay đi với: supply chain management (SCM), supply chain disruption, global supply chain, secure the supply chain.","usage_ja":"Hay đi với: サプライチェーン管理, サプライチェーンの寸断, サプライチェーン全体. Văn bản cũ đôi khi dùng 供給網.","context_vi":"Dùng khi phân tích rủi ro thiếu linh kiện, chọn nhà cung cấp thay thế, lập chiến lược mua hàng toàn cầu.","ex_en":"The earthquake disrupted the supply chain for automotive chips.","ex_ja":"地震により車載半導体のサプライチェーンが寸断された。","ex_vi":"Trận động đất đã làm đứt gãy chuỗi cung ứng chip ô tô.","syn_en":["SCM (supply chain management, liên quan)","value chain (gần nghĩa)"],"syn_ja":["供給網","SCM (liên quan)"]},{"en":"expediting","pos":"noun","ipa":"/ˈekspədaɪtɪŋ/","ja":"督促","kana":"とくそく","romaji":"tokusoku","vi":"đôn đốc tiến độ nhà cung cấp (expediting)","level":2,"def_vi":"Công việc theo dõi, liên hệ và thúc giục nhà cung cấp để hàng được thiết kế, chế tạo và giao đúng hạn.","def_en":"Following up and chasing suppliers so that ordered goods are designed, made and delivered on time.","def_ja":"発注品が期限どおりに設計・製作・納入されるよう、仕入先を追跡し催促すること。","usage_en":"Danh từ không đếm được; động từ expedite (expedite the order). Hay đi với: expediting report, expediting visit, expediter (người đôn đốc).","usage_ja":"Hay đi với: 納期督促, 督促する, 督促状. Trong dự án EPC Nhật cũng dùng katakana エクスペダイティング. Lưu ý 督促 còn dùng cho đòi tiền nợ.","context_vi":"Dùng trong dự án EPC và phòng mua hàng khi theo dõi các thiết bị giao lâu, đơn hàng có nguy cơ trễ.","ex_en":"Weekly expediting calls helped bring the valve delivery back on schedule.","ex_ja":"毎週の督促によって、バルブの納入が予定どおりに戻った。","ex_vi":"Các cuộc gọi đôn đốc hằng tuần đã giúp việc giao van trở lại đúng tiến độ.","syn_en":["chasing (khẩu ngữ)","follow-up"],"syn_ja":["納期督促","エクスペダイティング"]},{"en":"framework agreement","pos":"noun phrase","ipa":"/ˈfreɪmwɜːrk əˌɡriːmənt/","ja":"取引基本契約","kana":"とりひききほんけいやく","romaji":"torihikikihonkeiyaku","vi":"hợp đồng khung (hợp đồng nguyên tắc)","level":3,"def_vi":"Hợp đồng dài hạn quy định điều kiện chung giữa hai bên; từng lần mua sau đó chỉ cần đơn hàng riêng theo các điều kiện này.","def_en":"A long-term contract setting general terms between parties, under which individual orders are later placed.","def_ja":"取引の共通条件を定めた長期の契約で、個々の取引は個別の注文で行う。","usage_en":"Danh từ đếm được. Hay đi với: sign a framework agreement, call-off order, master agreement, blanket order (gần nghĩa).","usage_ja":"Khẩu ngữ gọi 基本契約. Hay đi với: 取引基本契約書を締結する, 個別契約 (hợp đồng/đơn hàng riêng lẻ).","context_vi":"Dùng khi thiết lập quan hệ lâu dài với nhà cung cấp linh kiện, đặc biệt trong công ty Nhật tại Việt Nam.","ex_en":"Under the framework agreement, each monthly order only needs a short purchase order.","ex_ja":"取引基本契約があるので、毎月の取引は簡単な注文書だけで済む。","ex_vi":"Theo hợp đồng khung, mỗi đơn hàng hằng tháng chỉ cần một đơn đặt hàng ngắn gọn.","syn_en":["master agreement","blanket order (gần nghĩa)"],"syn_ja":["基本契約 (khẩu ngữ)","個別契約 (liên quan)"]},{"en":"liquidated damages","pos":"noun phrase","ipa":"/ˌlɪkwɪdeɪtɪd ˈdæmɪdʒɪz/","ja":"遅延損害金","kana":"ちえんそんがいきん","romaji":"chiensongaikin","vi":"tiền phạt chậm trễ (bồi thường thiệt hại ấn định trước)","level":3,"def_vi":"Khoản bồi thường được định sẵn trong hợp đồng, thường tính theo % giá trị mỗi tuần chậm, bên bán phải trả khi giao trễ.","def_en":"A sum fixed in the contract, often a percentage per week, that the seller pays for late delivery.","def_ja":"納期遅れの際に売り手が支払う、契約であらかじめ定めた金額（週あたり何%など）。","usage_en":"Luôn ở số nhiều, viết tắt LDs. Hay đi với: delay liquidated damages, cap on liquidated damages, apply / waive LDs; khác penalty về mặt pháp lý.","usage_ja":"Hay đi với: 遅延損害金を請求する, 上限. Hợp đồng EPC Nhật cũng dùng 損害賠償額の予定 hoặc khẩu ngữ LD (エルディー); LD về hiệu suất gọi 性能LD.","context_vi":"Dùng khi đàm phán, quản lý hợp đồng mua thiết bị và EPC, khi tính thiệt hại do giao hàng hoặc hoàn thành trễ.","ex_en":"Liquidated damages are 0.5 % of the contract price per week, capped at 10 %.","ex_ja":"遅延損害金は週あたり契約金額の0.5 %で、上限は10 %である。","ex_vi":"Tiền phạt chậm trễ là 0,5 % giá hợp đồng mỗi tuần, tối đa 10 %.","syn_en":["LDs","delay damages"],"syn_ja":["損害賠償額の予定 (văn bản pháp lý)","LD (khẩu ngữ)"]},{"en":"force majeure","pos":"noun","ipa":"/ˌfɔːrs mæˈʒɜːr/","ja":"不可抗力","kana":"ふかこうりょく","romaji":"fukakouryoku","vi":"bất khả kháng","level":3,"def_vi":"Sự kiện ngoài khả năng kiểm soát của các bên như thiên tai, chiến tranh, dịch bệnh, miễn trách nhiệm cho việc chậm hoặc không thực hiện hợp đồng.","def_en":"Events beyond the parties' control, such as disasters, war or epidemics, excusing delay or non-performance.","def_ja":"天災、戦争、疫病など当事者が制御できない事象で、履行遅れや不履行の責任を免れるもの。","usage_en":"Danh từ không đếm được (gốc tiếng Pháp). Hay đi với: force majeure clause, force majeure event, declare / notify force majeure.","usage_ja":"Hay đi với: 不可抗力条項, 不可抗力事由, 不可抗力による遅延. Thường xuất hiện trong mọi hợp đồng mua bán, EPC.","context_vi":"Dùng trong điều khoản hợp đồng và khi nhà cung cấp xin miễn trách nhiệm giao chậm do bão, lũ, đại dịch.","ex_en":"The supplier notified force majeure after the flood stopped its factory.","ex_ja":"洪水で工場が停止したため、仕入先は不可抗力を通知してきた。","ex_vi":"Nhà cung cấp đã thông báo sự kiện bất khả kháng sau khi lũ làm nhà máy của họ ngừng hoạt động.","syn_en":["act of God (nghĩa hẹp hơn, thiên tai)","excusable delay (liên quan)"],"syn_ja":["天災地変 (nghĩa hẹp hơn)","フォースマジュール"]},{"en":"letter of credit","pos":"noun phrase","ipa":"/ˌletər əv ˈkredɪt/","ja":"信用状","kana":"しんようじょう","romaji":"shin'youjou","vi":"thư tín dụng (L/C)","level":3,"def_vi":"Cam kết của ngân hàng bên mua sẽ thanh toán cho bên bán khi bên bán xuất trình đủ chứng từ hợp lệ như vận đơn, hóa đơn.","def_en":"A bank's undertaking to pay the seller once compliant documents such as the bill of lading and invoice are presented.","def_ja":"船荷証券や請求書など条件どおりの書類が提示されれば、銀行が売り手に支払うと約束する書類。","usage_en":"Danh từ đếm được, viết tắt L/C hoặc LC, số nhiều letters of credit. Hay đi với: open / issue an L/C, irrevocable L/C, L/C at sight, discrepancy.","usage_ja":"Khẩu ngữ gọi L/C (エルシー). Hay đi với: 信用状を開設する, 取消不能信用状, 一覧払い, ディスクレ (chứng từ sai lệch).","context_vi":"Dùng trong thanh toán nhập khẩu máy móc giá trị lớn và khi làm việc với ngân hàng về bộ chứng từ.","ex_en":"Payment will be made by an irrevocable letter of credit at sight.","ex_ja":"支払いは一覧払いの取消不能信用状で行う。","ex_vi":"Việc thanh toán sẽ được thực hiện bằng thư tín dụng không hủy ngang trả ngay.","syn_en":["L/C","documentary credit"],"syn_ja":["L/C","荷為替信用状"]},{"en":"performance bond","pos":"noun","ipa":"/pərˈfɔːrməns bɑːnd/","ja":"履行保証","kana":"りこうほしょう","romaji":"rikouhoshou","vi":"bảo lãnh thực hiện hợp đồng","level":3,"def_vi":"Bảo lãnh do ngân hàng hoặc công ty bảo hiểm phát hành, cam kết trả cho bên mua một khoản tiền nếu nhà thầu không thực hiện đúng hợp đồng.","def_en":"A bank or insurer guarantee to pay the buyer a sum if the contractor fails to perform the contract.","def_ja":"請負者が契約を履行しない場合、銀行や保険会社が買い手に一定額を支払う保証。","usage_en":"Danh từ đếm được. Hay đi với: provide / submit a performance bond, 10 % performance bond, call the bond; liên quan advance payment bond, bid bond.","usage_ja":"Văn bản gọi 履行保証状 hoặc 契約履行保証; dự án quốc tế dùng パフォーマンスボンド. Hay đi với: 履行保証を差し入れる.","context_vi":"Dùng trong hợp đồng EPC, mua thiết bị lớn, dự án nhà nước để đảm bảo nhà thầu thực hiện nghĩa vụ.","ex_en":"The contractor must submit a performance bond of 10 % within 14 days of signing.","ex_ja":"請負者は契約締結後14日以内に、10 %の履行保証を提出しなければならない。","ex_vi":"Nhà thầu phải nộp bảo lãnh thực hiện hợp đồng 10 % trong vòng 14 ngày sau khi ký.","syn_en":["performance guarantee","bid bond (liên quan, bảo lãnh dự thầu)"],"syn_ja":["パフォーマンスボンド","履行保証状"]},{"en":"non-disclosure agreement","pos":"noun phrase","ipa":"/ˌnɑːn dɪsˈkloʊʒər əˌɡriːmənt/","ja":"秘密保持契約","kana":"ひみつほじけいやく","romaji":"himitsuhojikeiyaku","vi":"thỏa thuận bảo mật (NDA)","level":3,"def_vi":"Hợp đồng cam kết không tiết lộ và không dùng sai mục đích các thông tin kỹ thuật, kinh doanh mà các bên trao đổi.","def_en":"A contract binding parties not to disclose or misuse technical or business information they exchange.","def_ja":"やり取りする技術・営業情報を開示せず、目的外に使わないことを約束する契約。","usage_en":"Danh từ đếm được, viết tắt NDA. Hay đi với: sign an NDA, under NDA, mutual NDA, confidential information.","usage_ja":"Hay viết tắt NDA hoặc 機密保持契約. Hay đi với: 秘密保持契約を締結する, 秘密情報. Thường ký trước khi gửi bản vẽ cho nhà cung cấp mới.","context_vi":"Dùng trước khi gửi bản vẽ, mô hình 3D, quy trình công nghệ cho nhà cung cấp hoặc đối tác mới.","ex_en":"Drawings will be sent after the non-disclosure agreement is signed.","ex_ja":"秘密保持契約を締結した後に図面を送付する。","ex_vi":"Bản vẽ sẽ được gửi sau khi ký thỏa thuận bảo mật.","syn_en":["NDA","confidentiality agreement"],"syn_ja":["NDA","機密保持契約"]},{"en":"supplier audit","pos":"noun phrase","ipa":"/səˈplaɪər ˌɔːdɪt/","ja":"サプライヤー監査","kana":"サプライヤーかんさ","romaji":"sapuraiyaakansa","vi":"đánh giá nhà cung cấp (audit nhà cung cấp)","level":3,"def_vi":"Việc người mua đến nhà máy của nhà cung cấp để đánh giá hệ thống chất lượng, năng lực sản xuất và việc tuân thủ yêu cầu.","def_en":"A buyer's on-site evaluation of a supplier's quality system, production capability and compliance.","def_ja":"買い手が仕入先の工場を訪れ、品質体制、製造能力、要求事項の順守を評価すること。","usage_en":"Danh từ đếm được. Hay đi với: conduct / pass a supplier audit, audit findings, corrective action, second-party audit.","usage_ja":"Hay đi với: サプライヤー監査を実施する, 指摘事項, 是正処置. Công ty Nhật cũng gọi 仕入先監査 hoặc 工程監査.","context_vi":"Dùng khi phê duyệt nhà cung cấp mới, sau khi có lỗi chất lượng nghiêm trọng, hoặc đánh giá định kỳ hằng năm.","ex_en":"The supplier audit found that gauges were not calibrated on schedule.","ex_ja":"サプライヤー監査で、ゲージが計画どおりに校正されていないことが分かった。","ex_vi":"Đợt đánh giá nhà cung cấp phát hiện các dưỡng đo không được hiệu chuẩn đúng lịch.","syn_en":["vendor audit","supplier assessment"],"syn_ja":["仕入先監査","二者監査 (văn bản ISO)"]}]},{"id":100,"words":[{"en":"report","pos":"noun","ipa":"/rɪˈpɔːrt/","ja":"報告書","kana":"ほうこくしょ","romaji":"houkokusho","vi":"báo cáo (văn bản báo cáo)","level":1,"def_vi":"Văn bản trình bày có cấu trúc về kết quả công việc, thử nghiệm, sự cố hoặc tình hình để người khác nắm và ra quyết định.","def_en":"A structured document presenting the results of work, tests, incidents or status for others to review and act on.","def_ja":"作業、試験、トラブル、状況の結果を整理して記し、関係者の判断に使う文書。","usage_en":"Danh từ đếm được; cũng là động từ (report the defect to QA). Hay đi với: write / submit / issue a report, test report, monthly report, report on the failure.","usage_ja":"Hay đi với: 報告書を作成する, 報告書を提出する, 試験報告書, 月次報告書. Báo cáo bằng miệng dùng 報告 (ほうこく); khẩu ngữ cũng nói レポート.","context_vi":"Dùng ở mọi bộ phận kỹ thuật: báo cáo thử nghiệm, báo cáo hư hỏng, báo cáo tháng gửi cấp trên hoặc khách hàng.","ex_en":"Please submit the report on the spindle failure by Friday.","ex_ja":"主軸故障の報告書を金曜日までに提出してください。","ex_vi":"Vui lòng nộp báo cáo về hư hỏng trục chính trước thứ Sáu.","syn_en":["technical report","write-up (khẩu ngữ)"],"syn_ja":["レポート (khẩu ngữ)","報告 (báo cáo miệng)"]},{"en":"meeting minutes","pos":"noun phrase","ipa":"/ˈmiːtɪŋ ˌmɪnɪts/","ja":"議事録","kana":"ぎじろく","romaji":"gijiroku","vi":"biên bản cuộc họp","level":1,"def_vi":"Văn bản ghi lại người dự, nội dung thảo luận, quyết định và việc cần làm của một cuộc họp.","def_en":"A written record of attendees, discussion points, decisions and action items of a meeting.","def_ja":"会議の出席者、議論の内容、決定事項、宿題を記録した文書。","usage_en":"Luôn số nhiều (minutes). Hay đi với: take / write / circulate / approve the minutes, minutes of meeting (MOM); không nói a minute với nghĩa này.","usage_ja":"Hay đi với: 議事録を取る, 議事録を作成する, 議事録を配信する, 議事録の確認. Trong công ty Nhật, người trẻ thường được giao viết 議事録.","context_vi":"Dùng sau họp nội bộ, họp với khách hàng, họp kỹ thuật; là bằng chứng các quyết định đã thống nhất.","ex_en":"I will circulate the meeting minutes to all attendees this afternoon.","ex_ja":"今日の午後、出席者全員に議事録を送ります。","ex_vi":"Chiều nay tôi sẽ gửi biên bản cuộc họp cho tất cả người tham dự.","syn_en":["minutes","MOM (minutes of meeting)"],"syn_ja":["会議録","議事メモ (khẩu ngữ, đơn giản)"]},{"en":"presentation","pos":"noun","ipa":"/ˌpriːzenˈteɪʃən/","ja":"プレゼンテーション","kana":"プレゼンテーション","romaji":"purezenteeshon","vi":"bài thuyết trình","level":1,"def_vi":"Việc trình bày thông tin, kết quả hoặc đề xuất trước người nghe, thường kèm slide, hình vẽ, số liệu.","def_en":"A talk presenting information, results or proposals to an audience, usually with slides and figures.","def_ja":"スライドや図を使い、情報、結果、提案を聞き手に説明すること。","usage_en":"Danh từ đếm được. Hay đi với: give / make / prepare a presentation, presentation slides, presentation to the customer, Q&A after the presentation.","usage_ja":"Khẩu ngữ gần như luôn nói tắt プレゼン. Hay đi với: プレゼンする, プレゼン資料, 発表 (gần nghĩa, trang trọng hơn).","context_vi":"Dùng khi trình bày kết quả thiết kế, phương án cải tiến, báo cáo dự án trước khách hàng hoặc ban lãnh đạo.","ex_en":"She gave a presentation on the new fixture design to the production team.","ex_ja":"彼女は製造チームに新しい治具設計のプレゼンテーションを行った。","ex_vi":"Cô ấy đã thuyết trình về thiết kế đồ gá mới cho đội sản xuất.","syn_en":["talk","briefing (gần nghĩa, ngắn)"],"syn_ja":["プレゼン (khẩu ngữ)","発表"]},{"en":"agenda","pos":"noun","ipa":"/əˈdʒendə/","ja":"議題","kana":"ぎだい","romaji":"gidai","vi":"chương trình họp (nội dung họp)","level":1,"def_vi":"Danh sách các vấn đề sẽ được thảo luận trong cuộc họp, theo thứ tự và thường có thời lượng cho từng mục.","def_en":"The list of topics to be discussed in a meeting, in order and often with time allocated.","def_ja":"会議で話し合う事項を順番に並べたもの。","usage_en":"Danh từ đếm được. Hay đi với: send the agenda in advance, on the agenda, item 3 on the agenda, add to the agenda.","usage_ja":"議題 là từng chủ đề; cả bản chương trình họp gọi 議事次第 hoặc katakana アジェンダ. Hay đi với: 議題に挙げる, 次の議題に移る.","context_vi":"Dùng khi chuẩn bị và điều hành cuộc họp nội bộ, họp với khách hàng hoặc nhà cung cấp.","ex_en":"The vibration problem is the first item on the agenda.","ex_ja":"振動問題が最初の議題である。","ex_vi":"Vấn đề rung động là mục đầu tiên trong chương trình họp.","syn_en":["meeting agenda","topics (khẩu ngữ)"],"syn_ja":["アジェンダ","議事次第 (cả bản chương trình)"]},{"en":"figure","pos":"noun","ipa":"/ˈfɪɡjər/","ja":"図","kana":"ず","romaji":"zu","vi":"hình (hình minh họa)","level":1,"def_vi":"Hình vẽ, đồ thị, ảnh hoặc sơ đồ trong báo cáo, được đánh số và có chú thích để người đọc tham chiếu.","def_en":"A numbered drawing, graph, photo or diagram in a document, with a caption for reference.","def_ja":"文書中の番号と説明を付けた絵、グラフ、写真、模式図。","usage_en":"Danh từ đếm được, viết tắt Fig. Hay đi với: as shown in Figure 3, see Fig. 2, figure caption; khi chỉ hình cụ thể thì viết hoa Figure.","usage_ja":"Đánh số dạng 図1, 図2; hay đi với: 図に示す, 図1を参照, 図のように. Bảng thì dùng 表.","context_vi":"Dùng trong báo cáo kỹ thuật, bài báo, tài liệu hướng dẫn, slide để minh họa kết quả.","ex_en":"Figure 4 shows the temperature rise of the bearing over time.","ex_ja":"図4に軸受の温度上昇の時間変化を示す。","ex_vi":"Hình 4 thể hiện sự tăng nhiệt độ của ổ trục theo thời gian.","syn_en":["Fig.","illustration (gần nghĩa)"],"syn_ja":["図表 (nghĩa rộng hơn)","グラフ (một loại)"]},{"en":"table","pos":"noun","ipa":"/ˈteɪbəl/","ja":"表","kana":"ひょう","romaji":"hyou","vi":"bảng (bảng số liệu)","level":1,"def_vi":"Cách trình bày số liệu theo hàng và cột trong tài liệu, được đánh số và có tiêu đề.","def_en":"A numbered, titled arrangement of data in rows and columns within a document.","def_ja":"データを行と列に並べ、番号と表題を付けて示したもの。","usage_en":"Danh từ đếm được. Hay đi với: as listed in Table 2, table heading, row / column, summarize the results in a table.","usage_ja":"Đánh số dạng 表1, 表2; hay đi với: 表に示す, 表にまとめる, 一覧表. Khẩu ngữ trong công ty cũng hay nói テーブル (cơ sở dữ liệu) nhưng trong báo cáo dùng 表.","context_vi":"Dùng trong báo cáo thử nghiệm, bảng so sánh phương án, bảng thông số kỹ thuật.","ex_en":"Table 1 compares the hardness of the three samples.","ex_ja":"表1に3つの試料の硬さを比較して示す。","ex_vi":"Bảng 1 so sánh độ cứng của ba mẫu thử.","syn_en":["chart (khẩu ngữ, không chính xác)","list (gần nghĩa)"],"syn_ja":["一覧表","図表 (nghĩa rộng hơn)"]},{"en":"appendix","pos":"noun","ipa":"/əˈpendɪks/","ja":"付録","kana":"ふろく","romaji":"furoku","vi":"phụ lục","level":1,"def_vi":"Phần đặt ở cuối tài liệu chứa dữ liệu chi tiết, tính toán, bản vẽ hoặc ảnh bổ sung cho nội dung chính.","def_en":"A section at the end of a document containing detailed data, calculations, drawings or photos.","def_ja":"文書の最後に置き、詳細データ、計算、図面、写真などを補足する部分。","usage_en":"Danh từ đếm được; số nhiều appendices hoặc appendixes. Hay đi với: see Appendix A, attached in the appendix, put raw data in an appendix.","usage_ja":"Hay đi với: 付録Aを参照, 付録に示す. Trong báo cáo công ty và hợp đồng thường dùng 別紙 hoặc 添付資料; trong tiêu chuẩn JIS dùng 附属書.","context_vi":"Dùng trong báo cáo kỹ thuật, luận văn, hợp đồng và tiêu chuẩn để tách thông tin chi tiết khỏi phần chính.","ex_en":"The full FEA results are given in the appendix.","ex_ja":"FEAの全結果は付録に示す。","ex_vi":"Toàn bộ kết quả phân tích FEA được trình bày trong phụ lục.","syn_en":["annex","attachment (gần nghĩa)"],"syn_ja":["別紙","添付資料"]},{"en":"daily report","pos":"noun","ipa":"/ˌdeɪli rɪˈpɔːrt/","ja":"日報","kana":"にっぽう","romaji":"nippou","vi":"báo cáo ngày (nhật báo công việc)","level":1,"def_vi":"Báo cáo ngắn viết cuối mỗi ngày hoặc mỗi ca về công việc đã làm, sản lượng, vấn đề phát sinh và kế hoạch hôm sau.","def_en":"A short end-of-day or end-of-shift report on work done, output, problems and next-day plans.","def_ja":"毎日または毎直の終わりに、作業内容、生産数、問題点、翌日の予定を記す短い報告。","usage_en":"Danh từ đếm được. Hay đi với: write / submit the daily report, daily site report, shift report, daily production report.","usage_ja":"Rất phổ biến ở công ty Nhật: 日報を書く, 日報を提出する, 作業日報, 生産日報. Báo cáo tuần là 週報, tháng là 月報.","context_vi":"Dùng hằng ngày ở xưởng, công trường, phòng thiết kế; kỹ sư Việt làm cho công ty Nhật gần như luôn phải viết.","ex_en":"Record the machine stoppage and its cause in today's daily report.","ex_ja":"設備停止とその原因を今日の日報に記録してください。","ex_vi":"Hãy ghi lại sự cố dừng máy và nguyên nhân vào báo cáo ngày hôm nay.","syn_en":["shift report (theo ca)","daily log"],"syn_ja":["作業日報","週報 (báo cáo tuần, liên quan)"]},{"en":"inquiry","pos":"noun","ipa":"/ˈɪŋkwəri/","ja":"問い合わせ","kana":"といあわせ","romaji":"toiawase","vi":"yêu cầu thông tin (câu hỏi gửi đến)","level":1,"def_vi":"Câu hỏi hoặc yêu cầu cung cấp thông tin gửi tới một người, bộ phận hay công ty, thường qua email hoặc điện thoại.","def_en":"A question or request for information sent to a person, department or company, often by email or phone.","def_ja":"人、部署、会社に情報や回答を求めること、またはその質問。","usage_en":"Danh từ đếm được; Anh viết enquiry. Hay đi với: make / send / answer an inquiry, technical inquiry, thank you for your inquiry.","usage_ja":"Hay đi với: 問い合わせる, お問い合わせ (lịch sự), 問い合わせ先, 問い合わせに回答する. Cách viết 問合せ cũng dùng trong biểu mẫu.","context_vi":"Dùng trong email với khách hàng, nhà cung cấp, bộ phận khác khi cần làm rõ thông số, tiến độ, giá cả.","ex_en":"We received an inquiry from the customer about the paint color code.","ex_ja":"顧客から塗装色番号について問い合わせがあった。","ex_vi":"Chúng tôi đã nhận được câu hỏi của khách hàng về mã màu sơn.","syn_en":["enquiry (Anh)","query"],"syn_ja":["問合せ","照会 (trang trọng)"]},{"en":"executive summary","pos":"noun phrase","ipa":"/ɪɡˈzekjətɪv ˈsʌməri/","ja":"エグゼクティブサマリー","kana":"エグゼクティブサマリー","romaji":"eguzekutibusamarii","vi":"tóm tắt tổng quan (tóm tắt cho lãnh đạo)","level":2,"def_vi":"Phần tóm tắt ngắn ở đầu báo cáo nêu mục đích, kết quả chính và đề xuất để người quản lý đọc nhanh ra quyết định.","def_en":"A short section at the start of a report giving purpose, key findings and recommendations for busy decision-makers.","def_ja":"報告書の冒頭で目的、主な結果、提言を短くまとめ、意思決定者が素早く読めるようにした部分。","usage_en":"Danh từ đếm được. Hay đi với: write an executive summary, one-page executive summary; nên viết sau cùng nhưng đặt lên đầu.","usage_ja":"Công ty Nhật cũng dùng 要旨, 概要, サマリー. Hay đi với: エグゼクティブサマリーを付ける, 1ページにまとめる.","context_vi":"Dùng trong báo cáo dự án, báo cáo khả thi, báo cáo sự cố gửi ban giám đốc hoặc khách hàng.","ex_en":"The executive summary recommends replacing the cooling fans on line 2.","ex_ja":"エグゼクティブサマリーでは、2号ラインの冷却ファン交換を提言している。","ex_vi":"Phần tóm tắt tổng quan đề xuất thay quạt làm mát trên dây chuyền 2.","syn_en":["summary","management summary"],"syn_ja":["要旨","概要 (gần nghĩa)"]},{"en":"conclusion","pos":"noun","ipa":"/kənˈkluːʒən/","ja":"結論","kana":"けつろん","romaji":"ketsuron","vi":"kết luận","level":2,"def_vi":"Nhận định cuối cùng rút ra từ dữ liệu và phân tích, thường đặt ở cuối báo cáo hoặc nói đầu tiên khi báo cáo miệng.","def_en":"The final judgment drawn from data and analysis, placed at the end of a report or stated first in briefings.","def_ja":"データと分析から導いた最終的な判断で、報告書の最後や口頭報告の最初に述べる。","usage_en":"Danh từ đếm được. Hay đi với: draw / reach a conclusion, conclusions and recommendations, in conclusion; tránh kết luận không có số liệu hỗ trợ.","usage_ja":"Câu nói rất hay gặp ở công ty Nhật: 結論から言うと… (nói kết luận trước). Hay đi với: 結論を出す, 結論に至る.","context_vi":"Dùng trong báo cáo thử nghiệm, phân tích hư hỏng, báo cáo miệng với cấp trên người Nhật (nói kết luận trước).","ex_en":"The conclusion of the test is that the new seal meets the leak requirement.","ex_ja":"試験の結論として、新しいシールは漏れの要求を満たしている。","ex_vi":"Kết luận của thử nghiệm là phớt mới đáp ứng yêu cầu về rò rỉ.","syn_en":["finding (gần nghĩa)","outcome"],"syn_ja":["結果 (gần nghĩa)","まとめ (khẩu ngữ)"]},{"en":"recommendation","pos":"noun","ipa":"/ˌrekəmenˈdeɪʃən/","ja":"提言","kana":"ていげん","romaji":"teigen","vi":"đề xuất (khuyến nghị)","level":2,"def_vi":"Hành động được đề nghị thực hiện dựa trên kết luận của báo cáo, ví dụ thay vật liệu, sửa quy trình, đào tạo.","def_en":"A proposed action based on a report's conclusions, such as changing material, revising a procedure or training.","def_ja":"報告書の結論に基づき、材料変更、手順改訂、教育など、実施を勧める行動。","usage_en":"Danh từ đếm được. Hay đi với: make a recommendation, recommendation to replace the bearing, accept / implement the recommendations; động từ recommend + V-ing / that.","usage_ja":"Hay đi với: 提言する, 提言をまとめる. Trong báo cáo kỹ thuật cũng dùng 推奨事項 hoặc 提案; khẩu ngữ: 対策案.","context_vi":"Dùng ở cuối báo cáo phân tích, báo cáo kiểm tra, báo cáo kiểm toán năng lượng để đưa ra hướng xử lý.","ex_en":"Our main recommendation is to add a filter upstream of the valve.","ex_ja":"主な提言は、バルブの上流にフィルタを追加することである。","ex_vi":"Đề xuất chính của chúng tôi là bổ sung bộ lọc ở phía trước van.","syn_en":["proposal (gần nghĩa)","suggestion"],"syn_ja":["推奨事項","提案"]},{"en":"action item","pos":"noun","ipa":"/ˈækʃən ˌaɪtəm/","ja":"アクションアイテム","kana":"アクションアイテム","romaji":"akushon'aitemu","vi":"việc cần làm (hạng mục hành động)","level":2,"def_vi":"Công việc cụ thể được giao sau cuộc họp, có người phụ trách và hạn hoàn thành rõ ràng.","def_en":"A specific task agreed in a meeting, with an assigned owner and a due date.","def_ja":"会議で決まった具体的な作業で、担当者と期限を明確にしたもの。","usage_en":"Danh từ đếm được. Hay đi với: assign / close / follow up an action item, open action items, action item list, action owner.","usage_ja":"Khẩu ngữ trong công ty Nhật hay nói 宿題 (しゅくだい) hoặc 課題, ToDo. Hay đi với: アクションアイテムを割り当てる, 担当と期限.","context_vi":"Dùng ở cuối biên bản họp và khi theo dõi tiến độ xử lý vấn đề giữa các bộ phận.","ex_en":"Each action item in the minutes has an owner and a due date.","ex_ja":"議事録の各アクションアイテムには担当者と期限が付いている。","ex_vi":"Mỗi việc cần làm trong biên bản đều có người phụ trách và hạn hoàn thành.","syn_en":["action point (Anh)","to-do (khẩu ngữ)"],"syn_ja":["宿題 (khẩu ngữ)","ToDo"]},{"en":"incident report","pos":"noun","ipa":"/ˈɪnsɪdənt rɪˌpɔːrt/","ja":"事故報告書","kana":"じこほうこくしょ","romaji":"jikohoukokusho","vi":"báo cáo sự cố","level":2,"def_vi":"Báo cáo ghi lại diễn biến, nguyên nhân, hậu quả và biện pháp xử lý của một tai nạn hoặc sự cố trong xưởng.","def_en":"A report recording the sequence, cause, consequences and countermeasures of an accident or incident.","def_ja":"事故やトラブルの経緯、原因、影響、対策をまとめた報告書。","usage_en":"Danh từ đếm được. Hay đi với: file / submit an incident report, near-miss report, within 24 hours of the incident.","usage_ja":"Hay đi với: 事故報告書を提出する. Sự cố thiết bị, chất lượng thường gọi 不具合報告書 hoặc トラブル報告書; suýt xảy ra tai nạn là ヒヤリハット報告.","context_vi":"Dùng sau tai nạn lao động, cháy, rò rỉ, hỏng máy nghiêm trọng; gửi cho bộ phận an toàn và ban lãnh đạo.","ex_en":"An incident report must be submitted within 24 hours of any injury.","ex_ja":"負傷が発生した場合は、24時間以内に事故報告書を提出しなければならない。","ex_vi":"Phải nộp báo cáo sự cố trong vòng 24 giờ khi có bất kỳ thương tích nào.","syn_en":["accident report","near-miss report (liên quan)"],"syn_ja":["トラブル報告書","ヒヤリハット報告 (liên quan)"]},{"en":"business trip report","pos":"noun phrase","ipa":"/ˈbɪznəs trɪp rɪˌpɔːrt/","ja":"出張報告書","kana":"しゅっちょうほうこくしょ","romaji":"shutchouhoukokusho","vi":"báo cáo công tác","level":2,"def_vi":"Báo cáo viết sau chuyến công tác, nêu mục đích, người gặp, nội dung làm việc, kết quả và việc cần theo dõi.","def_en":"A report written after a business trip stating purpose, people met, work done, results and follow-up items.","def_ja":"出張後に、目的、面談者、作業内容、結果、今後の対応をまとめた報告書。","usage_en":"Danh từ đếm được; khẩu ngữ hay nói trip report hoặc visit report. Hay đi với: write a business trip report, site visit report.","usage_ja":"Rất phổ biến ở công ty Nhật: 出張報告書を提出する, 出張報告. Khi đi thăm khách hàng có khi gọi 訪問報告書.","context_vi":"Dùng sau khi đi hỗ trợ lắp đặt, thăm nhà cung cấp, đi kiểm tra tại xưởng khách hàng.","ex_en":"The business trip report lists three issues found at the customer's plant.","ex_ja":"出張報告書には、顧客工場で見つかった3つの問題が記載されている。","ex_vi":"Báo cáo công tác liệt kê ba vấn đề phát hiện tại nhà máy của khách hàng.","syn_en":["trip report","visit report"],"syn_ja":["出張報告","訪問報告書 (gần nghĩa)"]},{"en":"revision","pos":"noun","ipa":"/rɪˈvɪʒən/","ja":"改訂","kana":"かいてい","romaji":"kaitei","vi":"sửa đổi (lần ban hành sửa đổi)","level":2,"def_vi":"Việc sửa đổi tài liệu đã phát hành và phiên bản mới được ghi số hoặc chữ (Rev. A, Rev. 1) kèm nội dung thay đổi.","def_en":"A change to an issued document, and the new version identified by a letter or number such as Rev. A.","def_ja":"発行済み文書を改めること、またRev.Aなど記号で区別される新しい版。","usage_en":"Danh từ đếm được, viết tắt Rev. Hay đi với: latest revision, revision history, revision B, revise the document; luôn kiểm tra revision trước khi dùng.","usage_ja":"Hay đi với: 改訂する, 改訂版, 改訂履歴, 最新版. Ký hiệu trên bản vẽ, tài liệu: 改訂記号 hoặc Rev.","context_vi":"Dùng khi quản lý tài liệu, bản vẽ, quy trình; nhầm lần sửa đổi là nguyên nhân phổ biến của lỗi sản xuất.","ex_en":"The latest revision of the work instruction adds a torque check.","ex_ja":"作業指示書の最新の改訂では、トルク確認が追加された。","ex_vi":"Lần sửa đổi mới nhất của hướng dẫn công việc bổ sung bước kiểm tra mô-men xiết.","syn_en":["Rev.","version (gần nghĩa)"],"syn_ja":["改版","版 (gần nghĩa)"]},{"en":"handout","pos":"noun","ipa":"/ˈhændaʊt/","ja":"配布資料","kana":"はいふしりょう","romaji":"haifushiryou","vi":"tài liệu phát tay","level":2,"def_vi":"Tài liệu in hoặc tệp phát cho người dự họp, đào tạo, thuyết trình để theo dõi và giữ lại tham khảo.","def_en":"Printed or digital material given to attendees of a meeting, training or presentation for reference.","def_ja":"会議、研修、発表の参加者に配る紙や電子の資料。","usage_en":"Danh từ đếm được. Hay đi với: prepare / distribute handouts, training handout, refer to page 3 of the handout.","usage_ja":"Khẩu ngữ trong công ty Nhật hay chỉ nói 資料 (しりょう). Hay đi với: 配布資料を用意する, 資料を配る, 会議資料.","context_vi":"Dùng khi chuẩn bị họp, đào tạo an toàn, đào tạo vận hành máy cho công nhân.","ex_en":"The handout includes the wiring diagram and the start-up steps.","ex_ja":"配布資料には配線図と起動手順が含まれている。","ex_vi":"Tài liệu phát tay gồm sơ đồ đấu dây và các bước khởi động.","syn_en":["meeting materials","printout (bản in)"],"syn_ja":["資料 (khẩu ngữ)","会議資料"]},{"en":"bullet point","pos":"noun","ipa":"/ˈbʊlɪt ˌpɔɪnt/","ja":"箇条書き","kana":"かじょうがき","romaji":"kajougaki","vi":"gạch đầu dòng (liệt kê theo ý)","level":2,"def_vi":"Cách viết tách nội dung thành từng ý ngắn trên mỗi dòng, có ký hiệu đầu dòng, giúp đọc nhanh.","def_en":"A short item on its own line marked with a symbol, used to list points clearly.","def_ja":"内容を短い項目に分け、記号を付けて一行ずつ並べる書き方。","usage_en":"Danh từ đếm được, thường số nhiều. Hay đi với: in bullet points, use bullet points, bulleted list; mỗi bullet point nên bắt đầu cùng dạng ngữ pháp.","usage_ja":"箇条書き chỉ cả cách viết/danh sách, không phải từng dấu chấm. Hay đi với: 箇条書きにする, 箇条書きでまとめる. Ký hiệu gọi 中黒 hoặc ・.","context_vi":"Dùng trong slide, email, biên bản, báo cáo ngắn để trình bày các ý chính rõ ràng.","ex_en":"Summarize the test results in five bullet points on one slide.","ex_ja":"試験結果を1枚のスライドに5項目の箇条書きでまとめてください。","ex_vi":"Hãy tóm tắt kết quả thử nghiệm thành năm gạch đầu dòng trên một slide.","syn_en":["bulleted list","bullet (khẩu ngữ)"],"syn_ja":["リスト形式","項目立て (gần nghĩa)"]},{"en":"proofreading","pos":"noun","ipa":"/ˈpruːfriːdɪŋ/","ja":"校正","kana":"こうせい","romaji":"kousei","vi":"soát lỗi văn bản (đọc duyệt bản)","level":2,"def_vi":"Việc đọc kiểm tra văn bản trước khi phát hành để phát hiện lỗi chính tả, số liệu, đơn vị, định dạng.","def_en":"Checking a text before issue to find errors in spelling, numbers, units and formatting.","def_ja":"発行前に文書を読み、誤字、数値、単位、体裁の誤りを見つけること。","usage_en":"Danh từ không đếm được; động từ proofread. Hay đi với: do the proofreading, proofreading checklist, have a colleague proofread the report.","usage_ja":"Chú ý: 校正 cũng có nghĩa \"hiệu chuẩn\" (dụng cụ đo); đọc theo ngữ cảnh. Hay đi với: 校正する, 誤字脱字 (lỗi chính tả, sót chữ), 文書チェック.","context_vi":"Dùng trước khi gửi báo cáo, hướng dẫn sử dụng, catalog, tài liệu dịch Việt–Anh–Nhật cho khách hàng.","ex_en":"Proofreading found that the torque values were in N·m on one page and kgf·m on another.","ex_ja":"校正の結果、トルク値の単位がページによってN·mとkgf·mで混在していることが分かった。","ex_vi":"Khi soát lỗi văn bản, phát hiện giá trị mô-men xiết ghi N·m ở trang này và kgf·m ở trang khác.","syn_en":["proof-checking","editing (nghĩa rộng hơn)"],"syn_ja":["文書チェック","校閲 (kiểm tra nội dung, gần nghĩa)"]},{"en":"glossary","pos":"noun","ipa":"/ˈɡlɑːsəri/","ja":"用語集","kana":"ようごしゅう","romaji":"yougoshuu","vi":"bảng thuật ngữ","level":2,"def_vi":"Danh sách các thuật ngữ chuyên ngành, từ viết tắt dùng trong tài liệu kèm định nghĩa hoặc bản dịch thống nhất.","def_en":"A list of technical terms and abbreviations used in a document with their definitions or agreed translations.","def_ja":"文書で使う専門用語や略語を、定義や統一した訳語とともに並べたもの。","usage_en":"Danh từ đếm được. Hay đi với: project glossary, glossary of terms, add the term to the glossary, bilingual glossary.","usage_ja":"Hay đi với: 用語集を作成する, 対訳用語集 (bảng thuật ngữ song ngữ), 用語の統一.","context_vi":"Dùng trong dự án nhiều ngôn ngữ, khi dịch tài liệu Nhật–Việt–Anh, để mọi người dùng thuật ngữ thống nhất.","ex_en":"We created a Japanese–Vietnamese glossary so that all translators use the same terms.","ex_ja":"翻訳者全員が同じ用語を使えるよう、日越の用語集を作成した。","ex_vi":"Chúng tôi đã lập bảng thuật ngữ Nhật–Việt để mọi người dịch dùng cùng một thuật ngữ.","syn_en":["terminology list","list of abbreviations (một loại)"],"syn_ja":["対訳表","略語一覧 (một loại)"]},{"en":"interpreter","pos":"noun","ipa":"/ɪnˈtɜːrprətər/","ja":"通訳","kana":"つうやく","romaji":"tsuuyaku","vi":"phiên dịch viên (thông dịch)","level":2,"def_vi":"Người dịch lời nói từ ngôn ngữ này sang ngôn ngữ khác trực tiếp trong họp, đào tạo, làm việc tại hiện trường.","def_en":"A person who translates speech from one language to another in meetings, training or on site.","def_ja":"会議、研修、現場作業などで、話し言葉をほかの言語に訳して伝える人。","usage_en":"Danh từ đếm được. Hay đi với: through an interpreter, technical interpreter, work as an interpreter; translator là người dịch văn bản.","usage_ja":"通訳 vừa chỉ việc phiên dịch vừa chỉ người; trang trọng hơn là 通訳者. Hay đi với: 通訳する, 通訳を入れる. Dịch văn bản là 翻訳 (ほんやく).","context_vi":"Dùng trong công ty Nhật tại Việt Nam, khi chuyên gia Nhật hướng dẫn lắp đặt, đào tạo, họp kỹ thuật.","ex_en":"The Japanese engineer explained the alignment procedure through an interpreter.","ex_ja":"日本人技術者は通訳を介して芯出し手順を説明した。","ex_vi":"Kỹ sư Nhật đã giải thích quy trình căn tâm thông qua phiên dịch viên.","syn_en":["translator (dịch văn bản, liên quan)"],"syn_ja":["通訳者","翻訳者 (dịch văn bản, liên quan)"]},{"en":"5W1H","pos":"abbreviation","ipa":"/ˌfaɪv ˈdʌbəljuː ˌwʌn ˈeɪtʃ/","ja":"5W1H","kana":"ごダブリューいちエイチ","romaji":"godaburyuuichieichi","vi":"nguyên tắc 5W1H","level":2,"def_vi":"Khung kiểm tra thông tin gồm Ai, Cái gì, Khi nào, Ở đâu, Tại sao và Như thế nào, giúp báo cáo đầy đủ, rõ ràng.","def_en":"A checklist of Who, What, When, Where, Why and How used to make reports complete and clear.","def_ja":"誰が、何を、いつ、どこで、なぜ、どのようにを確認し、報告を漏れなく明確にする枠組み。","usage_en":"Viết tắt, không đổi hình thái. Hay đi với: use 5W1H, describe the problem with 5W1H; tiếng Anh cũng nói the five Ws and one H hoặc 5W2H (thêm How much).","usage_ja":"Rất phổ biến trong đào tạo nhân viên Nhật: 5W1Hで報告する, 5W1Hを明確にする. Biến thể 5W2H thêm いくら (How much).","context_vi":"Dùng khi viết báo cáo sự cố, mô tả vấn đề chất lượng, báo cáo miệng với cấp trên trong công ty Nhật.","ex_en":"Describe the defect using 5W1H before proposing a countermeasure.","ex_ja":"対策を提案する前に、不良の内容を5W1Hで説明してください。","ex_vi":"Hãy mô tả lỗi theo 5W1H trước khi đề xuất biện pháp khắc phục.","syn_en":["five Ws and one H","5W2H (biến thể)"],"syn_ja":["5W2H (biến thể)","六何の原則 (cách gọi cũ)"]},{"en":"technical writing","pos":"noun phrase","ipa":"/ˌteknɪkəl ˈraɪtɪŋ/","ja":"テクニカルライティング","kana":"テクニカルライティング","romaji":"tekunikururaitingu","vi":"viết tài liệu kỹ thuật","level":3,"def_vi":"Kỹ năng và phương pháp viết tài liệu kỹ thuật như hướng dẫn sử dụng, quy trình, báo cáo sao cho chính xác, ngắn gọn, dễ hiểu.","def_en":"The skill and practice of writing manuals, procedures and reports that are accurate, concise and easy to understand.","def_ja":"取扱説明書、手順書、報告書などを正確・簡潔・分かりやすく書く技術。","usage_en":"Danh từ không đếm được. Hay đi với: technical writing skills, technical writing course, technical writer (người viết tài liệu kỹ thuật).","usage_ja":"Hay đi với: テクニカルライティング研修, テクニカルライター. Ở Nhật có kỳ thi TC検定 về kỹ năng này.","context_vi":"Dùng khi soạn hướng dẫn vận hành máy, tài liệu bảo trì, quy trình làm việc, đặc biệt cho người đọc nước ngoài.","ex_en":"Good technical writing uses short sentences and one instruction per step.","ex_ja":"良いテクニカルライティングでは、短い文で1ステップに1つの指示を書く。","ex_vi":"Viết tài liệu kỹ thuật tốt là dùng câu ngắn và mỗi bước chỉ một chỉ dẫn.","syn_en":["technical documentation (gần nghĩa)","tech writing (khẩu ngữ)"],"syn_ja":["技術文書作成","マニュアル作成 (gần nghĩa)"]},{"en":"transmittal","pos":"noun","ipa":"/trænzˈmɪtəl/","ja":"送付状","kana":"そうふじょう","romaji":"soufujou","vi":"phiếu chuyển giao tài liệu (transmittal)","level":3,"def_vi":"Phiếu đi kèm khi gửi tài liệu chính thức, liệt kê số tài liệu, lần sửa đổi, mục đích gửi và yêu cầu phản hồi.","def_en":"A cover form sent with official documents listing document numbers, revisions, purpose of issue and required response.","def_ja":"正式な図書を送る際に添付し、文書番号、改訂、送付目的、回答要否を記す書類。","usage_en":"Danh từ đếm được. Hay đi với: document transmittal, transmittal number, issue a transmittal, for approval / for information; phổ biến trong dự án EPC.","usage_ja":"Trong dự án EPC dùng katakana トランスミッタル; thư thường gọi 送付状 hoặc 送り状. Hay đi với: 図書送付状, 承認用/参考用.","context_vi":"Dùng khi nộp bản vẽ, tài liệu kỹ thuật cho khách hàng, tư vấn trong dự án lớn, giúp truy vết ai đã nhận bản nào.","ex_en":"The P&IDs were sent for approval under transmittal No. 045.","ex_ja":"P&IDは送付状No.045で承認用として送付した。","ex_vi":"Các sơ đồ P&ID đã được gửi để phê duyệt kèm phiếu chuyển giao số 045.","syn_en":["document transmittal","cover letter (gần nghĩa)"],"syn_ja":["トランスミッタル","送り状"]},{"en":"technical query","pos":"noun","ipa":"/ˈteknɪkəl ˈkwɪri/","ja":"技術質疑","kana":"ぎじゅつしつぎ","romaji":"gijutsushitsugi","vi":"câu hỏi kỹ thuật chính thức (TQ)","level":3,"def_vi":"Câu hỏi kỹ thuật được gửi chính thức bằng văn bản để làm rõ thiết kế, yêu cầu kỹ thuật, có đánh số và phải được trả lời bằng văn bản.","def_en":"A formal, numbered written question to clarify design or specification requirements, needing a written reply.","def_ja":"設計や仕様の不明点を明らかにするため、番号を付けて文書で出す正式な質問。","usage_en":"Danh từ đếm được, viết tắt TQ. Hay đi với: raise / answer a TQ, TQ log, TQ response, pending technical queries.","usage_ja":"Hay dùng TQ hoặc 質疑書, 質疑応答書. Hay đi với: 技術質疑を提出する, 質疑回答, 質疑一覧.","context_vi":"Dùng giữa nhà thầu, nhà cung cấp và khách hàng trong dự án EPC, đấu thầu, chế tạo theo đơn đặt hàng.","ex_en":"We raised a technical query about the flange rating shown on the datasheet.","ex_ja":"データシートに記載されたフランジ定格について技術質疑を提出した。","ex_vi":"Chúng tôi đã gửi câu hỏi kỹ thuật chính thức về cấp áp lực mặt bích ghi trên bảng dữ liệu.","syn_en":["TQ","request for information (RFI, gần nghĩa)"],"syn_ja":["質疑書","TQ"]},{"en":"escalation","pos":"noun","ipa":"/ˌeskəˈleɪʃən/","ja":"エスカレーション","kana":"エスカレーション","romaji":"esukareeshon","vi":"chuyển lên cấp trên (escalation)","level":3,"def_vi":"Việc chuyển một vấn đề không giải quyết được ở cấp hiện tại lên cấp quản lý cao hơn để có quyết định hoặc hỗ trợ.","def_en":"Passing an unresolved issue to a higher management level for a decision or support.","def_ja":"現在のレベルで解決できない問題を、上位の管理者へ上げて判断や支援を求めること。","usage_en":"Danh từ không đếm được; động từ escalate (escalate the issue to the plant manager). Hay đi với: escalation path, escalation procedure.","usage_ja":"Hay đi với: エスカレーションする, 上長にエスカレーションする. Khẩu ngữ Nhật: 上に上げる; liên quan văn hóa 報連相.","context_vi":"Dùng trong quy trình xử lý sự cố, khiếu nại khách hàng, khi dự án có rủi ro chậm tiến độ lớn.","ex_en":"If the supplier does not respond within 48 hours, follow the escalation procedure.","ex_ja":"仕入先から48時間以内に回答がない場合は、エスカレーションの手順に従うこと。","ex_vi":"Nếu nhà cung cấp không phản hồi trong 48 giờ, hãy làm theo quy trình chuyển lên cấp trên.","syn_en":["escalate (động từ)","referral to management"],"syn_ja":["上申 (trang trọng)","報連相 (liên quan)"]},{"en":"peer review","pos":"noun","ipa":"/ˈpɪr rɪˌvjuː/","ja":"ピアレビュー","kana":"ピアレビュー","romaji":"piarebyuu","vi":"thẩm tra chéo (đồng nghiệp xem xét)","level":3,"def_vi":"Việc đồng nghiệp có chuyên môn tương đương đọc và kiểm tra tính toán, thiết kế, báo cáo để phát hiện lỗi trước khi phát hành.","def_en":"Checking of calculations, designs or reports by colleagues with similar expertise to find errors before issue.","def_ja":"同等の専門性を持つ同僚が計算、設計、報告書を確認し、発行前に誤りを見つけること。","usage_en":"Danh từ đếm được và không đếm được; cũng dùng như động từ (peer-review the calculation). Hay đi với: peer review comments, independent peer review.","usage_ja":"Hay đi với: ピアレビューを行う, 指摘事項. Trong công ty Nhật cũng dùng 相互レビュー, 相互チェック; xét duyệt thiết kế chính thức là デザインレビュー.","context_vi":"Dùng trong phòng thiết kế, phân tích FEA, viết bài báo khoa học, trước khi gửi báo cáo cho khách hàng.","ex_en":"The shaft calculation passed peer review with two minor comments.","ex_ja":"軸の強度計算は、軽微な指摘2件でピアレビューを通過した。","ex_vi":"Bản tính trục đã qua thẩm tra chéo với hai góp ý nhỏ.","syn_en":["independent check","design review (liên quan)"],"syn_ja":["相互チェック","デザインレビュー (liên quan)"]},{"en":"style guide","pos":"noun","ipa":"/ˈstaɪl ɡaɪd/","ja":"スタイルガイド","kana":"スタイルガイド","romaji":"sutairugaido","vi":"quy định trình bày văn bản (style guide)","level":3,"def_vi":"Bộ quy định thống nhất về cách viết, định dạng, đơn vị, số, thuật ngữ, ký hiệu dùng trong tài liệu của công ty hay dự án.","def_en":"A set of rules for wording, formatting, units, numbers and terminology in an organization's documents.","def_ja":"文書の書き方、書式、単位、数値、用語の統一ルールをまとめたもの。","usage_en":"Danh từ đếm được. Hay đi với: company style guide, follow the style guide, house style; ví dụ quy định dùng dấu chấm thập phân, SI units.","usage_ja":"Trong công ty Nhật thường gọi 表記ルール, 表記基準, 文書作成要領. Hay đi với: スタイルガイドに従う.","context_vi":"Dùng khi nhiều người cùng viết tài liệu hướng dẫn, catalog, báo cáo để giữ thống nhất về hình thức và thuật ngữ.","ex_en":"The style guide requires SI units with the imperial value in brackets.","ex_ja":"スタイルガイドでは、SI単位を用い、ヤード・ポンド法の値を括弧内に併記することになっている。","ex_vi":"Quy định trình bày văn bản yêu cầu dùng đơn vị SI, giá trị theo hệ Anh ghi trong ngoặc.","syn_en":["house style","writing guidelines"],"syn_ja":["表記ルール","文書作成要領"]},{"en":"technical paper","pos":"noun","ipa":"/ˌteknɪkəl ˈpeɪpər/","ja":"技術論文","kana":"ぎじゅつろんぶん","romaji":"gijutsuronbun","vi":"bài báo kỹ thuật","level":3,"def_vi":"Bài viết trình bày nghiên cứu hoặc kinh nghiệm kỹ thuật theo cấu trúc chuẩn, đăng trên tạp chí, kỷ yếu hội nghị.","def_en":"An article presenting technical research or experience in a standard structure, published in a journal or conference.","def_ja":"技術的な研究や知見を決まった構成でまとめ、学会誌や講演会で発表する文章。","usage_en":"Danh từ đếm được. Hay đi với: publish / present a technical paper, SAE technical paper, conference paper, abstract, peer-reviewed.","usage_ja":"Hay đi với: 論文を投稿する, 論文を発表する, 学会論文, 技報 (tạp chí kỹ thuật của công ty Nhật). Khẩu ngữ chỉ nói 論文.","context_vi":"Dùng ở viện nghiên cứu, trường đại học, bộ phận R&D khi công bố kết quả tại hội nghị JSME, SAE, ASME.","ex_en":"Our team presented a technical paper on gear noise at the JSME conference.","ex_ja":"当チームは日本機械学会の講演会で、歯車騒音に関する技術論文を発表した。","ex_vi":"Nhóm chúng tôi đã trình bày một bài báo kỹ thuật về tiếng ồn bánh răng tại hội nghị JSME.","syn_en":["journal paper","conference paper"],"syn_ja":["論文 (khẩu ngữ)","技報 (liên quan, tạp chí công ty)"]},{"en":"references","pos":"noun","ipa":"/ˈrefərənsɪz/","ja":"参考文献","kana":"さんこうぶんけん","romaji":"sankoubunken","vi":"tài liệu tham khảo","level":3,"def_vi":"Danh sách sách, tiêu chuẩn, bài báo, tài liệu được trích dẫn hoặc sử dụng trong báo cáo, ghi đủ thông tin để người đọc tìm lại.","def_en":"The list of books, standards, papers and documents cited in a report, with details for readers to find them.","def_ja":"報告書で引用・参照した書籍、規格、論文などを、探せるよう情報を付けて並べた一覧。","usage_en":"Dùng ở số nhiều khi chỉ danh mục cuối báo cáo. Hay đi với: list of references, cite a reference [3], reference standard; đôi khi gọi bibliography.","usage_ja":"Hay đi với: 参考文献を挙げる, 参考文献一覧, 文献[3]を参照. Tài liệu tham chiếu trong hợp đồng, dự án gọi 参照文書 hoặc 準拠規格.","context_vi":"Dùng ở cuối báo cáo kỹ thuật, bài báo, luận văn, bản tính để nêu nguồn công thức, tiêu chuẩn đã dùng.","ex_en":"The allowable stress values are taken from the standards listed in the references.","ex_ja":"許容応力の値は、参考文献に挙げた規格から引用している。","ex_vi":"Các giá trị ứng suất cho phép được lấy từ những tiêu chuẩn liệt kê trong tài liệu tham khảo.","syn_en":["bibliography","reference list"],"syn_ja":["引用文献 (tài liệu được trích dẫn)","参照文書 (liên quan)"]}]}]};
